module.exports = [{"id":"m-num-youlilishu","title":"有理数及其运算","subtitle":"人教版七上 · 第1章 有理数、第2章 有理数的运算","grade":"7a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七上 · 第1章 有理数、第2章 有理数的运算"},{"type":"note","title":"一句话概述","text":"认识正负数与有理数，掌握数轴、相反数、绝对值，熟练进行有理数四则运算与乘方。"},{"type":"h","text":"先看什么：一对相反意义的量"},{"type":"p","text":"温度零上 5^ 与零下 5^、收入 200 元与支出 200 元，都是「方向相反、大小相同」的量。数学上先规定一种意义记为正，另一种就用「-」记为负：于是 +5 与 -5 成为一对，负号只表示方向，不表示大小。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-s1","title":"用正负数表示相反意义的量","caption":"0 是分界，零上五与零下五到原点的距离相等","view":"wide","alt":"一条数轴，原点 0 标在中间，右侧的点表示零上五摄氏度，左侧的点表示零下五摄氏度，两点到原点的距离相等","prims":[{"t":"line","x1":8,"y1":34,"x2":82,"y2":34},{"t":"arrow","x1":82,"y1":34,"x2":92,"y2":34},{"t":"line","x1":11,"y1":31,"x2":11,"y2":37},{"t":"line","x1":18,"y1":31,"x2":18,"y2":37},{"t":"line","x1":25,"y1":31,"x2":25,"y2":37},{"t":"line","x1":32,"y1":31,"x2":32,"y2":37},{"t":"line","x1":39,"y1":31,"x2":39,"y2":37},{"t":"line","x1":46,"y1":31,"x2":46,"y2":37},{"t":"line","x1":53,"y1":31,"x2":53,"y2":37},{"t":"line","x1":60,"y1":31,"x2":60,"y2":37},{"t":"line","x1":67,"y1":31,"x2":67,"y2":37},{"t":"line","x1":74,"y1":31,"x2":74,"y2":37},{"t":"line","x1":81,"y1":31,"x2":81,"y2":37},{"t":"text","x":11,"y":44,"text":"-5","size":3.4,"anchor":"middle"},{"t":"text","x":46,"y":44,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":81,"y":44,"text":"+5","size":3.4,"anchor":"middle"},{"t":"dot","x":81,"y":34,"tone":"accent"},{"t":"dot","x":11,"y":34,"tone":"accent"},{"t":"text","x":78,"y":24,"text":"零上 5℃ 记作 +5","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":24,"y":56,"text":"零下 5℃ 记作 -5","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":26,"y":22,"text":"方向相反、大小相同","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"正负号表示的是意义方向，不是大小；作为相反意义的量记录时，符号不能省。"},{"type":"h","text":"比大小：看数轴上的位置"},{"type":"p","text":"数轴上右边的点表示的数总比左边的数大，所以比较大小除了用「正数大于 0、0 大于负数、正数大于一切负数」，还可以直接看位置。两个负数比较时，绝对值大的反而小：-7 在 -3 的左边，所以 -7<-3。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-s2","title":"数轴上右边的数总比左边的大","caption":"负七在负三的左边，所以负七小于负三","view":"wide","alt":"一条数轴标出负七、负三、零与四的位置，负七在负三左边，说明负七小于负三","prims":[{"t":"line","x1":15,"y1":34,"x2":84,"y2":34},{"t":"arrow","x1":84,"y1":34,"x2":93,"y2":34},{"t":"line","x1":25,"y1":31,"x2":25,"y2":37},{"t":"line","x1":45,"y1":31,"x2":45,"y2":37},{"t":"line","x1":60,"y1":31,"x2":60,"y2":37},{"t":"line","x1":80,"y1":31,"x2":80,"y2":37},{"t":"text","x":25,"y":44,"text":"-7","size":3.4,"anchor":"middle"},{"t":"text","x":45,"y":44,"text":"-3","size":3.4,"anchor":"middle"},{"t":"text","x":60,"y":44,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":80,"y":44,"text":"4","size":3.4,"anchor":"middle"},{"t":"dot","x":25,"y":34,"tone":"danger"},{"t":"dot","x":45,"y":34,"tone":"main"},{"t":"text","x":50,"y":56,"text":"两个负数比大小，绝对值大的反而小","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"画数轴比较大小最稳妥：只要分清谁在左谁在右，就不必死记符号规则。"},{"type":"h","text":"抓条件：绝对值就是到原点的距离"},{"type":"p","text":"把「在原点哪一侧」这层信息扔掉，只留下「离原点多远」，得到的就是绝对值 |a|。距离不可能为负，所以 |a|≥ 0；正数的绝对值是它本身，负数的绝对值是它的相反数。因此化简 |a| 之前，必须先判断 a 是正还是负。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-s3","title":"绝对值是点到原点的距离","caption":"正数与负数到原点的距离都记为正数","view":"wide","alt":"一条数轴，原点在中间，左边一个负数和右边一个正数分别用圆点标出，两条双向箭头分别表示两点到原点的距离","prims":[{"t":"line","x1":8,"y1":34,"x2":84,"y2":34},{"t":"arrow","x1":84,"y1":34,"x2":93,"y2":34},{"t":"line","x1":50,"y1":31,"x2":50,"y2":37},{"t":"text","x":50,"y":44,"text":"0","size":3.4,"anchor":"middle"},{"t":"dot","x":26,"y":34,"tone":"danger","label":"a","labelDy":-7},{"t":"dot","x":74,"y":34,"tone":"main","label":"b","labelDy":-7},{"t":"arrow","x1":50,"y1":54,"x2":26,"y2":54,"both":true,"tone":"danger","label":"|a|","labelDx":-6},{"t":"arrow","x1":50,"y1":54,"x2":74,"y2":54,"both":true,"tone":"main","label":"|b|","labelDx":6},{"t":"text","x":50,"y":16,"text":"绝对值恒不为负","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"化简含字母的绝对值一定要先判断正负，这就是「分类讨论」的由来。"},{"type":"h","text":"换个情境：异号相加为什么取绝对值大的符号"},{"type":"p","text":"-3+5 可以看成从 -3 出发向右走 5 个单位：先走 3 步回到 0，还剩 2 步，落在 +2。这说明异号两数相加，结果的符号由绝对值较大的加数决定，数值是「大绝对值减小绝对值」；若两数同号，就把绝对值相加、符号不变。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-s4","title":"负三加五：向右走五步落到正二","caption":"先用三步走到 0，剩下两步向右，结果为正二","view":"wide","alt":"一条数轴，从负三出发向右画一支长箭头表示走五个单位，途中经过原点 0，终点落在正二处","prims":[{"t":"line","x1":6,"y1":36,"x2":80,"y2":36},{"t":"arrow","x1":80,"y1":36,"x2":89,"y2":36},{"t":"line","x1":34,"y1":33,"x2":34,"y2":39},{"t":"text","x":34,"y":46,"text":"0","size":3.4,"anchor":"middle"},{"t":"dot","x":13,"y":36,"tone":"danger"},{"t":"dot","x":48,"y":36,"tone":"accent"},{"t":"arrow","x1":13,"y1":18,"x2":48,"y2":18,"tone":"accent","label":"+5","labelDy":-4},{"t":"text","x":13,"y":29,"text":"起点 -3","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":52,"y":29,"text":"结果 +2","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":58,"text":"|5| 大于 |-3|，取正号，数值 5 - 3 = 2","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"把加法看成「在数轴上走路」，正数向右、负数向左，符号就看最后落在原点的哪一侧。"},{"type":"h","text":"核心概念"},{"type":"p","text":"正数与负数：大于 0 的数叫正数，在正数前面加上符号「-」的数叫负数。0 既不是正数也不是负数，它是正数与负数的分界。用正负数可以表示具有相反意义的量，如收入 200 元记作 +200 元，支出 200 元记作 -200 元。"},{"type":"p","text":"有理数：整数和分数统称有理数，即正整数、0、负整数、正分数、负分数都是有理数。任何有理数都能写成 (p)/(q) 的形式（p、q 是整数，q≠ 0），因此一切有限小数和无限循环小数都是有理数。"},{"type":"p","text":"数轴：规定了原点、正方向和单位长度的直线叫数轴，它把「数」与「点」一一对应起来。数轴上右边的数总比左边的数大，所以比较大小既可用法则，也可看数轴上的位置。"},{"type":"p","text":"相反数：只有符号不同的两个数互为相反数，a 的相反数是 -a，0 的相反数还是 0。关键点：互为相反数的两数之和为 0，在数轴上它们位于原点两侧且到原点的距离相等。"},{"type":"p","text":"绝对值：数轴上表示数 a 的点与原点的距离叫做 a 的绝对值，记作 |a|。关键点：|a|≥ 0 恒成立；正数的绝对值是它本身，负数的绝对值是它的相反数，故化简 |a| 前必须先判断 a 的正负。"},{"type":"p","text":"倒数：乘积是 1 的两个数互为倒数，a 的倒数是 (1)/(a)（a≠ 0）。关键点：0 没有倒数；倒数等于本身的数是 1 和 -1，这与「相反数等于本身」只有 0 不同。"},{"type":"p","text":"乘方与科学记数法：求 n 个相同因数的积的运算叫乘方，结果叫幂，a 叫底数、n 叫指数。把一个大于 10 的数写成 a× 10^(n) 的形式（1≤ |a|<10，n 为正整数）叫科学记数法，n 比原数的整数位数少 1。"},{"type":"p","text":"有理数混合运算的顺序：先乘方，再乘除，最后加减；同级运算从左到右；有括号先算括号里的，按小括号、中括号、大括号的顺序进行。合理使用运算律可以简化计算。"},{"type":"note","title":"中考考法","text":"有理数的混合运算与符号判断\n常以选择、填空出现，给含乘方、绝对值、相反数的算式判断结果或正负，踩分点是先定符号再算绝对值，并严格按运算顺序分步。"},{"type":"note","title":"中考考法","text":"数轴、相反数与绝对值的综合应用\n结合数轴上的距离、折叠、动点考查，常与方程思想结合，踩分点是距离用两数差的绝对值表示，去绝对值前先分类讨论。"},{"type":"note","title":"中考考法","text":"用正负数表示实际量并进行有理数运算\n以温度变化、行走记录、质量检测为情境，小题常配合科学记数法，踩分点是明确正负的意义，求总路程时要取绝对值再相加。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["绝对值的意义","|a|=cases a & (a>0) \\\\ 0 & (a=0) \\\\ -a & (a<0) endcases","绝对值是距离，所以 |a|≥ 0 恒成立；当字母的正负未知时，结果要分类讨论。"],["有理数减法法则","a-b=a+(-b)","减去一个数等于加上这个数的相反数，减号与减数要一起变号，不能只变一个。"],["有理数除法法则","a÷ b=a· (1)/(b)\\ \\ (b≠ 0)","除以一个不为 0 的数等于乘这个数的倒数；除数不能为 0，分子为 0 时商为 0。"],["有理数乘方","a^(n)=a· a… a_(n)","底数是括号内的整体：(-2)³=-8，而 -2³=-8、-2²=-4、(-2)²=4，负号在括号外时不参与乘方。"],["科学记数法","其中 1≤ |a|<10，n 为整数；n 等于原数的整数位数减 1。","原数的绝对值小于 1 时，n 取负整数，如 0.00035=3.5× 10^(-4)。"],["有理数加法法则","同号两数相加，取相同的符号，并把绝对值相加；绝对值不相等的异号两数相加，取绝对值较大的加数的符号，并用较大的绝对值减去较小的绝对值；互为相反数的两个数相加得 0；一个数同 0 相加仍得这个数。","加法与减法统一成加法后，可把式子写成省略加号和括号的形式，再用法则计算。"]]},{"type":"note","title":"例题","text":"计算：-3²+(-(1)/(2))²-|-4|× (-2)。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-e1","title":"有理数混合运算的顺序","caption":"先乘方，再乘除，最后加减；有括号先算括号里的","view":"wide","alt":"三个自上而下排列的方框依次写有乘方、乘除、加减，箭头由上一个指向下一个，表示运算的先后次序","prims":[{"t":"rect","x":28,"y":8,"w":44,"h":11,"tone":"danger","label":"先算乘方"},{"t":"rect","x":28,"y":24,"w":44,"h":11,"tone":"accent","label":"再算乘除"},{"t":"rect","x":28,"y":40,"w":44,"h":11,"tone":"main","label":"最后算加减"},{"t":"arrow","x1":50,"y1":19,"x2":50,"y2":24,"tone":"muted"},{"t":"arrow","x1":50,"y1":35,"x2":50,"y2":40,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"同级运算从左到右；有括号先算括号内","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先算乘方与绝对值：-3²=-(3× 3)=-9，(-(1)/(2))²=(1)/(4)，|-4|=4。","再算乘法：|-4|× (-2)=4× (-2)=-8，所以原式 =-9+(1)/(4)-(-8)。","把减法统一成加法：原式 =-9+(1)/(4)+8。","按加法法则合并：-9+8=-1，故原式 =-1+(1)/(4)=-(3)/(4)。"]},{"type":"p","text":"答案：-(3)/(4)"},{"type":"note","title":"方法小结","text":"本题两处易错：-3² 中底数是 3 而不是 -3，结果为 -9；减去 -8 要变成加上 8。做混合运算先用横线标出每一步的运算顺序再动手。"},{"type":"note","title":"例题","text":"用简便方法计算：(-24)× ((1)/(3)-(3)/(4)+(5)/(8))。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-e2","title":"分配律：把负二十四分别乘到三项","caption":"三个积相加得负五，比先通分再乘快得多","view":"square","alt":"一条水平基准线，上方一根条形表示正十八，下方两根条形分别表示负八与负十五，三个积相加得到负五","prims":[{"t":"line","x1":12,"y1":40,"x2":88,"y2":40,"tone":"muted"},{"t":"rect","x":16,"y":40,"w":18,"h":12,"tone":"danger","label":"-8"},{"t":"rect","x":41,"y":13,"w":18,"h":27,"tone":"ok","label":"+18"},{"t":"rect","x":66,"y":40,"w":18,"h":15,"tone":"danger","label":"-15"},{"t":"text","x":50,"y":8,"text":"每个积 = -24 乘括号内的项","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":68,"text":"-8 + 18 - 15 = -5","size":3.8,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["观察发现括号内各项的分母都是 24 的因数，故用乘法分配律，把 -24 分别乘到括号内每一项。","(-24)× (1)/(3)=-8。","(-24)× (-(3)/(4))=+18（同号得正）。","(-24)× (5)/(8)=-15。","把三个积相加：-8+18-15=-5，所以原式 =-5。"]},{"type":"p","text":"答案：-5"},{"type":"note","title":"方法小结","text":"分配律使用时要连同符号一起分配，(-24)×(-(3)/(4)) 的结果是正数。若先算括号内通分，通分结果 =(8-18+15)/(24)=(5)/(24) 同样正确，但计算量大得多。"},{"type":"note","title":"例题","text":"已知 |a|=3，|b|=5，且 a>b，求 a+b 的值。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-e3","title":"用数轴筛选 a 与 b 的取值","caption":"只有 b 取负五、a 取正负三时才满足 a 大于 b","view":"wide","alt":"一条数轴标出负五、负三、零、三、五各点，a 可取正三与负三，b 可取正五与负五，满足 a 大于 b 的组合是 a 取三、b 取负五，或 a 取负三、b 取负五","prims":[{"t":"line","x1":14,"y1":36,"x2":82,"y2":36},{"t":"arrow","x1":82,"y1":36,"x2":91,"y2":36},{"t":"line","x1":20,"y1":33,"x2":20,"y2":39},{"t":"line","x1":32,"y1":33,"x2":32,"y2":39},{"t":"line","x1":50,"y1":33,"x2":50,"y2":39},{"t":"line","x1":68,"y1":33,"x2":68,"y2":39},{"t":"line","x1":80,"y1":33,"x2":80,"y2":39},{"t":"text","x":20,"y":46,"text":"-5","size":3.4,"anchor":"middle"},{"t":"text","x":32,"y":46,"text":"-3","size":3.4,"anchor":"middle"},{"t":"text","x":50,"y":46,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":68,"y":46,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":80,"y":46,"text":"5","size":3.4,"anchor":"middle"},{"t":"dot","x":32,"y":36,"tone":"main"},{"t":"dot","x":68,"y":36,"tone":"main"},{"t":"dot","x":20,"y":36,"tone":"accent"},{"t":"dot","x":80,"y":36,"tone":"accent"},{"t":"text","x":50,"y":20,"text":"a 可取 ±3，b 可取 ±5","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":58,"text":"留下 a = 3、b = -5 与 a = -3、b = -5","size":3.5,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["由 |a|=3 得 a=3 或 a=-3；由 |b|=5 得 b=5 或 b=-5。","逐一检验条件 a>b：a=3、b=5 时 3>5 不成立，舍去；a=-3、b=5 时 -3>5 不成立，舍去。","当 a=3、b=-5 时 3>-5 成立，a+b=3+(-5)=-2。","当 a=-3、b=-5 时 -3>-5 成立，a+b=(-3)+(-5)=-8。"]},{"type":"p","text":"答案：a+b=-2 或 a+b=-8"},{"type":"note","title":"方法小结","text":"含绝对值的条件题必须把所有可能取值列出后逐一筛选，不能只凭感觉取一个；两个负数比较大小，绝对值大的反而小。"},{"type":"note","title":"例题","text":"将画有数轴的纸条折叠，使表示数 1 的点与表示数 -3 的点重合。（1）求折点表示的数；（2）若表示数 -2 的点与表示数 a 的点重合，求 a；（3）若 B、C 两点经折叠后重合，且两点相距 8 个单位长度，求 B、C 表示的数。"},{"type":"figure","figure":{"id":"fig-m-num-youlilishu-zhedie-1","title":"数轴折叠：重合的点关于折点对称","caption":"1 与 -3 重合，折点是它们的中点 -1","view":"wide","alt":"一条数轴上标有从负 5 到 4 的整数刻度，折点在负 1 处用实心圆点标出；1 与负 3、负 2 与 0、负 5 与 3 分别用弧线连起来表示折叠后重合的点对","prims":[{"t":"line","x1":10,"y1":50,"x2":82,"y2":50},{"t":"arrow","x1":82,"y1":50,"x2":88,"y2":50},{"t":"line","x1":10,"y1":47,"x2":10,"y2":53},{"t":"line","x1":18,"y1":47,"x2":18,"y2":53},{"t":"line","x1":26,"y1":47,"x2":26,"y2":53},{"t":"line","x1":34,"y1":47,"x2":34,"y2":53},{"t":"line","x1":42,"y1":47,"x2":42,"y2":53},{"t":"line","x1":50,"y1":47,"x2":50,"y2":53},{"t":"line","x1":58,"y1":47,"x2":58,"y2":53},{"t":"line","x1":66,"y1":47,"x2":66,"y2":53},{"t":"line","x1":74,"y1":47,"x2":74,"y2":53},{"t":"line","x1":82,"y1":47,"x2":82,"y2":53},{"t":"text","x":10,"y":60,"text":"-5","size":3.4,"anchor":"middle"},{"t":"text","x":18,"y":60,"text":"-4","size":3.4,"anchor":"middle"},{"t":"text","x":26,"y":60,"text":"-3","size":3.4,"anchor":"middle"},{"t":"text","x":34,"y":60,"text":"-2","size":3.4,"anchor":"middle"},{"t":"text","x":42,"y":60,"text":"-1","size":3.4,"anchor":"middle"},{"t":"text","x":50,"y":60,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":58,"y":60,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":66,"y":60,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":74,"y":60,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":82,"y":60,"text":"4","size":3.4,"anchor":"middle"},{"t":"dot","x":42,"y":50,"tone":"accent","label":"折点","labelDx":0,"labelDy":-10},{"t":"dot","x":26,"y":50,"hollow":true},{"t":"dot","x":58,"y":50,"hollow":true},{"t":"dot","x":34,"y":50,"hollow":true},{"t":"dot","x":50,"y":50,"hollow":true},{"t":"dot","x":10,"y":50,"hollow":true},{"t":"dot","x":74,"y":50,"hollow":true},{"t":"arc","cx":42,"cy":50,"r":16,"from":0,"to":180,"tone":"muted","dashed":true},{"t":"arc","cx":42,"cy":50,"r":8,"from":0,"to":180,"tone":"muted","dashed":true},{"t":"arc","cx":42,"cy":50,"r":32,"from":0,"to":180,"tone":"muted","dashed":true}]}},{"type":"list","title":"解题步骤","items":["折叠后重合的两点关于折点对称，想到折点就是这两个点的中点，故折点表示 (1+(-3))/(2)=-1。","互相重合的点到折点距离相等，即折点始终是两点的中点，由 (-2+a)/(2)=-1 解得 a=0。","B、C 相距 8，每个点到折点的距离都是 8÷ 2=4。","在折点 -1 两侧各数 4 个单位：B=-1-4=-5，C=-1+4=3。"]},{"type":"p","text":"答案：（1）折点表示 -1；（2）a=0；（3）B、C 分别表示 -5 和 3"},{"type":"note","title":"方法小结","text":"折叠问题的本质是「中点重合」，折点就是任意一对重合点的中点。第（3）问要把两点距离平分到折点两侧，最容易只向一侧数而漏掉另一个点。"},{"type":"note","title":"例题","text":"某检修小组乘汽车从 A 地出发，在南北走向的公路上检修线路，约定向南为正、向北为负，当天的行驶记录依次为（单位：千米）：+8，-3，+4，-6，+10，-2，-5。（1）收工时汽车在 A 地的哪个方向？距 A 地多远？（2）若汽车每行驶 1 千米耗油 0.2 升，求从出发到收工共耗油多少升。"},{"type":"figure","figure":{"id":"fig-num-youlilishu-e5","title":"带符号记录与收工位置","caption":"代数和是正六，收工在 A 地以南 6 千米处","view":"wide","alt":"一条南北方向的竖直线，中点是出发点 A，南端标出收工位置，收工位置在 A 地以南六个单位处","prims":[{"t":"line","x1":40,"y1":16,"x2":40,"y2":56},{"t":"arrow","x1":40,"y1":16,"x2":40,"y2":8,"tone":"muted"},{"t":"text","x":33,"y":14,"text":"北","size":3.6,"anchor":"end","tone":"muted"},{"t":"text","x":33,"y":54,"text":"南","size":3.6,"anchor":"end","tone":"muted"},{"t":"dot","x":40,"y":32,"tone":"main","label":"A 地出发","labelDx":6},{"t":"dot","x":40,"y":48,"tone":"accent","label":"收工：南 6 km","labelDx":6},{"t":"text","x":62,"y":62,"text":"代数和 +6 定位置，绝对值之和 38 定路程","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["第（1）问求最终位置，把带符号的记录全部相加：8-3+4-6+10-2-5。","从左到右计算：8-3=5，5+4=9，9-6=3，3+10=13，13-2=11，11-5=6，结果为 +6。","结果为正，故收工时汽车在 A 地南方 6 千米处。","第（2）问耗油量只与路程有关、与方向无关，想到这一点就要先取绝对值再求和：|8|+|-3|+|4|+|-6|+|10|+|-2|+|-5|=38（千米）。","共耗油 38× 0.2=7.6（升）。"]},{"type":"p","text":"答案：（1）在 A 地南方 6 千米处；（2）共耗油 7.6 升"},{"type":"note","title":"方法小结","text":"最终位置看带符号数的代数和，行驶路程看绝对值之和，这是两类最容易混的问题。作答时方向与距离两个要素都要写全，耗油量要带单位。"},{"type":"list","title":"易错点","items":["把 $-3^{2}$ 算成 $9$。$-3^{2}$ 表示 $3^{2}$ 的相反数，结果是 $-9$；只有 $(-3)^{2}$ 才等于 $9$。这是乘方与负号结合时最高频的错误。","化简绝对值时不判断正负，直接把 $|a|$ 写成 $a$。当 $a<0$ 时 $|a|=-a$，如 $|\\sqrt{2}-2|=2-\\sqrt{2}$。","两个负数比较大小，误以为绝对值大的数大。事实上两个负数比较，绝对值大的反而小，如 $-7<-3$。","把「减去一个数」只变了被减数或只变了一个符号，如把 $5-(-3)$ 算成 $5-3$。减法统一成加法时符号要整体处理。","混淆 0 的性质：0 既不是正数也不是负数，0 的相反数、绝对值都是 0，但 0 没有倒数。","乘除混合运算中先算绝对值再定符号时漏看负号个数。多个因数相乘，负因数有奇数个时积为负，有偶数个时积为正。"]},{"type":"list","title":"解题方法","items":["加减混合运算统一成加法：把减法全部改写成加法，再写成省略加号与括号的形式，最后按加法法则计算。","乘除混合先定符号再算绝对值，并把除法统一化为乘法，约分后再乘，减少出错。","熟练运用运算律：互为倒数、同分母、凑整时优先使用分配律及其逆用，能口算的部分绝不硬算。","比较有理数大小时画数轴。正数大于 0，0 大于负数，正数大于一切负数；同号两数再比较绝对值。","用逆运算与估算检验结果：加减用减法回代检验，观察结果的符号与数量级是否合理。"]}],"questions":[{"id":"m-num-youlilishu-q1","type":"choice","stem":"下列说法正确的是（ ）","answer":"C","explain":"C 正确：|a|=a 要求 a≥ 0，即非负数（正数和 0）。A 错：没有最小的有理数，负数可以无限小，如 -1000<-1，而 0 只是最小的非负整数。B 错：-a 的正负取决于 a，当 a=-5 时 -a=5 是正数。D 错：倒数等于本身的数有 1 和 -1 两个，因为 1× 1=1，(-1)×(-1)=1。","options":["0 是最小的有理数","-a 一定是负数","绝对值等于它本身的数是非负数","倒数等于它本身的数只有 1"],"difficulty":1,"tags":["有理数","绝对值","概念辨析"]},{"id":"m-num-youlilishu-q2","type":"choice","stem":"计算 (-2)³× (-(1)/(2))²-(-1)²⁰²⁵ 的结果是（ ）","answer":"B","explain":"(-2)³=-8，(-(1)/(2))²=(1)/(4)，故 (-2)³×(-(1)/(2))²=(-8)×(1)/(4)=-2。又 (-1)²⁰²⁵=-1（2025 是奇数）。所以原式 =-2-(-1)=-2+1=-1，选 B。","options":["-3","-1","1","3"],"difficulty":2,"tags":["乘方","混合运算","符号"]},{"id":"m-num-youlilishu-q3","type":"fill","stem":"计算：-(1)/(2)+(2)/(3)-(3)/(4)=（ ）。","answer":"-7/12","explain":"取分母 2、3、4 的最小公倍数 12 通分：-(1)/(2)+(2)/(3)-(3)/(4)=-(6)/(12)+(8)/(12)-(9)/(12)=(-6+8-9)/(12)=-(7)/(12)。计算时先确定符号再算绝对值，避免分数加减中丢负号。","difficulty":1,"tags":["分数","加减运算"]},{"id":"m-num-youlilishu-q4","type":"fill","stem":"某地一天早晨的气温是 2^，中午前气温下降了 7^，傍晚又上升了 3^，则傍晚的气温是（ ）^。","answer":"-2","explain":"把上升记为正、下降记为负，气温变化为 2-7+3。先算 2-7=-5，再算 -5+3=-2。所以傍晚气温是 -2^。注意负数表示气温在零摄氏度以下，答案要带负号。","difficulty":1,"tags":["有理数","实际应用","正负数"]},{"id":"m-num-youlilishu-q5","type":"short","stem":"已知 |a-2|+(b+3)²=0，求 a^(b) 的值，并写出完整推理过程。","answer":"$a=2$，$b=-3$，$a^{b}=2^{-3}=\\frac{1}{8}$。","explain":"由绝对值和平方的非负性可知 |a-2|≥ 0，(b+3)²≥ 0。两个非负数的和为 0，只能是它们同时为 0，于是 a-2=0，b+3=0，解得 a=2，b=-3。代入得 a^(b)=2^(-3)=12³=(1)/(8)。","difficulty":2,"tags":["非负性","绝对值","乘方"],"rubric":["指出 |a-2|≥ 0 与 (b+3)²≥ 0（非负性和为零则各自为零）","正确解出 a=2","正确解出 b=-3","按负整数指数幂算出 2^(-3)=(1)/(8)（写成 0.125 同样给分）"]},{"id":"m-num-youlilishu-z1","type":"choice","stem":"计算 -1²⁰²⁶+(-2)³-|-3| 的结果是（ ）","answer":"D","explain":"-1²⁰²⁶ 中负号在括号外，表示 1²⁰²⁶ 的相反数，等于 -1；(-2)³=-8；|-3|=3。所以原式 =-1+(-8)-3=-12，选 D。若把 -1²⁰²⁶ 误算成 1，就会得到 -6 而错选 B。","options":["12","-6","6","-12"],"difficulty":2,"tags":["乘方","混合运算","符号"]},{"id":"m-num-youlilishu-z2","type":"short","stem":"数轴上点 A 表示 -4，点 B 表示 6。动点 P 从点 A 出发，以每秒 2 个单位长度的速度沿数轴向右运动；同时动点 Q 从点 B 出发，以每秒 1 个单位长度的速度沿数轴向左运动。设运动时间为 t 秒，当 P、Q 两点相距 3 个单位长度时，求 t 的值，并写出完整推理过程。","answer":"$t$ 秒后点 $P$ 表示 $-4+2t$，点 $Q$ 表示 $6-t$，由 $|(-4+2t)-(6-t)|=3$ 得 $|3t-10|=3$，解得 $t=\\frac{7}{3}$ 或 $t=\\frac{13}{3}$。","explain":"运动 t 秒后，点 P 向右移动 2t，表示的数是 -4+2t；点 Q 向左移动 t，表示的数是 6-t。数轴上两点的距离等于两数差的绝对值，故列方程 |(-4+2t)-(6-t)|=3，即 |3t-10|=3。由绝对值的意义得 3t-10=3 或 3t-10=-3，分别解得 t=(13)/(3)（相遇之后继续运动再次相距 3 个单位）和 t=(7)/(3)（相遇之前相距 3 个单位）。检验：t=(7)/(3) 时 P=(2)/(3)、Q=(11)/(3)，距离为 3；t=(13)/(3) 时 P=(14)/(3)、Q=(5)/(3)，距离也为 3，两个解都符合实际。","difficulty":3,"tags":["有理数","绝对值","实际应用"],"rubric":["用含 t 的式子正确表示两个动点的位置：P 为 -4+2t，Q 为 6-t","由「两点相距 3」列出绝对值方程 |3t-10|=3","分两种情况解出 t=(7)/(3) 与 t=(13)/(3)，两个解都写出并有检验"],"figure":{"id":"fig-num-youlilishu-dongdian","title":"数轴上相向而行的两个动点","caption":"A 表示 -4、B 表示 6；P 从 A 以每秒 2 个单位向右走，Q 从 B 以每秒 1 个单位向左走。图示为运动中的某一时刻，P 表示的数是 -4+2t、Q 表示的数是 6-t","view":"wide","alt":"一条数轴，点 A 在数轴上表示 -4、点 B 表示 6；点 P 从 A 出发向右移动、点 Q 从 B 出发向左移动，两处画有表示运动方向的箭头并标注速度。","prims":[{"t":"line","x1":16,"y1":56,"x2":92,"y2":56,"width":0.8},{"t":"arrow","x1":86,"y1":56,"x2":91,"y2":56,"tone":"muted"},{"t":"line","x1":48.6,"y1":53,"x2":48.6,"y2":59,"width":0.8},{"t":"text","x":48.6,"y":64,"text":"0","anchor":"middle","size":3.6,"tone":"muted"},{"t":"arrow","x1":31.9,"y1":44,"x2":40.1,"y2":44,"tone":"accent","label":"2/秒","labelDy":-5},{"t":"arrow","x1":76.1,"y1":36,"x2":73.3,"y2":36,"tone":"ok","label":"1/秒","labelDy":-5},{"t":"dot","x":26.9,"y":56,"label":"A","labelDx":-4.6,"labelDy":3.2},{"t":"dot","x":81.1,"y":56,"label":"B","labelDx":2.6,"labelDy":3.2},{"t":"dot","x":43.1,"y":56,"label":"P","labelDx":-1.6,"labelDy":-4},{"t":"dot","x":70.3,"y":56,"label":"Q","labelDx":-1.6,"labelDy":-4},{"t":"text","x":50,"y":76,"text":"P 表示 -4 + 2t，Q 表示 6 - t","anchor":"middle","size":3.6,"tone":"accent"}]}}]},{"id":"m-num-zhengshi-jiajian","title":"整式的加减","subtitle":"人教版七上 · 第4章 整式的加减","grade":"7a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七上 · 第4章 整式的加减"},{"type":"note","title":"一句话概述","text":"认识单项式、多项式与整式，掌握同类项合并、去括号法则，能熟练化简整式并求值。"},{"type":"h","text":"先看什么：一个式子该读出哪些信息"},{"type":"p","text":"看到 -(3)/(5)x²y，要能一眼读出两件事：数字因数是系数 -(3)/(5)（含符号），所有字母指数之和 2+1=3 是次数。几个单项式的和组成多项式，每个单项式是它的项，其中不含字母的项叫常数项。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-s1","title":"单项式的系数与次数","caption":"数字因数是系数，所有字母的指数之和是次数","view":"wide","alt":"一个方框内写着负五分之三乘 x 的平方再乘 y，左侧箭头指向系数负五分之三，右侧箭头指向次数三","prims":[{"t":"rect","x":32,"y":20,"w":36,"h":16,"tone":"main","label":"-3/5 x²y"},{"t":"arrow","x1":32,"y1":28,"x2":16,"y2":28,"tone":"accent","label":"系数","labelDy":-5},{"t":"arrow","x1":68,"y1":28,"x2":86,"y2":28,"tone":"ok","label":"次数","labelDy":-5},{"t":"text","x":16,"y":42,"text":"-3/5","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":86,"y":42,"text":"2 + 1 = 3","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":56,"text":"系数要带符号；次数只数字母的指数之和","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"分母含字母的式子（如 (2)/(x)）不是单项式，也不是整式。"},{"type":"h","text":"抓条件：判断两个项是不是同类项"},{"type":"p","text":"同类项的标准只有一条：所含字母相同，且相同字母的指数分别相同，与系数无关。3x 与 5x 是同类项，而 2x²y 与 2xy² 不是——虽然字母一样，但 x 的指数一个是 2、一个是 1。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-s2","title":"同类项要字母与指数都相同","caption":"3x 与 5x 是同类项，2x²y 与 2xy² 不是","view":"wide","alt":"四个方框两两成组，第一组写着三 x 与五 x，标注可以合并；第二组写着二 x 平方 y 与二 x y 平方，标注字母指数不同不能合并","prims":[{"t":"rect","x":8,"y":8,"w":20,"h":12,"tone":"ok","label":"3x"},{"t":"rect","x":32,"y":8,"w":20,"h":12,"tone":"ok","label":"5x"},{"t":"text","x":30,"y":28,"text":"可以合并","size":3.4,"anchor":"middle","tone":"ok"},{"t":"rect","x":8,"y":34,"w":20,"h":12,"tone":"danger","label":"2x²y"},{"t":"rect","x":32,"y":34,"w":20,"h":12,"tone":"danger","label":"2xy²"},{"t":"text","x":30,"y":54,"text":"不能合并","size":3.4,"anchor":"middle","tone":"danger"},{"t":"line","x1":58,"y1":6,"x2":58,"y2":58,"dashed":true,"tone":"muted"},{"t":"text","x":79,"y":14,"text":"字母与指数完全相同","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":79,"y":40,"text":"x 的指数不同","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"判断同类项与系数无关，也不看系数的大小或正负。"},{"type":"h","text":"建立关系：合并同类项就是「数个数」"},{"type":"p","text":"合并同类项的依据是乘法分配律的逆用：3x+5x=(3+5)x=8x。所以合并时只把系数相加，字母与字母的指数保持不变。去括号也是分配律的直接使用：括号前的因数（包括负号）要乘进括号里的每一项。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-s3","title":"合并同类项：条形首尾相接","caption":"三个 x 与五个 x 接起来共八个 x，系数相加、字母不变","view":"wide","alt":"两个条形首尾相接，左边条形长表示三 x，右边条形长表示五 x，下方一个等长的条形表示八 x","prims":[{"t":"rect","x":15,"y":14,"w":24,"h":12,"tone":"main","label":"3x"},{"t":"rect","x":39,"y":14,"w":40,"h":12,"tone":"accent","label":"5x"},{"t":"arrow","x1":15,"y1":32,"x2":79,"y2":32,"both":true,"tone":"muted"},{"t":"rect","x":15,"y":40,"w":64,"h":12,"tone":"ok","label":"8x"},{"t":"text","x":50,"y":8,"text":"(3 + 5)x = 8x","size":3.6,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":59,"text":"系数相加，字母与指数保持不变","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"3a²+2a³ 不是同类项，不能再合并，更不能把指数相加写成 5a⁵。"},{"type":"h","text":"换个情境：化简之后再求值"},{"type":"p","text":"遇到「先化简，再求值」的题，先把式子化到最简再代入数值，比直接代入原式快得多、也稳得多。若题目给出 |a+2|+(b-3)²=0 这类条件，先用非负性求出字母的值，再代入化简结果。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-s4","title":"去括号：括号前是负号则逐项变号","caption":"相当于用 -1 乘进括号里的每一项","view":"wide","alt":"左边写着 a 减括号 b 减 c，中间箭头标注乘负一，右边写着 a 减 b 加 c","prims":[{"t":"text","x":26,"y":32,"text":"a - (b - c)","size":4.2,"anchor":"middle","tone":"danger"},{"t":"arrow","x1":48,"y1":32,"x2":62,"y2":32,"tone":"accent","label":"×(-1)","labelDy":-5},{"t":"text","x":82,"y":32,"text":"a - b + c","size":4.2,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":14,"text":"去括号的依据是乘法分配律","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":52,"text":"括号里最后一项最容易漏变号","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"化简完可用一个简单数值代入检验，如取 x=1 比对原式与化简结果。"},{"type":"h","text":"核心概念"},{"type":"p","text":"单项式：数或字母的积组成的式子叫单项式，单独一个数或一个字母也是单项式，如 -(3)/(5)x²y、7、a。单项式中的数字因数叫系数，所有字母的指数之和叫次数。注意 (2)/(x) 的分母含字母，它不是单项式。"},{"type":"p","text":"多项式：几个单项式的和叫多项式，其中每个单项式叫多项式的项，不含字母的项叫常数项。多项式中次数最高项的次数就是这个多项式的次数。"},{"type":"p","text":"整式：单项式与多项式统称整式。判别关键：分母中不含字母的式子才是整式，(x+1)/(2) 是整式，而 (2)/(x)、(1)/(x-1) 都不是。"},{"type":"p","text":"同类项：所含字母相同，并且相同字母的指数也相同的项叫同类项，所有的常数项都是同类项。关键点：判断同类项只看字母及其指数，与系数无关，且 2x²y 与 2xy² 不是同类项（相同字母的指数不同）。"},{"type":"p","text":"合并同类项：把多项式中的同类项合并成一项叫合并同类项，法则是：把同类项的系数相加，字母和字母的指数保持不变。合并的依据是乘法分配律的逆用，如 3x+5x=(3+5)x=8x。"},{"type":"p","text":"去括号法则：括号前是「+」号，去括号后各项都不改变符号；括号前是「-」号，去括号后各项都改变符号。关键点：括号前的符号要看成系数的符号乘进括号内每一项。"},{"type":"p","text":"升幂与降幂排列：把一个多项式按某个字母的指数从小到大（升幂）或从大到小（降幂）排列，便于观察次数并检查同类项是否合并彻底。"},{"type":"note","title":"中考考法","text":"单项式、多项式与同类项的概念辨析\n以选择题判断系数、次数、同类项为主，常结合「合并后与某字母取值无关」考参数，踩分点是次数只数字母指数、同类项与系数无关。"},{"type":"note","title":"中考考法","text":"整式的化简：去括号与合并同类项\n填空与解答必考，常含多重括号或化简后求值，踩分点是括号前为负号时逐项变号，养成先化简、再代入数值的习惯。"},{"type":"note","title":"中考考法","text":"列整式表示规律或图形中的数量关系\n以火柴棒、点阵、月历等规律探究题出现，要求写出第 n 个式子，踩分点是先列前几项找增量，再代回前几项验证。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["合并同类项","ax+bx=(a+b)x","只有同类项才能合并，字母与指数不变，只把系数相加；3a²+2a³ 不是同类项，不能再合并。"],["去括号法则","a+(b-c)=a+b-c, a-(b-c)=a-b+c","括号前是负号时，括号内每一项都要变号，容易漏掉最后一项。"],["添括号法则","a+b-c=a+(b-c), a-b+c=a-(b-c)","添括号与去括号互为逆过程，添加括号后括号前是负号时，括到括号里的各项都要变号。"],["乘法分配律（去括号的依据）","m(a+b)=ma+mb","去括号实质是把括号前的因数分别乘到括号内每一项，负号相当于因数 -1。"],["单项式的系数与次数","单项式中的数字因数是系数（含符号），所有字母的指数之和是次数。","如 -(3)/(5)x²y 的系数是 -(3)/(5)，次数是 2+1=3；单独一个非零常数的次数是 0。"]]},{"type":"note","title":"例题","text":"化简：2(3x²-2x+1)-3(2x²-x-2)。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-e1","title":"两个括号分别乘开后的对照","caption":"负三乘进每一项，三项都变号","view":"wide","alt":"第一行是二乘括号三 x 平方减二 x 加一展开得六 x 平方减四 x 加二，第二行是负三乘括号二 x 平方减 x 减二展开得负六 x 平方加三 x 加六","prims":[{"t":"text","x":50,"y":11,"text":"2(3x² - 2x + 1) = 6x² - 4x + 2","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":24,"text":"×(-3)：-3(2x² - x - 2) = -6x² + 3x + 6","size":3.6,"anchor":"middle","tone":"danger"},{"t":"line","x1":12,"y1":31,"x2":88,"y2":31,"tone":"muted"},{"t":"text","x":50,"y":40,"text":"二次项抵消，一次项与常数项合并","size":3.5,"anchor":"middle","tone":"muted"},{"t":"rect","x":32,"y":47,"w":36,"h":12,"tone":"ok","label":"-x + 8"}]}},{"type":"list","title":"解题步骤","items":["先用分配律去括号：2(3x²-2x+1)=6x²-4x+2。","第二个括号前是 -3，括号内每一项都乘 -3：-3(2x²-x-2)=-6x²+3x+6。","把两部分相加：6x²-4x+2-6x²+3x+6。","合并同类项：二次项 6x²-6x²=0，一次项 -4x+3x=-x，常数项 2+6=8。","所以原式 =-x+8。"]},{"type":"p","text":"答案：-x+8"},{"type":"note","title":"方法小结","text":"括号前是负数时，括号内三项都要变号，-3×(-2)=+6 是本题最容易写错的一步。化简完可用 x=1 代入检验：原式 =2×(3-2+1)-3×(2-1-2)=4+3=7，化简结果 =-1+8=7，两者相等。"},{"type":"note","title":"例题","text":"化简：3a-[2a-3(a-b)]。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-e2","title":"多重括号由内向外逐层去","caption":"先去小括号，再去中括号","view":"wide","alt":"最上方是原式三 a 减中括号二 a 减三倍括号 a 减 b，向下依次写出先去小括号、再去中括号的结果四 a 减三 b","prims":[{"t":"text","x":50,"y":10,"text":"3a - [ 2a - 3(a - b) ]","size":3.8,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":12,"x2":12,"y2":26,"tone":"accent"},{"t":"text","x":50,"y":32,"text":"先去小括号：3(a - b) = 3a - 3b","size":3.5,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":12,"y1":36,"x2":12,"y2":48,"tone":"accent"},{"t":"text","x":50,"y":54,"text":"再去中括号得 4a - 3b","size":3.6,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["先去小括号：3(a-b)=3a-3b，故中括号内变成 2a-(3a-3b)。","再去中括号内的括号：2a-3a+3b=-a+3b。","去掉中括号，注意括号前是负号：3a-(-a+3b)=3a+a-3b。","合并同类项得 4a-3b。"]},{"type":"p","text":"答案：4a-3b"},{"type":"note","title":"方法小结","text":"多重括号可「由内向外」逐层去，也可「由外向内」先去中括号（此时中括号内每项变号后再处理小括号）。无论哪种顺序，都要盯住括号前的符号。"},{"type":"note","title":"例题","text":"已知 a-2b=3，求 5-2a+4b 的值。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-e3","title":"整体代入：把 a - 2b 当成一个整体","caption":"不必分别求出 a 与 b，直接整体代入即可","view":"wide","alt":"左侧方框写着 a 减二 b 等于三，箭头标注整体代入指向右侧方框五减二倍括号 a 减二 b，下方写出代入后的结果等于负一","prims":[{"t":"rect","x":6,"y":16,"w":36,"h":14,"tone":"main","label":"a - 2b = 3"},{"t":"arrow","x1":44,"y1":23,"x2":56,"y2":23,"tone":"accent","label":"整体代入","labelDy":-5},{"t":"rect","x":58,"y":16,"w":36,"h":14,"tone":"ok","label":"5 - 2(a - 2b)"},{"t":"text","x":50,"y":46,"text":"= 5 - 2 × 3 = -1","size":4.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":58,"text":"提取负号：-2a + 4b = -2(a - 2b)","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["观察所求式与已知条件的关系：-2a+4b=-2(a-2b)。","把已知条件整体代入：5-2a+4b=5-2(a-2b)。","代入 a-2b=3 得 5-2× 3=5-6=-1。"]},{"type":"p","text":"答案：-1"},{"type":"note","title":"方法小结","text":"这类题不要试图分别求出 a、b 的值，而应把 a-2b 看成一个整体直接代入，这就是整体代入法。提负号时注意 -(a-2b)=-a+2b。"},{"type":"note","title":"例题","text":"用火柴棒按如图方式搭正方形：搭 1 个正方形用 4 根火柴棒，搭 2 个正方形用 7 根，搭 3 个正方形用 10 根。（1）搭 4 个正方形用多少根火柴棒？（2）搭 n 个正方形需要多少根？用含 n 的式子表示；（3）搭 2026 个正方形需要多少根？"},{"type":"figure","figure":{"id":"fig-m-num-zhengshi-huochai-1","title":"搭正方形的火柴棒规律","caption":"每多搭一个正方形只需增加 3 根火柴棒","view":"wide","alt":"三组用火柴棒搭成的正方形，从左到右分别是 1 个正方形用 4 根、2 个相邻正方形用 7 根、3 个相邻正方形用 10 根，下方标注每增加一个正方形增加 3 根","prims":[{"t":"rect","x":8,"y":32,"w":12,"h":14},{"t":"text","x":14,"y":58,"text":"1 个：4 根","size":3.4,"anchor":"middle"},{"t":"line","x1":32,"y1":32,"x2":52,"y2":32},{"t":"line","x1":32,"y1":46,"x2":52,"y2":46},{"t":"line","x1":32,"y1":32,"x2":32,"y2":46},{"t":"line","x1":42,"y1":32,"x2":42,"y2":46},{"t":"line","x1":52,"y1":32,"x2":52,"y2":46},{"t":"text","x":42,"y":58,"text":"2 个：7 根","size":3.4,"anchor":"middle"},{"t":"line","x1":66,"y1":32,"x2":96,"y2":32},{"t":"line","x1":66,"y1":46,"x2":96,"y2":46},{"t":"line","x1":66,"y1":32,"x2":66,"y2":46},{"t":"line","x1":76,"y1":32,"x2":76,"y2":46},{"t":"line","x1":86,"y1":32,"x2":86,"y2":46},{"t":"line","x1":96,"y1":32,"x2":96,"y2":46},{"t":"text","x":81,"y":58,"text":"3 个：10 根","size":3.4,"anchor":"middle"},{"t":"arrow","x1":20,"y1":39,"x2":32,"y2":39,"tone":"accent","label":"+3","labelDx":0,"labelDy":-6},{"t":"arrow","x1":52,"y1":39,"x2":66,"y2":39,"tone":"accent","label":"+3","labelDx":0,"labelDy":-6},{"t":"text","x":50,"y":72,"text":"规律：4 + 3(n-1) = 3n + 1","size":3.6,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["先把已知数据列成表：1to 4、2to 7、3to 10，想到每多搭一个正方形只需与前一个共用一条边，增加 3 根火柴棒。","按这个规律搭 4 个用 10+3=13 根。","搭 n 个时，在第 1 个的 4 根基础上增加 (n-1) 次 3 根，故为 4+3(n-1)=3n+1。","用前三项验证：n=1 时 3× 1+1=4，n=2 时为 7，n=3 时为 10，都吻合。","当 n=2026 时，3× 2026+1=6078+1=6079（根）。"]},{"type":"p","text":"答案：（1）13 根；（2）(3n+1) 根；（3）6079 根"},{"type":"note","title":"方法小结","text":"规律题的突破口是「看增量」：相邻两项的差固定为 3，所以结果是「首项加增量乘次数减一」。写出式子后一定要代回前几项验证，防止把 3n+1 误写成 4n。"},{"type":"note","title":"例题","text":"先化简，再求值：3(a²b-ab²)-2(a²b-2ab²)，其中 a、b 满足 |a+2|+(b-3)²=0。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-e5","title":"先由非负性求字母，再化简代入","caption":"两项非负之和为 0，只能各自为 0","view":"wide","alt":"第一行写出绝对值与平方都大于等于零，第二行说明和为 0 只能各自为 0，得到 a 等于负二、b 等于三，第三行是化简结果 a 平方 b 加 a b 平方，最后代入得负六","prims":[{"t":"text","x":50,"y":10,"text":"|a + 2| ≥ 0，(b - 3)² ≥ 0","size":3.5,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":22,"text":"和为 0，只能各自为 0 → a = -2，b = 3","size":3.5,"anchor":"middle","tone":"accent"},{"t":"line","x1":12,"y1":30,"x2":88,"y2":30,"tone":"muted"},{"t":"text","x":50,"y":40,"text":"先化简：a²b + ab²","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":53,"text":"代入：12 + (-18) = -6","size":3.8,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["题目没有直接给出 a、b 的值，想到利用绝对值与平方的非负性：两部分都不小于 0，和为 0 只能各自为 0。","由 |a+2|=0 得 a=-2，由 (b-3)²=0 得 b=3。","先去括号化简：原式 =3a²b-3ab²-2a²b+4ab²（第二个括号前是 -2，两项都要变号）。","合并同类项：a²b+ab²。","代入 a=-2、b=3：a²b=4× 3=12，ab²=(-2)× 9=-18，故原式 =12-18=-6。"]},{"type":"p","text":"答案：化简结果为 a²b+ab²；值为 -6"},{"type":"note","title":"方法小结","text":"这类题的顺序是「由非负性求字母，再化简，最后代入」，切忌拿到数值直接代入原式硬算。去括号时 -2×(-2ab²)=+4ab² 是符号易错点。"},{"type":"list","title":"易错点","items":["去括号只变第一项的符号，后面的项漏变，如把 $a-(b+c-d)$ 写成 $a-b+c-d$。正确结果是 $a-b-c+d$。","合并同类项时把字母的指数也相加，如把 $3a^{2}+2a^{2}$ 算成 $5a^{4}$。正确结果是 $5a^{2}$。","误把 $2x^{2}y$ 与 $2xy^{2}$ 当同类项合并。判断同类项要求相同字母的指数分别相同，这两个式子的字母指数不同。","判断单项式的系数时漏掉负号或看错分数，如把 $-\\frac{3}{5}x^{2}y$ 的系数说成 $\\frac{3}{5}$（应为 $-\\frac{3}{5}$）。","把 $\\frac{2}{x}$、$\\frac{1}{x-1}$ 当作单项式或整式。它们的字母在分母上，不是整式。","求值时直接把数值代入原式硬算，不先化简，导致计算量大、错误率高。正确做法是先化简再代入求值。"]},{"type":"list","title":"解题方法","items":["化简三字诀「找、移、合」：先找同类项（可用不同的下划线标记），再连同符号一起移动位置，最后把系数相加。","去括号时用乘法分配律逐项检查：括号外因数是 m，括号内有几项，去括号后就应写出几项。","整体代入法：把已知的整式（如 a-2b）看成一个字母或整体，代入所求式并整理。","降幂排列后再合并同类项，同类项自动聚在一起，能有效防止漏项。","代入特殊值检验：化简完成后令字母取一个简单的值（如 x=1）分别计算原式与化简结果，两者相等说明化简正确。"]}],"questions":[{"id":"m-num-zhengshi-jiajian-q1","type":"choice","stem":"下列各式中是单项式的是（ ）","answer":"C","explain":"C 是数与字母的积，是单项式，系数为 -(3)/(5)，次数为 3。A 是 (1)/(2)x+(1)/(2)，是多项式。B 的分母中含字母 x，不是整式，更不是单项式。D 是两项的和，是多项式。","options":["(x+1)/(2)","(2)/(x)","-(3)/(5)x²y","x²+1"],"difficulty":1,"tags":["单项式","整式","概念辨析"]},{"id":"m-num-zhengshi-jiajian-q2","type":"choice","stem":"若 2x^(m)y³ 与 -5x²y^(n) 是同类项，则 m+n 的值为（ ）","answer":"B","explain":"同类项要求相同字母的指数相同，于是 x 的指数相等得 m=2，y 的指数相等得 n=3。所以 m+n=2+3=5，选 B。注意同类项与系数无关，2 与 -5 不参与判断。","options":["3","5","6","1"],"difficulty":1,"tags":["同类项","指数"]},{"id":"m-num-zhengshi-jiajian-q3","type":"fill","stem":"化简：5(2a-b)-3(a+2b)=（ ）。","answer":"7a-11b","explain":"先用分配律去括号：5(2a-b)=10a-5b，-3(a+2b)=-3a-6b（括号前是 -3，两项都要变号）。相加得 10a-5b-3a-6b，合并同类项：a 的项 10a-3a=7a，b 的项 -5b-6b=-11b，故结果是 7a-11b。","difficulty":1,"tags":["去括号","合并同类项"]},{"id":"m-num-zhengshi-jiajian-q4","type":"fill","stem":"已知 a²+2a=4，则 3a²+6a-5=（ ）。","answer":"7","explain":"观察 3a²+6a=3(a²+2a)，把已知条件整体代入：3a²+6a-5=3× 4-5=12-5=7。若硬解方程求 a 会得到无理数，计算量大且容易出错。","difficulty":2,"tags":["整体代入","化简求值"]},{"id":"m-num-zhengshi-jiajian-q5","type":"short","stem":"先化简，再求值：3x²y-[2xy²-2(xy-(3)/(2)x²y)+xy]+3xy²，其中 x=-1，y=2。","answer":"化简得 $xy^{2}+xy$，代入 $x=-1$、$y=2$ 得 $-4+(-2)=-6$。","explain":"第一步去小括号：2(xy-(3)/(2)x²y)=2xy-3x²y。第二步合并中括号内各项：2xy²-(2xy-3x²y)+xy=2xy²-2xy+3x²y+xy=2xy²-xy+3x²y。第三步去中括号（前有负号，各项变号）：3x²y-2xy²+xy-3x²y+3xy²=xy²+xy。第四步代入：x=-1，y=2 时 xy²=(-1)× 4=-4，xy=(-1)× 2=-2，故原式 =-4-2=-6。","difficulty":3,"tags":["整式化简","多重括号","化简求值"],"rubric":["正确去小括号得到 2xy-3x²y（符号全部正确）","正确化简中括号内为 2xy²-xy+3x²y","去中括号时各项变号，最终化简结果为 xy²+xy","代入 x=-1、y=2 算出 -6（过程完整，不是只写结果）"]},{"id":"m-num-zhengshi-jiajian-z1","type":"choice","stem":"若关于 x 的多项式 2x²+mx+nx²-3x+1 合并同类项后不含 x 的一次项，则 m 的值为（ ）","answer":"A","explain":"先合并同类项：原式 =(2+n)x²+(m-3)x+1。「不含 x 的一次项」即一次项系数为 0，故 m-3=0，解得 m=3，选 A。注意题中 n 只影响二次项，与一次项是否存在无关，不要被多余的字母干扰。","options":["3","-3","0","1"],"difficulty":2,"tags":["合并同类项","整式化简"]},{"id":"m-num-zhengshi-jiajian-z2","type":"short","stem":"在一张长为 (3a+2b)、宽为 (a+b) 的长方形纸片上，剪去一个边长为 (a+b) 的正方形。（1）用含 a、b 的整式表示剩余纸片的面积 S，并化简；（2）当 a=2、b=1 时，求 S 的值。","answer":"（1）$S=(3a+2b)(a+b)-(a+b)^{2}=2a^{2}+3ab+b^{2}$；（2）$a=2$、$b=1$ 时 $S=15$。","explain":"（1）剩余面积等于原长方形面积减去剪去的正方形面积。原面积为 (3a+2b)(a+b)=3a²+3ab+2ab+2b²=3a²+5ab+2b²，正方形面积为 (a+b)²=a²+2ab+b²，故 S=3a²+5ab+2b²-(a²+2ab+b²)=2a²+3ab+b²。（2）代入 a=2、b=1：S=2× 4+3× 2× 1+1=8+6+1=15。检验：原长方形长为 3× 2+2× 1=8、宽为 3，面积为 24；剪去的正方形边长 3、面积为 9；剩余 24-9=15，与化简后代入的结果一致。","difficulty":2,"tags":["整式化简","化简求值"],"rubric":["正确列出面积差 S=(3a+2b)(a+b)-(a+b)²","展开并化简为 2a²+3ab+b²（去括号时符号正确）","代入 a=2、b=1 算出 S=15，有检验或作答"]}]},{"id":"m-num-yiyuanyici","title":"一元一次方程","subtitle":"人教版七上 · 第5章 一元一次方程","grade":"7a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七上 · 第5章 一元一次方程"},{"type":"note","title":"一句话概述","text":"理解方程与方程的解，掌握等式性质与五步解法，能用一元一次方程解决实际问题。"},{"type":"h","text":"先看什么：天平与等式性质"},{"type":"p","text":"方程两边就像天平的两盘：只要对两边同时做同样的运算，平衡就不会被打破。等式性质 1 说两边同加（或减）同一个数（或式子）仍相等，性质 2 说两边同乘同一个数、同除以同一个不为 0 的数仍相等，这就是解方程每一步变形的依据。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-s1","title":"天平平衡与等式性质","caption":"两边做同样的运算，天平仍然平衡","view":"wide","alt":"一架保持平衡的天平，左右两盘上方分别标注 3x 减 2 与 7，上方写着等式性质，下方说明两边同加同减或同乘同除一个非零数天平仍平衡","prims":[{"t":"text","x":50,"y":12,"text":"等式性质：两边做同样的运算","size":3.6,"anchor":"middle","tone":"main"},{"t":"line","x1":20,"y1":28,"x2":80,"y2":28,"tone":"main"},{"t":"line","x1":50,"y1":28,"x2":50,"y2":40,"tone":"main"},{"t":"poly","points":[[44,46],[56,46],[50,40]],"closed":true,"tone":"main"},{"t":"line","x1":36,"y1":46,"x2":64,"y2":46,"tone":"main"},{"t":"line","x1":28,"y1":28,"x2":28,"y2":38,"tone":"muted"},{"t":"poly","points":[[22,38],[34,38],[32,44],[24,44]],"closed":true,"tone":"muted"},{"t":"line","x1":72,"y1":28,"x2":72,"y2":38,"tone":"muted"},{"t":"poly","points":[[66,38],[78,38],[76,44],[68,44]],"closed":true,"tone":"muted"},{"t":"text","x":28,"y":23,"text":"3x - 2","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":72,"y":23,"text":"7","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":56,"text":"两边同加（减）或同乘（除以非零数），天平仍平衡","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"两边同除的数必须不为 0；除以 0 没有意义，等式变形就失去了依据。"},{"type":"h","text":"抓条件：解是数轴上的一个点"},{"type":"p","text":"一元一次方程只含一个未知数，解出来是唯一的数，所以方程的解对应数轴上一个确定的点。判断某个数是不是解，就把它分别代入方程左右两边计算，两个值相等才是解。正因为它只对应一个点，一元一次方程不像一元一次不等式那样有「一段范围」。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-s2","title":"方程的解是数轴上一个点","caption":"唯一的一个点，就是方程的解","view":"wide","alt":"一条数轴标出从负二到三的整数刻度，x 等于一的位置用实心圆点标出，说明一元一次方程的解是数轴上一个确定的点","prims":[{"t":"line","x1":12,"y1":36,"x2":84,"y2":36},{"t":"arrow","x1":84,"y1":36,"x2":92,"y2":36},{"t":"line","x1":20,"y1":33,"x2":20,"y2":39},{"t":"line","x1":32,"y1":33,"x2":32,"y2":39},{"t":"line","x1":44,"y1":33,"x2":44,"y2":39},{"t":"line","x1":56,"y1":33,"x2":56,"y2":39},{"t":"line","x1":68,"y1":33,"x2":68,"y2":39},{"t":"line","x1":80,"y1":33,"x2":80,"y2":39},{"t":"text","x":20,"y":44,"text":"-2","size":3.4,"anchor":"middle"},{"t":"text","x":32,"y":44,"text":"-1","size":3.4,"anchor":"middle"},{"t":"text","x":44,"y":44,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":56,"y":44,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":68,"y":44,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":80,"y":44,"text":"3","size":3.4,"anchor":"middle"},{"t":"dot","x":56,"y":36,"tone":"accent"},{"t":"text","x":56,"y":24,"text":"方程的解 x = 1","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":56,"text":"检验：把这个点代回方程，看左右两边是否相等","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"一元一次方程有且只有一个解（除 0x=b 这类特殊情况），这是它和一元一次不等式最大的区别。"},{"type":"h","text":"建立关系：解方程的五个步骤"},{"type":"p","text":"解方程就是把方程一步步化成 x=a 的形式：先去分母，再去括号，然后移项、合并同类项，最后把系数化为 1。每一步都依据等式性质，所以顺序可以按题目灵活调整，但变形必须保证等式仍然成立，不能跳步。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-s3","title":"解一元一次方程的一般步骤","caption":"五个步骤依次进行，每一步都依据等式性质","view":"wide","alt":"一条横向流程，五个方框依次是去分母、去括号、移项、合并、系数化为 1，箭头由左向右连接，下方说明每一步都依据等式性质","prims":[{"t":"text","x":50,"y":11,"text":"解一元一次方程的一般步骤","size":3.6,"anchor":"middle","tone":"main"},{"t":"rect","x":2,"y":27,"w":16,"h":12,"tone":"main"},{"t":"rect","x":22,"y":27,"w":16,"h":12,"tone":"main"},{"t":"rect","x":42,"y":27,"w":16,"h":12,"tone":"main"},{"t":"rect","x":62,"y":27,"w":16,"h":12,"tone":"accent"},{"t":"rect","x":82,"y":27,"w":16,"h":12,"tone":"accent"},{"t":"text","x":10,"y":33,"text":"去分母","size":3.1},{"t":"text","x":30,"y":33,"text":"去括号","size":3.1},{"t":"text","x":50,"y":33,"text":"移项","size":3.1},{"t":"text","x":70,"y":33,"text":"合并","size":3.1},{"t":"text","x":90,"y":33,"text":"系数化为1","size":3},{"t":"arrow","x1":18,"y1":33,"x2":22,"y2":33,"tone":"muted"},{"t":"arrow","x1":38,"y1":33,"x2":42,"y2":33,"tone":"muted"},{"t":"arrow","x1":58,"y1":33,"x2":62,"y2":33,"tone":"muted"},{"t":"arrow","x1":78,"y1":33,"x2":82,"y2":33,"tone":"muted"},{"t":"text","x":50,"y":49,"text":"每一步都依据等式性质，保证等式仍然成立","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":57,"text":"去分母时不含分母的项也要乘，分子要加括号","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"去分母时不含分母的项（常数项）也必须乘公分母，分子是多项式的一定要加括号。"},{"type":"h","text":"换个情境：实际问题怎么变成方程"},{"type":"p","text":"实际问题没有现成的方程，要先把文字翻译成数学：设未知数把所求量记作 x，再抓住「共」「是……的几倍」「比……多」这些关键词，或者画线段图找出等量关系，列出方程后求解，最后把解代回原情境检验并作答。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-s4","title":"列方程解应用题的四步","caption":"从设未知数到检验作答，缺一不可","view":"wide","alt":"一条横向流程，四个方框依次是设未知数、列方程、解方程、检验作答，箭头由左向右连接，下方说明关键是找等量关系、解完必须检验并作答","prims":[{"t":"text","x":50,"y":11,"text":"列方程解应用题的四步","size":3.6,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":28,"w":18,"h":12,"tone":"main"},{"t":"rect","x":30,"y":28,"w":18,"h":12,"tone":"accent"},{"t":"rect","x":52,"y":28,"w":18,"h":12,"tone":"main"},{"t":"rect","x":74,"y":28,"w":18,"h":12,"tone":"ok"},{"t":"text","x":17,"y":34,"text":"设未知数","size":3.2},{"t":"text","x":39,"y":34,"text":"列方程","size":3.2},{"t":"text","x":61,"y":34,"text":"解方程","size":3.2},{"t":"text","x":83,"y":34,"text":"检验作答","size":3.2},{"t":"arrow","x1":26,"y1":34,"x2":30,"y2":34,"tone":"muted"},{"t":"arrow","x1":48,"y1":34,"x2":52,"y2":34,"tone":"muted"},{"t":"arrow","x1":70,"y1":34,"x2":74,"y2":34,"tone":"muted"},{"t":"text","x":50,"y":50,"text":"关键是找等量关系：关键词法、图示法、公式法","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":57,"text":"解完必须检验，并写单位与「答」","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"设未知数时要写清它的含义；解出后还要判断是否符合实际意义，如人数、个数不能为负或取分数。"},{"type":"h","text":"核心概念"},{"type":"p","text":"方程与一元一次方程：含有未知数的等式叫方程。只含有一个未知数，未知数的次数都是 1，且等号两边都是整式的方程叫一元一次方程，一般形式是 ax+b=0（a≠ 0）。"},{"type":"p","text":"方程的解：使方程左右两边相等的未知数的值叫方程的解。检验一个数是不是解，就是把它代入方程左右两边分别计算，看两个值是否相等。"},{"type":"p","text":"等式的性质：性质 1：等式两边加（或减）同一个数（或式子），结果仍相等。性质 2：等式两边乘同一个数，或除以同一个不为 0 的数，结果仍相等。这是解方程每一步变形的依据。"},{"type":"p","text":"移项：把方程一边的某项改变符号后移到另一边叫移项，依据是等式的性质 1。关键点：移项必须变号，不移的项不变号；通常把含未知数的项移到左边，常数项移到右边。"},{"type":"p","text":"解一元一次方程的一般步骤：去分母、去括号、移项、合并同类项、系数化为 1。五个步骤顺序可灵活调整，但每一步都要保证等式仍然成立。"},{"type":"p","text":"列方程解应用题：步骤为审题、设未知数、找等量关系列方程、解方程、检验、作答。核心是找等量关系，常用方法有列表法、画线段图法和抓住公式法（如路程、工程、利润公式）。"},{"type":"note","title":"中考考法","text":"一元一次方程的解法与方程的解\n填空题给解反求参数，解答题考去分母的完整步骤，踩分点是常数项也要乘公分母、分子是多项式要加括号，解出后代回检验。"},{"type":"note","title":"中考考法","text":"列一元一次方程解行程、工程与销售问题\n广州中考应用题高频模型，常考追及相遇、合作完工、打折利润，踩分点是设未知数写清含义，用 s=vt、工作量为 1 或利润率以进价为分母列式。"},{"type":"note","title":"中考考法","text":"方案选择与分段计费中的方程建模\n以购物优惠、出租车计费为情境比较两种方案，踩分点是先写清各段费用表达式，令两种费用相等求临界值，再结合题意选择方案。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["等式性质 1","a=b\\ ⇒\\ a± c=b± c","两边加或减的必须是同一个数或同一个式子，这是移项的依据。"],["等式性质 2","a=b\\ ⇒\\ ac=bc, (a)/(c)=(b)/(c)\\ (c≠ 0)","除数 c 不能为 0；解方程时要对两边同时乘除同一个数，不能只乘一项。"],["去分母（化为整数系数）","(x)/(a)=b\\ ⇒\\ x=ab\\ (a≠ 0)","去分母时方程两边都要乘各分母的最小公倍数，不含分母的项也必须乘。"],["行程问题关系式","s=vt","相遇问题中两者路程之和等于总路程，追及问题中两者路程之差等于初始距离。"],["销售问题关系式","其中 p 为售价、q 为进价、c 为利润、eta 为利润率，即利润 = 售价 - 进价。","打折销售中「售价 = 标价 × 折扣」，八折即乘 0.8；利润率的分母是进价而不是售价。"]]},{"type":"note","title":"例题","text":"解方程：(2x-1)/(3)-(10x+1)/(6)=(2x+1)/(4)-1。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-e1","title":"去分母：两边同乘公分母 12","caption":"常数项也要乘，分子要加括号","view":"wide","alt":"图上方标出去分母时两边同乘公分母 12，左侧方框提示分子要加括号，右侧方框提示常数项也要乘，下方写出化简后的方程","prims":[{"t":"text","x":50,"y":10,"text":"去分母：两边同乘公分母 12","size":3.6,"anchor":"middle","tone":"main"},{"t":"rect","x":4,"y":20,"w":32,"h":12,"tone":"main","label":"分子要加括号"},{"t":"rect","x":64,"y":20,"w":32,"h":12,"tone":"danger","label":"常数项也要乘"},{"t":"text","x":20,"y":40,"text":"(2x-1) × 4","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":80,"y":40,"text":"-1 × 12","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":54,"text":"得 4(2x-1) - 2(10x+1) = 3(2x+1) - 12","size":3.4,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["去分母：各分母 3、6、4 的最小公倍数是 12，两边同乘 12，注意 -1 也要乘，且分子要加括号。","得 4(2x-1)-2(10x+1)=3(2x+1)-12。","去括号：8x-4-20x-2=6x+3-12，即 -12x-6=6x-9。","移项：-12x-6x=-9+6，得 -18x=-3。","系数化为 1：两边同除以 -18，得 x=(-3)/(-18)=(1)/(6)。","检验：把 x=(1)/(6) 代入，左边 =(1)/(3)-13-(5)/(3)+16=-(2)/(3)，右边 =(4)/(3)4-1=-(2)/(3)，左右相等，故解正确。"]},{"type":"p","text":"答案：x=(1)/(6)"},{"type":"note","title":"方法小结","text":"去分母是本题两处易错的集中点：常数项 -1 必须乘 12 变成 -12；分子 10x+1 前是负号，去分母后要写成 -2(10x+1) 并整体变号。解完务必代入检验。"},{"type":"note","title":"例题","text":"某商品的进价是 200 元，按标价的八折销售，仍可获得 20% 的利润，求该商品的标价。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-e2","title":"销售问题：利润与利润率","caption":"利润率的分母是进价","view":"wide","alt":"上方写利润等于售价减进价、利润率等于利润除以进价，中间两个方框分别写进价 200 与售价 0.8x，下方列出方程 0.8x 减 200 等于 40","prims":[{"t":"text","x":50,"y":10,"text":"利润 = 售价 - 进价，利润率 = 利润 ÷ 进价","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":12,"y":22,"w":30,"h":13,"tone":"muted","label":"进价 200"},{"t":"rect","x":58,"y":22,"w":30,"h":13,"tone":"accent","label":"售价 0.8x"},{"t":"text","x":50,"y":48,"text":"0.8x - 200 = 200 × 20% = 40","size":3.6,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":58,"text":"利润率的分母是进价，不是售价","size":3.3,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["设标价为 x 元，则实际售价为 0.8x 元。","利润为售价减进价，即 0.8x-200。","题中「获得 20% 的利润」表示利润是进价的 20%，即 0.8x-200=200× 20\\%。","计算右边：200× 20\\%=40，方程变为 0.8x-200=40。","移项得 0.8x=240，系数化为 1 得 x=300。","答：标价是 300 元。（检验：售价 =300× 0.8=240 元，利润 =240-200=40 元，正好是进价的 20%。）"]},{"type":"p","text":"答案：标价为 300 元"},{"type":"note","title":"方法小结","text":"利润率的分母是进价而不是售价，这是销售问题最常错的地方。列方程前先写清「利润 = 售价 - 进价」，再按给定百分率补齐另一边。"},{"type":"note","title":"例题","text":"今年父亲的年龄是儿子年龄的 4 倍，5 年后父亲的年龄是儿子年龄的 3 倍，求儿子今年的年龄。"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-e3","title":"年龄问题：今年与 5 年后对照","caption":"两人年龄同时增加相同的年数","view":"wide","alt":"一个两行两列的表格，列出儿子与父亲今年和五年后的年龄分别为 x、4x 与 x 加 5、4x 加 5，下方写出方程 4x 加 5 等于 3 乘括号 x 加 5","prims":[{"t":"line","x1":12,"y1":18,"x2":84,"y2":18,"tone":"muted"},{"t":"line","x1":12,"y1":28,"x2":84,"y2":28,"tone":"muted"},{"t":"line","x1":12,"y1":38,"x2":84,"y2":38,"tone":"muted"},{"t":"line","x1":12,"y1":48,"x2":84,"y2":48,"tone":"muted"},{"t":"line","x1":12,"y1":18,"x2":12,"y2":48,"tone":"muted"},{"t":"line","x1":32,"y1":18,"x2":32,"y2":48,"tone":"muted"},{"t":"line","x1":58,"y1":18,"x2":58,"y2":48,"tone":"muted"},{"t":"line","x1":84,"y1":18,"x2":84,"y2":48,"tone":"muted"},{"t":"text","x":45,"y":23,"text":"儿子","size":3.4,"tone":"main"},{"t":"text","x":71,"y":23,"text":"父亲","size":3.4,"tone":"main"},{"t":"text","x":22,"y":33,"text":"今年","size":3.2,"tone":"muted"},{"t":"text","x":45,"y":33,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":71,"y":33,"text":"4x","size":3.4,"tone":"muted"},{"t":"text","x":22,"y":43,"text":"5 年后","size":3.2,"tone":"muted"},{"t":"text","x":45,"y":43,"text":"x + 5","size":3.4,"tone":"accent"},{"t":"text","x":71,"y":43,"text":"4x + 5","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":57,"text":"5 年后父亲年龄是儿子的 3 倍：4x + 5 = 3(x + 5)","size":3.3,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["设儿子今年 x 岁，则父亲今年 4x 岁。","5 年后儿子的年龄是 x+5 岁，父亲的年龄是 4x+5 岁。","由「5 年后父亲年龄是儿子的 3 倍」列方程：4x+5=3(x+5)。","去括号得 4x+5=3x+15。","移项、合并同类项得 x=10。","答：儿子今年 10 岁。（检验：5 年后儿子 15 岁、父亲 45 岁，45=3× 15，符合题意。）"]},{"type":"p","text":"答案：儿子今年 10 岁（父亲 40 岁）"},{"type":"note","title":"方法小结","text":"年龄问题的关键是「两人年龄同时增加相同的年数」。列式时把所有量都写成同一个时间点（5 年后）的表达式，不要混用今年的量和 5 年后的量。"},{"type":"note","title":"例题","text":"一项工程，甲队单独做需要 20 天完成，乙队单独做需要 30 天完成。先由甲队单独做 5 天后，余下的工程由甲、乙两队合作完成。还需要合作多少天才能完成全部工程？"},{"type":"figure","figure":{"id":"fig-m-num-yiyuanyici-gongcheng-1","title":"工程问题：把总工作量看作 1","caption":"甲先做 5 天完成 1/4，余下 3/4 由甲乙合作完成","view":"wide","alt":"一条代表总工作量 1 的长条，前四分之一标为甲单独做 5 天完成，其余四分之三标为甲乙合作完成，下方标注甲每天 1/20、乙每天 1/30、合作每天 1/12","prims":[{"t":"rect","x":10,"y":32,"w":80,"h":16,"tone":"muted"},{"t":"rect","x":10,"y":32,"w":20,"h":16,"tone":"accent","fill":true},{"t":"text","x":20,"y":43,"text":"甲独做 5 天","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":60,"y":43,"text":"甲乙合作","size":3.4,"anchor":"middle"},{"t":"line","x1":10,"y1":54,"x2":90,"y2":54,"tone":"muted"},{"t":"line","x1":10,"y1":52,"x2":10,"y2":56,"tone":"muted"},{"t":"line","x1":30,"y1":52,"x2":30,"y2":56,"tone":"muted"},{"t":"line","x1":90,"y1":52,"x2":90,"y2":56,"tone":"muted"},{"t":"text","x":10,"y":62,"text":"0","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":30,"y":62,"text":"1/4","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":90,"y":62,"text":"1","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":74,"text":"甲每天 1/20，乙每天 1/30，合作每天 1/12","size":3.5,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["工程问题把总工作量看作 1，想到先求两队的日工作量：甲每天完成 (1)/(20)，乙每天完成 (1)/(30)。","甲先做 5 天完成 (5)/(20)=(1)/(4)，余下工作量为 1-(1)/(4)=(3)/(4)。","设还需要合作 x 天，两队每天共完成 (1)/(20)+(1)/(30)=(3+2)/(60)=(1)/(12)，列方程 (1)/(12)x=(3)/(4)。","解得 x=(3)/(4)× 12=9（天）。"]},{"type":"p","text":"答案：还需要合作 9 天"},{"type":"note","title":"方法小结","text":"合作类工程题的等量关系是「各部分工作量之和等于 1」。也可以直接列 (5)/(20)+((1)/(20)+(1)/(30))x=1，关键是不同阶段的工作效率不要用错。"},{"type":"note","title":"例题","text":"一种笔记本在甲、乙两家文具店标价相同，均为每本 10 元。甲店一律按标价的九折销售；乙店规定购买不超过 20 本按标价销售，超过 20 本的部分按八折销售。某班要购买若干本（超过 20 本），问购买多少本时，两家店的费用相同？"},{"type":"figure","figure":{"id":"fig-num-yiyuanyici-e5","title":"两家店费用都写成一次式","caption":"令两式相等求临界本数","view":"wide","alt":"两个方框分别写出甲店费用 9x 与乙店费用 8x 加 40，下方令两式相等解得 x 等于 40，并注明 40 大于 20 落在乙店八折计费段内","prims":[{"t":"text","x":50,"y":12,"text":"两家店费用都写成关于 x 的一次式","size":3.5,"anchor":"middle","tone":"main"},{"t":"rect","x":10,"y":24,"w":36,"h":14,"tone":"accent"},{"t":"text","x":28,"y":31,"text":"甲店","size":3.4,"tone":"accent"},{"t":"text","x":28,"y":37,"text":"9x","size":3.4,"tone":"accent"},{"t":"rect","x":54,"y":24,"w":36,"h":14,"tone":"main"},{"t":"text","x":72,"y":31,"text":"乙店","size":3.4,"tone":"main"},{"t":"text","x":72,"y":37,"text":"8x + 40","size":3.4,"tone":"main"},{"t":"text","x":50,"y":50,"text":"令 9x = 8x + 40，得 x = 40","size":3.8,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":59,"text":"40 > 20，落在乙店八折的计费段内","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设购买 x 本（x>20）。甲店全部九折，费用为 10× 0.9x=9x。","乙店前 20 本按原价、超过部分八折，费用为 10× 20+10× 0.8(x-20)=200+8(x-20)=8x+40。","费用相同时列方程 9x=8x+40。","移项得 x=40，且 40>20，符合分段条件。"]},{"type":"p","text":"答案：购买 40 本时两家店费用相同"},{"type":"note","title":"方法小结","text":"方案比较题先把两种费用都写成关于 x 的一次式，再令其相等求临界点。求出后要核对结果是否落在所用计费段的取值范围内，本题 40>20 才说明八折表达式有效。"},{"type":"list","title":"易错点","items":["去分母时漏乘不含分母的项，如把 $\\frac{x}{2}=3$ 两边乘 2 后写成 $x=3$。常数项必须同时乘。","去分母时分子是多项式却不加括号，如把 $\\frac{2x-1}{3}$ 去分母写成 $2x-1\\times 3$。正确做法是加括号：$2x-1$ 整体乘公分母后写成 $2\\times(2x-1)$ 的形式。","移项忘记变号，如由 $3x=5-2x$ 变形时写成 $3x-2x=5$，把左边移到右边的 $-2x$ 没有变成 $+2x$。正确结果是 $3x+2x=5$。","系数化为 1 时忽略系数的符号，如由 $-2x=6$ 得 $x=3$。正确结果是 $x=-3$。","把「利润的 20%」当成售价的 20%。利润率的分母是进价。","解出结果后不检验、不写单位、不写「答」。实际问题中还要判断解是否符合实际意义（如人数不能为负数）。"]},{"type":"list","title":"解题方法","items":["五步法解方程：去分母、去括号、移项、合并同类项、系数化为 1，每一步写清依据，减少跳步出错。","遇到小数的系数先用分数基本性质把分母化为整数（分子分母同乘 10 的幂），再按常规步骤解。","找等量关系三招：关键词法（「共」「是……的几倍」「比……多」）、图示法（画线段图或表格）、公式法（路程、工程、利润公式）。","设未知数有技巧：设较小的量、设「一倍量」为 x，或设问题所问的量，能使方程尽量简单。","解完必须检验：把解代回原方程左右两边分别算，或代回实际问题情境中核对是否符合题意。"]}],"questions":[{"id":"m-num-yiyuanyici-q1","type":"choice","stem":"下列方程中是一元一次方程的是（ ）","answer":"C","explain":"一元一次方程要求只含一个未知数、未知数的次数是 1，且两边都是整式。A 中未知数次数为 2；B 中未知数在分母上，不是整式方程；D 含有两个未知数 x、y；只有 C 符合，故选 C。","options":["x²+1=0","(1)/(x)=2","2x-3=5","x+y=3"],"difficulty":1,"tags":["一元一次方程","概念辨析"]},{"id":"m-num-yiyuanyici-q2","type":"choice","stem":"方程 3(x-1)=2x+4 的解是（ ）","answer":"B","explain":"去括号得 3x-3=2x+4；移项得 3x-2x=4+3；合并同类项得 x=7。检验：左边 =3×(7-1)=18，右边 =2× 7+4=18，左右相等，故选 B。","options":["x=1","x=7","x=-7","x=5"],"difficulty":1,"tags":["解方程","去括号"]},{"id":"m-num-yiyuanyici-q3","type":"fill","stem":"若 x=-2 是方程 3x+a=1 的解，则 a=（ ）。","answer":"7","explain":"把 x=-2 代入方程得 3×(-2)+a=1，即 -6+a=1。移项得 a=1+6=7。所谓「是方程的解」就是代入后等式成立，这是解含字母参数方程的基本套路。","difficulty":1,"tags":["方程的解","代入"]},{"id":"m-num-yiyuanyici-q4","type":"fill","stem":"一个数的一半与 3 的和，等于这个数的 (1)/(3) 与 8 的和，则这个数是（ ）。","answer":"30","explain":"设这个数为 x，则由题意得 (1)/(2)x+3=(1)/(3)x+8。去分母（两边同乘 6）：3x+18=2x+48。移项得 3x-2x=48-18，即 x=30。检验：(1)/(2)× 30+3=18，(1)/(3)× 30+8=18，相等，故答案是 30。","difficulty":2,"tags":["列方程","去分母"]},{"id":"m-num-yiyuanyici-q5","type":"short","stem":"甲、乙两地相距 240 千米。一辆汽车从甲地开往乙地，速度是 60 千米/时；行驶 1 小时后，另一辆汽车从乙地开往甲地，速度是 80 千米/时。问第二辆汽车出发几小时后两车相遇？（要求设未知数、列方程、完整求解并作答）","answer":"设第二辆汽车出发 $x$ 小时后两车相遇，列方程 $60(x+1)+80x=240$，解得 $x=\\frac{9}{7}$，即第二辆汽车出发 $\\frac{9}{7}$ 小时后两车相遇。","explain":"第一辆车先行驶 1 小时，路程为 60× 1=60 千米，余下路程为 240-60=180 千米。设第二辆汽车出发 x 小时后两车相遇，则第一辆车在这段时间又行驶 60x 千米，第二辆车行驶 80x 千米，两车路程之和为 180 千米，列方程 60x+80x=180，也可直接写成 60(x+1)+80x=240。解方程：140x=180，x=(9)/(7)。检验：60×(1+(9)/(7))+80×(9)/(7)=60×(16)/(7)+(720)/(7)=(960+720)/(7)=240，符合题意。","difficulty":3,"tags":["行程问题","相遇","列方程解应用题"],"rubric":["正确设未知数并说明其含义（如「设第二辆汽车出发 x 小时后两车相遇」）","找出等量关系：两车路程之和等于 240 千米（或余下 180 千米）","列出方程 60(x+1)+80x=240（写成 60x+80x=180 同样给分）","正确解得 x=(9)/(7)（写成 1(2)/(7) 或约 1.29 小时亦给分）","有检验或作答语句，答案带单位「小时」"]},{"id":"m-num-yiyuanyici-z1","type":"choice","stem":"解方程 (x-1)/(2)-(2x+3)/(3)=1，得（ ）","answer":"D","explain":"两边同乘分母的最小公倍数 6，注意两个分子都要加括号、常数项 1 也要乘：3(x-1)-2(2x+3)=6。去括号得 3x-3-4x-6=6，合并得 -x-9=6，即 -x=15，所以 x=-15，选 D。检验：左边 =(-16)/(2)-(-27)/(3)=-8-(-9)=1，与右边相等。","options":["x=15","x=3","x=-3","x=-15"],"difficulty":2,"tags":["解方程","去分母"]},{"id":"m-num-yiyuanyici-z2","type":"short","stem":"弟弟以每分钟 80 米的速度从家步行去学校，5 分钟后哥哥发现弟弟忘带文具盒，立即骑自行车以每分钟 180 米的速度沿同一路线去追。哥哥出发多少分钟后追上弟弟？追上时离家多少米？（要求设未知数、列方程、完整求解并作答）","answer":"设哥哥出发 $x$ 分钟后追上弟弟，列方程 $180x=80(x+5)$，解得 $x=4$，追上时离家 $180\\times 4=720$ 米。","explain":"设哥哥出发 x 分钟后追上弟弟。此时哥哥骑车行驶了 180x 米；弟弟比哥哥早出发 5 分钟，一共走了 (x+5) 分钟，路程为 80(x+5) 米。追上时两人路程相等，列方程 180x=80(x+5)。去括号得 180x=80x+400，移项、合并得 100x=400，解得 x=4。追上时离家 180× 4=720（米）。检验：弟弟走了 4+5=9 分钟，路程为 80× 9=720 米，与哥哥相同，追上关系成立。","difficulty":3,"tags":["行程问题","列方程解应用题"],"rubric":["正确设未知数，并写出哥哥路程 180x 与弟弟路程 80(x+5)","由「追上时路程相等」列出方程 180x=80(x+5) 并解出 x=4","算出追上时离家 720 米，有检验或作答且带单位"]}]},{"id":"m-num-shishu","title":"实数","subtitle":"人教版七下 · 第8章 实数","grade":"7b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七下 · 第8章 实数"},{"type":"note","title":"一句话概述","text":"掌握平方根、立方根与无理数概念，理解实数与数轴一一对应，会化简与估算。"},{"type":"h","text":"先看什么：边长 1 的正方形对角线"},{"type":"p","text":"边长 1 的正方形，对角线长是多少？由勾股定理得它的平方是 1²+1²=2，所以对角线长是 √(2)，约等于 1.414。把这个长度用圆规「转」到数轴上，就得到了一个不是有理数的点——这说明数轴上除了有理数，还存在开不尽方的数。"},{"type":"figure","figure":{"id":"fig-num-shishu-s1","title":"用正方形对角线在数轴上作出 √2","caption":"对角线长 √2，转到数轴上即得它的位置","view":"wide","alt":"一条数轴标出 0、1、2、3，在 0 与 1 上方画一个边长为 1 的正方形，它的对角线长标注为根号 2，把对角线转到数轴上的点标为根号 2 约等于 1.414","prims":[{"t":"text","x":50,"y":9,"text":"边长 1 的正方形，对角线长 √2","size":3.5,"anchor":"middle","tone":"main"},{"t":"poly","points":[[20,44],[42,44],[42,22],[20,22]],"closed":true,"tone":"main"},{"t":"line","x1":20,"y1":44,"x2":42,"y2":22,"tone":"accent"},{"t":"angle","x":42,"y":44,"from":90,"to":180,"right":true,"tone":"muted"},{"t":"text","x":31,"y":40,"text":"1","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":17,"y":33,"text":"1","size":3.2,"anchor":"end","tone":"muted"},{"t":"text","x":36,"y":30,"text":"√2","size":3.4,"anchor":"start","tone":"accent"},{"t":"line","x1":10,"y1":44,"x2":88,"y2":44},{"t":"arrow","x1":88,"y1":44,"x2":94,"y2":44},{"t":"line","x1":20,"y1":41,"x2":20,"y2":47},{"t":"line","x1":42,"y1":41,"x2":42,"y2":47},{"t":"line","x1":64,"y1":41,"x2":64,"y2":47},{"t":"line","x1":86,"y1":41,"x2":86,"y2":47},{"t":"text","x":20,"y":51,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":42,"y":51,"text":"1","size":3.2,"anchor":"middle"},{"t":"text","x":64,"y":51,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":86,"y":51,"text":"3","size":3.2,"anchor":"middle"},{"t":"arc","cx":20,"cy":44,"r":31.1,"from":45,"to":0,"dashed":true,"tone":"accent"},{"t":"dot","x":51,"y":44,"tone":"accent"},{"t":"text","x":51,"y":38,"text":"√2 ≈ 1.414","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":59,"text":"把对角线转到数轴上，就得到 √2 的位置","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"√2 是开不尽方的数，它不能写成分数，却能在数轴上精确地找到一个点，这就是无理数的来源。"},{"type":"h","text":"抓条件：平方根与立方根的区别"},{"type":"p","text":"平方根回答的是「哪个数的平方等于 a」：把正方形面积 a 开平方就得到边长 √(a)。立方根回答的是「哪个数的立方等于 a」：把正方体体积 a 开立方就得到棱长 (a)^(1/3)。边长不能为负，所以正数的平方根要取正的那一个；而棱长可以取负，所以任何数都有立方根。"},{"type":"figure","figure":{"id":"fig-num-shishu-s2","title":"平方根求边长，立方根求棱长","caption":"一个对应正方形，一个对应正方体","view":"wide","alt":"左侧是一个正方形，标注面积为 a、边长为根号 a；右侧是一个正方体，标注体积为 a、棱长为 a 的立方根，下方说明正数有两个平方根而立方根只有一个","prims":[{"t":"text","x":50,"y":8,"text":"平方根求边长，立方根求棱长","size":3.5,"anchor":"middle","tone":"main"},{"t":"rect","x":10,"y":16,"w":24,"h":24,"tone":"main","fill":true},{"t":"text","x":22,"y":25,"text":"面积 a","size":3.1,"anchor":"middle","tone":"muted"},{"t":"text","x":22,"y":33,"text":"正方形","size":3.1,"anchor":"middle","tone":"muted"},{"t":"text","x":22,"y":48,"text":"边长 √a","size":3.4,"anchor":"middle","tone":"accent"},{"t":"solid","x":70,"y":45,"kind":"cube","w":22,"h":22,"d":8,"tone":"main"},{"t":"text","x":70,"y":31,"text":"体积 a","size":3.1,"anchor":"middle","tone":"muted"},{"t":"text","x":70,"y":39,"text":"正方体","size":3.1,"anchor":"middle","tone":"muted"},{"t":"text","x":70,"y":54,"text":"棱长 ∛a","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":61,"text":"正数有两个平方根（正负各一），而立方根只有一个","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"负数没有平方根，却有立方根；(-8)^(1/3)=-2，而 √(-8) 无意义。"},{"type":"h","text":"建立关系：用夹逼法估计 √2"},{"type":"p","text":"要估计 √(2) 的大小，就找两个平方数把它「夹」在中间：1²=1<2<4=2²，所以 1<√(2)<2；再把范围缩到十分位，1.4²=1.96<2<2.25=1.5²，于是 1.4<√(2)<1.5。每比较一次平方，就把范围缩小一档，这就是估算无理数的通用方法。"},{"type":"figure","figure":{"id":"fig-num-shishu-s3","title":"用夹逼法估计 √2","caption":"1.4² = 1.96 < 2 < 2.25 = 1.5²","view":"wide","alt":"一条数轴标出 1、1.4、1.5、2，1.4 与 1.5 之间的一段被加粗，根号 2 约等于 1.414 的点落在加粗段内，下方写出 1.4 的平方小于 2 小于 1.5 的平方","prims":[{"t":"text","x":50,"y":10,"text":"用夹逼法估计 √2 在哪两个数之间","size":3.5,"anchor":"middle","tone":"main"},{"t":"line","x1":12,"y1":40,"x2":84,"y2":40},{"t":"arrow","x1":84,"y1":40,"x2":92,"y2":40},{"t":"line","x1":20,"y1":37,"x2":20,"y2":43},{"t":"line","x1":40,"y1":37,"x2":40,"y2":43},{"t":"line","x1":50,"y1":37,"x2":50,"y2":43},{"t":"line","x1":80,"y1":37,"x2":80,"y2":43},{"t":"text","x":20,"y":49,"text":"1","size":3.3,"anchor":"middle"},{"t":"text","x":40,"y":49,"text":"1.4","size":3.3,"anchor":"middle"},{"t":"text","x":50,"y":49,"text":"1.5","size":3.3,"anchor":"middle"},{"t":"text","x":80,"y":49,"text":"2","size":3.3,"anchor":"middle"},{"t":"line","x1":40,"y1":40,"x2":50,"y2":40,"width":4,"tone":"ok"},{"t":"dot","x":43.5,"y":40,"tone":"accent"},{"t":"text","x":43.5,"y":32,"text":"√2 ≈ 1.414","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":59,"text":"1.4² = 1.96 < 2 < 2.25 = 1.5²","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"估算要一步步缩小范围：先定整数位，再定十分位、百分位，每次都用平方去比较。"},{"type":"h","text":"换个情境：实数怎么分类"},{"type":"p","text":"把所有数放在一起看，可以按「能否写成两个整数之比」分成两类：能写成分数形式的是有理数，包括整数和分数；不能写成的是无理数，如 π、√(2)、0.1010010001…。这两类合在一起就是实数，它们与数轴上的点一一对应。"},{"type":"figure","figure":{"id":"fig-num-shishu-s4","title":"实数的分类","caption":"有理数与无理数合起来就是实数","view":"wide","alt":"一个分类树，最上方是实数，向下分成有理数与无理数两支，有理数再分成整数与分数，无理数一支举出圆周率和根号 2、零点一零一零零一零零零一这类例子","prims":[{"t":"text","x":50,"y":8,"text":"实数","size":3.6,"anchor":"middle","tone":"main"},{"t":"line","x1":50,"y1":12,"x2":50,"y2":18,"tone":"main"},{"t":"line","x1":26,"y1":18,"x2":74,"y2":18,"tone":"main"},{"t":"line","x1":26,"y1":18,"x2":26,"y2":26,"tone":"main"},{"t":"line","x1":74,"y1":18,"x2":74,"y2":26,"tone":"main"},{"t":"text","x":26,"y":30,"text":"有理数","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":74,"y":30,"text":"无理数","size":3.4,"anchor":"middle","tone":"danger"},{"t":"line","x1":26,"y1":34,"x2":26,"y2":40,"tone":"main"},{"t":"line","x1":14,"y1":40,"x2":38,"y2":40,"tone":"main"},{"t":"line","x1":14,"y1":40,"x2":14,"y2":46,"tone":"main"},{"t":"line","x1":38,"y1":40,"x2":38,"y2":46,"tone":"main"},{"t":"text","x":14,"y":50,"text":"整数","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":38,"y":50,"text":"分数","size":3.2,"anchor":"middle","tone":"main"},{"t":"line","x1":74,"y1":34,"x2":74,"y2":40,"tone":"danger"},{"t":"text","x":74,"y":44,"text":"π、√2","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":74,"y":51,"text":"0.1010010001…","size":2.9,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":59,"text":"有理数能写成两个整数之比，无理数是无限不循环小数","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"带根号的数不一定是无理数，如 √(9)=3 就是有理数；判断的关键是看它能否写成分数。"},{"type":"h","text":"核心概念"},{"type":"p","text":"平方根：如果一个数的平方等于 a（a≥ 0），这个数就叫 a 的平方根（也叫二次方根），记作 ±√(a)。关键点：正数有两个互为相反数的平方根，0 的平方根是 0，负数没有平方根。"},{"type":"p","text":"算术平方根：正数 a 的正的平方根叫 a 的算术平方根，记作 √(a)，规定 √(0)=0。关键点：√(a) 本身非负，√(9)=3 而不能写成 ± 3。"},{"type":"p","text":"立方根：如果一个数的立方等于 a，这个数就叫 a 的立方根，记作 (a)^(1/3)。关键点：任何数都有且只有一个立方根，正数的立方根是正数，负数的立方根是负数，0 的立方根是 0。"},{"type":"p","text":"无理数：无限不循环小数叫无理数，如 π、√(2)、0.1010010001…。关键点：带根号的数不一定是无理数，√(4)=2 是有理数；(22)/(7) 是分数，也是有理数。"},{"type":"p","text":"实数：有理数和无理数统称实数。实数与数轴上的点一一对应：每一个实数都能用数轴上的一个点表示，反之数轴上的每一个点都表示一个实数。"},{"type":"p","text":"实数的性质与运算：在实数范围内，相反数、倒数、绝对值的意义与有理数中一致；有理数的运算法则和运算律在实数范围内同样适用。去绝对值时要先判断被减数与减数的大小关系。"},{"type":"p","text":"实数的估算与比较大小：用夹逼法可估计无理数的大小：由 3²=9<13<16=4² 得 3<√(13)<4。比较两个正数的大小可以比较它们的平方，比较两个负数则要反向判断。"},{"type":"note","title":"中考考法","text":"平方根、算术平方根、立方根与无理数的辨析\n选择题给一组数判断无理数个数，或求「某数平方根的平方根」，踩分点是先算出根号的值再开方，负数没有平方根、√(a) 只取正根。"},{"type":"note","title":"中考考法","text":"实数的混合运算、化简与大小估计\n解答题常把平方根、立方根、绝对值、乘方混合，并用夹逼法估计范围，踩分点是去绝对值先比较大小，结果中算术平方根取非负值。"},{"type":"note","title":"中考考法","text":"算术平方根、绝对值与平方的非负性综合\n几个非负数之和为 0 的条件求值题，常与乘方、代数式求值综合，踩分点是识别各部分均非负、令其分别为 0，再代入所求式。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["平方根的定义","x²=a\\ (a≥ 0)\\ ⇒\\ x=±√(a)","被开方数必须非负；√(a) 与 -√(a) 互为相反数，正数有两个平方根。"],["算术平方根与平方的关系","√(a)≥ 0, (√(a))²=a\\ (a≥ 0), a²=|a|","a²=|a| 而不是 a，如 (-5)²=5；注意 (√(a))² 与 a² 的区别。"],["立方根的性质","(-a)^(1/3)=-(a)^(1/3)","负数有立方根但没有平方根；如 (-8)^(1/3)=-2，而 √(-8) 无意义。"],["二次根式的乘法与除法","√(a)·√(b)=√(ab)\\ (a≥ 0,\\ b≥ 0), √(a)√(b)=√((a)/(b))\\ (a≥ 0,\\ b>0)","被开方数为负时不成立；除法中除数 b≠ 0，故 b>0。"],["实数的绝对值","|a|=cases a & (a≥ 0) \\\\ -a & (a<0) endcases","化简形如 |√(2)-2| 的式子，要先比较 √(2) 与 2 的大小，再决定去绝对值后的符号。"]]},{"type":"note","title":"例题","text":"求 √(81) 的平方根。"},{"type":"figure","figure":{"id":"fig-num-shishu-e1","title":"两层说法：先算根号，再求平方根","caption":"81 开平方得 9，再对 9 求平方根","view":"wide","alt":"流程图，81 经过开平方得到 9，再对 9 求平方根得到正负 3，说明遇到根号的平方根要先算出根号的值再开方","prims":[{"t":"text","x":50,"y":10,"text":"先算 √81 的值，再求这个值的平方根","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":6,"y":26,"w":18,"h":14,"tone":"main"},{"t":"text","x":15,"y":33,"text":"81","size":3.8,"anchor":"middle","tone":"main"},{"t":"arrow","x1":24,"y1":33,"x2":34,"y2":33,"tone":"muted"},{"t":"text","x":29,"y":24,"text":"开平方","size":2.8,"anchor":"middle","tone":"muted"},{"t":"rect","x":34,"y":26,"w":24,"h":14,"tone":"accent"},{"t":"text","x":46,"y":33,"text":"√81 = 9","size":3.3,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":58,"y1":33,"x2":68,"y2":33,"tone":"muted"},{"t":"text","x":63,"y":24,"text":"再求平方根","size":2.8,"anchor":"middle","tone":"muted"},{"t":"rect","x":68,"y":26,"w":26,"h":14,"tone":"ok"},{"t":"text","x":81,"y":33,"text":"±3","size":3.8,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":52,"text":"81 的平方根是 ±9，算术平方根是 9，√81 的平方根是 ±3","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先算 √(81) 的值：因为 9²=81，所以 √(81)=9。","题目问的是「9 的平方根」而不是「81 的平方根」，这一步是本题的转折点。","由平方根定义，x²=9 的解是 x=± 3。","所以 √(81) 的平方根是 ± 3。"]},{"type":"p","text":"答案：± 3"},{"type":"note","title":"方法小结","text":"遇到「√(a) 的平方根」这类两层说法，务必先算出 √(a) 的值再求它的平方根。另外要区分：81 的平方根是 ± 9，81 的算术平方根是 9，√(81) 的平方根是 ± 3。"},{"type":"note","title":"例题","text":"计算：√(16)-(-27)^(1/3)+|√(2)-2|。"},{"type":"figure","figure":{"id":"fig-num-shishu-e2","title":"三部分分别化简再合并","caption":"平方根取正、立方根带负号、绝对值先比大小","view":"wide","alt":"三个方框分别算出根号 16 等于正 4、负 27 的立方根等于负 3、根号 2 减 2 的绝对值等于 2 减根号 2，下方把三项相加得到 9 减根号 2","prims":[{"t":"text","x":50,"y":10,"text":"把三个部分分别算清楚，再合并","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":6,"y":18,"w":28,"h":20,"tone":"main"},{"t":"text","x":20,"y":25,"text":"√16","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":20,"y":33,"text":"= 4（取正）","size":2.9,"anchor":"middle","tone":"muted"},{"t":"rect","x":36,"y":18,"w":28,"h":20,"tone":"accent"},{"t":"text","x":50,"y":25,"text":"∛(−27)","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":33,"text":"= −3（可取负）","size":2.9,"anchor":"middle","tone":"muted"},{"t":"rect","x":66,"y":18,"w":28,"h":20,"tone":"ok"},{"t":"text","x":80,"y":25,"text":"|√2 − 2|","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":80,"y":33,"text":"= 2 − √2","size":2.9,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":47,"text":"4 − (−3) + (2 − √2) = 9 − √2","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":57,"text":"减负 3 要变号；去绝对值前先比较 √2 与 2 的大小","size":2.9,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["√(16)=4（算术平方根取正值）。","(-27)^(1/3)=-3（负数的立方根是负数）。","因为 √(2)≈ 1.414<2，所以 √(2)-2<0，于是 |√(2)-2|=2-√(2)。","把三项相加：4-(-3)+(2-√(2))=4+3+2-√(2)=9-√(2)。"]},{"type":"p","text":"答案：9-√(2)"},{"type":"note","title":"方法小结","text":"三个易错点：√(16) 是 4 不是 ± 4；(-27)^(1/3) 是 -3，减去它要变号；去绝对值前必须先比较大小，|√(2)-2|=2-√(2)。"},{"type":"note","title":"例题","text":"比较 √(13) 与 3.6 的大小，并说明 √(13) 在哪两个连续整数之间。"},{"type":"figure","figure":{"id":"fig-num-shishu-e3","title":"平方比较法：比平方，不比本身","caption":"两数都为正，平方大的原数就大","view":"wide","alt":"一张比较表，左边是根号 13、它的平方 13，右边是 3.6、它的平方 12.96，因为 13 大于 12.96 所以根号 13 大于 3.6；下方还写出 3 的平方小于 13 小于 4 的平方，说明根号 13 在 3 和 4 之间","prims":[{"t":"text","x":50,"y":10,"text":"平方比较法：比平方，不比本身","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":18,"w":38,"h":11,"tone":"accent"},{"t":"text","x":27,"y":23.5,"text":"√13","size":3.4,"anchor":"middle","tone":"accent"},{"t":"rect","x":50,"y":18,"w":38,"h":11,"tone":"main"},{"t":"text","x":69,"y":23.5,"text":"3.6","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":29,"w":38,"h":11,"tone":"accent"},{"t":"text","x":27,"y":34.5,"text":"(√13)² = 13","size":2.9,"anchor":"middle","tone":"muted"},{"t":"rect","x":50,"y":29,"w":38,"h":11,"tone":"main"},{"t":"text","x":69,"y":34.5,"text":"3.6² = 12.96","size":2.9,"anchor":"middle","tone":"muted"},{"t":"rect","x":8,"y":40,"w":80,"h":11,"tone":"ok"},{"t":"text","x":48,"y":45.5,"text":"13 > 12.96，所以 √13 > 3.6","size":3.1,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":58,"text":"3² = 9 < 13 < 16 = 4²，故 3 < √13 < 4","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["比较平方：3.6²=12.96，而 (√(13))²=13。","因为 13>12.96 且两数都为正，所以 √(13)>3.6。","再找连续整数：3²=9<13<16=4²，故 3<√(13)<4。","结论：3<√(13)<4，且 √(13)>3.6。"]},{"type":"p","text":"答案：3<√(13)<4，且 √(13)>3.6"},{"type":"note","title":"方法小结","text":"比较大小的通法是「平方比较法」，但要注意前提：两个数都为正数。若是两个负数比较大小，平方大的反而小，如 -√(5)<-2。"},{"type":"note","title":"例题","text":"已知实数 x、y、z 满足 √(x+2)+(y-1)²+|z+3|=0，求 xyz 的值。"},{"type":"figure","figure":{"id":"fig-num-shishu-e4","title":"非负性：几个非负数之和为 0","caption":"三部分都非负，只有各自为 0 才可能相加得 0","view":"wide","alt":"三个方框分别写着根号 x 加 2、y 减 1 的平方、z 加 3 的绝对值，每个都大于等于 0，三者相加等于 0，下方箭头指向 x 加 2 等于 0、y 减 1 等于 0、z 加 3 等于 0，并算出 x 等于负 2、y 等于 1、z 等于负 3，xyz 等于 6","prims":[{"t":"text","x":50,"y":9,"text":"几个非负数的和是 0，每个都为 0","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":6,"y":20,"w":24,"h":18,"tone":"main"},{"t":"text","x":18,"y":27,"text":"√(x+2)","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":18,"y":34,"text":"≥ 0","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":33,"y":29,"text":"+","size":3.6,"anchor":"middle","tone":"muted"},{"t":"rect","x":36,"y":20,"w":24,"h":18,"tone":"accent"},{"t":"text","x":48,"y":27,"text":"(y−1)²","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":48,"y":34,"text":"≥ 0","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":63,"y":29,"text":"+","size":3.6,"anchor":"middle","tone":"muted"},{"t":"rect","x":66,"y":20,"w":24,"h":18,"tone":"ok"},{"t":"text","x":78,"y":27,"text":"|z+3|","size":3.2,"anchor":"middle","tone":"ok"},{"t":"text","x":78,"y":34,"text":"≥ 0","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":95,"y":29,"text":"= 0","size":3.2,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":40,"x2":50,"y2":45,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"x + 2 = 0，y − 1 = 0，z + 3 = 0","size":3.1,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":59.5,"text":"x = −2，y = 1，z = −3，xyz = 6","size":3.3,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["观察发现等式由算术平方根、平方、绝对值三部分相加而成，想到这三部分各自都具有非负性，都不小于 0。","三个非负数的和为 0，只能是每一部分都等于 0，于是 x+2=0，y-1=0，z+3=0。","解得 x=-2，y=1，z=-3。","代入计算：xyz=(-2)× 1×(-3)=6。"]},{"type":"p","text":"答案：xyz=6"},{"type":"note","title":"方法小结","text":"非负性的标准结构是「几个非负式相加等于 0，则每个都为 0」。常见的非负式有算术平方根、一个数的平方（偶次幂）和绝对值，看到它们相加为 0 就直接令各部分为 0。"},{"type":"note","title":"例题","text":"设 5+√(7) 的小数部分为 a，5-√(7) 的小数部分为 b，求 a+b 的值。"},{"type":"figure","figure":{"id":"fig-m-num-shishu-genhao-1","title":"用夹逼法确定 √7 的范围","caption":"2²=4<7<9=3²，故 2<√7<3","view":"wide","alt":"一条数轴从 0 到 8，标出根号 7 位于 2 和 3 之间约 2.65 的位置；5 加根号 7 位于 7 和 8 之间，整数部分为 7；5 减根号 7 位于 2 和 3 之间，整数部分为 2","prims":[{"t":"line","x1":10,"y1":40,"x2":90,"y2":40},{"t":"arrow","x1":90,"y1":40,"x2":94,"y2":40},{"t":"line","x1":10,"y1":37,"x2":10,"y2":43},{"t":"line","x1":20,"y1":37,"x2":20,"y2":43},{"t":"line","x1":30,"y1":37,"x2":30,"y2":43},{"t":"line","x1":40,"y1":37,"x2":40,"y2":43},{"t":"line","x1":50,"y1":37,"x2":50,"y2":43},{"t":"line","x1":60,"y1":37,"x2":60,"y2":43},{"t":"line","x1":70,"y1":37,"x2":70,"y2":43},{"t":"line","x1":80,"y1":37,"x2":80,"y2":43},{"t":"line","x1":90,"y1":37,"x2":90,"y2":43},{"t":"text","x":10,"y":50,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":30,"y":50,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":40,"y":50,"text":"3","size":3.2,"anchor":"middle"},{"t":"text","x":70,"y":50,"text":"7","size":3.2,"anchor":"middle"},{"t":"text","x":80,"y":50,"text":"8","size":3.2,"anchor":"middle"},{"t":"dot","x":36.5,"y":40,"tone":"accent","label":"√7","labelDx":0,"labelDy":-10},{"t":"text","x":35,"y":30,"text":"2<√7<3","size":3.4,"anchor":"middle","tone":"muted"},{"t":"dot","x":76.5,"y":40,"tone":"main","label":"5+√7","labelDx":0,"labelDy":-10},{"t":"dot","x":33.5,"y":40,"tone":"ok","label":"5−√7","labelDx":0,"labelDy":12},{"t":"line","x1":70,"y1":33,"x2":80,"y2":33,"tone":"main","dashed":true},{"t":"text","x":75,"y":28,"text":"整数部分 7","size":3.2,"anchor":"middle","tone":"main"},{"t":"line","x1":30,"y1":56,"x2":40,"y2":56,"tone":"ok","dashed":true},{"t":"text","x":35,"y":62,"text":"整数部分 2","size":3.2,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["要求小数部分，先估计 √(7) 的范围：2²=4<7<9=3²，故 2<√(7)<3。","于是 7<5+√(7)<8，其整数部分是 7，小数部分 a=(5+√(7))-7=√(7)-2。","再看 5-√(7)：由 2<√(7)<3 得 2<5-√(7)<3，整数部分是 2，小数部分 b=(5-√(7))-2=3-√(7)。","所以 a+b=(√(7)-2)+(3-√(7))=1。"]},{"type":"p","text":"答案：a+b=1"},{"type":"note","title":"方法小结","text":"一个数减去它的整数部分就是小数部分，因此关键是先用夹逼法确定整数部分。两个小数部分中的根式恰好抵消，这是命题设计好的化简出口，算到含 √(7) 的形式先不要取近似值。"},{"type":"list","title":"易错点","items":["混淆平方根与算术平方根：正数有两个平方根，而 $\\sqrt{a}$ 只表示其中正的那个，$\\sqrt{9}=3$ 不能写成 $\\pm 3$。","认为「$\\sqrt{a}$ 的平方根」等于 $\\pm\\sqrt{a}$ 的某种简单形式。必须先算出 $\\sqrt{a}$ 的值再求平方根，如 $\\sqrt{81}$ 的平方根是 $\\pm 3$。","给负数求平方根，如写出 $\\sqrt{-4}=-2$。负数没有平方根，只有立方根，且 $\\sqrt[3]{-8}=-2$。","误以为所有带根号的数都是无理数。$\\sqrt{9}=3$、$\\sqrt{0.25}=0.5$ 都是有理数。","去绝对值时不判断符号，把 $|\\sqrt{2}-2|$ 写成 $\\sqrt{2}-2$。应先比较被减数与减数的大小。","把 $\\sqrt{a^{2}}$ 当成 $a$。$\\sqrt{a^{2}}=|a|$，如 $\\sqrt{(-3)^{2}}=3$，而不是 $-3$。"]},{"type":"list","title":"解题方法","items":["「先算值、再判断」：遇到带根号的复合问题（如「√(a) 的平方根」），先把根号算出一个确定的数，再按定义作答。","比较实数大小四法：平方比较法（适用于两个正数）、夹逼法（估范围）、数轴法、作差法。","化简 a² 与 |a| 型式子，统一按「先定号、再脱号」处理，必要时分类讨论字母的正负。","熟练掌握常用近似值：√(2)≈ 1.414，√(3)≈ 1.732，√(5)≈ 2.236，用于快速估算和检验。","利用非负性解题：√(a)≥ 0、a²≥ 0、|a|≥ 0，几个非负数的和为 0 时它们分别为 0。"]}],"questions":[{"id":"m-num-shishu-q1","type":"choice","stem":"√(16) 的平方根是（ ）","answer":"D","explain":"先算出 √(16)=4，再求 4 的平方根：因为 (± 2)²=4，所以 4 的平方根是 ± 2，选 D。A 项 4 是 √(16) 的值本身；B 项 ± 4 是 16 的平方根；C 项 2 只是 4 的算术平方根。","options":["4","± 4","2","± 2"],"difficulty":2,"tags":["平方根","算术平方根","易错"]},{"id":"m-num-shishu-q2","type":"choice","stem":"下列各数中是无理数的是（ ）","answer":"C","explain":"π 是无限不循环小数，是无理数。(22)/(7) 是分数，属有理数（它只是 π 的近似值）；√(9)=3 是整数，属有理数；0.3=0.333… 是无限循环小数，属有理数。故选 C。","options":["(22)/(7)","√(9)","π","0.3"],"difficulty":1,"tags":["无理数","有理数","概念辨析"]},{"id":"m-num-shishu-q3","type":"fill","stem":"计算：(-64)^(1/3)+√(25)=（ ）。","answer":"1","explain":"因为 (-4)³=-64，所以 (-64)^(1/3)=-4；因为 5²=25 且取算术平方根，所以 √(25)=5。故原式 =-4+5=1。注意负数的立方根是负数，而 √(25) 只能取正值 5。","difficulty":1,"tags":["立方根","算术平方根","计算"]},{"id":"m-num-shishu-q4","type":"fill","stem":"比较大小：√(10)（ ）(10)/(3)（填「>」「<」或「=」）。","answer":"<","explain":"两个数都是正数，比较它们的平方：(√(10))²=10，((10)/(3))²=(100)/(9)≈ 11.11。因为 10<(100)/(9)，所以 √(10)<(10)/(3)。用近似值检验：√(10)≈ 3.162，(10)/(3)≈ 3.333，结论一致。","difficulty":2,"tags":["实数比较大小","平方比较法"]},{"id":"m-num-shishu-q5","type":"short","stem":"已知实数 x、y 满足 √(x-2)+|y+1|=0，求 (x+y)²⁰²⁶ 的值，并写出推理过程。","answer":"$x=2$，$y=-1$，$x+y=1$，故 $(x+y)^{2026}=1^{2026}=1$。","explain":"由算术平方根的非负性得 √(x-2)≥ 0，由绝对值的非负性得 |y+1|≥ 0。两个非负数的和为 0，只能是每个都为 0，于是 x-2=0 且 y+1=0，解得 x=2、y=-1。所以 x+y=2+(-1)=1，从而 (x+y)²⁰²⁶=1²⁰²⁶=1。","difficulty":2,"tags":["非负性","实数","综合"],"rubric":["指出 √(x-2)≥ 0 与 |y+1|≥ 0（非负性）","由「非负数之和为 0」得出 x-2=0、y+1=0","正确解出 x=2，y=-1","算出 x+y=1，进而得到 1²⁰²⁶=1"]},{"id":"m-num-shishu-z1","type":"choice","stem":"估计 √(17) 的值（ ）","answer":"A","explain":"用夹逼法：4²=16<17<25=5²，所以 4<√(17)<5，即 √(17) 在 4 和 5 之间，选 A。进一步还可估算 √(17)≈ 4.12，方向与范围一致。","options":["在 4 和 5 之间","在 3 和 4 之间","在 5 和 6 之间","在 2 和 3 之间"],"difficulty":2,"tags":["实数比较大小","平方比较法","计算"]},{"id":"m-num-shishu-z2","type":"short","stem":"已知 2a-1 的平方根是 ± 3，3a+b-1 的算术平方根是 4，求 a+2b 的平方根，并写出完整推理过程。","answer":"由 $2a-1=(\\pm 3)^{2}=9$ 得 $a=5$；由 $3a+b-1=4^{2}=16$ 得 $b=2$。故 $a+2b=9$，它的平方根是 $\\pm 3$。","explain":"「2a-1 的平方根是 ± 3」意味着 (± 3)²=2a-1，即 2a-1=9，解得 a=5。「3a+b-1 的算术平方根是 4」意味着 3a+b-1=4²=16，把 a=5 代入得 15+b-1=16，解得 b=2。于是 a+2b=5+2× 2=9，而 9 的平方根是 ± 3（注意题目问的是平方根，要同时写出 +3 和 -3，不能只写 3）。检验：2a-1=9，平方根确为 ± 3；3a+b-1=16，算术平方根确为 4。","difficulty":3,"tags":["平方根","算术平方根","综合"],"rubric":["由平方根定义列出 2a-1=9，正确解出 a=5","由算术平方根定义列出 3a+b-1=16，正确解出 b=2","算出 a+2b=9 并写出它的平方根为 ± 3（正负两个都写全）"]}]},{"id":"m-num-eryuan-yici","title":"二元一次方程组","subtitle":"人教版七下 · 第10章 二元一次方程组","grade":"7b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七下 · 第10章 二元一次方程组"},{"type":"note","title":"一句话概述","text":"理解二元一次方程与方程组，掌握代入消元与加减消元法，会用方程组解决实际问题。"},{"type":"h","text":"先看什么：一个方程画成一条直线"},{"type":"p","text":"把 2x+y=7 的每一对解 (x,y) 当作点的坐标画出来，会发现它们恰好排成一条直线；反过来，这条直线上每个点的坐标都满足方程。所以「一个二元一次方程有无数个解」，在图上看就是「一条直线上有无穷多个点」——这就是它和一元一次方程最大的不同。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-s1","title":"一个二元一次方程就是一条直线","caption":"直线上的每一个点都是一个解","view":"square","alt":"平面直角坐标系中画出直线 2x 加 y 等于 7，直线上标出点 1 逗号 5、点 2 逗号 3、点 3 逗号 1，说明这个方程有无数个解，每个解对应直线上一个点","prims":[{"t":"plane","x":16,"y":84,"right":76,"up":76,"down":4,"left":8,"xLabel":"x","yLabel":"y","xTicks":[{"at":10,"label":"1"},{"at":30,"label":"3"},{"at":50,"label":"5"},{"at":70,"label":"7"}],"yTicks":[{"at":10,"label":"1"},{"at":30,"label":"3"},{"at":50,"label":"5"},{"at":70,"label":"7"}]},{"t":"curve","points":[[16,14],[51,84]],"tone":"accent"},{"t":"dot","x":26,"y":34,"tone":"accent"},{"t":"dot","x":36,"y":54,"tone":"accent"},{"t":"dot","x":46,"y":74,"tone":"accent","label":"(3,1)","labelDx":6,"labelDy":-16},{"t":"text","x":68,"y":18,"text":"2x + y = 7","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":70,"y":30,"text":"一个方程有无数个解","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"只给一个二元一次方程，解是不确定的；把解写成点的坐标画出来，就能看见「无数个」长什么样。"},{"type":"h","text":"建立关系：交点就是方程组的解"},{"type":"p","text":"把两个方程各自的直线画在同一个坐标系里：两条直线相交时，交点坐标同时满足两个方程，它就是方程组的解；如果两条直线平行、没有公共点，方程组就无解。这就是「解方程组」和「求两条直线的交点」是同一件事的原因。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-s2","title":"两条直线的交点就是方程组的解","caption":"2x + y = 7 与 x − y = 2 交于 (3,1)","view":"square","alt":"平面直角坐标系中画出两条相交直线 2x 加 y 等于 7 与 x 减 y 等于 2，交点标为 3 逗号 1，两条虚线分别连到 x 轴与 y 轴读出横纵坐标，说明交点坐标就是方程组的解","prims":[{"t":"plane","x":16,"y":84,"right":76,"up":76,"down":4,"left":8,"xLabel":"x","yLabel":"y","xTicks":[{"at":10,"label":"1"},{"at":30,"label":"3"},{"at":50,"label":"5"}],"yTicks":[{"at":10,"label":"1"},{"at":30,"label":"3"},{"at":50,"label":"5"},{"at":70,"label":"7"}]},{"t":"curve","points":[[16,14],[51,84]],"tone":"accent"},{"t":"curve","points":[[36,84],[86,34]],"tone":"main"},{"t":"line","x1":46,"y1":74,"x2":46,"y2":84,"dashed":true,"tone":"muted"},{"t":"line","x1":16,"y1":74,"x2":46,"y2":74,"dashed":true,"tone":"muted"},{"t":"dot","x":46,"y":74,"tone":"danger","label":"(3,1)","labelDx":6,"labelDy":4},{"t":"text","x":66,"y":18,"text":"2x + y = 7","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":70,"y":36,"text":"x − y = 2","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":32,"y":22,"text":"交点就是解","size":3.2,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"两条直线平行（同一个未知数系数成比例、常数不成比例）时方程组无解；两条直线重合时方程组有无数多组解。"},{"type":"h","text":"怎么解：代入与加减两条消元路"},{"type":"p","text":"图象法能看出解，但画图既慢又不精确，所以还要掌握代数解法。两条路的本质都是消元：先想办法消去一个未知数，把「二元」问题变成已经会解的「一元」问题。某个未知数的系数是 1 或 -1 时用代入法最省事；同一个未知数的系数相同、相反或成倍数关系时，用加减法最快。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-s3","title":"代入消元与加减消元","caption":"两条路都通向「消去一个未知数」","view":"square","alt":"左右两栏流程图对比，左栏是代入消元法：变形用一个未知数表示另一个、代入另一个方程、化为一元一次方程；右栏是加减消元法：两边同乘配系数、两式相减或相加、消去一个未知数","prims":[{"t":"text","x":50,"y":8,"text":"两条路，都是消元","size":3.4,"anchor":"middle","tone":"main"},{"t":"line","x1":50,"y1":14,"x2":50,"y2":80,"dashed":true,"tone":"muted"},{"t":"text","x":25,"y":17,"text":"代入消元法","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":75,"y":17,"text":"加减消元法","size":3.3,"anchor":"middle","tone":"ok"},{"t":"rect","x":5,"y":22,"w":40,"h":13,"tone":"accent"},{"t":"text","x":25,"y":28.5,"text":"① 变形：y = 7 − 2x","size":2.9,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":25,"y1":35.5,"x2":25,"y2":40.5,"tone":"muted"},{"t":"rect","x":5,"y":41,"w":40,"h":13,"tone":"accent"},{"t":"text","x":25,"y":47.5,"text":"② 代入另一个方程","size":2.9,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":25,"y1":54.5,"x2":25,"y2":59.5,"tone":"muted"},{"t":"rect","x":5,"y":60,"w":40,"h":13,"tone":"accent"},{"t":"text","x":25,"y":66.5,"text":"③ 化为一元一次方程","size":2.9,"anchor":"middle","tone":"accent"},{"t":"rect","x":55,"y":22,"w":40,"h":13,"tone":"ok"},{"t":"text","x":75,"y":28.5,"text":"① 两边同乘配系数","size":2.9,"anchor":"middle","tone":"ok"},{"t":"arrow","x1":75,"y1":35.5,"x2":75,"y2":40.5,"tone":"muted"},{"t":"rect","x":55,"y":41,"w":40,"h":13,"tone":"ok"},{"t":"text","x":75,"y":47.5,"text":"② 两式相减或相加","size":2.9,"anchor":"middle","tone":"ok"},{"t":"arrow","x1":75,"y1":54.5,"x2":75,"y2":59.5,"tone":"muted"},{"t":"rect","x":55,"y":60,"w":40,"h":13,"tone":"ok"},{"t":"text","x":75,"y":66.5,"text":"③ 消去一个未知数","size":2.9,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":88,"text":"消元后都变成一元一次方程，再回代求另一个未知数","size":2.9,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"配系数时两个方程都要乘，且右边的常数项也要乘；求出一个未知数后必须回代，才能求出另一个。"},{"type":"h","text":"换个情境：两个未知量要两个关系"},{"type":"p","text":"鸡兔同笼里有两个未知量（鸡、兔的只数），恰好也有两个独立的关系（头数之和、脚数之和）：每个关系写成一个方程，两个方程合起来才能定出唯一一组解。若只能找到一个关系，就只有一个方程，解有无穷多组；若两个关系其实重复，方程组也解不出唯一答案。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-s4","title":"头数与脚数：两个关系定一组解","caption":"鸡兔同笼的两个等量关系","view":"wide","alt":"一张表格，第一行写明鸡 x 只、兔 y 只，第二行是头数关系 x 加 y 等于 35，第三行是脚数关系 2x 加 4y 等于 94，最后一行给出 x 等于 23、y 等于 12","prims":[{"t":"text","x":50,"y":8,"text":"两个未知量，就要找两个独立关系","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":15,"w":36,"h":11,"tone":"main"},{"t":"text","x":26,"y":20.5,"text":"鸡 x 只","size":3,"anchor":"middle","tone":"main"},{"t":"rect","x":50,"y":15,"w":42,"h":11,"tone":"main"},{"t":"text","x":71,"y":20.5,"text":"兔 y 只","size":3,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":26,"w":36,"h":11,"tone":"ok"},{"t":"text","x":26,"y":31.5,"text":"头数：x + y = 35","size":2.9,"anchor":"middle","tone":"ok"},{"t":"rect","x":50,"y":26,"w":42,"h":11,"tone":"ok"},{"t":"text","x":71,"y":31.5,"text":"脚数：2x + 4y = 94","size":2.9,"anchor":"middle","tone":"ok"},{"t":"rect","x":8,"y":42,"w":84,"h":12,"tone":"accent"},{"t":"text","x":50,"y":48,"text":"解得 x = 23，y = 12","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":60,"text":"少一个关系，解就有无数多组","size":2.9,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"两个方程必须互相独立：如果一个是另一个乘常数得来的，说明等量关系重复，此时方程组有无数多组解。"},{"type":"h","text":"核心概念"},{"type":"p","text":"二元一次方程：含有两个未知数，并且含未知数的项的次数都是 1 的整式方程叫二元一次方程，如 2x+y=7。关键点：它的一般形式是 ax+by=c（a、b 不同时为 0），满足它的有序数对有无数组。"},{"type":"p","text":"二元一次方程的解：使二元一次方程两边的值相等的一对未知数的值，叫做这个方程的一个解，记作 cases x= \\\\ y= endcases 的形式。关键点：一个二元一次方程有无数个解，但若限定为正整数解则个数有限。"},{"type":"p","text":"二元一次方程组及其解：把两个含有相同未知数的二元一次方程合在一起就组成一个二元一次方程组。同时满足两个方程的解叫方程组的解，它必须使每一个方程都成立。"},{"type":"p","text":"代入消元法：把一个方程中的某个未知数用含另一个未知数的式子表示出来，再代入另一个方程，实现消元，进而求出解。适用于某个未知数的系数是 1 或 -1 的方程组。"},{"type":"p","text":"加减消元法：当两个方程中同一个未知数的系数相同或互为相反数时，把两个方程相减或相加就能消去这个未知数。若系数不成倍数关系，可先把方程两边乘适当的数，使系数相同或互为相反数。"},{"type":"p","text":"消元思想：解方程组的基本思路是「消元」：把「二元」化为「一元」，把未知问题转化为已知问题。代入法、加减法都是消元的具体手段，选择哪一种只看哪种更快。"},{"type":"p","text":"列方程组解应用题：当问题中有两个未知量、且能找到两个独立的等量关系时，设两个未知数列方程组比列一元一次方程更直接。解出后要检验是否符合实际意义，并完整作答。"},{"type":"note","title":"中考考法","text":"二元一次方程组的解法：代入消元与加减消元\n填空与解答以解方程组为主，常需先给方程配系数，踩分点是两边同乘不漏常数项，求出一个未知数后必须回代求另一个。"},{"type":"note","title":"中考考法","text":"方程组的解与含字母系数问题\n给一组解代入方程求系数，或两个方程组同解、看错系数求正确解，踩分点是把解整体代入，转化为关于字母的方程（组）求解。"},{"type":"note","title":"中考考法","text":"列方程组解和差倍分、配套与鸡兔同笼问题\n广州中考应用建模常考题，以人数、价格、零件配套为情境，踩分点是设两个未知数、找两个独立的等量关系，解后检验实际意义。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["二元一次方程的一般形式","其中 a、b 不同时为 0；一个这样的方程有无数个解。","方程中的项必须都是整式，(1)/(x)+y=1 不是二元一次方程。"],["代入消元","y=(c-ax)/(b)\\ (b≠ 0)","把一个方程变形后整体代入另一个方程，代入时要把整个式子加括号，防止符号错误。"],["加减消元","当同一个未知数的系数互为相反数时把两个方程相加，系数相同时把两个方程相减，即可消去该未知数。","若系数不成倍数关系，先把两个方程分别乘适当的数再加减，注意两个方程都要乘。"],["常见结构的解","cases x+y=a \\\\ x-y=b endcases\\ ⇒\\ x=(a+b)/(2),\\ y=(a-b)/(2)","两式相加得 2x=a+b，两式相减得 2y=a-b，这是和差型方程组最快的方法。"],["实际问题中的等量关系","常见模型：和差倍分（两量之和与两量之差）、配套问题（各种零件的数量比）、行程问题（s=vt）、销售问题（利润 = 售价 - 进价）。","两个方程必须互相独立，不能由其中一个变形直接得到另一个，否则方程组有无数组解。"]]},{"type":"note","title":"例题","text":"解方程组：cases 2x+y=7 \\\\ x-y=2 endcases。"},{"type":"figure","figure":{"id":"fig-m-num-eryuan-jiaodian-1","title":"方程组的解就是两直线的交点","caption":"2x+y=7 与 x-y=2 交于点 (3,1)","view":"square","alt":"平面直角坐标系中画出两条直线，一条经过 0 到 7 和 3 到 1，另一条经过 0 到负 2 和 3 到 1，两条直线相交于点 3 逗号 1","prims":[{"t":"axis","x":20,"y":68,"w":60,"h":42,"xLabel":"x","yLabel":"y","origin":true,"xTicks":[{"at":3,"label":"3"}],"yTicks":[{"at":1,"label":"1"},{"at":7,"label":"7"}]},{"t":"curve","points":[[20,26],[38,62],[44,74]],"tone":"accent"},{"t":"curve","points":[[20,80],[38,62],[50,50]],"tone":"main"},{"t":"dot","x":38,"y":62,"tone":"danger","label":"(3,1)","labelDx":6,"labelDy":-4},{"t":"text","x":28,"y":22,"text":"2x+y=7","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":46,"text":"x−y=2","size":3.4,"tone":"main"}]}},{"type":"list","title":"解题步骤","items":["观察两个方程中 y 的系数分别是 1 和 -1，互为相反数，适合用加减法。","把两个方程相加消去 y：(2x+y)+(x-y)=7+2，得 3x=9。","解得 x=3。","把 x=3 代入 x-y=2，得 3-y=2，解得 y=1。","写出解为 cases x=3 \\\\ y=1 endcases，并检验：2× 3+1=7，3-1=2，两个方程都成立。"]},{"type":"p","text":"答案：cases x=3 \\\\ y=1 endcases"},{"type":"note","title":"方法小结","text":"系数互为相反数用加法，系数相同用减法，这是加减消元的口诀。求出第一个未知数后一定要回代求另一个，不能只写一半就收笔。"},{"type":"note","title":"例题","text":"解方程组：cases 2x+3y=12 \\\\ 3x-2y=5 endcases。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-e2","title":"配系数：两个方程都要乘，右边也要乘","caption":"把 x 的系数配成相同再相减","view":"wide","alt":"流程图，第一个方程 2x 加 3y 等于 12 两边乘 3 得 6x 加 9y 等于 36，第二个方程 3x 减 2y 等于 5 两边乘 2 得 6x 减 4y 等于 10，两式相减得 13y 等于 26，解得 y 等于 2","prims":[{"t":"text","x":50,"y":8,"text":"配系数：让 x 的系数相同","size":3.4,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":16,"w":40,"h":12,"tone":"accent"},{"t":"text","x":28,"y":22,"text":"2x + 3y = 12","size":3,"anchor":"middle","tone":"accent"},{"t":"text","x":54,"y":22,"text":"×3","size":3,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":60,"y1":22,"x2":65,"y2":22,"tone":"muted"},{"t":"rect","x":66,"y":16,"w":30,"h":12,"tone":"accent"},{"t":"text","x":81,"y":22,"text":"6x + 9y = 36","size":2.8,"anchor":"middle","tone":"accent"},{"t":"rect","x":8,"y":32,"w":40,"h":12,"tone":"ok"},{"t":"text","x":28,"y":38,"text":"3x − 2y = 5","size":3,"anchor":"middle","tone":"ok"},{"t":"text","x":54,"y":38,"text":"×2","size":3,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":60,"y1":38,"x2":65,"y2":38,"tone":"muted"},{"t":"rect","x":66,"y":32,"w":30,"h":12,"tone":"ok"},{"t":"text","x":81,"y":38,"text":"6x − 4y = 10","size":2.8,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":52,"text":"两式相减：13y = 26，得 y = 2","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":60,"text":"右边的常数项也必须乘","size":2.9,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["两个未知数的系数都不成倍数关系，先设法使 x 的系数相同：把第一个方程两边都乘 3，第二个方程两边都乘 2。","得 cases 6x+9y=36 \\\\ 6x-4y=10 endcases。","两式相减消去 x：(6x+9y)-(6x-4y)=36-10，得 13y=26。","解得 y=2。","把 y=2 代入 2x+3y=12：2x+6=12，得 2x=6，x=3。","所以 cases x=3 \\\\ y=2 endcases。检验：2× 3+3× 2=12，3× 3-2× 2=5，均成立。"]},{"type":"p","text":"答案：cases x=3 \\\\ y=2 endcases"},{"type":"note","title":"方法小结","text":"为了消去 x 而让两个方程分别乘 3 和 2 时，方程右边的常数项也必须乘，漏乘右边是加减法最常见的错误。也可以选择消去 y（分别乘 2 和 3），结果相同。"},{"type":"note","title":"例题","text":"某班 40 名学生参加植树活动，男生每人植 3 棵，女生每人植 2 棵，共植树 100 棵。求男、女生各有多少人。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-e3","title":"植树问题的两个等量关系","caption":"人数之和与植树总数","view":"wide","alt":"表格显示男生 x 人每人植 3 棵、女生 y 人每人植 2 棵，两个等量关系是 x 加 y 等于 40 与 3x 加 2y 等于 100，解得 x 等于 20、y 等于 20","prims":[{"t":"text","x":50,"y":8,"text":"两个未知量，两个独立等量关系","size":3.3,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":15,"w":40,"h":12,"tone":"main"},{"t":"text","x":28,"y":21,"text":"男生 x 人（每人 3 棵）","size":2.8,"anchor":"middle","tone":"main"},{"t":"rect","x":52,"y":15,"w":40,"h":12,"tone":"main"},{"t":"text","x":72,"y":21,"text":"女生 y 人（每人 2 棵）","size":2.8,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":29,"w":40,"h":12,"tone":"ok"},{"t":"text","x":28,"y":35,"text":"人数：x + y = 40","size":2.9,"anchor":"middle","tone":"ok"},{"t":"rect","x":52,"y":29,"w":40,"h":12,"tone":"ok"},{"t":"text","x":72,"y":35,"text":"棵数：3x + 2y = 100","size":2.9,"anchor":"middle","tone":"ok"},{"t":"rect","x":8,"y":45,"w":84,"h":12,"tone":"accent"},{"t":"text","x":50,"y":51,"text":"解得 x = 20，y = 20","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":61,"text":"少一个关系就定不出唯一答案","size":2.9,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设男生有 x 人，女生有 y 人。","由总人数得方程 x+y=40。","由植树总棵数得方程 3x+2y=100。","由第一个方程得 y=40-x，代入第二个方程：3x+2(40-x)=100。","化简得 3x+80-2x=100，即 x=20。","代回得 y=40-20=20。","答：男生 20 人，女生 20 人。（检验：20+20=40 人，3× 20+2× 20=100 棵。）"]},{"type":"p","text":"答案：男生 20 人，女生 20 人"},{"type":"note","title":"方法小结","text":"设两个未知数后要找出两个独立的等量关系：一个是「人数之和」，一个是「植树总数」。若只找到一个关系，说明缺条件或另一个关系没读出来。"},{"type":"note","title":"例题","text":"已知 x、y 满足方程组 cases 2x+y=7 \\\\ x+2y=8 endcases，不解方程组，直接求 x+y 与 x-y 的值。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-e4","title":"整体相加、相减，不必先求 x、y","caption":"所求的正好是两未知数的和与差","view":"wide","alt":"两个方程 2x 加 y 等于 7 与 x 加 2y 等于 8，相加得 3 乘 x 加 y 等于 15 即 x 加 y 等于 5，相减得 x 减 y 等于负 1，说明用整体思想可直接求出和与差","prims":[{"t":"text","x":50,"y":8,"text":"整体相加、相减：直接求 x + y 与 x − y","size":3.2,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":18,"w":38,"h":14,"tone":"accent"},{"t":"text","x":27,"y":25,"text":"2x + y = 7","size":3.1,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":25,"text":"+","size":3.6,"anchor":"middle","tone":"muted"},{"t":"rect","x":54,"y":18,"w":38,"h":14,"tone":"ok"},{"t":"text","x":73,"y":25,"text":"x + 2y = 8","size":3.1,"anchor":"middle","tone":"ok"},{"t":"arrow","x1":27,"y1":34,"x2":27,"y2":40,"tone":"muted"},{"t":"arrow","x1":73,"y1":34,"x2":73,"y2":40,"tone":"muted"},{"t":"text","x":27,"y":47,"text":"相加：3(x + y) = 15","size":2.9,"anchor":"middle","tone":"accent"},{"t":"text","x":73,"y":47,"text":"相减：x − y = −1","size":2.9,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":58,"text":"所以 x + y = 5，x − y = −1","size":3.2,"anchor":"middle","tone":"main"}]}},{"type":"list","title":"解题步骤","items":["所求的恰好是两未知数的和与差，想到把两个方程整体相加、相减，不必分别求出 x、y。","两式相加：(2x+y)+(x+2y)=7+8，即 3(x+y)=15，故 x+y=5。","两式相减（第一式减第二式）：(2x+y)-(x+2y)=7-8，即 x-y=-1。","回代检验：由 x+y=5、x-y=-1 得 x=2、y=3，代入原方程组两式都成立。"]},{"type":"p","text":"答案：x+y=5，x-y=-1"},{"type":"note","title":"方法小结","text":"观察所求式与方程系数的整体关系，是「整体思想」在方程组中的典型用法。相减时要固定顺序（第一式减第二式），右边的常数也按同一顺序相减。"},{"type":"note","title":"例题","text":"一个两位数，十位数字与个位数字之和为 9。把这个两位数的十位数字与个位数字对调，所得的新两位数比原数大 27。求原来的两位数。"},{"type":"figure","figure":{"id":"fig-num-eryuan-yici-e5","title":"数字问题：原数与对调后的新数","caption":"对调后比原数大 27","view":"wide","alt":"示意图，原数十位 x、个位 y 写成 10x 加 y，对调后写成 10y 加 x，两者之差等于 27，又知 x 加 y 等于 9，解得 x 等于 3、y 等于 6，原数为 36","prims":[{"t":"text","x":50,"y":7,"text":"把两位数写成 10 × 十位 + 个位","size":3.3,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":15,"w":40,"h":14,"tone":"accent"},{"t":"text","x":28,"y":22,"text":"原数 = 10x + y","size":3.1,"anchor":"middle","tone":"accent"},{"t":"text","x":53,"y":22,"text":"对调","size":3,"anchor":"middle","tone":"muted"},{"t":"rect","x":62,"y":15,"w":40,"h":14,"tone":"ok"},{"t":"text","x":82,"y":22,"text":"新数 = 10y + x","size":3.1,"anchor":"middle","tone":"ok"},{"t":"arrow","x1":28,"y1":31,"x2":28,"y2":37,"tone":"muted"},{"t":"arrow","x1":82,"y1":31,"x2":82,"y2":37,"tone":"muted"},{"t":"text","x":50,"y":44,"text":"新数 − 原数 = 27，即 9(y − x) = 27","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":53,"text":"与 x + y = 9 联立，解得 x = 3，y = 6","size":3.1,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":60,"text":"原数为 36（对调后 63，正好大 27）","size":2.8,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["设原数的十位数字为 x，个位数字为 y。数字问题中想到两位数的值要写成 10x+y，而不是 xy。","由数字之和为 9 列方程：x+y=9。","对调后的新数为 10y+x，由「新数比原数大 27」列方程：(10y+x)-(10x+y)=27，化简得 9(y-x)=27，即 y-x=3。","联立 cases x+y=9 \\\\ y-x=3 endcases，两式相加得 2y=12，y=6，从而 x=3。"]},{"type":"p","text":"答案：原来的两位数是 36"},{"type":"note","title":"方法小结","text":"数字问题的关键是把两位数正确表示为 10× 十位数字 + 个位数字。检验：对调后为 63，63-36=27，且 3+6=9，两个条件同时满足。"},{"type":"list","title":"易错点","items":["代入时不给整体加括号，如由 $y=40-x$ 代入 $3x+2y$ 时写成 $3x+2\\times 40-x$。正确写法是 $3x+2(40-x)$。","加减消元时相减的顺序搞错导致符号出错。用第一个方程减第二个方程时，右边的常数也要按同样顺序相减。","为配系数而乘某个数时只乘了方程左边，漏乘右边的常数项。","求出一个未知数就当作答案，忘记回代求另一个未知数。","列方程组时两个方程实际上等价（如一个方程是另一个的 2 倍），导致解不出来，说明等量关系没有找全或重复。","解出结果后不检验、不写答。实际问题还要判断解的意义，如人数必须是正整数。"]},{"type":"list","title":"解题方法","items":["观察系数选方法：某个未知数的系数为 1 或 -1 时用代入法；同一未知数的系数相同、相反或成倍数关系时用加减法。","整体代入与换元：把某个式子（如 x+y）看成一个整体，可简化复杂方程组。","和差型速解：形如 cases x+y=a \\\\ x-y=b endcases 的方程组直接相加、相减得出 x、y。","应用题先列表把两个未知量与它们的和、差、倍数关系摆清楚，再逐条写成方程。","检验时把解代回原方程组的两个方程，两个都成立才算正确。"]}],"questions":[{"id":"m-num-eryuan-yici-q1","type":"choice","stem":"方程组 cases x+y=5 \\\\ 2x-y=1 endcases 的解是（ ）","answer":"A","explain":"两式相加消去 y：(x+y)+(2x-y)=5+1，得 3x=6，x=2。代入 x+y=5 得 y=3。检验第二个方程：2× 2-3=1，成立。故选 A。B 项的 x、y 恰好写反，是常见误选。","options":["cases x=2 \\\\ y=3 endcases","cases x=3 \\\\ y=2 endcases","cases x=1 \\\\ y=4 endcases","cases x=4 \\\\ y=1 endcases"],"difficulty":1,"tags":["方程组","加减消元"]},{"id":"m-num-eryuan-yici-q2","type":"choice","stem":"若 cases x=2 \\\\ y=1 endcases 是方程 kx-3y=1 的一个解，则 k 的值是（ ）","answer":"B","explain":"把 x=2、y=1 代入 kx-3y=1，得 2k-3=1。移项得 2k=4，所以 k=2，选 B。检验：2× 2-3× 1=1，成立。","options":["1","2","-2","4"],"difficulty":1,"tags":["方程的解","代入求值"]},{"id":"m-num-eryuan-yici-q3","type":"fill","stem":"解方程组 cases 3x+2y=16 \\\\ 3x-y=10 endcases，得 x=（ ），y=（ ）。（填「x=值，y=值」的格式，如 x=1,y=2）","answer":"x=4,y=2","explain":"两个方程中 x 的系数都是 3，适合相减消元：① - ② 得 (3x+2y)-(3x-y)=16-10，即 3y=6，解得 y=2。把 y=2 代入 3x-y=10 得 3x-2=10，3x=12，x=4。检验：3× 4+2× 2=16，3× 4-2=10，均成立。","difficulty":1,"tags":["方程组","加减消元","计算"]},{"id":"m-num-eryuan-yici-q4","type":"fill","stem":"笼子里有鸡和兔共 35 只，共有 94 只脚。则鸡有（ ）只，兔有（ ）只。（填「鸡多少只，兔多少只」的格式，如 鸡1只，兔2只）","answer":"鸡23只，兔12只","explain":"设鸡有 x 只，兔有 y 只。由头数得 x+y=35；鸡 2 只脚、兔 4 只脚，由脚数得 2x+4y=94。把 x=35-y 代入：2(35-y)+4y=94，即 70-2y+4y=94，2y=24，y=12。故 x=35-12=23。检验：23+12=35，2× 23+4× 12=46+48=94，符合题意。","difficulty":2,"tags":["方程组应用","鸡兔同笼"]},{"id":"m-num-eryuan-yici-q5","type":"short","stem":"某商店购进甲、乙两种商品共 50 件，甲种每件进价 20 元，乙种每件进价 30 元，共花费 1300 元。求甲、乙两种商品各购进多少件。（要求设两个未知数、列方程组、完整求解并检验）","answer":"设甲种商品购进 $x$ 件、乙种 $y$ 件，列方程组 $\\begin{cases} x+y=50 \\\\ 20x+30y=1300 \\end{cases}$，解得 $x=20$，$y=30$，即甲种 20 件、乙种 30 件。","explain":"设甲种商品购进 x 件，乙种商品购进 y 件。等量关系有两个：件数之和为 50，总进价为 1300 元，于是 cases x+y=50 \\\\ 20x+30y=1300 endcases。由第一式得 x=50-y，代入第二式：20(50-y)+30y=1300，即 1000-20y+30y=1300，10y=300，y=30，从而 x=20。检验：20+30=50 件，20× 20+30× 30=400+900=1300 元，符合题意。","difficulty":2,"tags":["方程组应用","销售问题","建模"],"rubric":["设出两个未知数并说明含义","写出件数关系方程 x+y=50","写出总价关系方程 20x+30y=1300","正确解出 x=20、y=30","有检验或作答，答案含单位「件」且明确指出哪种商品多少件"]},{"id":"m-num-eryuan-yici-z1","type":"choice","stem":"方程组 cases x+2y=5 \\\\ 3x-y=1 endcases 的解是（ ）","answer":"D","explain":"由第二个方程得 y=3x-1，代入第一个方程：x+2(3x-1)=5，即 7x-2=5，解得 x=1，再代回得 y=2。检验：1+2× 2=5，3× 1-2=1，两个方程都成立，故选 D。","options":["cases x=1 \\\\ y=-2 endcases","cases x=-1 \\\\ y=2 endcases","cases x=2 \\\\ y=1 endcases","cases x=1 \\\\ y=2 endcases"],"difficulty":2,"tags":["方程组","计算"]},{"id":"m-num-eryuan-yici-z2","type":"fill","stem":"若 cases x=1 \\\\ y=2 endcases 是方程组 cases ax+by=7 \\\\ bx-ay=1 endcases 的解，则 a+b=（ ）。","answer":"4","explain":"把 x=1、y=2 代入方程组，得 cases a+2b=7 \\\\ b-2a=1 endcases。由第二式得 b=1+2a，代入第一式：a+2(1+2a)=7，即 5a+2=7，解得 a=1，b=3。所以 a+b=4。检验：1+2× 3=7，3-2× 1=1，与原方程组一致。","difficulty":2,"tags":["方程的解","代入求值"]}]},{"id":"m-num-budengshi","title":"不等式与不等式组","subtitle":"人教版七下 · 第11章 不等式与不等式组","grade":"7b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七下 · 第11章 不等式与不等式组"},{"type":"note","title":"一句话概述","text":"掌握不等式三条性质与一元一次不等式（组）解法，会用数轴表示解集并解决实际问题。"},{"type":"h","text":"先看什么：不等式说的是一个范围"},{"type":"p","text":"像 x>2 这样的不等式，答案不是一个数，而是所有比 2 大的数——在数轴上就是「从 2 出发向右的一条射线」。端点 2 取不取到，看不等号带不带等号：x>2 不含 2（空心圆圈），x≥ 2 含 2（实心圆点）。这就是解集必须画在数轴上看的原因。"},{"type":"figure","figure":{"id":"fig-num-budengshi-s1","title":"x > 2 与 x ≥ 2 的数轴表示","caption":"端点取不取到，决定画空心还是实心","view":"wide","alt":"上下两条数轴，上一条在 2 处画空心圆圈并向右画箭头表示 x 大于 2，下一条在 2 处画实心圆点并向右画箭头表示 x 大于等于 2","prims":[{"t":"text","x":50,"y":8,"text":"不等式表示的是一个范围","size":3.5,"anchor":"middle","tone":"main"},{"t":"line","x1":12,"y1":28,"x2":84,"y2":28},{"t":"line","x1":16,"y1":25,"x2":16,"y2":31},{"t":"line","x1":28,"y1":25,"x2":28,"y2":31},{"t":"line","x1":40,"y1":25,"x2":40,"y2":31},{"t":"line","x1":52,"y1":25,"x2":52,"y2":31},{"t":"line","x1":64,"y1":25,"x2":64,"y2":31},{"t":"text","x":16,"y":36,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":28,"y":36,"text":"1","size":3.2,"anchor":"middle"},{"t":"text","x":40,"y":36,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":52,"y":36,"text":"3","size":3.2,"anchor":"middle"},{"t":"text","x":64,"y":36,"text":"4","size":3.2,"anchor":"middle"},{"t":"arrow","x1":40,"y1":28,"x2":84,"y2":28,"width":1.6,"tone":"accent"},{"t":"dot","x":40,"y":28,"hollow":true,"tone":"accent"},{"t":"text","x":32,"y":19,"text":"x > 2：空心圆圈，向右画","size":3,"anchor":"middle","tone":"accent"},{"t":"line","x1":12,"y1":48,"x2":84,"y2":48},{"t":"line","x1":16,"y1":45,"x2":16,"y2":51},{"t":"line","x1":28,"y1":45,"x2":28,"y2":51},{"t":"line","x1":40,"y1":45,"x2":40,"y2":51},{"t":"line","x1":52,"y1":45,"x2":52,"y2":51},{"t":"line","x1":64,"y1":45,"x2":64,"y2":51},{"t":"text","x":16,"y":56,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":28,"y":56,"text":"1","size":3.2,"anchor":"middle"},{"t":"text","x":40,"y":56,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":52,"y":56,"text":"3","size":3.2,"anchor":"middle"},{"t":"text","x":64,"y":56,"text":"4","size":3.2,"anchor":"middle"},{"t":"arrow","x1":40,"y1":48,"x2":84,"y2":48,"width":1.6,"tone":"ok"},{"t":"dot","x":40,"y":48,"tone":"ok"},{"t":"text","x":32,"y":40,"text":"x ≥ 2：实心圆点，向右画","size":3,"anchor":"middle","tone":"ok"}]}},{"type":"note","title":"","text":"把 x>2 写成「x=2」或「x=3」都是错的：解集是一个范围，必须用不等号或数轴上的一段来表示。"},{"type":"h","text":"抓条件：乘除负数必须变号"},{"type":"p","text":"两边同加同减一个数，大小关系不会变；两边同乘或同除一个正数，关系也不变。可是两边同乘或同除一个负数，先后顺序就整个反过来了：2<3 两边同乘 -1，左边得 -2、右边得 -3，而 -2>-3。这就是性质 3，也是解不等式最容易失分的一步。"},{"type":"figure","figure":{"id":"fig-num-budengshi-s2","title":"两边同乘 −1，大小关系反过来","caption":"2 < 3，但 −2 > −3","view":"wide","alt":"上下两条数轴，上一条标出 2 小于 3，下一条标出负 2 大于负 3，说明两边同乘负 1 后两个数的位置互换、不等号方向改变","prims":[{"t":"text","x":50,"y":7,"text":"两边乘负数，不等号方向反过来","size":3.5,"anchor":"middle","tone":"main"},{"t":"line","x1":12,"y1":22,"x2":86,"y2":22},{"t":"arrow","x1":86,"y1":22,"x2":92,"y2":22},{"t":"line","x1":20,"y1":19,"x2":20,"y2":25},{"t":"line","x1":30,"y1":19,"x2":30,"y2":25},{"t":"line","x1":40,"y1":19,"x2":40,"y2":25},{"t":"line","x1":50,"y1":19,"x2":50,"y2":25},{"t":"line","x1":60,"y1":19,"x2":60,"y2":25},{"t":"line","x1":70,"y1":19,"x2":70,"y2":25},{"t":"line","x1":80,"y1":19,"x2":80,"y2":25},{"t":"text","x":20,"y":29,"text":"−3","size":3,"anchor":"middle"},{"t":"text","x":30,"y":29,"text":"−2","size":3,"anchor":"middle"},{"t":"text","x":40,"y":29,"text":"−1","size":3,"anchor":"middle"},{"t":"text","x":50,"y":29,"text":"0","size":3,"anchor":"middle"},{"t":"text","x":60,"y":29,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":70,"y":29,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":80,"y":29,"text":"3","size":3,"anchor":"middle"},{"t":"line","x1":70,"y1":22,"x2":80,"y2":22,"width":2.4,"tone":"accent"},{"t":"dot","x":70,"y":22,"tone":"accent"},{"t":"dot","x":80,"y":22,"tone":"accent"},{"t":"text","x":78,"y":14,"text":"2 < 3","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":36,"text":"两边同乘 −1，大小关系反过来","size":3.2,"anchor":"middle","tone":"muted"},{"t":"line","x1":12,"y1":46,"x2":86,"y2":46},{"t":"arrow","x1":86,"y1":46,"x2":92,"y2":46},{"t":"line","x1":20,"y1":43,"x2":20,"y2":49},{"t":"line","x1":30,"y1":43,"x2":30,"y2":49},{"t":"line","x1":40,"y1":43,"x2":40,"y2":49},{"t":"line","x1":50,"y1":43,"x2":50,"y2":49},{"t":"line","x1":60,"y1":43,"x2":60,"y2":49},{"t":"line","x1":70,"y1":43,"x2":70,"y2":49},{"t":"line","x1":80,"y1":43,"x2":80,"y2":49},{"t":"text","x":20,"y":53,"text":"−3","size":3,"anchor":"middle"},{"t":"text","x":30,"y":53,"text":"−2","size":3,"anchor":"middle"},{"t":"text","x":40,"y":53,"text":"−1","size":3,"anchor":"middle"},{"t":"text","x":50,"y":53,"text":"0","size":3,"anchor":"middle"},{"t":"text","x":60,"y":53,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":70,"y":53,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":80,"y":53,"text":"3","size":3,"anchor":"middle"},{"t":"line","x1":20,"y1":46,"x2":30,"y2":46,"width":2.4,"tone":"danger"},{"t":"dot","x":20,"y":46,"tone":"danger"},{"t":"dot","x":30,"y":46,"tone":"danger"},{"t":"text","x":24,"y":60,"text":"−2 > −3","size":3.2,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"乘（除）正数方向不变，乘（除）负数方向改变。判断时先看清乘除的数是正是负，负号一出现就立刻把不等号翻过来。"},{"type":"h","text":"建立关系：解集取公共部分"},{"type":"p","text":"不等式组要求每个不等式同时成立，所以解集必须是各个解集的公共部分。把每个解集都画到同一条数轴上，重叠的那一段才是答案；如果没有重叠，不等式组就无解。这也是「同大取大、同小取小」这些口诀的来源。"},{"type":"figure","figure":{"id":"fig-num-budengshi-s3","title":"不等式组的解集是公共部分","caption":"x ≥ 1 与 x < 4 的公共部分是 1 ≤ x < 4","view":"wide","alt":"三条数轴，第一条在 1 处画实心点并向右画表示 x 大于等于 1，第二条在 4 处画空心圈并向左画表示 x 小于 4，第三条在 1 到 4 之间画粗线、左端实心右端空心，表示公共部分 1 小于等于 x 小于 4","prims":[{"t":"text","x":50,"y":7,"text":"不等式组的解集是公共部分","size":3.5,"anchor":"middle","tone":"main"},{"t":"line","x1":12,"y1":20,"x2":72,"y2":20},{"t":"arrow","x1":72,"y1":20,"x2":78,"y2":20},{"t":"line","x1":16,"y1":17,"x2":16,"y2":23},{"t":"line","x1":28,"y1":17,"x2":28,"y2":23},{"t":"line","x1":40,"y1":17,"x2":40,"y2":23},{"t":"line","x1":52,"y1":17,"x2":52,"y2":23},{"t":"line","x1":64,"y1":17,"x2":64,"y2":23},{"t":"text","x":16,"y":27,"text":"0","size":3,"anchor":"middle"},{"t":"text","x":28,"y":27,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":40,"y":27,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":52,"y":27,"text":"3","size":3,"anchor":"middle"},{"t":"text","x":64,"y":27,"text":"4","size":3,"anchor":"middle"},{"t":"arrow","x1":28,"y1":20,"x2":72,"y2":20,"width":1.5,"tone":"ok"},{"t":"dot","x":28,"y":20,"tone":"ok"},{"t":"text","x":88,"y":20,"text":"x ≥ 1","size":3,"anchor":"middle","tone":"ok"},{"t":"line","x1":12,"y1":36,"x2":72,"y2":36},{"t":"arrow","x1":72,"y1":36,"x2":78,"y2":36},{"t":"line","x1":16,"y1":33,"x2":16,"y2":39},{"t":"line","x1":28,"y1":33,"x2":28,"y2":39},{"t":"line","x1":40,"y1":33,"x2":40,"y2":39},{"t":"line","x1":52,"y1":33,"x2":52,"y2":39},{"t":"line","x1":64,"y1":33,"x2":64,"y2":39},{"t":"text","x":16,"y":43,"text":"0","size":3,"anchor":"middle"},{"t":"text","x":28,"y":43,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":40,"y":43,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":52,"y":43,"text":"3","size":3,"anchor":"middle"},{"t":"text","x":64,"y":43,"text":"4","size":3,"anchor":"middle"},{"t":"arrow","x1":64,"y1":36,"x2":12,"y2":36,"width":1.5,"tone":"accent"},{"t":"dot","x":64,"y":36,"hollow":true,"tone":"accent"},{"t":"text","x":88,"y":36,"text":"x < 4","size":3,"anchor":"middle","tone":"accent"},{"t":"line","x1":12,"y1":52,"x2":72,"y2":52},{"t":"arrow","x1":72,"y1":52,"x2":78,"y2":52},{"t":"line","x1":16,"y1":49,"x2":16,"y2":55},{"t":"line","x1":28,"y1":49,"x2":28,"y2":55},{"t":"line","x1":40,"y1":49,"x2":40,"y2":55},{"t":"line","x1":52,"y1":49,"x2":52,"y2":55},{"t":"line","x1":64,"y1":49,"x2":64,"y2":55},{"t":"text","x":16,"y":59,"text":"0","size":3,"anchor":"middle"},{"t":"text","x":28,"y":59,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":40,"y":59,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":52,"y":59,"text":"3","size":3,"anchor":"middle"},{"t":"text","x":64,"y":59,"text":"4","size":3,"anchor":"middle"},{"t":"line","x1":28,"y1":52,"x2":64,"y2":52,"width":2.6,"tone":"main"},{"t":"dot","x":28,"y":52,"tone":"main"},{"t":"dot","x":64,"y":52,"hollow":true,"tone":"main"},{"t":"text","x":88,"y":52,"text":"1 ≤ x < 4","size":3,"anchor":"middle","tone":"main"}]}},{"type":"note","title":"","text":"如果两个解集没有重叠部分（如 x>3 与 x<1），不等式组无解，不能硬填一个范围。"},{"type":"h","text":"换个情境：把「至少、不超过」翻成符号"},{"type":"p","text":"实际问题里的关键词要先翻译成不等号：至少、不少于用 ≥，最多、不超过用 ≤，超过用 >，不足、低于用 <。翻好之后按「解出范围 → 结合整数要求取值 → 端点回代检验」三步走，方案才不会漏。"},{"type":"figure","figure":{"id":"fig-num-budengshi-s4","title":"关键词与不等号的对应","caption":"先把关键词圈出来再列不等式","view":"wide","alt":"一张对照表，至少、不少于对应大于等于号，最多、不超过对应小于等于号，超过、多于对应大于号，不足、低于对应小于号，下方举出 A 型不少于 2 台且总费用不超过 36000 元推出 2 小于等于 x 小于等于 6，共 5 种整数方案","prims":[{"t":"text","x":50,"y":7,"text":"关键词与不等号的对应","size":3.5,"anchor":"middle","tone":"main"},{"t":"rect","x":8,"y":14,"w":40,"h":12,"tone":"ok"},{"t":"text","x":28,"y":20,"text":"至少、不少于 → ≥","size":3,"anchor":"middle","tone":"ok"},{"t":"rect","x":52,"y":14,"w":40,"h":12,"tone":"ok"},{"t":"text","x":72,"y":20,"text":"最多、不超过 → ≤","size":3,"anchor":"middle","tone":"ok"},{"t":"rect","x":8,"y":28,"w":40,"h":12,"tone":"danger"},{"t":"text","x":28,"y":34,"text":"超过、多于 → >","size":3,"anchor":"middle","tone":"danger"},{"t":"rect","x":52,"y":28,"w":40,"h":12,"tone":"danger"},{"t":"text","x":72,"y":34,"text":"不足、低于 → <","size":3,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":47,"text":"例：x ≥ 2 且 1000x + 30000 ≤ 36000，得 2 ≤ x ≤ 6","size":3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":57,"text":"x 取整数得 2、3、4、5、6，共 5 种方案","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"「不超过」是 ≤ 而不是 <，「至少」是 ≥ 而不是 >；带不带等号直接决定端点方案算不算在内。"},{"type":"h","text":"核心概念"},{"type":"p","text":"不等式：用符号「<」「>」「≤」「≥」「≠」连接的式子叫不等式，它表示两个量之间的大小关系。关键点：等式表示相等，不等式表示范围。"},{"type":"p","text":"不等式的解与解集：能使不等式成立的未知数的值叫不等式的解；所有解组成的集合叫不等式的解集。关键点：解集通常是一个范围，不能用某几个数代替，在数轴上用一段线表示。"},{"type":"p","text":"不等式的基本性质：性质 1：两边加（或减）同一个数（或式子），不等号方向不变。性质 2：两边乘（或除以）同一个正数，方向不变。性质 3：两边乘（或除以）同一个负数，不等号方向改变。性质 3 是不等式与等式最大的区别。"},{"type":"p","text":"一元一次不等式：只含一个未知数，未知数的次数是 1，且不等号两边都是整式的不等式叫一元一次不等式，如 2x-3>5。它的解集是一个范围，一般形式为 ax+b>0 或 ax+b<0（a≠ 0）。"},{"type":"p","text":"一元一次不等式组：几个含有同一个未知数的一元一次不等式合在一起组成一元一次不等式组。各个不等式解集的公共部分就是不等式组的解集；若没有公共部分，则不等式组无解。"},{"type":"p","text":"数轴上表示解集：大于向右画、小于向左画，含等号（≥、≤）用实心圆点，不含等号（>、<）用空心圆圈。这是把解集直观化的关键工具。"},{"type":"note","title":"中考考法","text":"不等式基本性质与变号判断\n选择题判断变形是否一定成立，选项常含字母乘数，踩分点是乘除负数必须反向，字母正负不明确时要分类讨论或举反例。"},{"type":"note","title":"中考考法","text":"一元一次不等式（组）的解法与数轴表示\n解答题求解集、在数轴上表示并写出整数解，踩分点是空心与实心分清，不等式组画数轴取各解集的公共部分。"},{"type":"note","title":"中考考法","text":"用不等式（组）解决方案设计与最值问题\n以进货、租车、物资分配为情境求整数方案数与最省费用，踩分点是「至少、不超过」翻译准确，端点回代验算后结合整数要求取值。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["不等式性质 1","a>b\\ ⇒\\ a± c>b± c","两边加或减同一个数（式），不等号方向不变。"],["不等式性质 2","a>b,\\ c>0\\ ⇒\\ ac>bc","乘或除以同一个正数，不等号方向不变，如两边乘 (1)/(2) 后仍是 >。"],["不等式性质 3","a>b,\\ c<0\\ ⇒\\ ac<bc","乘或除以同一个负数，不等号方向必须改变，如 -2x>6 解得 x<-3。这是最高频的失分点。"],["一元一次不等式的一般形式","ax+b>0\\ (a≠ 0)","解集可写为 x>-(b)/(a)（a>0 时）或 x<-(b)/(a)（a<0 时），关键看除以的数的正负。"],["不等式组解集的四种情形","设 a<b：cases x>a \\\\ x>b endcases 的解集为 x>b（同大取大）；cases x<a \\\\ x<b endcases 的解集为 x<a（同小取小）；cases x>a \\\\ x<b endcases 的解集为 a<x<b（大小小大取中间）；cases x<a \\\\ x>b endcases 无解（大大小小无解）。","口诀要配合数轴使用，端点是否包含取决于原不等号是否带等号。"]]},{"type":"note","title":"例题","text":"解不等式：(2x-1)/(3)-(3x+2)/(6)≤ 1，并把解集在数轴上表示出来。"},{"type":"figure","figure":{"id":"fig-num-budengshi-e1","title":"解集 x≤10 的数轴表示","caption":"10 处画实心圆点，再向左画线","view":"wide","alt":"数轴上 10 处画实心圆点，从 0 到 10 的整段用粗线标出并写有 x 小于等于 10，表示解集是所有不大于 10 的数","prims":[{"t":"line","x1":14,"y1":38,"x2":90,"y2":38},{"t":"arrow","x1":90,"y1":38,"x2":96,"y2":38},{"t":"line","x1":14,"y1":35,"x2":14,"y2":41},{"t":"line","x1":21,"y1":35,"x2":21,"y2":41},{"t":"line","x1":28,"y1":35,"x2":28,"y2":41},{"t":"line","x1":35,"y1":35,"x2":35,"y2":41},{"t":"line","x1":42,"y1":35,"x2":42,"y2":41},{"t":"line","x1":49,"y1":35,"x2":49,"y2":41},{"t":"line","x1":56,"y1":35,"x2":56,"y2":41},{"t":"line","x1":63,"y1":35,"x2":63,"y2":41},{"t":"line","x1":70,"y1":35,"x2":70,"y2":41},{"t":"line","x1":77,"y1":35,"x2":77,"y2":41},{"t":"line","x1":84,"y1":35,"x2":84,"y2":41},{"t":"text","x":14,"y":48,"text":"0","size":3.4},{"t":"text","x":28,"y":48,"text":"2","size":3.4},{"t":"text","x":42,"y":48,"text":"4","size":3.4},{"t":"text","x":56,"y":48,"text":"6","size":3.4},{"t":"text","x":70,"y":48,"text":"8","size":3.4},{"t":"text","x":84,"y":48,"text":"10","size":3.4},{"t":"line","x1":14,"y1":38,"x2":84,"y2":38,"width":3.2,"tone":"accent"},{"t":"dot","x":84,"y":38,"tone":"accent"},{"t":"text","x":55,"y":26,"text":"x≤10","size":3.6,"tone":"accent"},{"t":"text","x":49,"y":56,"text":"实心圆点，向左画","size":3,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["去分母：两边同乘 6（正数，不等号方向不变），注意常数项 1 也要乘，分子要加括号。","得 2(2x-1)-(3x+2)≤ 6。","去括号：4x-2-3x-2≤ 6。","合并同类项：x-4≤ 6。","移项得 x≤ 10。","在数轴上，10 处画实心圆点，向左画线（写成 x≤ 10）。"]},{"type":"p","text":"答案：x≤ 10"},{"type":"note","title":"方法小结","text":"本题两边同乘的是正数 6，不等号方向不变；但去括号时 -(3x+2)=-3x-2 两项都要变号，这是最容易漏的地方。若某一步两边同乘或除以负数，一定要立刻把不等号反向。"},{"type":"note","title":"例题","text":"解不等式组：cases 2x-1>3 \\\\ 3x-2≤ 10-x endcases。"},{"type":"figure","figure":{"id":"fig-m-num-budengshi-shuzhou-1","title":"不等式组解集的数轴表示","caption":"x>2 与 x≤3 的公共部分是 2<x≤3","view":"wide","alt":"数轴上 2 处是空心圆圈向右画线表示 x 大于 2，3 处是实心圆点向左画线表示 x 小于等于 3，两条线重叠在 2 到 3 之间即为公共部分","prims":[{"t":"line","x1":10,"y1":50,"x2":90,"y2":50},{"t":"arrow","x1":90,"y1":50,"x2":94,"y2":50},{"t":"line","x1":10,"y1":47,"x2":10,"y2":53},{"t":"line","x1":26,"y1":47,"x2":26,"y2":53},{"t":"line","x1":42,"y1":47,"x2":42,"y2":53},{"t":"line","x1":58,"y1":47,"x2":58,"y2":53},{"t":"line","x1":74,"y1":47,"x2":74,"y2":53},{"t":"line","x1":90,"y1":47,"x2":90,"y2":53},{"t":"text","x":10,"y":60,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":26,"y":60,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":42,"y":60,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":58,"y":60,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":74,"y":60,"text":"4","size":3.4,"anchor":"middle"},{"t":"dot","x":42,"y":50,"hollow":true,"tone":"accent"},{"t":"arrow","x1":42,"y1":34,"x2":88,"y2":34,"tone":"accent"},{"t":"text","x":60,"y":29,"text":"x>2","size":3.4,"tone":"accent","anchor":"middle"},{"t":"dot","x":58,"y":50,"tone":"main"},{"t":"arrow","x1":58,"y1":42,"x2":14,"y2":42,"tone":"main"},{"t":"text","x":30,"y":38,"text":"x≤3","size":3.4,"tone":"main","anchor":"middle"},{"t":"line","x1":42,"y1":50,"x2":58,"y2":50,"width":4,"tone":"ok"},{"t":"text","x":50,"y":70,"text":"公共部分：2<x≤3","size":3.6,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["解第一个不等式：2x-1>3，移项得 2x>4，解得 x>2。","解第二个不等式：3x-2≤ 10-x，移项得 3x+x≤ 10+2，即 4x≤ 12，解得 x≤ 3。","在数轴上分别画出 x>2（2 处空心圆点向右）和 x≤ 3（3 处实心圆点向左）。","取公共部分：两个解集重叠的范围是 2<x≤ 3。","所以不等式组的解集为 2<x≤ 3。"]},{"type":"p","text":"答案：2<x≤ 3"},{"type":"note","title":"方法小结","text":"不等式组的解集是「公共部分」，必须画数轴取交集，不能凭口诀硬套。注意端点：x>2 不含 2（空心），x≤ 3 含 3（实心），所以结果是 2<x≤ 3。"},{"type":"note","title":"例题","text":"某次数学竞赛共 20 道题，答对一题得 5 分，答错或不答一题倒扣 1 分。小明得分超过 80 分，他至少答对多少道题？"},{"type":"figure","figure":{"id":"fig-num-budengshi-e3","title":"求出范围后要结合实际取整数","caption":"答对 16 题只有 76 分不够，17 题得 82 分才行","view":"wide","alt":"由 6x 减 20 大于 80 解得 x 大于 16.67，检验答对 16 题得 76 分不足 80 分，答对 17 题得 82 分超过 80 分，所以至少答对 17 题","prims":[{"t":"text","x":50,"y":8,"text":"由 6x−20>80 解得 x>16.67","size":3.2},{"t":"rect","x":6,"y":15,"w":22,"h":14},{"t":"text","x":17,"y":22,"text":"答对 16 题","size":3},{"t":"arrow","x1":28,"y1":22,"x2":38,"y2":22},{"t":"rect","x":38,"y":15,"w":24,"h":14},{"t":"text","x":50,"y":22,"text":"5×16−4=76","size":2.8},{"t":"text","x":86,"y":22,"text":"不足 80，不行","size":3,"tone":"danger"},{"t":"rect","x":6,"y":34,"w":22,"h":14},{"t":"text","x":17,"y":41,"text":"答对 17 题","size":3},{"t":"arrow","x1":28,"y1":41,"x2":38,"y2":41},{"t":"rect","x":38,"y":34,"w":24,"h":14},{"t":"text","x":50,"y":41,"text":"5×17−3=82","size":2.8},{"t":"text","x":86,"y":41,"text":"超过 80，可以","size":3,"tone":"ok"},{"t":"text","x":50,"y":56,"text":"题数要取整数，所以至少 17 题","size":3.2,"tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["设小明答对 x 道题，则答错或不答的有 (20-x) 道。","答对得分 5x，扣分 (20-x)，总分为 5x-(20-x)。","由「得分超过 80 分」列不等式：5x-(20-x)>80。","化简：5x-20+x>80，即 6x-20>80。","移项得 6x>100，两边同除以 6（正数，方向不变）得 x>(100)/(6)≈ 16.67。","因为题数必须是整数，所以 x≥ 17；检验：答对 17 题时得分 5× 17-3=82>80，答对 16 题时得分 5× 16-4=76<80。"]},{"type":"p","text":"答案：至少答对 17 道题"},{"type":"note","title":"方法小结","text":"「至少」「最多」「超过」「不超过」要准确翻译成 ≥、≤、>、<。求出范围后必须结合实际意义取整，并检验端点两侧是否真的满足题意。"},{"type":"note","title":"例题","text":"关于 x 的不等式 2x-a≤ 3 的解集在数轴上表示为 x≤ 2，求 a 的值。"},{"type":"figure","figure":{"id":"fig-num-budengshi-e4","title":"两个解集的端点必须相同","caption":"含参数解出的端点与题给端点相等，就能求出 a","view":"wide","alt":"左边框是含参数解出的解集 x 小于等于 a 加 3 除以 2，右边框是题目给出的解集 x 小于等于 2，两个端点相等得 a 加 3 除以 2 等于 2，解得 a 等于 1","prims":[{"t":"text","x":50,"y":11,"text":"端点相同","size":3,"tone":"muted"},{"t":"rect","x":6,"y":20,"w":34,"h":18},{"t":"text","x":23,"y":26,"text":"含参数解出","size":3,"tone":"muted"},{"t":"text","x":23,"y":33,"text":"x ≤ (a+3)/2","size":3},{"t":"rect","x":60,"y":20,"w":34,"h":18},{"t":"text","x":77,"y":26,"text":"题给解集","size":3,"tone":"muted"},{"t":"text","x":77,"y":33,"text":"x ≤ 2","size":3},{"t":"arrow","x1":40,"y1":29,"x2":47,"y2":29,"tone":"main"},{"t":"arrow","x1":60,"y1":29,"x2":53,"y2":29,"tone":"main"},{"t":"text","x":50,"y":46,"text":"(a+3)/2 = 2","size":3.2},{"t":"text","x":50,"y":57,"text":"解得 a = 1","size":3.6,"tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["先把 a 当作已知数解不等式：移项得 2x≤ a+3。","两边同除以正数 2，不等号方向不变，解集为 x≤ (a+3)/(2)。","题目给出的解集是 x≤ 2，两个解集的端点必须相同，故 (a+3)/(2)=2。","解得 a+3=4，即 a=1。"]},{"type":"p","text":"答案：a=1"},{"type":"note","title":"方法小结","text":"「已知解集反求参数」的做法是先正常解出含参数的解集，再让端点与题给端点对应相等。端点能否取到（实心还是空心）要与原不等号核对，本题两处都带等号，直接相等即可。"},{"type":"note","title":"例题","text":"某公司计划购买 A、B 两种型号的电脑共 10 台，A 型每台 4000 元，B 型每台 3000 元。要求购买 A 型不少于 2 台，且总费用不超过 36000 元。共有哪几种购买方案？其中费用最低的方案花费多少元？"},{"type":"figure","figure":{"id":"fig-num-budengshi-e5","title":"A 型台数被限制在 2 到 6 之间","caption":"x 只能取 2、3、4、5、6 五种整数","view":"wide","alt":"数轴上 2 与 6 处都画实心圆点，2 到 6 之间用粗线标出，中间还有 3、4、5 三个整数点，表示 A 型台数可取 2、3、4、5、6 共五种方案","prims":[{"t":"line","x1":12,"y1":38,"x2":86,"y2":38},{"t":"arrow","x1":86,"y1":38,"x2":93,"y2":38},{"t":"line","x1":14,"y1":35,"x2":14,"y2":41},{"t":"line","x1":24,"y1":35,"x2":24,"y2":41},{"t":"line","x1":34,"y1":35,"x2":34,"y2":41},{"t":"line","x1":44,"y1":35,"x2":44,"y2":41},{"t":"line","x1":54,"y1":35,"x2":54,"y2":41},{"t":"line","x1":64,"y1":35,"x2":64,"y2":41},{"t":"line","x1":74,"y1":35,"x2":74,"y2":41},{"t":"line","x1":84,"y1":35,"x2":84,"y2":41},{"t":"text","x":14,"y":48,"text":"0","size":3.4},{"t":"text","x":24,"y":48,"text":"1","size":3.4},{"t":"text","x":34,"y":48,"text":"2","size":3.4},{"t":"text","x":44,"y":48,"text":"3","size":3.4},{"t":"text","x":54,"y":48,"text":"4","size":3.4},{"t":"text","x":64,"y":48,"text":"5","size":3.4},{"t":"text","x":74,"y":48,"text":"6","size":3.4},{"t":"text","x":84,"y":48,"text":"7","size":3.4},{"t":"line","x1":34,"y1":38,"x2":74,"y2":38,"width":3.2,"tone":"accent"},{"t":"dot","x":34,"y":38,"tone":"accent"},{"t":"dot","x":44,"y":38,"tone":"accent"},{"t":"dot","x":54,"y":38,"tone":"accent"},{"t":"dot","x":64,"y":38,"tone":"accent"},{"t":"dot","x":74,"y":38,"tone":"accent"},{"t":"text","x":54,"y":26,"text":"2≤x≤6","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"整数解：2、3、4、5、6 共 5 种","size":3,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设购买 A 型 x 台，则 B 型为 (10-x) 台。由「A 型不少于 2 台」得 x≥ 2。","总费用为 4000x+3000(10-x)=1000x+30000，由「不超过 36000 元」列不等式：1000x+30000≤ 36000。","解得 x≤ 6，结合 x≥ 2 且台数为整数，得 x=2,3,4,5,6，共 5 种方案。","费用 1000x+30000 随 x 增大而增大，故 x=2 时费用最低。","最低费用为 1000× 2+30000=32000（元），此时买 A 型 2 台、B 型 8 台。"]},{"type":"p","text":"答案：共有 5 种方案（A 型分别买 2、3、4、5、6 台）；最低费用为 32000 元"},{"type":"note","title":"方法小结","text":"方案题把两个限制（台数下限、费用上限）合在一起得到整数范围，再逐个列出方案。求最省费用不用算遍五种，利用费用随 x 增减的单调性直接取端点即可。"},{"type":"list","title":"易错点","items":["不等式两边同乘或同除以负数时忘记改变不等号方向，如由 $-3x>6$ 写成 $x>-2$。正确结果是 $x<-2$。","去分母时漏乘不含分母的项，或分子是多项式却不加括号，如把 $\\frac{3x+2}{6}$ 去分母写成 $3x+2$ 而不是 $(3x+2)$。","数轴上实心点与空心圈混用：$\\leq$、$\\geq$ 用实心点，$<$、$>$ 用空心圈。","解不等式组不画数轴，凭印象取范围，端点错漏。","把不等式的解集写成单个数值，如把 $x>5$ 写成 $x=5$。解集是一个范围，必须用不等号表示。","实际问题中求出范围后忘记取整数解或检验端点，如人数、题数必须为正整数。"]},{"type":"list","title":"解题方法","items":["解一元一次不等式的步骤与解方程相同（去分母、去括号、移项、合并同类项、系数化为 1），但要牢记「乘除负数变方向」。","数轴法求不等式组解集：每个不等式画一条，公共重叠处即为解集，端点用实心或空心区分。","求整数解的问题：先解出解集范围，再在范围内数出整数，端点是否包含要用原不等式验算。","关键词翻译：至少 ≥、最多 ≤、超过 >、不足 <、不超过 ≤。列出不等式前先把关键词圈出来。","检验时取解集内、解集外各一个数代入原不等式，确认方向正确。"]}],"questions":[{"id":"m-num-budengshi-q1","type":"choice","stem":"若 a>b，则下列不等式一定成立的是（ ）","answer":"C","explain":"C 正确：由 a>b 两边同除以 -2，不等号改变方向，得 -(a)/(2)<-(b)/(2)。A 错：c 的正负未知，若 c≤ 0 则不成立。B 错：两边同减 2 方向不变，应为 a-2>b-2。D 错：取 a=1、b=-3 时 a>b 但 a²=1<9=b²。","options":["ac>bc","a-2<b-2","-(a)/(2)<-(b)/(2)","a²>b²"],"difficulty":2,"tags":["不等式性质","符号","概念辨析"]},{"id":"m-num-budengshi-q2","type":"choice","stem":"不等式 2(x-1)>x+3 的解集是（ ）","answer":"A","explain":"去括号得 2x-2>x+3；移项得 2x-x>3+2；合并同类项得 x>5。检验：取 x=6，左边 =2× 5=10，右边 =9，10>9 成立，故选 A。","options":["x>5","x<5","x>1","x<1"],"difficulty":1,"tags":["解不等式","去括号"]},{"id":"m-num-budengshi-q3","type":"fill","stem":"解不等式 -3x+1≤ 7，得 x（ ）。（填「大于等于/小于等于某个数」的答案，如 x≥1）","answer":"x≥-2|x>=-2","explain":"移项得 -3x≤ 7-1，即 -3x≤ 6。两边同除以 -3，因为除数是负数，不等号方向改变，得 x≥ -2。检验：取 x=-1，左边 =-3×(-1)+1=4≤ 7 成立；取 x=-3，左边 =10>7 不成立，说明解集正确。","difficulty":2,"tags":["解不等式","变号","易错"]},{"id":"m-num-budengshi-q4","type":"fill","stem":"不等式组 cases x+1>2 \\\\ x-1≤ 2 endcases 的解集是（ ）。（如 1<x≤3）","answer":"1<x≤3","explain":"解第一个不等式得 x>1；解第二个不等式得 x≤ 3。在数轴上取公共部分：x>1 是 1 处空心向右，x≤ 3 是 3 处实心向左，重叠部分为 1<x≤ 3。检验：取 x=2，两个不等式都成立；取 x=3，3+1=4>2 成立、3-1=2≤ 2 成立，端点 3 包含在内。","difficulty":2,"tags":["不等式组","数轴","解集"]},{"id":"m-num-budengshi-q5","type":"short","stem":"某小组学生分配一批树苗：若每人分 3 棵，则还剩 10 棵；若每人分 4 棵，则最后一人分到的树苗不足 3 棵，但至少分到 1 棵。问这个小组有多少名学生，这批树苗共有多少棵？（要求设未知数、列不等式组、完整求解并检验）","answer":"设学生有 $x$ 人，则树苗有 $(3x+10)$ 棵。由最后一人分到 $14-x$ 棵，得 $1\\leq 14-x<3$，解得 $11<x\\leq 13$，故 $x=12$ 或 $x=13$：12 人时树苗 46 棵，13 人时树苗 49 棵。","explain":"设学生有 x 人，则树苗总数是每人 3 棵后的剩余，即 3x+10 棵。若每人分 4 棵，前 (x-1) 人共分掉 4(x-1) 棵，最后一人分到 3x+10-4(x-1)=14-x 棵。由「不足 3 棵」得 14-x<3，即 x>11；由「至少分到 1 棵」得 14-x≥ 1，即 x≤ 13。合起来是 11<x≤ 13，x 为正整数，所以 x=12 或 x=13。当 x=12 时树苗有 3× 12+10=46 棵，检验：每人 3 棵分掉 36 棵剩 10 棵；每人 4 棵时前 11 人分 44 棵，最后一人分 46-44=2 棵，不足 3 棵且不少于 1 棵，符合题意。当 x=13 时树苗有 3× 13+10=49 棵，检验：每人 4 棵时前 12 人分 48 棵，最后一人分 1 棵，同样符合题意。若 x=11，最后一人分 14-11=3 棵，不满足「不足 3 棵」；若 x=14，最后一人分 0 棵，不满足「至少分到 1 棵」，故只有上述两解。","difficulty":3,"tags":["不等式组应用","整数解","建模"],"rubric":["正确设未知数并写出树苗总数的代数式 3x+10","正确写出最后一人分到的棵数 14-x（这一步是本题关键）","列出不等式组 1≤ 14-x<3","解得 11<x≤ 13 并说明 x 取正整数，得 x=12 或 x=13","分别算出对应的树苗棵数 46 棵与 49 棵，并有检验或作答语句"]},{"id":"m-num-budengshi-z1","type":"choice","stem":"不等式组 cases x+1>0 \\\\ 2x-6≤ 0 endcases 的解集是（ ）","answer":"A","explain":"解第一个不等式得 x>-1；解第二个不等式：2x≤ 6，即 x≤ 3。在数轴上取公共部分，-1 处空心向右、3 处实心向左，重叠范围为 -1<x≤ 3，故选 A。D 项把两个端点的取舍都弄反了。","options":["-1<x≤ 3","x<-1","x≤ 3","-1≤ x<3"],"difficulty":2,"tags":["不等式组","数轴","解集"]},{"id":"m-num-budengshi-z2","type":"short","stem":"若关于 x 的不等式组 cases x>a \\\\ x>2 endcases 的解集是 x>2，求 a 的取值范围，并说明理由（含等号能否取到的讨论）。","answer":"由「同大取大」，要使解集为 $x>2$，必须有 $a\\leq 2$。","explain":"两个不等式都是「大于」型，按照「同大取大」，不等式组的解集是 x>max(a,2)。题给解集为 x>2，说明两者中较大的临界值是 2，即 a 不能大于 2，所以 a≤ 2。端点要单独讨论：当 a=2 时，不等式组变为 cases x>2 \\\\ x>2 endcases，解集仍是 x>2，符合题意，因此等号可以取到；若 a>2（如 a=3），解集就变成 x>3，与题给解集不符。","difficulty":3,"tags":["不等式组","解集","概念辨析"],"rubric":["由「同大取大」判断出必须满足 a≤ 2","单独讨论 a=2 的情形，说明此时解集仍为 x>2、等号能取到","说明 a>2 时解集变为 x>a，与题意不符"]}]},{"id":"m-num-zhengshi-chengfa","title":"整式的乘法与因式分解","subtitle":"人教版八上 · 第16章 整式的乘法、第17章 因式分解","grade":"8a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八上 · 第16章 整式的乘法、第17章 因式分解"},{"type":"note","title":"一句话概述","text":"掌握幂的四条运算性质、整式乘法法则与乘法公式，理解因式分解与整式乘法互逆。"},{"type":"h","text":"先分清：四条幂的运算各管什么"},{"type":"p","text":"幂的运算看着都是「指数在变」，但原因完全不同。同底数幂相乘是几个相同底数连乘，所以指数相加；幂的乘方是若干组连乘再整体相乘，所以指数相乘。先把运算类型认准，再决定指数怎么变，就不会把 a²· a³ 算成 a⁶。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-s1","title":"幂的四条运算各管什么","caption":"先分清是哪一种运算，再决定指数怎么变","view":"wide","alt":"四张对照卡：同底数幂相乘指数相加得 a 的五次方，幂的乘方指数相乘得 a 的六次方，同底数幂相除指数相减得 a 的三次方，积的乘方各因式分别乘方得 a 立方 b 立方","prims":[{"t":"rect","x":4,"y":6,"w":44,"h":22,"tone":"accent"},{"t":"text","x":26,"y":14,"text":"同底数幂相乘：指数相加","size":3,"tone":"accent"},{"t":"text","x":26,"y":22.5,"text":"a²·a³ = a⁵","size":3.4},{"t":"rect","x":52,"y":6,"w":44,"h":22,"tone":"ok"},{"t":"text","x":74,"y":14,"text":"幂的乘方：指数相乘","size":3,"tone":"ok"},{"t":"text","x":74,"y":22.5,"text":"(a²)³ = a⁶","size":3.4},{"t":"rect","x":4,"y":34,"w":44,"h":22,"tone":"danger"},{"t":"text","x":26,"y":42,"text":"同底数幂相除：指数相减","size":3,"tone":"danger"},{"t":"text","x":26,"y":50.5,"text":"a⁵ ÷ a² = a³","size":3.4},{"t":"rect","x":52,"y":34,"w":44,"h":22},{"t":"text","x":74,"y":42,"text":"积的乘方：各自乘方","size":3},{"t":"text","x":74,"y":50.5,"text":"(ab)³ = a³b³","size":3.4}]}},{"type":"h","text":"看结构：整式乘法就是逐项相乘"},{"type":"p","text":"多项式乘多项式并不需要背口诀，它的依据只是乘法分配律：前一个括号里的每一项，都要乘后一个括号里的每一项。用长方形面积来看最直观——把大长方形按 a 与 b、c 与 d 切成四块，四块面积之和就是乘积，一块都不会漏。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-s2","title":"整式乘法就是分配律逐项相乘","caption":"大长方形分成四块，面积就是四个乘积的和","view":"square","alt":"边长分别为 a 加 b 与 c 加 d 的大长方形被分成四块，面积分别是 ac、bc、ad、bd，说明 (a+b)(c+d) 等于这四个乘积之和","prims":[{"t":"rect","x":14,"y":20,"w":44,"h":36,"fill":true,"tone":"accent"},{"t":"text","x":36,"y":38,"text":"ac","size":4},{"t":"rect","x":58,"y":20,"w":28,"h":36,"fill":true,"tone":"ok"},{"t":"text","x":72,"y":38,"text":"bc","size":4},{"t":"rect","x":14,"y":56,"w":44,"h":24,"fill":true,"tone":"muted"},{"t":"text","x":36,"y":68,"text":"ad","size":4},{"t":"rect","x":58,"y":56,"w":28,"h":24,"fill":true,"tone":"danger"},{"t":"text","x":72,"y":68,"text":"bd","size":4},{"t":"text","x":36,"y":15,"text":"a","size":3.4},{"t":"text","x":72,"y":15,"text":"b","size":3.4},{"t":"text","x":9,"y":38,"text":"c","size":3.4},{"t":"text","x":9,"y":68,"text":"d","size":3.4},{"t":"text","x":50,"y":92,"text":"(a+b)(c+d) = ac + ad + bc + bd","size":3.4}]}},{"type":"h","text":"建立关系：两个乘法公式从哪来"},{"type":"p","text":"平方差与完全平方都不是新东西，把括号逐项乘开就能得到。(a+b)² 展开后有两块 ab 完全相同，合并成 2ab，所以正方形被分成一块 a²、两块 ab、一块 b²。记住中间那一块是自己乘出来的，就不会把 (a+b)² 写成 a²+b²。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-s3","title":"完全平方公式的正方形分割","caption":"(a+b)² 展开成一块 a²、两块 ab、一块 b²","view":"square","alt":"边长为 a 加 b 的大正方形分成四块：一块边长 a 的正方形面积 a 平方，两块 a 乘 b 的长方形，一块边长 b 的正方形面积 b 平方，说明 (a+b) 的平方等于 a 平方加 2ab 加 b 平方","prims":[{"t":"rect","x":14,"y":18,"w":46,"h":46,"fill":true,"tone":"accent"},{"t":"text","x":37,"y":41,"text":"a²","size":4},{"t":"rect","x":60,"y":18,"w":26,"h":46,"fill":true,"tone":"ok"},{"t":"text","x":73,"y":41,"text":"ab","size":4},{"t":"rect","x":14,"y":64,"w":46,"h":26,"fill":true,"tone":"ok"},{"t":"text","x":37,"y":77,"text":"ab","size":4},{"t":"rect","x":60,"y":64,"w":26,"h":26,"fill":true,"tone":"danger"},{"t":"text","x":73,"y":77,"text":"b²","size":4},{"t":"text","x":37,"y":12,"text":"a","size":3.4},{"t":"text","x":73,"y":12,"text":"b","size":3.4},{"t":"text","x":9,"y":41,"text":"a","size":3.4},{"t":"text","x":9,"y":77,"text":"b","size":3.4},{"t":"text","x":50,"y":96,"text":"(a+b)² = a² + 2ab + b²","size":3.4}]}},{"type":"h","text":"换个方向：因式分解走回去"},{"type":"p","text":"因式分解就是把整式乘法倒过来走：整式乘法把积展开成和，因式分解把和化回积。所以检验分解对不对，最稳的办法就是把结果乘开看看能否还原。对于二次三项式，十字相乘就是在找两个数，使它们的乘积等于常数项、和等于一次项系数。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-s4","title":"十字相乘：拆常数项、凑一次项","caption":"把 x²−5x+6 拆成 (x−2)(x−3)","view":"square","alt":"左边两行分别写 x 与 x，右边两行分别写负 2 与负 3，两条对角线交叉相乘，交叉相乘的和负 2x 加负 3x 等于负 5x 正好是一次项，负 2 乘负 3 等于 6 正好是常数项","prims":[{"t":"text","x":50,"y":10,"text":"把 x² − 5x + 6 分解","size":3.4},{"t":"text","x":18,"y":30,"text":"x","size":4.2},{"t":"text","x":46,"y":30,"text":"−2","size":4.2},{"t":"text","x":18,"y":56,"text":"x","size":4.2},{"t":"text","x":46,"y":56,"text":"−3","size":4.2},{"t":"line","x1":24,"y1":26,"x2":40,"y2":60,"tone":"accent"},{"t":"line","x1":40,"y1":26,"x2":24,"y2":60,"tone":"accent"},{"t":"text","x":58,"y":30,"text":"−2x − 3x = −5x","size":3.2,"anchor":"start"},{"t":"text","x":58,"y":40,"text":"正好是一次项","size":3,"tone":"ok","anchor":"start"},{"t":"text","x":58,"y":56,"text":"(−2)×(−3) = 6","size":3.2,"anchor":"start"},{"t":"text","x":58,"y":66,"text":"正好是常数项","size":3,"tone":"ok","anchor":"start"},{"t":"text","x":50,"y":88,"text":"所以 x²−5x+6 = (x−2)(x−3)","size":3.4,"tone":"ok"}]}},{"type":"h","text":"核心概念"},{"type":"p","text":"同底数幂的乘法：同底数幂相乘，底数不变，指数相加：a^(m)· a^(n)=a^(m+n)（m、n 为正整数）。关键点：只有底数相同才能用这条性质，a²· b³ 不能再化简。"},{"type":"p","text":"幂的乘方与积的乘方：幂的乘方，底数不变，指数相乘：(a^(m))^(n)=a^(mn)；积的乘方，等于把积的每一个因式分别乘方再相乘：(ab)^(n)=a^(n)b^(n)。关键点：(a²)³=a⁶ 与 a²· a³=a⁵ 完全不同。"},{"type":"p","text":"同底数幂的除法与零指数幂：同底数幂相除，底数不变，指数相减：a^(m)÷ a^(n)=a^(m-n)（a≠ 0，m>n）；规定 a⁰=1（a≠ 0）。关键点：底数不能为 0，0⁰ 无意义。"},{"type":"p","text":"整式的乘法法则：单项式乘单项式：系数相乘、同底数幂相乘，其余字母连同指数照写。单项式乘多项式与多项式乘多项式都依据乘法分配律展开，多项式乘多项式时每一项都要乘到另一个多项式的每一项。"},{"type":"p","text":"平方差公式：两个数的和与这两个数的差的积，等于这两个数的平方差：(a+b)(a-b)=a²-b²。关键点：识别特征是「两项、其中一项符号相同、另一项符号相反」。"},{"type":"p","text":"完全平方公式：两数和（或差）的平方，等于它们的平方和加上（或减去）它们积的 2 倍：(a± b)²=a²± 2ab+b²。关键点：中间项 ± 2ab 最容易漏写。"},{"type":"p","text":"因式分解：把一个多项式化成几个整式的积的形式叫因式分解，它与整式乘法互为逆运算。关键点：结果必须是乘积形式，且每个因式都要分解到不能再分解为止。"},{"type":"note","title":"中考考法","text":"幂的四条运算性质辨析与逆用\n选择题判断幂的运算是否正确，解答题常逆用性质求 a^(m+n) 的值，踩分点是相乘加指数、乘方乘指数，且底数必须相同才能合并。"},{"type":"note","title":"中考考法","text":"乘法公式的综合计算与几何背景\n平方差与完全平方常混合出现在化简求值中，也用面积图形验证恒等式，踩分点是完全平方不漏中间项，善用两数和与积整体代入。"},{"type":"note","title":"中考考法","text":"因式分解及其在分式、方程中的工具作用\n直接考分解，或在分式约分、解一元二次方程中作为步骤考查，踩分点是先提公因式再套公式，且每个因式分解到不能再分解。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["同底数幂的乘法","a^(m)· a^(n)=a^(m+n)","底数必须相同；底数不同时不能合并，如 a²+a³ 也不能合并。"],["幂的乘方","(a^(m))^(n)=a^(mn)","指数相乘而不是相加；(a²)³=a⁶，而 a²· a³=a⁵。"],["积的乘方","(ab)^(n)=a^(n)b^(n)","每一个因式都要乘方，包括数字因数，如 (-2a²b)³=-8a⁶b³。"],["同底数幂的除法与零指数幂","a^(m)÷ a^(n)=a^(m-n)\\ (a≠ 0,\\ m>n), a⁰=1\\ (a≠ 0)","底数 a≠ 0 是前提；指数相减，不要漏掉负数情况 a^(m-n) 的形式。"],["平方差公式","a²-b²=(a+b)(a-b)","适用于两项都是平方且相减的式子；a²+b² 在有理数范围内不能再分解。"],["完全平方公式","(a± b)²=a²± 2ab+b²","中间项是两数积的 2 倍，符号与括号内一致；(a-b)²=(b-a)²，但 (a-b)³=-(b-a)³。"]]},{"type":"note","title":"例题","text":"计算：(2x+3y)(2x-3y)-(x-2y)²。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-e1","title":"两道乘法公式各算各的","caption":"前面用平方差，后面用完全平方，最后合并","view":"wide","alt":"前半段 (2x+3y)(2x−3y) 套平方差公式得 4x 平方减 9y 平方，后半段 (x−2y) 的平方套完全平方公式得 x 平方减 4xy 加 4y 平方，整体相减后合并得 3x 平方加 4xy 减 13y 平方","prims":[{"t":"rect","x":4,"y":6,"w":44,"h":24,"tone":"accent"},{"t":"text","x":26,"y":12,"text":"(2x+3y)(2x−3y)","size":2.8,"tone":"accent"},{"t":"text","x":26,"y":21,"text":"平方差 → 4x² − 9y²","size":3},{"t":"rect","x":52,"y":6,"w":44,"h":24,"tone":"ok"},{"t":"text","x":74,"y":12,"text":"(x−2y)²","size":2.8,"tone":"ok"},{"t":"text","x":74,"y":21,"text":"完全平方 → x²−4xy+4y²","size":2.8},{"t":"text","x":50,"y":40,"text":"整体相减时括号内每一项都要变号","size":3.2,"tone":"danger"},{"t":"text","x":50,"y":53,"text":"结果：3x² + 4xy − 13y²","size":3.4,"tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["第一项符合平方差公式：(2x+3y)(2x-3y)=(2x)²-(3y)²=4x²-9y²。","第二项用完全平方公式：(x-2y)²=x²-4xy+4y²（中间项是 -2· x· 2y=-4xy）。","代入原式并注意括号前是负号：4x²-9y²-(x²-4xy+4y²)=4x²-9y²-x²+4xy-4y²。","合并同类项：二次项 4x²-x²=3x²，中间项 +4xy，y 的平方项 -9y²-4y²=-13y²。","所以原式 =3x²+4xy-13y²。"]},{"type":"p","text":"答案：3x²+4xy-13y²"},{"type":"note","title":"方法小结","text":"减去一个多项式时，括号内每一项都要变号，「-4xy 变成 +4xy」是最容易错的一步。另外要记牢：(x-2y)² 的中间项是 -4xy，不是 +4xy。"},{"type":"note","title":"例题","text":"把 3a³-12ab² 因式分解。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-e2","title":"先提公因式，再套平方差","caption":"两步都要做完，停在中间不算分解完","view":"square","alt":"第一步从 3a 立方减 12a b 平方中提出公因式 3a，得到 3a 乘括号 a 平方减 4b 平方；第二步再对括号内套平方差，得到 3a 乘 (a+2b) 乘 (a−2b)，此时每个因式都不能再分解","prims":[{"t":"rect","x":10,"y":8,"w":80,"h":14,"label":"3a³ − 12ab²"},{"t":"arrow","x1":50,"y1":22,"x2":50,"y2":34,"tone":"accent"},{"t":"text","x":54,"y":28,"text":"提公因式 3a","size":3,"anchor":"start"},{"t":"rect","x":10,"y":34,"w":80,"h":14,"label":"3a(a² − 4b²)"},{"t":"arrow","x1":50,"y1":48,"x2":50,"y2":60,"tone":"accent"},{"t":"text","x":54,"y":54,"text":"再套平方差","size":3,"anchor":"start"},{"t":"rect","x":10,"y":60,"w":80,"h":14,"label":"3a(a+2b)(a−2b)"},{"t":"text","x":50,"y":84,"text":"每一步都要分解到不能再分解","size":3.2,"tone":"danger"},{"t":"text","x":50,"y":94,"text":"停在 3a(a²−4b²) 会扣分","size":3,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先找公因式：两项的系数 3 与 12 有公因数 3，字母部分都含有 a，故公因式是 3a。","提取公因式：3a³-12ab²=3a(a²-4b²)。","观察括号内 a²-4b² 是两项的平方差，符合平方差公式，其中 4b²=(2b)²。","继续分解：a²-4b²=(a+2b)(a-2b)。","所以 3a³-12ab²=3a(a+2b)(a-2b)，两个因式都不能再分解，分解完成。"]},{"type":"p","text":"答案：3a(a+2b)(a-2b)"},{"type":"note","title":"方法小结","text":"因式分解的顺序是「先提公因式，再套用公式」。若只写 3a(a²-4b²) 就停下，属于分解不彻底，考试要扣分。"},{"type":"note","title":"例题","text":"用简便方法计算：2026²-2025× 2027。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-e3","title":"凑成平方差，大数不用硬算","caption":"2025 与 2027 正好是 2026 减 1、加 1","view":"wide","alt":"把 2025 乘 2027 改写成 (2026−1)(2026+1)，用平方差公式得到 2026 平方减 1；原式等于 2026 平方减 (2026 平方减 1)，结果是 1","prims":[{"t":"rect","x":4,"y":8,"w":38,"h":14,"label":"2025 × 2027"},{"t":"arrow","x1":42,"y1":15,"x2":60,"y2":15,"label":"改写"},{"t":"rect","x":60,"y":8,"w":38,"h":14,"label":"(2026−1)(2026+1)"},{"t":"text","x":50,"y":32,"text":"= 2026² − 1²（平方差）","size":3.2},{"t":"text","x":50,"y":42,"text":"原式 = 2026² − (2026² − 1)","size":3},{"t":"text","x":50,"y":54,"text":"= 1","size":3.6,"tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["观察 2025 与 2027 都和 2026 相差 1，把它们改写成 2026-1 与 2026+1。","于是 2025× 2027=(2026-1)(2026+1)。","用平方差公式：(2026-1)(2026+1)=2026²-1²=2026²-1。","代入原式：2026²-(2026²-1)=2026²-2026²+1=1。"]},{"type":"p","text":"答案：1"},{"type":"note","title":"方法小结","text":"看到两个数关于某个数对称（相差相同）的乘法，立刻想到平方差公式，这比直接乘出两个大数快得多，也不会算错。"},{"type":"note","title":"例题","text":"已知 a^(m)=2，a^(n)=3，求下列各式的值：（1）a²m+n；（2）a³m-2n。"},{"type":"figure","figure":{"id":"fig-num-zhengshi-chengfa-e4","title":"逆用幂的性质，把指数拆成 m 与 n","caption":"指数相加对应相乘，指数相减对应相除","view":"wide","alt":"左边把 a 的 2m 加 n 次方拆成 a 的 m 次方的平方乘 a 的 n 次方，右边把 a 的 3m 减 2n 次方拆成 a 的 m 次方的立方除以 a 的 n 次方的平方，代入 a 的 m 次方等于 2、a 的 n 次方等于 3 后分别得 12 与 9 分之 8","prims":[{"t":"text","x":50,"y":10,"text":"把指数拆成 m 与 n 的组合","size":3},{"t":"rect","x":4,"y":18,"w":44,"h":16,"tone":"accent"},{"t":"text","x":26,"y":24,"text":"a^(2m+n)","size":3.2},{"t":"text","x":26,"y":31,"text":"= (a^m)² · a^n","size":3},{"t":"rect","x":52,"y":18,"w":44,"h":16,"tone":"ok"},{"t":"text","x":74,"y":24,"text":"a^(3m−2n)","size":3.2},{"t":"text","x":74,"y":31,"text":"= (a^m)³ ÷ (a^n)²","size":3},{"t":"text","x":50,"y":42,"text":"代入 a^m = 2，a^n = 3","size":3},{"t":"text","x":26,"y":53,"text":"2²×3 = 12","size":3.2,"tone":"ok"},{"t":"text","x":74,"y":53,"text":"2³÷3² = 8/9","size":3.2,"tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["所求式的指数是和与差的形式，想到逆用幂的运算性质，把目标式改写成含 a^(m)、a^(n) 的结构。","a²m+n=a²m· a^(n)=(a^(m))²· a^(n)=2²× 3=12。","a³m-2n=a³m÷ a²n=(a^(m))³÷(a^(n))²。","代入得 2³÷ 3²=(8)/(9)。"]},{"type":"p","text":"答案：（1）12；（2）(8)/(9)"},{"type":"note","title":"方法小结","text":"已知 a^(m)、a^(n) 的值求其他幂，通法是把指数拆成 m、n 的倍数再整体代入。指数相减对应同底数幂相除，注意写成分数形式而不是把指数算成负数。"},{"type":"note","title":"例题","text":"如图，从一个边长为 a 的大正方形中剪去一个边长为 b 的小正方形（a>b），把剩余的阴影部分剪拼成一个长方形。（1）用 a、b 写出剪拼前后面积相等所验证的恒等式；（2）若 a+b=10，a-b=2，求阴影部分的面积。"},{"type":"figure","figure":{"id":"fig-m-num-zhengshi-pingfangcha-1","title":"平方差公式的几何背景","caption":"a²−b² = (a+b)(a−b)","view":"wide","alt":"左图是一个边长为 a 的大正方形右上角剪去一个边长为 b 的小正方形，剩余阴影部分面积为 a 平方减 b 平方；右图是把剩余部分剪拼成一个长为 a 加 b、宽为 a 减 b 的长方形","prims":[{"t":"rect","x":8,"y":14,"w":28,"h":28,"tone":"muted"},{"t":"rect","x":26,"y":14,"w":10,"h":10,"dashed":true,"tone":"danger"},{"t":"hatch","x":8,"y":24,"w":28,"h":18},{"t":"text","x":22,"y":50,"text":"a","size":3.6,"anchor":"middle"},{"t":"text","x":4,"y":28,"text":"a","size":3.6,"anchor":"middle"},{"t":"text","x":31,"y":11,"text":"b","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":22,"y":58,"text":"剪拼前：a²−b²","size":3.6,"anchor":"middle"},{"t":"arrow","x1":40,"y1":30,"x2":50,"y2":30,"tone":"accent","label":"剪拼","labelDx":0,"labelDy":-6},{"t":"rect","x":52,"y":20,"w":38,"h":18,"tone":"muted"},{"t":"hatch","x":52,"y":20,"w":38,"h":18},{"t":"text","x":71,"y":45,"text":"a+b","size":3.6,"anchor":"middle"},{"t":"text","x":48,"y":30,"text":"a−b","size":3.6,"anchor":"middle"},{"t":"text","x":71,"y":56,"text":"剪拼后：(a+b)(a−b)","size":3.6,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["剪拼前阴影面积是大正方形减小正方形：a²-b²。","剪拼后的长方形长为 a+b、宽为 a-b，面积为 (a+b)(a-b)。剪拼不改变面积，故验证恒等式 a²-b²=(a+b)(a-b)。","第（2）问已知恰好是长方形的长与宽，想到直接代入右边：S=(a+b)(a-b)。","代入 a+b=10、a-b=2，得 S=10× 2=20。"]},{"type":"p","text":"答案：（1）a²-b²=(a+b)(a-b)；（2）阴影面积为 20"},{"type":"note","title":"方法小结","text":"图形剪拼问题的依据是「面积不变」，它从几何角度验证了平方差公式。第（2）问不必分别求出 a=6、b=4，把 a+b 与 a-b 整体相乘最快。"},{"type":"list","title":"易错点","items":["混淆幂的运算性质：把 $a^{2}\\cdot a^{3}$ 算成 $a^{6}$（应为 $a^{5}$），或把 $(a^{2})^{3}$ 算成 $a^{5}$（应为 $a^{6}$）。相乘加指数，乘方乘指数。","完全平方公式漏写中间项，把 $(a+b)^{2}$ 写成 $a^{2}+b^{2}$。正确结果是 $a^{2}+2ab+b^{2}$。","积的乘方漏把数字因数乘方，如把 $(2x)^{3}$ 写成 $2x^{3}$（应为 $8x^{3}$），也忘记负号，$-8a^{6}b^{3}$ 写成 $8a^{6}b^{3}$。","因式分解不彻底，如 $3a^{3}-12ab^{2}=3a(a^{2}-4b^{2})$ 就停笔，未继续分解为 $3a(a+2b)(a-2b)$。","把 $a^{2}+b^{2}$ 分解成 $(a+b)^{2}$。在有理数范围内 $a^{2}+b^{2}$ 不能分解，$(a+b)^{2}=a^{2}+2ab+b^{2}$ 多了一项。","把 $(a-b)^{2}$ 与 $a^{2}-b^{2}$ 混为一谈。前者是完全平方，后者是平方差。"]},{"type":"list","title":"解题方法","items":["幂的运算口诀「相乘加、乘方乘、相除减」，遇到混合运算先分清是哪种运算再动笔。","乘法公式的识别：平方差是「两项、都是平方、中间相减」，完全平方是「三项、首尾都是平方、中间是两数积的 2 倍」，展开时记「首平方、尾平方、首尾两倍中间放」，符号跟着括号内的加减走。","因式分解「一提二套三十字四分组」：先提公因式，再套用公式，二次三项式试十字相乘，项数多时分组分解。","简便计算中把接近整数的数拆成「整数 ± 小数」，再用乘法公式或分配律，既快又准。","检验方法：把分解结果乘开，看是否还原成原多项式；或用特殊值代入两边分别计算比对。"]}],"questions":[{"id":"m-num-zhengshi-chengfa-q1","type":"choice","stem":"下列计算正确的是（ ）","answer":"D","explain":"D 正确，积的乘方等于各因式分别乘方。A 错：同底数幂相乘指数相加，应为 a⁵。B 错：幂的乘方指数相乘，应为 a⁶。C 错：同底数幂相除指数相减，应为 a⁴。","options":["a²· a³=a⁶","(a²)³=a⁵","a⁶÷ a²=a³","(ab)²=a²b²"],"difficulty":1,"tags":["幂的运算","性质辨析","易错"]},{"id":"m-num-zhengshi-chengfa-q2","type":"choice","stem":"把 x²-5x+6 因式分解，结果是（ ）","answer":"B","explain":"常数项 6 分解为两个因数，它们的和要等于一次项系数 -5。取 -2 与 -3：(-2)×(-3)=6，(-2)+(-3)=-5，故 x²-5x+6=(x-2)(x-3)。检验：展开得 x²-3x-2x+6=x²-5x+6，正确。A 的乘积是 x²-7x+6，C 是 x²+5x+6，D 是 x²+x-6。","options":["(x-1)(x-6)","(x-2)(x-3)","(x+2)(x+3)","(x-2)(x+3)"],"difficulty":1,"tags":["因式分解","十字相乘"]},{"id":"m-num-zhengshi-chengfa-q3","type":"fill","stem":"计算：(-2a²b)³=（ ）。","answer":"-8a^6b^3","explain":"积的乘方要把每一个因式分别乘方：(-2a²b)³=(-2)³·(a²)³· b³=-8a⁶b³。三个要点：数字因数 -2 要立方得 -8；a² 的立方是指数相乘得 a⁶；b 的指数是 1，立方后得 b³。","difficulty":2,"tags":["积的乘方","幂的运算","计算"]},{"id":"m-num-zhengshi-chengfa-q4","type":"fill","stem":"已知 a+b=5，ab=6，则 a²+b²=（ ）。","answer":"13","explain":"由完全平方公式 (a+b)²=a²+2ab+b² 得 a²+b²=(a+b)²-2ab。代入已知得 a²+b²=5²-2× 6=25-12=13。（也可验证：a、b 分别是 2 和 3，2²+3²=13，一致。）","difficulty":2,"tags":["完全平方公式","整体代入"]},{"id":"m-num-zhengshi-chengfa-q5","type":"short","stem":"已知 x+y=7，xy=10，不解方程求 x²+2xy+y² 与 x²-xy+y² 的值，并写出完整过程。","answer":"$x^{2}+2xy+y^{2}=(x+y)^{2}=49$；$x^{2}-xy+y^{2}=(x+y)^{2}-3xy=49-30=19$。","explain":"第一个式子恰好是完全平方公式的右边：x²+2xy+y²=(x+y)²=7²=49。第二个式子需要变形：x²-xy+y²=(x²+2xy+y²)-3xy=(x+y)²-3xy，代入得 49-3× 10=49-30=19。检验：由 x+y=7、xy=10 可取 x=2、y=5，此时 x²-xy+y²=4-10+25=19，结果一致。","difficulty":3,"tags":["乘法公式","整体代入","恒等变形"],"rubric":["正确看出 x²+2xy+y²=(x+y)² 并算出 49","把 x²-xy+y² 变形为 (x+y)²-3xy（或 x²+xy+y² 再减 2xy 同理）","正确代入 x+y=7、xy=10 算出 19","过程完整，有必要的文字说明或变形依据"]},{"id":"m-num-zhengshi-chengfa-z1","type":"choice","stem":"计算 (-2x²y)²· 3xy² 的结果是（ ）","answer":"D","explain":"先算积的乘方：(-2x²y)²=(-2)²(x²)²y²=4x⁴y²（偶次乘方结果为正）。再做单项式乘法：4x⁴y²· 3xy²=12x⁴+1y²+2=12x⁵y⁴，故选 D。B 项把 (-2)² 误算成负数，C 项漏乘了第二个因式中的 x。","options":["6x⁵y⁴","-12x⁴y⁴","12x⁴y⁴","12x⁵y⁴"],"difficulty":2,"tags":["积的乘方","幂的运算","计算"]},{"id":"m-num-zhengshi-chengfa-z2","type":"fill","stem":"若 2^(x)=3，2^(y)=5，则 2^(x+y)=（ ）。","answer":"15","explain":"逆用同底数幂的乘法：2^(x+y)=2^(x)· 2^(y)=3× 5=15。这里不需要分别求出 x、y 的值，把已知的两个幂整体相乘即可。","difficulty":2,"tags":["幂的运算","计算"]}]},{"id":"m-num-fenshi","title":"分式","subtitle":"人教版八上 · 第18章 分式","grade":"8a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八上 · 第18章 分式"},{"type":"note","title":"一句话概述","text":"理解分式的意义与基本性质，掌握分式四则运算，会解分式方程并检验增根。"},{"type":"h","text":"先看什么：分母不能是零"},{"type":"p","text":"分式 (A)/(B) 的本质是一次除法，B 是除数。除数不能为 0，所以 B≠ 0 是分式有意义的前提。而要让分式的值为 0，只需分子 A=0，但此时分母仍必须不为 0——两个条件缺一不可。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-s1","title":"分母为零的点要从数轴上挖去","caption":"x=2 时分母 x-2=0，分式无意义","view":"wide","alt":"一条数轴，在 2 的位置画空心圆圈表示这个点要挖去，数轴上从负端到 2 之前用加粗箭头标出分式有意义的范围，并注明分母 x 减 2 不等于 0 即 x 不等于 2","prims":[{"t":"line","x1":8,"y1":38,"x2":84,"y2":38},{"t":"arrow","x1":84,"y1":38,"x2":93,"y2":38},{"t":"line","x1":14,"y1":35,"x2":14,"y2":41},{"t":"line","x1":30,"y1":35,"x2":30,"y2":41},{"t":"line","x1":46,"y1":35,"x2":46,"y2":41},{"t":"line","x1":62,"y1":35,"x2":62,"y2":41},{"t":"line","x1":78,"y1":35,"x2":78,"y2":41},{"t":"text","x":14,"y":47,"text":"-2","size":3.4,"anchor":"middle"},{"t":"text","x":30,"y":47,"text":"-1","size":3.4,"anchor":"middle"},{"t":"text","x":46,"y":47,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":62,"y":47,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":78,"y":47,"text":"2","size":3.4,"anchor":"middle"},{"t":"arrow","x1":14,"y1":38,"x2":72,"y2":38,"tone":"ok","width":1.6},{"t":"dot","x":78,"y":38,"hollow":true,"tone":"danger"},{"t":"text","x":78,"y":26,"text":"x=2 要挖去","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":42,"y":20,"text":"分母 x - 2 ≠ 0，即 x ≠ 2","size":3.6,"anchor":"middle","tone":"muted"},{"t":"text","x":42,"y":56,"text":"除 x=2 外，分式都有意义","size":3.5,"anchor":"middle","tone":"ok"}]}},{"type":"note","title":"","text":"值等于 0 只要求分子为 0；若分子分母同时为 0，分式仍然无意义，不能说它的值为 0。"},{"type":"h","text":"抓条件：分子分母同乘非零数"},{"type":"p","text":"分数的 (1)/(2) 与 (2)/(4) 相等，因为把每一份再对半切开，份数变多了、取到的多少没变。分式也一样：(A)/(B)=(A· C)/(B· C)。这里的 C 必须非零——一旦 C=0，分母就变成 0，式子反而失去意义。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-s2","title":"同乘非零数：份数变多、值不变","caption":"二分之一与四分之二表示同样大的阴影","view":"wide","alt":"左边一个正方形平均分成两份、取其中一份表示二分之一，右边同样大的正方形平均分成四份、取其中两份表示四分之二，中间双向箭头标注同乘 2，说明分子分母同乘同一个非零数分式的值不变","prims":[{"t":"poly","points":[[12,18],[26,18],[26,46],[12,46]],"closed":true,"tone":"accent","fill":true},{"t":"rect","x":12,"y":18,"w":28,"h":28,"tone":"main"},{"t":"line","x1":26,"y1":18,"x2":26,"y2":46,"tone":"main"},{"t":"text","x":26,"y":12,"text":"1/2","size":3.6,"anchor":"middle","tone":"main"},{"t":"poly","points":[[54,18],[68,18],[68,46],[54,46]],"closed":true,"tone":"accent","fill":true},{"t":"rect","x":54,"y":18,"w":28,"h":28,"tone":"main"},{"t":"line","x1":61,"y1":18,"x2":61,"y2":46,"tone":"main"},{"t":"line","x1":68,"y1":18,"x2":68,"y2":46,"tone":"main"},{"t":"line","x1":75,"y1":18,"x2":75,"y2":46,"tone":"main"},{"t":"text","x":68,"y":12,"text":"2/4","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":42,"y1":32,"x2":52,"y2":32,"both":true,"tone":"accent","label":"同乘 2","labelDy":-4},{"t":"text","x":50,"y":54,"text":"分子分母同乘同一个非零数，分式的值不变","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":60,"text":"若乘的数是 0，分母为 0，分式就没有意义","size":3.4,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"分子、分母必须同时乘或同时除以同一个非零整式，只变一边就不是恒等变形。"},{"type":"h","text":"建立关系：去分母后必须验根"},{"type":"p","text":"解分式方程的思路是「去分母」：两边同乘最简公分母，把它变成整式方程。但这一步会放大未知数的取值范围——原方程里分母不能为 0，乘完之后这个限制消失了。所以整式方程的根必须代回最简公分母检验，使公分母为 0 的根叫增根，必须舍去。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-s3","title":"分式方程的求解流程与验根","caption":"整式方程的根若使公分母为 0，就是增根","view":"square","alt":"自上而下的流程：原方程 x 除以 x 减 3 等于 2 加 3 除以 x 减 3，去分母两边同乘最简公分母，得整式方程 x 等于 2 乘 x 减 3 加 3，解得 x 等于 3，验根时 x 减 3 等于 0 说明公分母为零，结论是 x 等于 3 是增根要舍去、原方程无解","prims":[{"t":"text","x":50,"y":12,"text":"原方程：x/(x-3) = 2 + 3/(x-3)","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":17,"x2":12,"y2":26,"tone":"accent"},{"t":"text","x":50,"y":32,"text":"去分母：两边同乘最简公分母 (x-3)","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":44,"text":"得整式方程：x = 2(x-3) + 3","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":49,"x2":12,"y2":58,"tone":"accent"},{"t":"text","x":50,"y":64,"text":"解整式方程，得 x = 3","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":69,"x2":12,"y2":78,"tone":"danger"},{"t":"text","x":50,"y":84,"text":"验根：x-3 = 3-3 = 0，公分母为 0","size":3.6,"anchor":"middle","tone":"danger"},{"t":"rect","x":20,"y":90,"w":60,"h":9,"tone":"danger","label":"增根舍去，原方程无解"}]}},{"type":"note","title":"","text":"去分母时不含分母的项（如本例中的 2）也要乘最简公分母，漏乘是最常见的错误。"},{"type":"h","text":"换个情境：先化简再代入"},{"type":"p","text":"遇到「先化简，再求值」的题，先把分式化到最简，再代入数值。这样做有两个好处：化简后式子更短、代入后算得更快；而且化简过程中能看清哪些值会让分母为 0，代入前就把不合格的值排除掉。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-s4","title":"先化简再代入的流程","caption":"化到最简分式后再代入，既快又不易错","view":"wide","alt":"自上而下的流程：原式先算括号、把除法改为乘法并约分，得到最简结果 a 加一分之一，再代入 a 等于 2，算出结果为三分之一","prims":[{"t":"text","x":50,"y":12,"text":"原式 = (a-1)/a ÷ (a - 1/a)","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":18,"x2":50,"y2":26,"tone":"accent"},{"t":"text","x":50,"y":32,"text":"括号先算，除法改乘法，约去 a 与 (a-1)","size":3.5,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":50,"y1":37,"x2":50,"y2":45,"tone":"accent"},{"t":"rect","x":22,"y":46,"w":40,"h":12,"tone":"ok","label":"= 1/(a+1)"},{"t":"arrow","x1":64,"y1":52,"x2":71,"y2":52,"tone":"accent"},{"t":"rect","x":72,"y":46,"w":24,"h":12,"tone":"accent","label":"1/3"},{"t":"text","x":84,"y":42,"text":"代入 a=2","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"代入之前先列出所有限制条件（如 a≠ 0、a≠ ± 1），题目给的候选值中只有满足条件的才能用。"},{"type":"h","text":"核心概念"},{"type":"p","text":"分式：如果 A、B 表示两个整式，且 B 中含有字母，那么式子 (A)/(B) 叫做分式，A 是分子、B 是分母。关键点：判断是否为分式只看分母中是否含字母，与分子无关。"},{"type":"p","text":"分式有意义与值为 0 的条件：分式有意义要求分母不为 0，即 B≠ 0；分式的值为 0 要求分子为 0且分母不为 0，即 A=0 且 B≠ 0。关键点：值为 0 的两个条件缺一不可。"},{"type":"p","text":"分式的基本性质：分式的分子与分母同乘（或同除以）一个不等于 0 的整式，分式的值不变。它是约分与通分的依据。关键点：所乘除的整式必须不为 0。"},{"type":"p","text":"约分与最简分式：把分式的分子与分母的公因式约去叫约分；分子与分母没有公因式的分式叫最简分式。关键点：约分前要先把分子分母分别因式分解，约分结果应是最简分式或整式。"},{"type":"p","text":"分式的四则运算：乘法：分子乘分子、分母乘分母，能约分先约分。除法：除以一个分式等于乘它的倒数。加减法：同分母分母不变、分子相加减；异分母先通分化为同分母再加减。"},{"type":"p","text":"负整数指数幂：规定 a^(-n)=1a^(n)（a≠ 0，n 为正整数），即任何不等于 0 的数的 -n 次幂等于它的 n 次幂的倒数。关键点：((1)/(2))^(-1)=2，(2x)^(-2)=14x²。"},{"type":"p","text":"分式方程与增根：分母中含有未知数的方程叫分式方程。解分式方程的基本思路是去分母化为整式方程，但去分母时两边乘的最简公分母可能为 0，因此必须把整式方程的根代入最简公分母检验，使公分母为 0 的根叫增根，必须舍去。"},{"type":"note","title":"中考考法","text":"分式有意义与值为 0 的条件\n选择填空常考分母不为零、分子为零且分母不为零，多个限制时取交集，踩分点是值为 0 的两个条件缺一不可，零指数幂的底数也不能为 0。"},{"type":"note","title":"中考考法","text":"分式的混合运算与「先化简再求值」\n广州中考解答题常客，常把加减乘除与因式分解综合，踩分点是先分解因式再约分，所选的代入值必须使原分式有意义。"},{"type":"note","title":"中考考法","text":"分式方程的解法、增根检验与实际应用\n工程、行程问题列分式方程，踩分点是去分母时常数项不漏乘、把根代入最简公分母检验，增根舍去并会写「无解」的结论。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["分式的基本性质","(A)/(B)=(A· C)/(B· C), (A)/(B)=(A÷ C)/(B÷ C)\\ (C≠ 0)","乘除的整式 C 不能为 0；分子、分母必须同时乘或除，不能只变一边。"],["分式的乘除法则","(a)/(b)· (c)/(d)=(ac)/(bd), (a)/(b)÷ (c)/(d)=(a)/(b)· (d)/(c)=(ad)/(bc)\\ (b,c,d≠ 0)","除法要「颠倒相乘」，除式的分子不能为 0；运算结果要化成最简分式。"],["分式的加减法则","(a)/(c)± (b)/(c)=(a± b)/(c), (a)/(b)± (c)/(d)=(ad± bc)/(bd)","同分母相加减时分母不变、分子相加减；异分母先通分，最简公分母取各分母所有因式的最高次幂。"],["负整数指数幂","a^(-n)=1a^(n), a⁰=1\\ (a≠ 0)","底数 a 不能为 0；(2x)^(-2)=1(2x)²=14x²，不能把 2 漏掉。"],["分式的值为 0","分子 A=0 且分母 B≠ 0 时，分式 (A)/(B) 的值为 0。","两个条件必须同时满足；若 A=0 时 B 也等于 0，则该分式无意义。"],["分式方程的解法","方程两边同乘最简公分母，化为整式方程后求解，再把根代入最简公分母检验：公分母不为 0 的才是原方程的根，为 0 的是增根。","增根的产生源于去分母时扩大了未知数的取值范围，因此「检验」是分式方程解法中不可省略的一步。"]]},{"type":"note","title":"例题","text":"化简：x²-4x²-4x+4。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-e1","title":"先分解因式，再约去公因式","caption":"分子分母分别因式分解后才能约分","view":"wide","alt":"自上而下三步：分子 x 平方减 4 分解为 x 加 2 乘 x 减 2，分母 x 平方减 4x 加 4 分解为 x 减 2 的平方，约去公因式 x 减 2 后原式等于 x 减 2 分之 x 加 2，并注明 x 不等于 2","prims":[{"t":"text","x":50,"y":10,"text":"分子：x² - 4 = (x+2)(x-2)","size":3.5,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":22,"text":"分母：x² - 4x + 4 = (x-2)²","size":3.5,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":27,"x2":12,"y2":35,"tone":"accent"},{"t":"text","x":50,"y":40,"text":"约去公因式 (x-2)","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":52,"text":"原式 = (x+2)/(x-2)（x ≠ 2）","size":3.8,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["把分子因式分解：x²-4=(x+2)(x-2)。","把分母因式分解：x²-4x+4=(x-2)²（完全平方公式，注意中间项是 -4x）。","写成积的形式：(x+2)(x-2)(x-2)²。","约去公因式 (x-2)，得 (x+2)/(x-2)。","结论：原式 =(x+2)/(x-2)（其中 x≠ 2，因为原分式的分母不能为 0）。"]},{"type":"p","text":"答案：(x+2)/(x-2)（x≠ 2）"},{"type":"note","title":"方法小结","text":"分式化简必须先因式分解再约分，不能直接把分子分母中的 x² 约掉。另外约分后即使分母中不再显含 x-2 的零因子，原分式的限制条件 x≠ 2 依然存在。"},{"type":"note","title":"例题","text":"先化简，再求值：(a-1)/(a)÷ (a-(1)/(a))，其中 a=2。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-e2","title":"三步化简后代入","caption":"括号先通分，除法改乘法，约分后再代入","view":"wide","alt":"从左到右三个方框依次是括号通分、除法改乘法、约分，化简结果为 a 加一分之一，下方代入 a 等于 2 算出三分之一，并注明候选值要使原式所有分母都不为 0","prims":[{"t":"text","x":50,"y":12,"text":"化简结果 1/(a+1)","size":3.6,"anchor":"middle","tone":"muted"},{"t":"rect","x":4,"y":20,"w":26,"h":14,"tone":"main","label":"括号通分"},{"t":"arrow","x1":31,"y1":27,"x2":37,"y2":27,"tone":"accent"},{"t":"rect","x":38,"y":20,"w":26,"h":14,"tone":"main","label":"除改乘"},{"t":"arrow","x1":65,"y1":27,"x2":71,"y2":27,"tone":"accent"},{"t":"rect","x":72,"y":20,"w":24,"h":14,"tone":"ok","label":"约分"},{"t":"text","x":50,"y":46,"text":"代入 a = 2：1/(2+1) = 1/3","size":3.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":58,"text":"候选值必须使原式所有分母都不为 0","size":3.4,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["先化简括号内：a-(1)/(a)=a²a-(1)/(a)=a²-1a。","把除法化为乘法：原式 =(a-1)/(a)· aa²-1。","把 a²-1 因式分解：a²-1=(a+1)(a-1)。","于是原式 =(a-1)/(a)· (a)/((a+1)(a-1))，约去 a 与 (a-1) 得 (1)/(a+1)。","代入 a=2：(1)/(2+1)=(1)/(3)。"]},{"type":"p","text":"答案：(1)/(3)"},{"type":"note","title":"方法小结","text":"「先化简再求值」的顺序不能颠倒。代入的值要使原式中所有分母都不为 0，本题 a≠ 0、a≠ ± 1，a=2 满足条件。"},{"type":"note","title":"例题","text":"解分式方程：(x)/(x-3)=2+(3)/(x-3)。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-e3","title":"整式方程的解要过验根这一关","caption":"x=3 使公分母为 0，是增根必须舍去","view":"wide","alt":"左侧方框写着整式方程解出 x 等于 3，向右箭头标注代入最简公分母，右侧方框得出 x 减 3 等于 0、公分母为零，判定为增根舍去，结论是原方程无解","prims":[{"t":"rect","x":6,"y":16,"w":30,"h":14,"tone":"main","label":"解得 x = 3"},{"t":"arrow","x1":37,"y1":23,"x2":55,"y2":23,"tone":"accent","label":"代入最简公分母","labelDy":-8},{"t":"rect","x":56,"y":16,"w":38,"h":14,"tone":"danger","label":"x-3 = 0 → 增根"},{"t":"text","x":50,"y":42,"text":"公分母为 0，说明这个根是去分母时多出来的","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":54,"text":"结论：x = 3 舍去，原分式方程无解","size":3.7,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["确定最简公分母为 (x-3)。","方程两边同乘 (x-3)：x=2(x-3)+3。","去括号得 x=2x-6+3。","移项、合并同类项得 -x=-3，所以 x=3。","检验：把 x=3 代入最简公分母 x-3，得 3-3=0，公分母为 0。","所以 x=3 是增根，原分式方程无解。"]},{"type":"p","text":"答案：原方程无解（x=3 是增根）"},{"type":"note","title":"方法小结","text":"解分式方程的最后一步「检验」不能省。本题整式方程解出的 x=3 恰好让分母为 0，说明原方程根本没有解，若直接写 x=3 就错了。"},{"type":"note","title":"例题","text":"化简：(1+(2)/(x-2))· x²-4x。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-e4","title":"混合运算：先括号、再分解、后约分","caption":"整式与分式相加先通分，分子分母分解后约分","view":"wide","alt":"自上而下三步：括号内 1 加 x 减 2 分之 2 通分得 x 减 2 分之 x，把 x 平方减 4 分解成 x 加 2 乘 x 减 2，约去 x 与 x 减 2 后结果等于 x 加 2，并注明 x 不等于 0 且 x 不等于 2","prims":[{"t":"text","x":50,"y":12,"text":"括号内通分：1 + 2/(x-2) = x/(x-2)","size":3.5,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":24,"text":"分解：x² - 4 = (x+2)(x-2)","size":3.5,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":29,"x2":12,"y2":37,"tone":"accent"},{"t":"text","x":50,"y":42,"text":"约去 x 与 (x-2)","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":54,"text":"结果：x + 2（x ≠ 0 且 x ≠ 2）","size":3.8,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["括号内是整式加分式，想到先通分：1=(x-2)/(x-2)，故括号内为 (x-2+2)/(x-2)=(x)/(x-2)。","把 x²-4 用平方差公式分解：x²-4=(x+2)(x-2)。","原式化为 (x)/(x-2)· ((x+2)(x-2))/(x)。","约去公因式 x 与 (x-2)，得 x+2（原分式要求 x≠ 0 且 x≠ 2）。"]},{"type":"p","text":"答案：x+2（x≠ 0 且 x≠ 2）"},{"type":"note","title":"方法小结","text":"分式混合运算的顺序与有理数一致：先算括号，除法转化为乘法。分子分母是多项式时先因式分解再约分，能约分的因式一眼就能配对。"},{"type":"note","title":"例题","text":"某校学生到距学校 15 千米的植物园春游。一部分同学骑自行车先走，40 分钟后其余同学乘汽车出发，结果他们同时到达。已知汽车的平均速度是自行车平均速度的 3 倍，求自行车的平均速度。"},{"type":"figure","figure":{"id":"fig-m-num-fenshi-xingcheng-1","title":"行程问题：抓住时间差列分式方程","caption":"自行车比汽车多用 40 分钟，同时到达","view":"wide","alt":"一条线段表示学校到植物园 15 千米的路程，上方箭头表示自行车从出发到到达用时较长，下方箭头表示汽车晚出发 40 分钟但用时较短，两者同时到达植物园","prims":[{"t":"line","x1":12,"y1":45,"x2":88,"y2":45},{"t":"dot","x":12,"y":45,"label":"学校","labelDx":0,"labelDy":12},{"t":"dot","x":88,"y":45,"label":"植物园","labelDx":0,"labelDy":12},{"t":"text","x":50,"y":52,"text":"15 千米","size":3.6,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":12,"y1":32,"x2":88,"y2":32,"tone":"accent","label":"自行车：用时 15/x 小时","labelDx":0,"labelDy":-6},{"t":"line","x1":50,"y1":32,"x2":50,"y2":45,"tone":"muted","dashed":true},{"t":"arrow","x1":50,"y1":58,"x2":88,"y2":58,"tone":"main","label":"汽车：用时 15/(3x) 小时","labelDx":0,"labelDy":8},{"t":"arrow","x1":12,"y1":52,"x2":50,"y2":52,"tone":"danger","label":"先走 40 分钟","labelDx":0,"labelDy":-5},{"t":"text","x":50,"y":72,"text":"时间差：15/x − 15/(3x) = 2/3","size":3.6,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["设自行车的平均速度为 x 千米/时，则汽车速度为 3x 千米/时，想到时间等于路程除以速度。","自行车用时 (15)/(x) 小时，汽车用时 (15)/(3x) 小时；汽车晚出发 40 分钟（即 (2)/(3) 小时）却同时到达，故时间差为 (2)/(3)。","列分式方程：(15)/(x)-(15)/(3x)=(2)/(3)。","化简：(10)/(x)=(2)/(3)，解得 x=15。","检验：x=15 时分母不为 0；自行车用时 1 小时、汽车用时 (1)/(3) 小时，相差 (2)/(3) 小时即 40 分钟，符合题意。"]},{"type":"p","text":"答案：自行车的平均速度为 15 千米/时"},{"type":"note","title":"方法小结","text":"行程类分式方程要抓住「时间差」列方程，并注意把分钟换算成小时使单位统一。解出后既要看是否为增根，又要代回情境核对时间差。"},{"type":"list","title":"易错点","items":["解分式方程不检验增根，或检验时只代入原方程而不知道要看最简公分母是否为 0。使最简公分母为 0 的根必须舍去。","去分母时漏乘不含分母的项，如解 $\\frac{x}{x-3}=2+\\frac{3}{x-3}$ 时右边只把 $\\frac{3}{x-3}$ 乘了 $(x-3)$ 而漏乘 2。","分子是多项式时去分母不加括号，如把 $\\frac{3x+2}{6}$ 中的分子直接写成 $3x+2$ 乘公分母后不括起来。","约分时把分子分母中的项直接约掉，如把 $\\frac{x+2}{x+3}$ 中的 $x$ 约去。只有因式才能约分，必须先分解因式。","负整数指数幂计算错误，如把 $(2x)^{-2}$ 写成 $\\frac{1}{2x^{2}}$（正确是 $\\frac{1}{4x^{2}}$），或把 $\\left(-\\frac{1}{3}\\right)^{-2}$ 写成 $-9$（正确是 9）。","求分式的值为 0 时只令分子为 0，忽略分母不为 0 的条件，如把 $\\frac{x-1}{x-1}$ 的值为 0 说成 $x=1$。"]},{"type":"list","title":"解题方法","items":["分式化简三步：分解因式、约去公因式、写成最简分式。分子分母都要先分解成积的形式再动手。","「先化简，再代入」求值，并先算出使原式有意义的所有限制条件，代入前核对取值是否合格。","解分式方程四步：去分母（两边乘最简公分母）、解整式方程、检验（代入最简公分母）、写出结论。","通分技巧：最简公分母 = 各分母系数的最小公倍数 × 所有出现过的因式的最高次幂。","整体变形：遇到 a²+1a 这类结构可拆成 a+(1)/(a)，简化后续运算。"]}],"questions":[{"id":"m-num-fenshi-q1","type":"choice","stem":"要使分式 (x-1)/(x+2) 有意义，x 应满足的条件是（ ）","answer":"B","explain":"分式有意义的条件是分母不为 0，即 x+2≠ 0，所以 x≠ -2，选 B。A 项 x≠ 1 是「分式的值为 0」时的分子条件（此时还需 x≠ -2），与题意不符；C、D 都不正确。","options":["x≠ 1","x≠ -2","x>-2","x≠ ± 2"],"difficulty":1,"tags":["分式有意义","取值范围"]},{"id":"m-num-fenshi-q2","type":"choice","stem":"下列分式中，是最简分式的是（ ）","answer":"C","explain":"C 中分子 x²+1 在有理数范围内不能分解，与分母 x+1 没有公因式，是最简分式。A 的分母 x²-1=(x+1)(x-1)，与分子有公因式 x+1。B 约分后得 x+1（已不是分式）。D 约分后得 (1)/(2x)。","options":["x+1x²-1","x²-1x-1","x²+1x+1","2x4x²"],"difficulty":2,"tags":["最简分式","约分"]},{"id":"m-num-fenshi-q3","type":"fill","stem":"化简 a²-9a+3（a≠ -3），结果是（ ）。","answer":"a-3","explain":"分子用平方差公式因式分解：a²-9=(a+3)(a-3)。所以 a²-9a+3=((a+3)(a-3))/(a+3)=a-3。注意条件是 a≠ -3，否则分母为 0，分式无意义。","difficulty":1,"tags":["约分","平方差","化简"]},{"id":"m-num-fenshi-q4","type":"fill","stem":"解方程 (3)/(x)=(2)/(x-1)，得 x=（ ）。","answer":"3","explain":"两边同乘最简公分母 x(x-1)：3(x-1)=2x。去括号得 3x-3=2x，移项得 x=3。检验：把 x=3 代入 x(x-1) 得 3× 2=6≠ 0，不是增根；且 (3)/(3)=1、(2)/(2)=1，左右相等。故 x=3。","difficulty":2,"tags":["分式方程","检验","计算"]},{"id":"m-num-fenshi-q5","type":"short","stem":"解分式方程 (2)/(x-1)=(x)/(x-1)-1，并说明每一步的依据与检验过程。","answer":"方程两边同乘 $(x-1)$ 得 $2=x-(x-1)$，化简得 $2=1$，等式不成立，故原分式方程无解。","explain":"最简公分母为 (x-1)，方程两边同乘 (x-1)：2=x-(x-1)，即 2=x-x+1=1，得到矛盾式 2=1。这说明整式方程无解，从而原分式方程无解。也可用移项的方式说明：原方程两边同时减 (x)/(x-1) 得 (2-x)/(x-1)=-1，即 2-x=-(x-1)，整理得 2=1，同样矛盾。检验环节表明：不存在使分母不为 0 且使等式成立的 x，故原方程无解。","difficulty":3,"tags":["分式方程","无解","去分母"],"rubric":["正确找出最简公分母 (x-1) 并在两边同乘","去分母时右边 -1 也乘 (x-1)，写出 2=x-(x-1)（漏乘 -1 则不得分）","化简得到矛盾式 2=1，说明整式方程无解","写出「原分式方程无解」的结论，而不是误答 x=1 或某个具体值"]},{"id":"m-num-fenshi-q6","type":"fill","stem":"一项工作，甲单独做需要 10 天完成，甲、乙两人合作需要 6 天完成，则乙单独做需要（ ）天完成。","answer":"15","explain":"把总工作量看作 1，则甲每天完成 (1)/(10)，两人合作每天完成 (1)/(6)。设乙单独做需要 x 天，则乙每天完成 (1)/(x)，列方程 (1)/(10)+(1)/(x)=(1)/(6)。移项得 (1)/(x)=(1)/(6)-(1)/(10)=(5-3)/(30)=(2)/(30)=(1)/(15)，故 x=15。检验：(1)/(10)+(1)/(15)=(3+2)/(30)=(1)/(6)，日完成量正确，6 天恰好完成全部工作。","difficulty":2,"tags":["分式方程应用","工程问题"]},{"id":"m-num-fenshi-z1","type":"choice","stem":"若分式 x²-1x+1 的值为 0，则 x 的值为（ ）","answer":"A","explain":"分式值为 0 要求分子为 0 且分母不为 0。由 x²-1=0 得 x=± 1；但分母 x+1≠ 0，即 x≠ -1，故只能取 x=1，选 A。直接由分子为 0 取 ± 1 会错选 C，因为 x=-1 时分式无意义。","options":["1","-1","± 1","0"],"difficulty":2,"tags":["分式有意义","取值范围","计算"]},{"id":"m-num-fenshi-z2","type":"short","stem":"先化简，再求值：((x)/(x-1)-1)÷ 1x²-1，并从 2、0、1 中选择一个合适的数作为 x 的值代入，写出完整过程。","answer":"原式化简为 $x+1$（$x\\neq 0$ 且 $x\\neq \\pm 1$）；只能选 $x=2$，代入得 $3$。","explain":"先确定取值范围：原式中分母有 x-1 与 x²-1，除式的分子相当于要求 x≠ 0，故 x≠ 0 且 x≠ ± 1，给出的三个数中只能选 x=2。化简时先算括号：(x)/(x-1)-1=(x-(x-1))/(x-1)=(1)/(x-1)。把除法化为乘法并分解因式：原式 =(1)/(x-1)·(x²-1)=(1)/(x-1)·(x-1)(x+1)=x+1。代入 x=2 得 2+1=3。若选 x=1 或 x=0，原式中分母为 0，不能代入。","difficulty":3,"tags":["化简","约分","平方差"],"rubric":["正确化简：括号内算得 (1)/(x-1)，最终结果为 x+1","说明取值限制 x≠ 0 且 x≠ ± 1，据此只能选 x=2","代入 x=2 算出结果 3"]}]},{"id":"m-num-erci-genshi","title":"二次根式","subtitle":"人教版八下 · 第19章 二次根式","grade":"8b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八下 · 第19章 二次根式"},{"type":"note","title":"一句话概述","text":"理解二次根式的双重非负性，掌握二次根式的化简、乘除、加减与分母有理化。"},{"type":"h","text":"先看什么：被开方数不能是负数"},{"type":"p","text":"在实数范围内，负数没有平方根，所以 √(a) 有意义的前提是 a≥ 0。字母在根号下时，取值范围就由这个条件决定：√(x-3) 要求 x-3≥ 0，即 x≥ 3；端点 x=3 时根式等于 0，仍然有意义，要保留。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-s1","title":"被开方数非负时根式才有意义","caption":"原点右侧才有意义，负的被开方数取不到","view":"wide","alt":"一条数轴，原点处画实心圆点，向右的加粗箭头表示被开方数大于等于 0 时二次根式有意义，原点左侧标注被开方数为负数时根式无意义","prims":[{"t":"line","x1":10,"y1":38,"x2":84,"y2":38},{"t":"arrow","x1":84,"y1":38,"x2":93,"y2":38},{"t":"line","x1":14,"y1":35,"x2":14,"y2":41},{"t":"line","x1":30,"y1":35,"x2":30,"y2":41},{"t":"line","x1":46,"y1":35,"x2":46,"y2":41},{"t":"line","x1":62,"y1":35,"x2":62,"y2":41},{"t":"line","x1":78,"y1":35,"x2":78,"y2":41},{"t":"text","x":14,"y":48,"text":"-2","size":3.4,"anchor":"middle"},{"t":"text","x":30,"y":48,"text":"-1","size":3.4,"anchor":"middle"},{"t":"text","x":46,"y":48,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":62,"y":48,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":78,"y":48,"text":"2","size":3.4,"anchor":"middle"},{"t":"dot","x":46,"y":38,"tone":"main"},{"t":"arrow","x1":46,"y1":38,"x2":82,"y2":38,"tone":"ok","width":1.8},{"t":"text","x":26,"y":26,"text":"负数：无意义","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":66,"y":26,"text":"非负数：有意义","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":58,"text":"被开方数 a ≥ 0，端点 0 也要保留","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"端点能取到时要用「≥」而不是「>」：x=3 时 √(x-3)=√(0)=0，根式仍有意义。"},{"type":"h","text":"抓条件：开方结果要分类讨论"},{"type":"p","text":"把 a 平方再开方，得到的不是 a，而是 |a|：a²=|a|。原因是算术平方根的结果始终非负，而 a 本身可能是负数。所以化简时必须分 a>0、a=0、a<0 三种情况讨论：正数取本身，零还是零，负数要取它的相反数。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-s2","title":"√(a²) 随 a 的正负而变","caption":"a 为负时结果要取相反数 -a","view":"wide","alt":"一条数轴上从左到右标出 a 小于 0、a 等于 0、a 大于 0 三个位置，下方分别对应根号 a 平方的结果是负 a、0、a，说明必须按 a 的正负分类讨论","prims":[{"t":"line","x1":10,"y1":36,"x2":86,"y2":36},{"t":"arrow","x1":86,"y1":36,"x2":94,"y2":36},{"t":"dot","x":26,"y":36,"tone":"danger"},{"t":"dot","x":50,"y":36,"tone":"main"},{"t":"dot","x":74,"y":36,"tone":"ok"},{"t":"text","x":26,"y":24,"text":"a < 0","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":24,"text":"a = 0","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":74,"y":24,"text":"a > 0","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":26,"y":48,"text":"|a| = -a","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":48,"text":"|a| = 0","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":74,"y":48,"text":"|a| = a","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":58,"text":"开方的结果总是非负数，所以要分类讨论","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"a²=|a| 与 (√(a))²=a 不同：后者要求 a≥ 0，前者对一切实数都有意义。"},{"type":"h","text":"建立关系：平方因子要开出来"},{"type":"p","text":"化简的根据是 a²b=a√(b)（a≥ 0，b≥ 0）。所以先把被开方数分解成因数的积，把「能开得尽方」的平方因数开出来，剩下的留在根号里。例如 √(12)=√(4× 3)=2√(3)，面积是 12 的正方形可以看成 4 个面积为 3 的小正方形拼成，边长自然是 2√(3)。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-s3","title":"面积模型：平方因子开出来","caption":"12 = 4 × 3，边长 √12 = 2√3","view":"wide","alt":"一个正方形被横向纵向各平分一次、分成四个相同的小正方形，每个小正方形面积是 3，整体正方形面积是 12，边长等于根号 12 即二倍根号 3，说明被开方数中的平方因子 4 可以开出来","prims":[{"t":"rect","x":32,"y":16,"w":28,"h":28,"tone":"main"},{"t":"line","x1":46,"y1":16,"x2":46,"y2":44,"tone":"main"},{"t":"line","x1":32,"y1":30,"x2":60,"y2":30,"tone":"main"},{"t":"text","x":39,"y":23,"text":"3","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":53,"y":23,"text":"3","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":39,"y":37,"text":"3","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":53,"y":37,"text":"3","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":46,"y":8,"text":"整体面积 = 4 × 3 = 12","size":3.5,"anchor":"middle","tone":"main"},{"t":"text","x":46,"y":54,"text":"边长 = √12 = √(4×3) = 2√3","size":3.6,"anchor":"middle","tone":"ok"},{"t":"text","x":84,"y":30,"text":"开出来的","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":84,"y":38,"text":"是 2","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"开方开出来的一定是非负数：√(18)=3√(2)，不要写成 -3√(2)。"},{"type":"h","text":"换个情境：分母有理化"},{"type":"p","text":"分母里带根号不便于计算与比较，所以要把它「化去」。分母是单项根式 √(a) 时，分子分母同乘 √(a)；分母是 √(a)±√(b) 时，同乘它的共轭式 √(a)∓√(b)，相乘后恰好是平方差，根号一次消掉。这个操作的依据仍是分式的基本性质。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-s4","title":"分母有理化的两种情形","caption":"单项根式同乘本身，两根式同乘共轭式","view":"wide","alt":"左边分式根号 3 分之一，箭头标注分子分母同乘根号 3，右边得到三分之根号 3，下方另举一例：分母是根号 a 加减根号 b 时同乘共轭式，用平方差去掉根号","prims":[{"t":"text","x":24,"y":26,"text":"1/√3","size":4.2,"anchor":"middle","tone":"main"},{"t":"arrow","x1":40,"y1":26,"x2":58,"y2":26,"tone":"accent","label":"分子分母同乘 √3","labelDy":-6},{"t":"text","x":78,"y":26,"text":"√3/3","size":4.2,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":44,"text":"分母是 √a ± √b 时，同乘共轭式 √a ∓ √b","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":56,"text":"相乘后用平方差公式，根号一次消掉","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"分子与分母必须同乘，只乘分母就把式子的值改了；共轭式是「符号相反」的那一个。"},{"type":"h","text":"核心概念"},{"type":"p","text":"二次根式：形如 √(a)（a≥ 0）的式子叫二次根式，a 叫被开方数。关键点：被开方数必须是非负数，字母在根号下时取值范围要由「被开方数 ≥ 0」确定。"},{"type":"p","text":"二次根式的双重非负性：一方面被开方数非负（a≥ 0），另一方面二次根式的值本身也非负（√(a)≥ 0）。关键点：这两条非负性是求取值范围、化简与解最值问题的依据。"},{"type":"p","text":"最简二次根式：被开方数不含分母，也不含能开得尽方的因数或因式的二次根式叫最简二次根式，如 2√(3)、√(5)。关键点：运算结果必须化成最简二次根式。"},{"type":"p","text":"同类二次根式：化成最简二次根式后，被开方数相同的二次根式叫同类二次根式，如 √(8)=2√(2) 与 √(18)=3√(2) 是同类二次根式。关键点：只有同类二次根式才能合并，合并方法与合并同类项相同。"},{"type":"p","text":"二次根式的乘除法：√(a)·√(b)=√(ab)（a≥ 0，b≥ 0），√(a)√(b)=√((a)/(b))（a≥ 0，b>0）。关键点：除法中分母上的根式不为 0，故要求 b>0。"},{"type":"p","text":"二次根式的加减法：先把各个二次根式化成最简二次根式，再把同类二次根式合并，即把根号外的因数相加减、被开方数不变。关键点：√(2)+√(3) 不能合并，因为它们不是同类二次根式。"},{"type":"p","text":"分母有理化：把分母中的根号化去叫分母有理化，通常分子分母同乘分母的根式或它的共轭式，如 1√(3)=√(3)3，1√(5)-2=√(5)+2(√(5))²-2²=√(5)+2。"},{"type":"note","title":"中考考法","text":"二次根式有意义的条件与取值范围\n填空常把被开方数非负、分母不为零、零指数幂底数不为零组合考查，踩分点是各限制取交集，等号能否取到要单独验证。"},{"type":"note","title":"中考考法","text":"二次根式的化简与四则混合运算\n解答题考化最简、合并同类二次根式与分母有理化，常配合平方差、完全平方公式，踩分点是先化简再合并、a²=|a|。"},{"type":"note","title":"中考考法","text":"含根式代数式的整体求值\n给 x=√(a)± b 或一对共轭式求对称式的值，踩分点是先配方或求出 x+y、xy 再整体代入，避免硬算根式和近似值。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["二次根式的性质（平方与开方）","(√(a))²=a\\ (a≥ 0), a²=|a|","a²=|a| 而非 a，如 (-5)²=5；(√(a))² 要求 a≥ 0，而 a² 对一切实数都有意义。"],["二次根式的乘法","√(a)· √(b)=√(ab)\\ (a≥ 0,\\ b≥ 0)","被开方数必须都非负；反过来 √(ab)=√(a)·√(b) 也要求 a≥ 0、b≥ 0。"],["二次根式的除法","√(a)√(b)=√((a)/(b))\\ (a≥ 0,\\ b>0)","分母上的根式不能为 0，所以要求 b>0；结果要化成最简二次根式。"],["最简二次根式的化简","a²b=a√(b)\\ (a≥ 0,\\ b≥ 0)","把能开得尽方的因数开出来，如 √(12)=2√(3)、√(18)=3√(2)、√((1)/(3))=√(3)3。"],["分母有理化","1√(a)=√(a)a\\ (a>0), 1√(a)-√(b)=√(a)+√(b)a-b\\ (a≠ b)","分子分母同乘分母的共轭式，注意共轭式符号相反，展开后分母是平方差。"],["二次根式的加减","先把各根式化为最简二次根式，再把同类二次根式的系数相加减，被开方数不变，如 2√(3)+3√(3)=5√(3)。","被开方数不同的二次根式不能合并；√(a)+√(b)≠ √(a+b)。"]]},{"type":"note","title":"例题","text":"化简：√(12)-√((1)/(3))+√(27)。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-e1","title":"先化最简，再合并同类根式","caption":"三个根式都化成含 √3 的形式再合并系数","view":"wide","alt":"自上而下三步：把根号 12 化为二倍根号 3、根号三分之一化为三分之根号 3、根号 27 化为三倍根号 3，合并根号外的系数二减三分之一加三等于三分之十四，结果是三分之十四倍根号三","prims":[{"t":"text","x":50,"y":10,"text":"√12 = 2√3，√(1/3) = √3/3，√27 = 3√3","size":3.5,"anchor":"middle","tone":"main"},{"t":"arrow","x1":12,"y1":15,"x2":12,"y2":23,"tone":"accent"},{"t":"text","x":50,"y":28,"text":"合并系数：2 - 1/3 + 3 = 14/3","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":38,"text":"被开方数不变，只把根号外的系数相加减","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":52,"text":"原式 = (14/3)√3","size":3.9,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["把每个二次根式化成最简二次根式：√(12)=√(4× 3)=2√(3)。","√((1)/(3))=√(1)√(3)=√(3)3（分母有理化）。","√(27)=√(9× 3)=3√(3)。","代入原式得 2√(3)-√(3)3+3√(3)。","合并同类二次根式：系数 2-(1)/(3)+3=(6-1+9)/(3)=(14)/(3)，所以原式 =(14)/(3)√(3)。"]},{"type":"p","text":"答案：(14)/(3)√(3)"},{"type":"note","title":"方法小结","text":"二次根式加减的第一步永远是「先化最简」，不化简就急着合并是最大误区。计算 2-(1)/(3)+3 时可以先算 2+3=5，再算 5-(1)/(3)=(14)/(3)，避免通分出错。"},{"type":"note","title":"例题","text":"计算：(√(5)+√(2))(√(5)-√(2))+(-3)²。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-e2","title":"平方差与算术平方根各算一半","caption":"共轭式相乘用平方差，开方结果取非负值","view":"wide","alt":"分两部分计算：用平方差公式把根号 5 加根号 2 乘根号 5 减根号 2 算得 3，又由算术平方根把根号负三的平方算得 3，两部分相加等于 6，并注明根号负三的平方等于三而不是负三","prims":[{"t":"text","x":50,"y":12,"text":"平方差：(√5+√2)(√5-√2) = 5 - 2 = 3","size":3.5,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":26,"text":"算术根：√((-3)²) = √9 = |-3| = 3","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":42,"text":"两部分相加：3 + 3 = 6","size":3.8,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":56,"text":"√((-3)²) = 3，而 (√-3)² 无意义","size":3.4,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["前半部分符合平方差公式：(√(5)+√(2))(√(5)-√(2))=(√(5))²-(√(2))²=5-2=3。","后半部分：(-3)²=√(9)=3（也可用 a²=|a|=|-3|=3）。","把两部分相加：3+3=6。"]},{"type":"p","text":"答案：6"},{"type":"note","title":"方法小结","text":"要分清 (-3)²=3（结果为 3）与 (√(-3))²（无意义）。平方差公式在二次根式乘法中非常好用，看到 √(a)+√(b) 与 √(a)-√(b) 相乘就立刻套用。"},{"type":"note","title":"例题","text":"已知 x=√(3)+1，求 x²-2x 的值。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-e3","title":"先配方，再整体代入","caption":"x²-2x=(x-1)²-1，代入后只剩一个干净的整体","view":"wide","alt":"自上而下三步：先把 x 平方减 2x 配方成 x 减 1 的平方减 1，再代入 x 等于根号 3 加 1 得 x 减 1 等于根号 3，最后算得原式等于 3 减 1 等于 2","prims":[{"t":"text","x":50,"y":10,"text":"配方：x² - 2x = (x-1)² - 1","size":3.8,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":15,"x2":50,"y2":23,"tone":"accent"},{"t":"text","x":50,"y":30,"text":"代入 x = √3 + 1，得 x - 1 = √3","size":3.7,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":50,"y1":36,"x2":50,"y2":44,"tone":"accent"},{"t":"text","x":50,"y":52,"text":"原式 = (√3)² - 1 = 3 - 1 = 2","size":3.9,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["观察所求式：x²-2x=(x-1)²-1，这是配方法。","把 x=√(3)+1 代入得 x-1=√(3)。","所以 (x-1)²=(√(3))²=3。","因此 x²-2x=3-1=2。","也可以直接计算检验：x²=(√(3)+1)²=3+2√(3)+1=4+2√(3)，2x=2√(3)+2，相减得 4+2√(3)-2√(3)-2=2，结果一致。"]},{"type":"p","text":"答案：2"},{"type":"note","title":"方法小结","text":"含根式的代数式求值，优先考虑配方法或整体代换：本题中 x-1=√(3) 是一个很干净的整体，直接代入比展开 x² 更省力、更不易错。"},{"type":"note","title":"例题","text":"求使代数式 √(x-2)+(1)/(x-3) 在实数范围内有意义的 x 的取值范围。"},{"type":"figure","figure":{"id":"fig-m-num-erci-genshi-quzhi-1","title":"取值范围：两类限制取交集","caption":"x≥2 且 x≠3","view":"wide","alt":"数轴上从 2 开始向右画实心圆点和射线表示 x 大于等于 2，在 3 处画空心圆圈表示 x 不等于 3，最终取值范围是 x 大于等于 2 且不等于 3","prims":[{"t":"line","x1":10,"y1":50,"x2":90,"y2":50},{"t":"arrow","x1":90,"y1":50,"x2":94,"y2":50},{"t":"line","x1":10,"y1":47,"x2":10,"y2":53},{"t":"line","x1":26,"y1":47,"x2":26,"y2":53},{"t":"line","x1":42,"y1":47,"x2":42,"y2":53},{"t":"line","x1":58,"y1":47,"x2":58,"y2":53},{"t":"line","x1":74,"y1":47,"x2":74,"y2":53},{"t":"text","x":10,"y":60,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":26,"y":60,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":42,"y":60,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":58,"y":60,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":74,"y":60,"text":"4","size":3.4,"anchor":"middle"},{"t":"dot","x":42,"y":50,"tone":"accent"},{"t":"arrow","x1":42,"y1":50,"x2":88,"y2":50,"tone":"accent","width":2},{"t":"dot","x":58,"y":50,"hollow":true,"tone":"danger"},{"t":"text","x":58,"y":40,"text":"排除 x=3","size":3.4,"tone":"danger","anchor":"middle"},{"t":"text","x":66,"y":38,"text":"（分母不能为 0）","size":3.2,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":70,"text":"x≥2 且 x≠3","size":3.8,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["代数式由二次根式与分式两部分组成，想到两部分各自的限制要同时满足。","二次根式要求被开方数非负：x-2≥ 0，即 x≥ 2。","分式要求分母不为 0：x-3≠ 0，即 x≠ 3。","取两个条件的公共部分，得 x≥ 2 且 x≠ 3。"]},{"type":"p","text":"答案：x 的取值范围是 x≥ 2 且 x≠ 3"},{"type":"note","title":"方法小结","text":"复合代数式的取值范围是各部分限制的交集：x=2 时根号为 0 仍有意义，要保留；x=3 时分母为 0，必须排除。两类限制的端点处理方式不同，最容易合并成一个连续区间而漏掉排除点。"},{"type":"note","title":"例题","text":"观察下列各式：1√(2)+1=√(2)-1，1√(3)+√(2)=√(3)-√(2)，1√(4)+√(3)=√(4)-√(3)，……利用其中的规律计算：1√(2)+1+1√(3)+√(2)+1√(4)+√(3)+…+1√(100)+√(99)。"},{"type":"list","title":"解题步骤","items":["观察每个分母都是相邻两数的平方根之和，想到用平方差公式进行分母有理化：1√(n+1)+√(n)=√(n+1)-√(n)。","按规律改写每一项，原式 =(√(2)-1)+(√(3)-√(2))+(√(4)-√(3))+…+(√(100)-√(99))。","相邻两项的根式首尾抵消（裂项相消），只剩 -1 与最后一项的 √(100)。","故原式 =√(100)-1=10-1=9。"]},{"type":"p","text":"答案：9"},{"type":"note","title":"方法小结","text":"「分母是相邻两根号之和」的一串式子，分母有理化后必然裂项相消，中间项全部抵消，只留下首尾两项。最后一项 √(100)=10 要记得取算术根。"},{"type":"list","title":"易错点","items":["忽略被开方数非负的条件，如认为 $\\sqrt{x-3}$ 中 $x$ 可以取任意实数。正确条件是 $x\\geq 3$。","把 $\\sqrt{a}+\\sqrt{b}$ 合并成 $\\sqrt{a+b}$，如错误地写 $\\sqrt{2}+\\sqrt{3}=\\sqrt{5}$。根号内不能这样相加。","混淆 $(\\sqrt{a})^{2}$ 与 $\\sqrt{a^{2}}$：前者等于 $a$（需 $a\\geq 0$），后者等于 $|a|$，如 $\\sqrt{(-3)^{2}}=3$。","化简结果不是最简二次根式，如把 $\\sqrt{8}$ 写成 $2\\sqrt{2}$ 之后仍留着，或把 $\\sqrt{\\frac{1}{2}}$ 直接写成 $\\frac{\\sqrt{1}}{\\sqrt{2}}$ 而不有理化。","分母有理化时只乘分子或只乘分母，或忘记分子也要同乘，如把 $\\frac{1}{\\sqrt{3}}$ 写成 $\\frac{1\\times\\sqrt{3}}{\\sqrt{3}}$。","合并同类二次根式时把被开方数也相加，如算成 $2\\sqrt{3}+3\\sqrt{3}=5\\sqrt{6}$。被开方数不变，只合并系数。"]},{"type":"list","title":"解题方法","items":["二次根式加减三步：化简（化最简二次根式）、判断（找同类二次根式）、合并（系数相加减）。","分母有理化两招：分母是单项根式就同乘该根式；分母是 √(a)±√(b) 就同乘共轭式，用平方差公式去掉根号。","乘法优先用公式：平方差公式与完全平方公式在根式运算中同样成立，能省去大量展开计算。","求值先化简或配方，把含未知数的式子整理成易于代入的形式，如把 x²-2x 写成 (x-1)²-1。","判断取值范围三条：被开方数 ≥ 0、分母 ≠ 0、零指数与负指数幂的底数 ≠ 0。"]}],"questions":[{"id":"m-num-erci-genshi-q1","type":"choice","stem":"若 √(x-3) 有意义，则 x 的取值范围是（ ）","answer":"B","explain":"二次根式有意义的条件是被开方数非负，即 x-3≥ 0，解得 x≥ 3，选 B。注意不能用 x>3：当 x=3 时 √(0)=0 是有意义的。","options":["x>3","x≥ 3","x≤ 3","x≠ 3"],"difficulty":1,"tags":["二次根式","取值范围"]},{"id":"m-num-erci-genshi-q2","type":"choice","stem":"下列计算正确的是（ ）","answer":"C","explain":"C 正确：√(8)=√(4× 2)=2√(2)。A 错：被开方数不同的二次根式不能直接相加。B 错：(-3)²=√(9)=3，算术平方根为正值。D 错：3√(2)-√(2)=(3-1)√(2)=2√(2)，不能把被开方数丢掉。","options":["√(2)+√(3)=√(5)","(-3)²=-3","√(8)=2√(2)","3√(2)-√(2)=3"],"difficulty":1,"tags":["二次根式运算","化简","易错"]},{"id":"m-num-erci-genshi-q3","type":"fill","stem":"计算：√(18)-√(8)=（ ）。","answer":"√2","explain":"先化成最简二次根式：√(18)=√(9× 2)=3√(2)，√(8)=√(4× 2)=2√(2)。再合并同类二次根式：3√(2)-2√(2)=(3-2)√(2)=√(2)。若直接算 √(18)-√(8)=√(10) 就完全错了，被开方数不能直接相减。","difficulty":1,"tags":["二次根式加减","化简"]},{"id":"m-num-erci-genshi-q4","type":"fill","stem":"计算：(√(7)-2)(√(7)+2)=（ ）。","answer":"3","explain":"用平方差公式：(√(7)-2)(√(7)+2)=(√(7))²-2²=7-4=3。这里两个括号恰好是共轭式，相乘后根号被消去，这是根式运算中最常用的技巧。","difficulty":2,"tags":["平方差","二次根式乘法"]},{"id":"m-num-erci-genshi-q5","type":"short","stem":"已知 a=√(5)+2，b=√(5)-2，求 a²-ab+b² 的值，并写出完整推理过程。","answer":"$a+b=2\\sqrt{5}$，$ab=(\\sqrt{5})^{2}-2^{2}=1$，所以 $a^{2}-ab+b^{2}=(a+b)^{2}-3ab=(2\\sqrt{5})^{2}-3\\times 1=20-3=17$。","explain":"先算两个关键的整体：a+b=(√(5)+2)+(√(5)-2)=2√(5)；ab=(√(5)+2)(√(5)-2)=(√(5))²-2²=5-4=1。再把所求式变形：a²-ab+b²=(a²+2ab+b²)-3ab=(a+b)²-3ab。代入得 (2√(5))²-3× 1=4× 5-3=20-3=17。检验：a²=5+4√(5)+4=9+4√(5)，b²=9-4√(5)，ab=1，所以 a²-ab+b²=9+4√(5)-1+9-4√(5)=17，结果一致。","difficulty":3,"tags":["整体代入","乘法公式","二次根式"],"rubric":["正确算出 a+b=2√(5)","正确算出 ab=1（用平方差公式）","把 a²-ab+b² 变形为 (a+b)²-3ab","代入并正确计算 (2√(5))²=20，最终得 17"]},{"id":"m-num-erci-genshi-z1","type":"choice","stem":"下列二次根式中，与 √(3) 是同类二次根式的是（ ）","answer":"D","explain":"同类二次根式要先化成最简二次根式再看被开方数是否相同：√(12)=√(4× 3)=2√(3)，与 √(3) 的被开方数相同，故选 D。√(18)=3√(2)、√(8)=2√(2) 都与 √(2) 同类，√(6) 已是最简且被开方数为 6，均不符合。","options":["√(6)","√(18)","√(8)","√(12)"],"difficulty":2,"tags":["二次根式","化简","二次根式加减"]},{"id":"m-num-erci-genshi-z2","type":"fill","stem":"将 2√(6)-√(2) 分母有理化，结果是（ ）。","answer":"(√6+√2)/2|（√6+√2)/2","explain":"分母是两根式之差，分子分母同乘它的共轭式 √(6)+√(2)：原式 =2(√(6)+√(2))(√(6)-√(2))(√(6)+√(2))=2(√(6)+√(2))6-2=2(√(6)+√(2))4=√(6)+√(2)2。分母用平方差公式后根号全部消去。","difficulty":3,"tags":["平方差","二次根式乘法","化简"]}]},{"id":"m-num-yici-hanshu","title":"一次函数","subtitle":"人教版八下 · 第23章 一次函数","grade":"8b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八下 · 第23章 一次函数"},{"type":"note","title":"一句话概述","text":"理解函数与变量，掌握一次函数的图像与性质、待定系数法求解析式及实际应用。"},{"type":"h","text":"先看什么：图象是一条直线"},{"type":"p","text":"一次函数 y=kx+b 的图象是一条直线，所以作图只要确定两个点：任取两个 x 的值，算出对应的 y，描点连线即可。取点时通常挑与坐标轴的交点，因为计算最省事。反过来，若已知图象是一条直线经过某两点，就能把它的解析式完全确定下来。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-s1","title":"一次函数的图象是一条直线","caption":"直线 y=2x-3 由点 P、Q 确定","view":"square","alt":"平面直角坐标系中一条从左下到右上的直线表示一次函数 y 等于 2x 减 3，直线上标出 P、Q 两点，说明一次函数的图象是一条直线、两点就能确定它","prims":[{"t":"plane","x":46,"y":46,"right":46,"left":40,"up":40,"down":50,"xLabel":"x","yLabel":"y","xTicks":[{"at":12,"label":"1"},{"at":24,"label":"2"},{"at":36,"label":"3"}],"yTicks":[{"at":12,"label":"1"},{"at":24,"label":"2"}]},{"t":"curve","points":[[40,94],[46,82],[58,58],[70,34],[82,10]],"tone":"main","width":2},{"t":"dot","x":46,"y":82,"tone":"accent","label":"P","labelDx":6,"labelDy":2},{"t":"dot","x":70,"y":34,"tone":"accent","label":"Q","labelDx":5,"labelDy":5},{"t":"text","x":30,"y":14,"text":"y = 2x - 3","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":62,"y":88,"text":"两点确定一条直线","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"画图取点时常选与两坐标轴的交点：令 x=0 得与 y 轴交点，令 y=0 得与 x 轴交点。"},{"type":"h","text":"抓条件：k 的正负决定升降"},{"type":"p","text":"斜率 k 决定直线的倾斜方向，也就是函数的增减性。k>0 时图象左低右高，y 随 x 增大而增大；k<0 时图象左高右低，y 随 x 增大而减小。所以只要看直线是「上升」还是「下降」，就能判断 k 的符号；反过来知道 k 的符号，图象的走向也就定了。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-s2","title":"k>0 上升，k<0 下降","caption":"一条从左下到右上，一条从左上到右下","view":"square","alt":"平面直角坐标系中有两条都经过原点的直线，一条从左下到右上表示 k 大于 0 时 y 随 x 增大而增大，另一条从左上到右下表示 k 小于 0 时 y 随 x 增大而减小","prims":[{"t":"plane","x":50,"y":44,"right":44,"left":44,"up":36,"down":40,"xLabel":"x","yLabel":"y","xTicks":[{"at":11,"label":"1"},{"at":-11,"label":"-1"}],"yTicks":[{"at":11,"label":"1"}]},{"t":"curve","points":[[17,77],[50,44],[83,11]],"tone":"accent","width":2},{"t":"curve","points":[[17,11],[50,44],[83,77]],"tone":"danger","width":2},{"t":"text","x":80,"y":26,"text":"y = x","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":80,"y":62,"text":"y = -x","size":3.5,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":10,"text":"k>0：图象上升（左低右高）","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":80,"text":"k<0：图象下降（左高右低）","size":3.3,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"一次函数的增减性在整个实数范围内都一样：k>0 时 x 越大 y 越大，k<0 时 x 越大 y 越小，不存在需要分区间讨论的情形。"},{"type":"h","text":"建立关系：b 定与 y 轴的交点"},{"type":"p","text":"常数项 b 决定直线与 y 轴交点的纵坐标，交点恒为 (0,b)——因为令 x=0 就有 y=b。所以 k 相同的直线互相平行，只是整体上下挪动：b>0 交于 y 轴正半轴，b<0 交于负半轴，b=0 时经过原点，此时它就是正比例函数。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-s3","title":"三条平行直线，b 各不同","caption":"k 相同则平行，b 决定与 y 轴的交点","view":"square","alt":"平面直角坐标系中三条互相平行的直线，斜率相同而截距不同，分别与 y 轴交于正 2、0、负 2 三处，说明 b 决定直线与 y 轴交点的位置，b 为 0 时经过原点","prims":[{"t":"plane","x":44,"y":50,"right":52,"left":40,"up":46,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":18,"label":"2"},{"at":-18,"label":"-2"}],"yTicks":[{"at":18,"label":"2"},{"at":-18,"label":"-2"}]},{"t":"curve","points":[[8,86],[44,50],[80,14]],"tone":"main","width":2},{"t":"curve","points":[[8,68],[44,32],[71,5]],"tone":"accent","width":2},{"t":"curve","points":[[26,86],[44,68],[80,32]],"tone":"ok","width":2},{"t":"dot","x":44,"y":32,"tone":"accent","label":"b=2","labelDx":5,"labelDy":0},{"t":"dot","x":44,"y":50,"tone":"main","label":"b=0","labelDx":5,"labelDy":0},{"t":"dot","x":44,"y":68,"tone":"ok","label":"b=-2","labelDx":5,"labelDy":0},{"t":"text","x":50,"y":92,"text":"三条直线互相平行，b 决定与 y 轴交点的位置","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"b 是直线与 y 轴交点的纵坐标，不是与 x 轴交点的横坐标，两者不要弄混。"},{"type":"h","text":"换个情境：两点定一条直线"},{"type":"p","text":"已知图象经过两个点，就能求出解析式，方法是待定系数法：先设 y=kx+b，把两个点的坐标分别代入，得到关于 k、b 的二元一次方程组，解出后写出解析式，最后回代两点检验。正比例函数只有一个未知数 k，所以一个点就够了。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-s4","title":"两点代入求出 k 与 b","caption":"A(1,3)、B(-1,-1) 都在直线 y=2x+1 上","view":"square","alt":"平面直角坐标系中标出 A(1,3) 与 B(-1,-1) 两点，一条直线同时经过这两点，表示由两点求出的解析式 y 等于 2x 加 1，说明两点就能确定一条直线","prims":[{"t":"plane","x":46,"y":46,"right":44,"left":40,"up":44,"down":40,"xLabel":"x","yLabel":"y","xTicks":[{"at":12,"label":"1"},{"at":-12,"label":"-1"}],"yTicks":[{"at":12,"label":"1"},{"at":24,"label":"2"}]},{"t":"curve","points":[[28,70],[34,58],[46,34],[58,10],[62,2]],"tone":"main","width":2},{"t":"dot","x":58,"y":10,"tone":"accent","label":"A(1,3)","labelDx":4,"labelDy":-5},{"t":"dot","x":34,"y":58,"tone":"accent","label":"B(-1,-1)","labelDx":4,"labelDy":0},{"t":"text","x":22,"y":34,"text":"两点定直线","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":62,"y":90,"text":"设 y = kx + b，代入两点解方程组","size":3.4,"anchor":"middle","tone":"ok"}]}},{"type":"note","title":"","text":"待定系数法必须代入两个点：只代入一个点解不出 k 与 b，这是最常见的失分点。"},{"type":"h","text":"核心概念"},{"type":"p","text":"函数：在一个变化过程中有两个变量 x、y，如果对于 x 的每一个确定的值，y 都有唯一确定的值与其对应，就称 y 是 x 的函数，x 是自变量。关键点：唯一确定是函数概念的核心。"},{"type":"p","text":"自变量的取值范围：使函数有意义的自变量取值的全体叫自变量的取值范围。实际问题的取值范围还要受实际意义限制，如人数取正整数、时间取非负数。"},{"type":"p","text":"正比例函数：形如 y=kx（k≠ 0）的函数叫正比例函数，k 叫比例系数。它的图像是一条经过原点的直线；k>0 时图像经过第一、三象限，y 随 x 增大而增大；k<0 时经过第二、四象限，y 随 x 增大而减小。"},{"type":"p","text":"一次函数：形如 y=kx+b（k≠ 0，k、b 为常数）的函数叫一次函数。关键点：k≠ 0 是前提；当 b=0 时它成为正比例函数，所以正比例函数是一次函数的特例。"},{"type":"p","text":"一次函数的图像与性质：一次函数的图像是一条直线，k 决定倾斜方向与增减性（k>0 时 y 随 x 增大而增大，k<0 时减小），b 决定直线与 y 轴交点的位置 (0,b)。画图只需确定两个点。"},{"type":"p","text":"待定系数法：先设出函数解析式（如 y=kx+b），再把图像上已知点的坐标代入，得到关于 k、b 的方程（组），求出系数后写出解析式。求正比例函数只需一个点，求一次函数需要两个点。"},{"type":"p","text":"一次函数与方程、不等式的关系：直线 y=kx+b 与 x 轴交点的横坐标就是方程 kx+b=0 的解；使 kx+b>0 的 x 的取值范围就是图像在 x 轴上方部分对应的横坐标范围。这就是用图像法解方程与不等式。"},{"type":"note","title":"中考考法","text":"一次函数的图象、性质与 $k$、$b$ 的符号\n选择题由图象经过的象限判断 k、b 符号、增减性或比较函数值，踩分点是看直线升降定 k、看与 y 轴交点定 b。"},{"type":"note","title":"中考考法","text":"用待定系数法求一次函数解析式\n给两个点或一组对应值求解析式，常结合平移、平行关系考查，踩分点是设 y=kx+b、代点解方程组，求回两个点检验。"},{"type":"note","title":"中考考法","text":"一次函数与方程、不等式的联系及实际建模\n以分段计费、行程图象为情境求交点、面积或方案，踩分点是写清自变量取值范围，由图象在 x 轴上下方读出不等式解集。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["一次函数的一般形式","y=kx+b\\ (k≠ 0)","k≠ 0 是前提，否则 y=b 是常值函数而不是一次函数；b=0 时即为正比例函数。"],["正比例函数","y=kx\\ (k≠ 0)","图像过原点，是 b=0 时的一次函数；只要给出一对非零的对应值就能确定 k。"],["由两点求斜率","k=y₂-y₁x₂-x₁\\ (x₁≠ x₂)","分子是纵坐标之差，分母是横坐标之差，顺序必须一致；x₁=x₂ 时直线垂直于 x 轴，不是函数图像。"],["与坐标轴的交点","直线 y=kx+b 与 y 轴交于点 (0,b)，与 x 轴交于点 (-(b)/(k),0)。","令 x=0 得与 y 轴交点，令 y=0 得与 x 轴交点；与两坐标轴围成的直角三角形面积为 (1)/(2)|(b)/(k)|· |b|。"],["图像的平移","向上平移 m 个单位（m>0）得 y=kx+b+m，向下平移 m 个单位得 y=kx+b-m，即「上加下减」直接改变 b。","左右平移要写成 y=k(x-h)+b 的形式（左加右减），斜率 k 始终不变，如 y=2x 向左平移 3 个单位得 y=2(x+3)=2x+6。"]]},{"type":"note","title":"例题","text":"已知一次函数的图像经过点 (1,3) 和 (-1,-1)，求这个一次函数的解析式。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-e1","title":"由两点求一次函数解析式","caption":"A(1,3)、B(-1,-1) 确定直线 y=2x+1","view":"square","alt":"平面直角坐标系中标出 A 点坐标一逗号三与 B 点坐标负一逗号负一，一条直线同时经过这两点，直线表达式为 y 等于 2x 加 1，说明把两点坐标代入 y 等于 kx 加 b 就能求出解析式","prims":[{"t":"plane","x":46,"y":46,"right":44,"left":38,"up":44,"down":42,"xLabel":"x","yLabel":"y","xTicks":[{"at":12,"label":"1"},{"at":-12,"label":"-1"}],"yTicks":[{"at":12,"label":"1"},{"at":24,"label":"2"},{"at":36,"label":"3"}]},{"t":"curve","points":[[28,70],[34,58],[46,34],[58,10]],"tone":"main","width":2},{"t":"dot","x":58,"y":10,"tone":"accent","label":"A(1,3)","labelDx":4,"labelDy":-5},{"t":"dot","x":34,"y":58,"tone":"accent","label":"B(-1,-1)","labelDx":4,"labelDy":5},{"t":"text","x":26,"y":22,"text":"y = 2x + 1","size":3.5,"tone":"main"},{"t":"text","x":70,"y":92,"text":"代入两点求 k、b","size":3.2,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设一次函数解析式为 y=kx+b（k≠ 0）。","把两点坐标分别代入：3=k+b，-1=-k+b。","两式相减消去 b：3-(-1)=(k+b)-(-k+b)，得 4=2k，所以 k=2。","把 k=2 代入 3=k+b，得 3=2+b，所以 b=1。","所求解析式为 y=2x+1，检验：x=1 时 y=3；x=-1 时 y=-2+1=-1，两点都满足。"]},{"type":"p","text":"答案：y=2x+1"},{"type":"note","title":"方法小结","text":"待定系数法三步「设、代、解」：设解析式、代入点的坐标、解方程组。求出 k、b 后务必用两个点都回代检验一遍。"},{"type":"note","title":"例题","text":"已知一次函数 y=-2x+4，求它分别与 x 轴、y 轴交点的坐标，并求它与两坐标轴围成的三角形面积；再指出当 x 取何值时 y<0。"},{"type":"figure","figure":{"id":"fig-m-num-yici-tuxiang-1","title":"一次函数 y=−2x+4 的图像","caption":"与 x 轴交于 (2,0)，与 y 轴交于 (0,4)，面积为 4","view":"square","alt":"平面直角坐标系中画出直线 y 等于负 2x 加 4，它与 y 轴交于 0 逗号 4，与 x 轴交于 2 逗号 0，直线与两坐标轴围成的直角三角形用阴影标出","prims":[{"t":"axis","x":20,"y":70,"w":56,"h":44,"xLabel":"x","yLabel":"y","origin":true,"xTicks":[{"at":2,"label":"2"}],"yTicks":[{"at":4,"label":"4"}]},{"t":"poly","points":[[20,70],[36,70],[20,38]],"closed":true,"tone":"accent","fill":true},{"t":"curve","points":[[20,38],[36,70],[52,102]],"tone":"main","width":2},{"t":"dot","x":20,"y":38,"tone":"danger","label":"(0,4)","labelDx":6,"labelDy":0},{"t":"dot","x":36,"y":70,"tone":"danger","label":"(2,0)","labelDx":4,"labelDy":10},{"t":"text","x":26,"y":60,"text":"面积=½×2×4=4","size":3.4,"tone":"accent","anchor":"middle"},{"t":"text","x":44,"y":52,"text":"y=−2x+4","size":3.4,"tone":"main"}]}},{"type":"list","title":"解题步骤","items":["令 x=0，得 y=4，所以与 y 轴交于 (0,4)。","令 y=0，得 -2x+4=0，x=2，所以与 x 轴交于 (2,0)。","两交点与原点构成直角三角形，两条直角边分别为 2 和 4。","面积 =(1)/(2)× 2× 4=4。","由 y<0 得 -2x+4<0，即 -2x<-4，两边同除以 -2（负数）得 x>2。","所以当 x>2 时 y<0。（从图像看，此时直线位于 x 轴下方。）"]},{"type":"p","text":"答案：与 y 轴交于 (0,4)，与 x 轴交于 (2,0)，面积 4；当 x>2 时 y<0"},{"type":"note","title":"方法小结","text":"求面积要先求出两个交点坐标，再判断直角三角形的两条直角边。由 y<0 解不等式时两边除以负数 -2，不等号方向要改变，这是与图像法互相印证的关键一步。"},{"type":"note","title":"例题","text":"某城市出租车的收费规定：当行驶里程不超过 3 千米时收起步价；超过 3 千米后，超过部分按每千米计费。已知行驶 4 千米收费 12 元，行驶 7 千米收费 21 元。求收费 y（元）与里程 x（千米，x≥ 3）之间的函数关系式，并计算行驶 10 千米应付多少元。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-e3","title":"出租车收费的一次函数图像","caption":"直线上两点 (4,12)、(7,21) 确定 y=3x","view":"square","alt":"平面直角坐标系中一条从原点出发向右上方延伸的直线，横轴表示里程千米，纵轴表示收费元，直线上标出四千米收费十二元与七千米收费二十一元两个点，说明收费 y 等于 3 倍里程，每千米 3 元","prims":[{"t":"plane","x":46,"y":46,"right":46,"left":40,"up":44,"down":46,"xLabel":"里程/千米","yLabel":"收费/元","xTicks":[{"at":12,"label":"1"},{"at":24,"label":"2"},{"at":36,"label":"3"}],"yTicks":[{"at":12,"label":"3"},{"at":24,"label":"6"},{"at":36,"label":"9"}]},{"t":"curve","points":[[46,46],[56,26],[66,6]],"tone":"main","width":2},{"t":"dot","x":56,"y":26,"tone":"accent","label":"(4,12)","labelDx":4,"labelDy":-6},{"t":"dot","x":66,"y":6,"tone":"accent","label":"(7,21)","labelDx":4,"labelDy":-5},{"t":"text","x":50,"y":64,"text":"斜率 k=3：每千米 3 元","size":3.2,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["由题意，x≥ 3 时 y 与 x 满足一次函数关系，设 y=kx+b。","代入两组数据：12=4k+b，21=7k+b。","两式相减得 9=3k，所以 k=3。","把 k=3 代入 12=4k+b，得 12=12+b，所以 b=0。","故函数关系式为 y=3x（x≥ 3），即超过 3 千米后按每千米 3 元计费，起步价部分已包含在公式中（3 千米时应收 9 元）。","当 x=10 时，y=3× 10=30（元）。"]},{"type":"p","text":"答案：y=3x（x≥ 3）；行驶 10 千米应付 30 元"},{"type":"note","title":"方法小结","text":"实际问题建模要抓两个量：「变化率」就是 k（每千米 3 元），「初始量」就是 b。同时必须写清自变量的取值范围 x≥ 3，否则函数关系就不完整。"},{"type":"note","title":"例题","text":"小明骑车从家出发去郊外：第 1 小时匀速行驶 20 千米，随后停留休息 0.5 小时，再用 1 小时匀速行驶 10 千米到达目的地，最后按原路以恒定速度返回，0.5 小时回到家。设出发后经过 t 小时，离家路程为 s 千米（s 随 t 变化的图象由几段线段组成）。求：（1）返回时的平均速度；（2）从出发到回到家，整个过程的平均速度（含休息时间）。"},{"type":"list","title":"解题步骤","items":["从文字中读出各段时间与路程：到达目的地时离家 20+10=30 千米，共经过 1+0.5+1=2.5 小时。","返回时路程为 30 千米、用时 0.5 小时，返回平均速度为 30÷ 0.5=60 千米/时。","求整个过程的平均速度要用「总路程除以总时间」，想到往返路程都要计入。","总路程 =30× 2=60 千米，总时间 =2.5+0.5=3 小时，平均速度 =60÷ 3=20 千米/时。"]},{"type":"p","text":"答案：（1）返回平均速度为 60 千米/时；（2）整个过程的平均速度为 20 千米/时"},{"type":"note","title":"方法小结","text":"行程图象题先把每段的时间、路程理清再计算。平均速度必须用总路程除以总时间：往返时总路程是单程的 2 倍，休息、停留时间也要计入总时间，不能只把几段速度取平均值。"},{"type":"note","title":"例题","text":"已知一次函数 y=2x+4 的图象与 x 轴、y 轴分别交于点 A、B。把该图象沿 y 轴向上平移 m 个单位长度（m>0），平移后的直线与两坐标轴围成的三角形面积为 9，求 m 的值。"},{"type":"figure","figure":{"id":"fig-m-num-yici-hanshu-e4","title":"向上平移后与坐标轴围成的三角形","caption":"y=2x+4 向上平移 2 个单位得 y=2x+6，面积由 4 变为 9","view":"square","alt":"平面直角坐标系中画出两条互相平行的直线，y 等于 2x 加 4 与 y 等于 2x 加 6，一条向上的箭头表示直线整体向上平移，说明平移后直线与两坐标轴围成的直角三角形面积变大","prims":[{"t":"plane","x":40,"y":52,"right":48,"left":34,"up":40,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":24,"label":"2"},{"at":-24,"label":"-2"}],"yTicks":[{"at":24,"label":"2"},{"at":48,"label":"4"}]},{"t":"curve","points":[[10,64],[40,4]],"tone":"main","width":2},{"t":"curve","points":[[4,52],[16,28],[28,4]],"tone":"accent","width":2},{"t":"arrow","x1":22,"y1":40,"x2":22,"y2":16,"tone":"accent","label":"向上平移 2","labelDx":36},{"t":"dot","x":16,"y":52,"tone":"danger","label":"A(-2,0)","labelDx":2,"labelDy":13},{"t":"text","x":12,"y":78,"text":"y = 2x + 4","size":3.4,"tone":"main"},{"t":"text","x":16,"y":20,"text":"y = 2x + 6","size":3.4,"tone":"accent"},{"t":"text","x":62,"y":92,"text":"平移后三角形面积为 9","size":3.2,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先求原直线与坐标轴的交点：令 y=0 得 x=-2，故 A(-2,0)；令 x=0 得 y=4，故 B(0,4)。","直线向上平移 m 个单位，想到「上加下减在常数项」，新解析式为 y=2x+4+m。","新直线与坐标轴交于 (-(4+m)/(2),0) 与 (0,4+m)，两截距的绝对值分别为 (4+m)/(2) 和 4+m。","由三角形面积为 9 列方程：(1)/(2)× (4+m)/(2)×(4+m)=9，即 (4+m)²=36。因 m>0，故 4+m=6，得 m=2。"]},{"type":"p","text":"答案：m=2"},{"type":"note","title":"方法小结","text":"图象平移后求与坐标轴围成的面积，先写出平移后的解析式，再取两轴交点作为直角三角形的两条直角边。面积列方程会得到平方的形式，要结合题设 m>0 取舍负根。"},{"type":"list","title":"易错点","items":["忽略 $k\\neq 0$ 这一前提，如把 $y=b$ 当作一次函数，或在含参数的题目中忘记讨论二次项系数。","把一次函数与正比例函数混为一谈，认为一次函数都是正比例函数。正比例函数是一次函数中 $b=0$ 的特殊情况。","由图像判断 $k$、$b$ 的符号出错，如直线从左向右下降却判定 $k>0$。记住：左低右高的直线 $k>0$，左高右低则 $k<0$；与 $y$ 轴交点在原点上方则 $b>0$。","左右平移的规律用错，如把 $y=2x$ 向左平移 3 个单位写成 $y=2x+3$。正确结果是 $y=2(x+3)=2x+6$（左加右减作用于 $x$）。","待定系数法只代入一个点就求 $k$、$b$，得出错误的解析式。一次函数需要两个点。","实际问题中不写自变量取值范围，或忽略「里程取正数」等实际限制。"]},{"type":"list","title":"解题方法","items":["待定系数法三步：设解析式、代点坐标、解方程组，最后回代检验。","数形结合：由解析式画图（取两点定直线），由图像读性质（升降看 k、交点看 b、象限看符号）。","判断增减性与最值：k>0 时 y 随 x 增大而增大，在给定区间的最小值在左端点、最大值在右端点，k<0 时相反。","与方程、不等式的互化：令 y=0 求方程的解，令 y>0 或 y<0 解不等式，都可在图像上直观验证。","实际应用题建模：找出「起始量」（对应 b）与「单位变化量」（对应 k），再写取值范围。"]}],"questions":[{"id":"m-num-yici-hanshu-q1","type":"choice","stem":"一次函数 y=-3x+2 的图像经过（ ）","answer":"B","explain":"因为 k=-3<0，y 随 x 增大而减小，直线左高右低；又 b=2>0，直线与 y 轴交于正半轴上的点 (0,2)。这样的直线经过第一、二、四象限，不经过第三象限，故选 B。可验证：取 x=0 得点 (0,2)，取 y=0 得点 ((2)/(3),0)，画图连线即可看出。","options":["第一、二、三象限","第一、二、四象限","第二、三、四象限","第一、三、四象限"],"difficulty":2,"tags":["一次函数图像","象限","k与b的符号"]},{"id":"m-num-yici-hanshu-q2","type":"choice","stem":"若 y 与 x 成正比例，且当 x=2 时 y=-6，则 y 与 x 的函数关系式是（ ）","answer":"B","explain":"设 y=kx（k≠ 0）。把 x=2、y=-6 代入得 -6=2k，所以 k=-3，解析式为 y=-3x。检验：x=2 时 y=-3× 2=-6，与已知相符，故选 B。","options":["y=3x","y=-3x","y=-(1)/(3)x","y=(1)/(3)x"],"difficulty":1,"tags":["正比例函数","待定系数法"]},{"id":"m-num-yici-hanshu-q3","type":"fill","stem":"一次函数 y=2x-6 的图像与 x 轴的交点坐标是（ ）。（如 (1,0)）","answer":"(3,0)","explain":"与 x 轴的交点纵坐标为 0，令 y=0 得 2x-6=0，解得 x=3，所以交点坐标是 (3,0)。顺便可知与 y 轴交点为 (0,-6)，函数图像经过第一、三、四象限。","difficulty":1,"tags":["一次函数","交点坐标"]},{"id":"m-num-yici-hanshu-q4","type":"fill","stem":"直线 y=kx+b 经过点 (0,3) 和 (2,7)，则 k+b=（ ）。","answer":"5","explain":"点 (0,3) 在 y 轴上，故 b=3。把 (2,7) 代入 y=kx+3 得 7=2k+3，所以 2k=4，k=2。因此 k+b=2+3=5。检验：解析式为 y=2x+3，x=2 时 y=7，与已知相符。","difficulty":2,"tags":["待定系数法","一次函数"]},{"id":"m-num-yici-hanshu-q5","type":"short","stem":"某文具店销售一种笔记本，售价为每本 5 元，同时推出优惠方案：一次性购买 10 本以上（含 10 本）时，超过 10 本的部分按每本 4 元计价。设购买 x 本（x≥ 10）需付 y 元，求 y 与 x 的函数关系式，并求购买 20 本需付多少元。（要求写出建模过程）","answer":"$y=5\\times 10+4(x-10)=4x+10$（$x\\geq 10$）；购买 20 本时 $y=4\\times 20+10=90$ 元。","explain":"前 10 本按每本 5 元计价，共 5× 10=50 元；超过 10 本的部分有 (x-10) 本，按每本 4 元计价，共 4(x-10) 元。所以 y=50+4(x-10)=50+4x-40=4x+10（x≥ 10）。这是一次函数，其中 k=4 表示超过部分每本 4 元，b=10 是式子整理后的常数项。当 x=20 时，y=4× 20+10=90 元。检验：前 10 本 50 元，后 10 本 10× 4=40 元，合计 90 元，一致。","difficulty":3,"tags":["一次函数应用","分段计价","建模"],"rubric":["正确区分「前 10 本」与「超过 10 本的部分」，写出 4(x-10)（或说明超过部分为 x-10 本）","列出 y=50+4(x-10) 并化简为 y=4x+10","注明自变量取值范围 x≥ 10","正确算出购买 20 本需付 90 元","有检验或作答语句，答案带单位「元」"]},{"id":"m-num-yici-hanshu-z1","type":"choice","stem":"已知某一次函数的图象平行于直线 y=2x，且经过点 (0,3)，则该函数的解析式为（ ）","answer":"A","explain":"两直线平行则斜率相同，故 k=2，设解析式为 y=2x+b。图象过点 (0,3)，即与 y 轴交于 (0,3)，故 b=3，解析式为 y=2x+3，选 A。C 项斜率取反，B 项截距符号错误。","options":["y=2x+3","y=2x-3","y=-2x+3","y=(1)/(2)x+3"],"difficulty":2,"tags":["待定系数法","一次函数","一次函数图像"]},{"id":"m-num-yici-hanshu-z2","type":"fill","stem":"将直线 y=-2x+1 沿 y 轴向上平移 3 个单位长度，则平移后直线与 y 轴的交点坐标为（ ）。","answer":"(0，4)|(0,4)|（0，4）|（0,4）","explain":"直线沿 y 轴向上平移 3 个单位，常数项加 3，新直线为 y=-2x+1+3=-2x+4。令 x=0，得 y=4，故与 y 轴交点为 (0,4)。","difficulty":2,"tags":["一次函数图像","一次函数","交点坐标"]}]},{"id":"m-num-yiyuan-erci","title":"一元二次方程","subtitle":"人教版九上 · 第25章 一元二次方程","grade":"9a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版九上 · 第25章 一元二次方程"},{"type":"note","title":"一句话概述","text":"掌握一元二次方程四种解法、根的判别式与根与系数关系，会解增长率等应用题。"},{"type":"h","text":"判别式决定交点个数"},{"type":"p","text":"把方程 ax²+bx+c=0 改写成函数 y=ax²+bx+c，方程的根就是抛物线与 x 轴交点的横坐标。判别式 Δ=b²-4ac 的符号决定了这条抛物线与 x 轴有没有交点、有几个交点，所以不解方程也能先判断根的情况。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-s1","title":"判别式 Δ 的三种情形","caption":"Δ 的符号对应抛物线与 x 轴交点的个数","view":"wide","alt":"并排三个小坐标系各画一条开口向上的抛物线：左图判别式大于零，抛物线与 x 轴交于两点，有两个交点；中图判别式等于零，抛物线与 x 轴只有一个交点；右图判别式小于零，抛物线与 x 轴没有交点","prims":[{"t":"line","x1":4,"y1":44,"x2":32,"y2":44,"tone":"muted"},{"t":"arrow","x1":32,"y1":44,"x2":35,"y2":44,"tone":"muted"},{"t":"line","x1":17,"y1":52,"x2":17,"y2":10,"tone":"muted"},{"t":"arrow","x1":17,"y1":10,"x2":17,"y2":7,"tone":"muted"},{"t":"curve","points":[[5,26],[8,36.5],[11,44],[14,48.5],[17,50],[20,48.5],[23,44],[26,36.5],[29,26]],"tone":"main","width":2},{"t":"dot","x":11,"y":44,"tone":"danger"},{"t":"dot","x":23,"y":44,"tone":"danger"},{"t":"text","x":17,"y":57,"text":"Δ>0","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":17,"y":61.5,"text":"两个交点","size":3.2,"anchor":"middle","tone":"muted"},{"t":"line","x1":37,"y1":44,"x2":65,"y2":44,"tone":"muted"},{"t":"arrow","x1":65,"y1":44,"x2":68,"y2":44,"tone":"muted"},{"t":"line","x1":50,"y1":52,"x2":50,"y2":10,"tone":"muted"},{"t":"arrow","x1":50,"y1":10,"x2":50,"y2":7,"tone":"muted"},{"t":"curve","points":[[42,51.7],[45,46.9],[48,44.5],[50,44],[52,44.5],[55,46.9],[58,51.7]],"tone":"main","width":2},{"t":"dot","x":50,"y":44,"tone":"danger"},{"t":"text","x":50,"y":57,"text":"Δ=0","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":61.5,"text":"一个交点","size":3.2,"anchor":"middle","tone":"muted"},{"t":"line","x1":70,"y1":44,"x2":94,"y2":44,"tone":"muted"},{"t":"arrow","x1":94,"y1":44,"x2":97,"y2":44,"tone":"muted"},{"t":"line","x1":83,"y1":52,"x2":83,"y2":10,"tone":"muted"},{"t":"arrow","x1":83,"y1":10,"x2":83,"y2":7,"tone":"muted"},{"t":"curve","points":[[72,42.9],[76,36.2],[80,32.8],[83,32],[86,32.8],[90,36.2],[94,42.9]],"tone":"main","width":2},{"t":"text","x":83,"y":57,"text":"Δ<0","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":83,"y":61.5,"text":"无交点","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"判别式只管「有没有、有几个」实数根，不告诉你根是多少；要算出根还得靠因式分解或求根公式。"},{"type":"h","text":"配方法：拼成完全平方"},{"type":"p","text":"配方法的目标是把方程左边凑成一个完全平方式。x²+bx 可以看成长 x、宽 x 的正方形缺了两个长条缺口，补上两个 x·(b)/(2) 的长条和一块边长为 (b)/(2) 的小正方形，正好拼成边长 x+(b)/(2) 的大正方形，也就是 x²+bx+((b)/(2))²=(x+(b)/(2))²。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-s2","title":"用面积拼图看懂配方","caption":"四块面积拼成边长 x+b/2 的大正方形","view":"square","alt":"一个大正方形被分成四块：左上角是边长 x 的正方形，面积为 x 平方；右上和左下是两个面积都为 x 乘二分之 b 的长方形；右下角是面积为二分之 b 的平方的小正方形。四块拼起来正好是边长 x 加二分之 b 的大正方形，所以 x 平方加 bx 加二分之 b 的平方等于 x 加二分之 b 的平方","prims":[{"t":"rect","x":20,"y":20,"w":42,"h":42,"tone":"accent","fill":true},{"t":"rect","x":62,"y":20,"w":18,"h":42,"tone":"main","fill":true},{"t":"rect","x":20,"y":62,"w":42,"h":18,"tone":"main","fill":true},{"t":"rect","x":62,"y":62,"w":18,"h":18,"tone":"ok","fill":true},{"t":"text","x":41,"y":43.5,"text":"x²","size":4.6,"anchor":"middle"},{"t":"text","x":71,"y":43.5,"text":"x·b/2","size":3,"anchor":"middle"},{"t":"text","x":41,"y":73.5,"text":"x·b/2","size":3,"anchor":"middle"},{"t":"text","x":71,"y":73.5,"text":"(b/2)²","size":2.8,"anchor":"middle"},{"t":"text","x":41,"y":14,"text":"x","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":71,"y":14,"text":"b/2","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":13,"y":41,"text":"x","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":13,"y":71,"text":"b/2","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":91,"text":"x² + 2·x·(b/2) + (b/2)² = (x + b/2)²","size":3.4,"anchor":"middle","tone":"main"}]}},{"type":"note","title":"","text":"两边都要加上 ((b)/(2))²，只加一边就不成等式了；配方后右边是负数，说明原方程没有实数根。"},{"type":"h","text":"因式分解与公式法对照"},{"type":"p","text":"同一个方程有两条路可走。因式分解把方程改写成 (x-x₁)(x-x₂)=0 的形式，由「积为 0 则至少一个因式为 0」一眼看出两个根；求根公式 x=-b±b²-4ac2a 对一切有实数根的方程都管用，是万能兜底。能分解时分解更快，分不动就用公式。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-s3","title":"两种解法殊途同归","caption":"能分解就分解，不能分解用公式","view":"wide","alt":"上方写着一元二次方程的一般形式 ax 平方加 bx 加 c 等于零，其中 a 不等于零。左侧方框是因式分解法，写成 x 减 x₁ 乘 x 减 x₂ 等于零；右侧方框是求根公式法，用 x 等于 2a 分之负 b 加减根号下 b 平方减 4ac。两条路都指向下方，得到方程的两个根","prims":[{"t":"text","x":50,"y":11,"text":"ax² + bx + c = 0（a≠0）","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":36,"y1":16,"x2":22,"y2":22,"tone":"accent"},{"t":"arrow","x1":64,"y1":16,"x2":78,"y2":22,"tone":"main"},{"t":"rect","x":5,"y":22,"w":36,"h":26,"tone":"accent"},{"t":"rect","x":59,"y":22,"w":36,"h":26,"tone":"main"},{"t":"text","x":23,"y":32,"text":"因式分解法","size":3.8,"anchor":"middle","tone":"accent"},{"t":"text","x":23,"y":41,"text":"(x-x₁)(x-x₂)=0","size":3,"anchor":"middle"},{"t":"text","x":77,"y":32,"text":"求根公式法","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":77,"y":41,"text":"x=(-b±√Δ)/(2a)","size":3,"anchor":"middle"},{"t":"arrow","x1":23,"y1":49,"x2":42,"y2":58,"tone":"accent"},{"t":"arrow","x1":77,"y1":49,"x2":58,"y2":58,"tone":"main"},{"t":"rect","x":30,"y":58,"w":40,"h":12,"tone":"ok","label":"方程的两个根"}]}},{"type":"note","title":"","text":"因式分解只对「能分解」的方程好用；公式法对所有 Δ≥ 0 的方程都适用，是保底方法。"},{"type":"h","text":"实际问题要取舍根"},{"type":"p","text":"增长率、面积这类实际问题列出的方程，两根常常都算得出来，但只有一根符合实际意义。增长率模型 a(1+x)²=b 求出的负根表示「下降超过 100%」，面积问题里大于边长的根也放不进图形，都必须舍去。所以解完方程一定要回到题目情境里检验。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-s4","title":"两根都要回题目里检验","caption":"增长率、长度不能为负，负根必须舍去","view":"wide","alt":"解一元二次方程得到两个根：左侧 x 等于 0.2，因为增长率为正、符合题意而保留；右侧 x 等于负 2.2，因为增长率为负、不符合实际而舍去。说明实际问题解完方程后必须回到题目情境里检验取舍","prims":[{"t":"text","x":50,"y":12,"text":"解方程得到两个根","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":42,"y1":17,"x2":27,"y2":24,"tone":"accent"},{"t":"arrow","x1":58,"y1":17,"x2":73,"y2":24,"tone":"danger"},{"t":"rect","x":6,"y":25,"w":40,"h":14,"tone":"ok"},{"t":"rect","x":54,"y":25,"w":40,"h":14,"tone":"danger"},{"t":"text","x":26,"y":32,"text":"x = 0.2","size":4,"anchor":"middle","tone":"ok"},{"t":"text","x":74,"y":32,"text":"x = -2.2","size":4,"anchor":"middle","tone":"danger"},{"t":"text","x":26,"y":46,"text":"增长率为正，符合题意","size":3.2,"anchor":"middle","tone":"ok"},{"t":"text","x":74,"y":46,"text":"增长率为负，舍去","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":57,"text":"只有符合实际的根才是答案","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"纯计算题两根都要写；只有实际问题才需要结合情境取舍，取舍的理由要写清楚。"},{"type":"h","text":"核心概念"},{"type":"p","text":"一元二次方程的定义：只含有一个未知数，并且未知数的最高次数是 2 的整式方程叫一元二次方程，一般形式为 ax²+bx+c=0（a≠ 0）。关键点：a≠ 0 是定义的一部分，a 叫二次项系数、b 叫一次项系数、c 叫常数项。"},{"type":"p","text":"一元二次方程的根：使一元二次方程左右两边相等的未知数的值叫方程的根（解）。关键点：一元二次方程最多有两个实数根，判断某数是否为根只需代入检验。"},{"type":"p","text":"直接开平方法与配方法：形如 (x+m)²=n（n≥ 0）的方程用直接开平方法解得 x=-m±√(n)；一般方程可先配方成这种形式，配方时两边都加上一次项系数一半的平方。"},{"type":"p","text":"公式法：把方程化为一般形式后，代入求根公式 x=-b±b²-4ac2a 求解。关键点：使用前必须确定 a、b、c 的值（含符号），并先算出判别式判断是否有实数根。"},{"type":"p","text":"因式分解法：若方程一边为 0，另一边能分解成两个一次因式的积，则令每个因式为 0 分别求解，即由 AB=0 得 A=0 或 B=0。关键点：千万不能两边直接约去含未知数的公因式，那样会丢根。"},{"type":"p","text":"根的判别式：把 b²-4ac 叫做根的判别式，记作 Δ。当 Δ>0 时方程有两个不相等的实数根；Δ=0 时有两个相等的实数根；Δ<0 时没有实数根。"},{"type":"p","text":"根与系数的关系（韦达定理）：若 x₁、x₂ 是方程 ax²+bx+c=0（a≠ 0，Δ≥ 0）的两个根，则 x₁+x₂=-(b)/(a)，x₁x₂=(c)/(a)。关键点：使用时必须先保证方程有实数根。"},{"type":"note","title":"中考考法","text":"一元二次方程的四种解法与丢根问题\n直接开平方法、配方法、公式法、因式分解法按方程特征选用，踩分点是两边不能直接约去含未知数的因式，否则丢零根。"},{"type":"note","title":"中考考法","text":"根的判别式与参数范围\n由「有两个不相等/相等实数根、无实数根」转化为 Δ 的符号求参数范围，证明题常配方成完全平方式说明 Δ≥ 0。"},{"type":"note","title":"中考考法","text":"韦达定理的整体代入与实际应用\n不求根而求两根对称式的值，或列增长率、面积、利润方程，踩分点是用前先验 Δ≥ 0，应用题对不符合实际的根要舍去。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["一元二次方程的一般形式","ax²+bx+c=0\\ (a≠ 0)","a≠ 0 是前提；判断是否为一元二次方程必须先整理成一般形式再比较最高次数。"],["求根公式","x=-b±b²-4ac2a","要求 a≠ 0 且 b²-4ac≥ 0；a、b、c 必须取自一般形式，符号不能丢。"],["根的判别式","Δ=b²-4ac","Δ>0 有两个不相等的实数根，Δ=0 有两个相等的实数根，Δ<0 无实数根。"],["根与系数的关系","x₁+x₂=-(b)/(a), x₁x₂=(c)/(a)","前提是方程有两个实数根（Δ≥ 0）且 a≠ 0；常用于不解方程求含根的对称式的值。"],["配方法","x²+px+q=0\\ ⇒\\ (x+(p)/(2))²=p²4-q","两边同时加上一次项系数一半的平方 ((p)/(2))²，配方后要求右边非负才有实数根。"],["增长率（下降率）模型","a(1± x)²=b","a 为变化前的量，b 为两次变化后的量，x 为平均增长率（取加号）或下降率（取减号）；求出两根后要舍去不合题意的根。"]]},{"type":"note","title":"例题","text":"解方程：x²-4x-5=0。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-paowuxian-1","title":"方程的根就是抛物线与 x 轴的交点","caption":"y=x²−4x−5 与 x 轴交于 (−1,0) 和 (5,0)","view":"wide","alt":"平面直角坐标系中画出开口向上的抛物线 y 等于 x 平方减 4x 减 5，顶点在 2 逗号负 9，对称轴为直线 x 等于 2，与 x 轴交于负 1 逗号 0 和 5 逗号 0 两点","prims":[{"t":"line","x1":10,"y1":45,"x2":82,"y2":45},{"t":"line","x1":30,"y1":10,"x2":30,"y2":82},{"t":"arrow","x1":82,"y1":45,"x2":86,"y2":45},{"t":"arrow","x1":30,"y1":10,"x2":30,"y2":6},{"t":"line","x1":22,"y1":43,"x2":22,"y2":47},{"t":"line","x1":70,"y1":43,"x2":70,"y2":47},{"t":"line","x1":28,"y1":27,"x2":32,"y2":27},{"t":"text","x":22,"y":53,"text":"-1","size":3.2,"anchor":"middle"},{"t":"text","x":70,"y":53,"text":"5","size":3.2,"anchor":"middle"},{"t":"text","x":25,"y":27,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":86,"y":48,"text":"x","size":3.4,"anchor":"middle"},{"t":"text","x":34,"y":12,"text":"y","size":3.4},{"t":"line","x1":46,"y1":20,"x2":46,"y2":78,"tone":"muted","dashed":true},{"t":"text","x":48,"y":18,"text":"对称轴 x=2","size":3.2,"tone":"muted"},{"t":"curve","points":[[14,19],[22,45],[30,62.5],[46,76.5],[62,62.5],[70,45],[78,20.5]],"tone":"main","width":2},{"t":"dot","x":22,"y":45,"tone":"danger","label":"(-1,0)","labelDx":-4,"labelDy":12},{"t":"dot","x":70,"y":45,"tone":"danger","label":"(5,0)","labelDx":4,"labelDy":12},{"t":"dot","x":46,"y":76.5,"tone":"accent","label":"顶点(2,-9)","labelDx":8,"labelDy":0}]}},{"type":"list","title":"解题步骤","items":["观察常数项与一次项系数，尝试十字相乘：把 -5 分解为 -5 与 1，而 -5+1=-4，正好是一次项系数。","因式分解得 (x-5)(x+1)=0。","由「两个因式的积为 0，则至少有一个因式为 0」，得 x-5=0 或 x+1=0。","所以 x₁=5，x₂=-1。","检验：5²-4× 5-5=25-20-5=0；(-1)²-4×(-1)-5=1+4-5=0，两根都正确。"]},{"type":"p","text":"答案：x₁=5，x₂=-1"},{"type":"note","title":"方法小结","text":"能用因式分解的方程优先因式分解，比公式法快得多。分解后必须写成「A· B=0」的形式再分别令因式为 0，不能把方程写成 (x-5)(x+1)=0 之后直接答 5 和 -1 而不写过程。"},{"type":"note","title":"例题","text":"解方程：2x²-4x+1=0。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-e2","title":"2x²-4x+1=0 的两根就是交点横坐标","caption":"Δ=8>0，抛物线与 x 轴有两个交点","view":"square","alt":"平面直角坐标系中画出开口向上的抛物线 y 等于 2x 平方减 4x 加 1，顶点在 1 逗号负 1，与 x 轴交于约 0.29 和约 1.71 两点；判别式等于 8 大于零，所以方程有两个不相等的实数根","prims":[{"t":"line","x1":8,"y1":70,"x2":92,"y2":70,"tone":"muted"},{"t":"arrow","x1":92,"y1":70,"x2":97,"y2":70,"tone":"muted"},{"t":"line","x1":40,"y1":92,"x2":40,"y2":12,"tone":"muted"},{"t":"arrow","x1":40,"y1":12,"x2":40,"y2":7,"tone":"muted"},{"t":"text","x":36,"y":76,"text":"O","size":3.2,"anchor":"end","tone":"muted"},{"t":"text","x":95,"y":75,"text":"x","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":43.5,"y":10,"text":"y","size":3.4,"anchor":"middle","tone":"muted"},{"t":"curve","points":[[33.7,22.4],[40,52],[45.3,70],[49,79],[58,88],[67,79],[70.7,70],[76,52],[82.3,22.4]],"tone":"main","width":2},{"t":"dot","x":45.3,"y":70,"tone":"danger","label":"x₁≈0.29","labelDx":-16,"labelDy":8},{"t":"dot","x":70.7,"y":70,"tone":"danger","label":"x₂≈1.71","labelDx":2,"labelDy":8},{"t":"dot","x":58,"y":88,"tone":"accent","label":"顶点(1,-1)","labelDx":-2,"labelDy":8},{"t":"text","x":74,"y":13,"text":"y = 2x² - 4x + 1","size":3.4,"anchor":"middle","tone":"main"}]}},{"type":"list","title":"解题步骤","items":["确定各系数：a=2，b=-4，c=1。","计算判别式：Δ=b²-4ac=(-4)²-4× 2× 1=16-8=8>0，所以方程有两个不相等的实数根。","代入求根公式：x=-b±√(Δ)2a=4±√(8)4。","化简根式：√(8)=2√(2)，故 x=4± 2√(2)4。","约分得 x=2±√(2)2，即 x₁=2+√(2)2，x₂=2-√(2)2。"]},{"type":"p","text":"答案：x₁=2+√(2)2，x₂=2-√(2)2"},{"type":"note","title":"方法小结","text":"公式法中 b=-4 带负号代入，-b=4 要变号，这是最容易出错的一步。结果必须化成最简形式：4± 2√(2)4 中的分子分母要同时约去 2。"},{"type":"note","title":"例题","text":"某超市 2024 年的销售额为 500 万元，2026 年的销售额达到 720 万元。求这两年销售额的年平均增长率。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-e3","title":"连续两年增长链","caption":"每次都在前一年的基础上乘 (1+x)","view":"wide","alt":"一条增长链从 2024 年的 500 万元开始，乘以 1 加 x 得到 2025 年的 500 乘 1 加 x 万元，再乘以 1 加 x 得到 2026 年的 500 乘 1 加 x 的平方万元，等于题目给出的 720 万元","prims":[{"t":"rect","x":4,"y":20,"w":26,"h":12,"tone":"accent"},{"t":"rect","x":38,"y":20,"w":28,"h":12,"tone":"main"},{"t":"rect","x":74,"y":20,"w":24,"h":12,"tone":"ok"},{"t":"text","x":17,"y":26,"text":"2024年：500万","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":52,"y":26,"text":"2025年：500(1+x)","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":86,"y":26,"text":"2026年：720万","size":3.2,"anchor":"middle","tone":"ok"},{"t":"arrow","x1":31,"y1":26,"x2":37,"y2":26,"tone":"accent","label":"× (1+x)","labelDy":-7},{"t":"arrow","x1":67,"y1":26,"x2":73,"y2":26,"tone":"main","label":"× (1+x)","labelDy":-7},{"t":"text","x":50,"y":40,"text":"500(1+x)² = 720","size":4,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":50,"text":"解出 x 后，负根 x=-2.2 不合题意要舍去","size":3.2,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["设年平均增长率为 x，则 2025 年的销售额为 500(1+x) 万元。","2026 年的销售额为 500(1+x)(1+x)=500(1+x)² 万元。","由题意列方程：500(1+x)²=720。","两边同除以 500 得 (1+x)²=1.44。","直接开平方得 1+x=1.2 或 1+x=-1.2。","解得 x=0.2 或 x=-2.2。因为增长率不能为负数（-2.2 表示下降 220%，不合题意），舍去 x=-2.2。","所以年平均增长率为 x=0.2=20\\%。检验：500× 1.2× 1.2=720（万元），符合题意。"]},{"type":"p","text":"答案：年平均增长率为 20%"},{"type":"note","title":"方法小结","text":"增长率模型的标准式是 a(1+x)^(n)=b，其中 n 是增长的次数。求出两根后必须结合实际情况舍去不合题意的根，这是应用题与纯计算题最大的区别。"},{"type":"note","title":"例题","text":"已知关于 x 的一元二次方程 x²-(m+2)x+2m=0。（1）求证：无论 m 取何实数，该方程总有实数根；（2）若等腰三角形的一边长为 3，另两边长恰好是该方程的两个根，求 m 的值与三角形的周长。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-e4","title":"等腰三角形的两种情况","caption":"方程两根 2 与 m，分「3 为腰」和「两根为腰」","view":"square","alt":"上方标出方程两根 x₁ 等于 2、x₂ 等于 m。左图是第一种情况，等腰三角形的三边为 3、3、2，此时 m 等于 3，周长 8；右图是第二种情况，两条腰是方程的两根，三边为 2、2、3，此时 m 等于 2，周长 7。两种情况都满足三角形三边关系","prims":[{"t":"text","x":50,"y":12,"text":"方程两根：x₁ = 2，x₂ = m","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":24,"y":26,"text":"① 3、3、2，周长 8","size":3.4,"anchor":"middle","tone":"main"},{"t":"poly","points":[[24,32],[12,64],[36,64]],"closed":true,"tone":"main"},{"t":"text","x":13,"y":47,"text":"3","size":3.4,"anchor":"end","tone":"main"},{"t":"text","x":35,"y":47,"text":"3","size":3.4,"anchor":"start","tone":"main"},{"t":"text","x":24,"y":71,"text":"2","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":76,"y":26,"text":"② 2、2、3，周长 7","size":3.4,"anchor":"middle","tone":"accent"},{"t":"poly","points":[[76,38],[60,64],[92,64]],"closed":true,"tone":"accent"},{"t":"text","x":61,"y":50,"text":"2","size":3.4,"anchor":"end","tone":"accent"},{"t":"text","x":91,"y":50,"text":"2","size":3.4,"anchor":"start","tone":"accent"},{"t":"text","x":76,"y":71,"text":"3","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":86,"text":"m 取 3 或 2，都满足三边关系","size":3.4,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["第（1）问要证明总有实数根，想到计算判别式并配方：Δ=(m+2)²-4× 2m=m²+4m+4-8m=(m-2)²。","因为 (m-2)²≥ 0 对一切实数 m 恒成立，即 Δ≥ 0，故方程总有实数根。","第（2）问把方程因式分解：(x-2)(x-m)=0，得两根为 x₁=2、x₂=m。","等腰三角形两边相等，分两种情况：① 腰为 3，则 m=3，三边为 3、3、2，周长 8；② 两腰是方程的两根，则 m=2，三边为 2、2、3，周长 7。两种情况都满足三边关系。"]},{"type":"p","text":"答案：（1）由 Δ=(m-2)²≥ 0 得证；（2）m=3 时周长为 8，或 m=2 时周长为 7"},{"type":"note","title":"方法小结","text":"含参数的判别式证明题，配方成完全平方式是最有力的结论；几何与方程综合时，方程的两根对应三角形的两边，等腰要分「已知边为腰」和「两根相等为腰」两种情况，并用三边关系检验。"},{"type":"note","title":"例题","text":"在一块长 32 米、宽 20 米的矩形空地上，计划沿长边一侧修一条宽度相同的纵向步道，沿宽边一侧修一条同宽的横向步道（两条步道在角落相连），其余部分全部绿化。若绿化面积为 540 平方米，求步道的宽度。"},{"type":"figure","figure":{"id":"fig-m-num-yiyuan-erci-e5","title":"两条等宽步道把绿地拼成小矩形","caption":"绿化面积 (32-x)(20-x)=540","view":"square","alt":"一个长 32 米、宽 20 米的矩形空地，右侧有一条纵向步道、下方有一条横向步道，两条步道宽度相同都是 x，并在右下角相交；其余部分是面积为 540 平方米的绿化，绿化部分可以拼成一个长 32 减 x、宽 20 减 x 的小矩形","prims":[{"t":"rect","x":20,"y":22,"w":62,"h":34,"tone":"ok","fill":true},{"t":"rect","x":82,"y":22,"w":10,"h":44,"tone":"accent","fill":true},{"t":"rect","x":20,"y":56,"w":72,"h":10,"tone":"accent","fill":true},{"t":"rect","x":20,"y":22,"w":72,"h":44,"tone":"main"},{"t":"text","x":51,"y":41,"text":"绿化 540 米²","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":87,"y":44,"text":"x","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":61,"text":"x","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":10,"y":43,"text":"20 米","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":56,"y":76,"text":"32 米","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":92,"text":"绿地拼成 (32-x) × (20-x) 的小矩形","size":3.4,"anchor":"middle","tone":"main"}]}},{"type":"list","title":"解题步骤","items":["设步道宽 x 米，想到两条步道把绿化部分拼成一个长、宽都减少 x 的小矩形。","绿化部分的长为 (32-x) 米、宽为 (20-x) 米，由绿化面积列方程：(32-x)(20-x)=540。","整理：640-52x+x²=540，即 x²-52x+100=0，因式分解为 (x-2)(x-50)=0，得 x=2 或 x=50。","检验实际意义：x=50 超过空地的长和宽，不合题意，舍去；取 x=2。"]},{"type":"p","text":"答案：步道的宽度为 2 米"},{"type":"note","title":"方法小结","text":"「修两条垂直等宽通道」问题可把剩余绿地平移拼成一个完整矩形，长和宽各减去通道宽度。方程的两个根要对照图形尺寸取舍，大于边长的根直接舍去。"},{"type":"list","title":"易错点","items":["忽略一元二次方程的定义条件 $a\\neq 0$，含参数题目中忘记讨论二次项系数。","用公式法时没把方程整理成一般形式就取系数，导致 $a$、$b$、$c$ 取错，尤其是符号错误。","判别式 $\\Delta<0$ 时仍继续用求根公式计算，写出不存在的实数根。应先判断 $\\Delta$ 的符号再决定用什么方法。","配方法时加的常数写错，应加一次项系数一半的平方，如 $x^{2}+6x$ 配成 $(x+3)^{2}-9$，而不是加 $6^{2}$。","用因式分解法时两边约去含未知数的公因式而丢根，如解 $x(x-2)=3(x-2)$ 时两边除以 $(x-2)$ 只得到 $x=3$，丢掉了 $x=2$。正确做法是移项后因式分解：$(x-2)(x-3)=0$。","实际问题中不检验、不舍去不合题意的根，如把增长率为负数的根写进答案，或把长度为负数的根留下。"]},{"type":"list","title":"解题方法","items":["解法选择顺序：能直接开平方的先开平方，能因式分解的优先因式分解，都不行再用公式法，配方法主要用于推导与求最值。","十字相乘法：把二次项系数与常数项分别分解成两个因数，交叉相乘之和等于一次项系数，如 x²-5x+6=(x-2)(x-3)。","判别式的三大用途：判断根的情况、由根的情况求参数取值范围、证明方程一定有两个实数根。","韦达定理配合恒等变形：x₁²+x₂²=(x₁+x₂)²-2x₁x₂，1x₁+1x₂=x₁+x₂x₁x₂，不解方程即可求值。","应用题建模：增长率用 a(1± x)^(n)=b，面积与几何问题用图形关系列方程，销售问题用「总利润 = 单件利润 × 销量」，最后都要检验取舍。"]}],"questions":[{"id":"m-num-yiyuan-erci-q1","type":"choice","stem":"方程 x²-2x-3=0 的两个根是（ ）","answer":"A","explain":"用十字相乘分解：把 -3 分为 -3 与 1，而 -3+1=-2 恰为一次项系数，故 x²-2x-3=(x-3)(x+1)=0，得 x₁=3、x₂=-1。检验：3²-2× 3-3=0，(-1)²-2×(-1)-3=0，均成立，故选 A。","options":["x₁=3，x₂=-1","x₁=-3，x₂=1","x₁=3，x₂=1","x₁=-3，x₂=-1"],"difficulty":1,"tags":["解方程","因式分解法"]},{"id":"m-num-yiyuan-erci-q2","type":"choice","stem":"关于 x 的方程 x²-2x+m=0 有两个不相等的实数根，则 m 的取值范围是（ ）","answer":"A","explain":"这里 a=1，b=-2，c=m，判别式 Δ=(-2)²-4× 1× m=4-4m。两个不相等的实数根要求 Δ>0，即 4-4m>0，解得 m<1，选 A。若要求「有两个相等的实数根」则应取 m=1；若要求「有实数根」则应取 m≤ 1。","options":["m<1","m≤ 1","m>1","m<0"],"difficulty":2,"tags":["根的判别式","参数范围"]},{"id":"m-num-yiyuan-erci-q3","type":"fill","stem":"若 x₁、x₂ 是方程 x²-3x-2=0 的两个根，则 x₁+x₂+x₁x₂=（ ）。","answer":"1","explain":"这里 a=1，b=-3，c=-2，由根与系数的关系得 x₁+x₂=-(b)/(a)=-(-3)/(1)=3，x₁x₂=(c)/(a)=(-2)/(1)=-2。所以 x₁+x₂+x₁x₂=3+(-2)=1。使用韦达定理前可先验算 Δ=9+8=17>0，确实有两个实数根。","difficulty":2,"tags":["根与系数关系","整体代入"]},{"id":"m-num-yiyuan-erci-q4","type":"fill","stem":"解方程 x(x-2)=3(x-2)，得 x₁=（ ），x₂=（ ）。（如 x1=1,x2=2）","answer":"x1=2,x2=3","explain":"先把右边移到左边：x(x-2)-3(x-2)=0。提取公因式 (x-2) 得 (x-2)(x-3)=0，于是 x-2=0 或 x-3=0，解得 x₁=2、x₂=3。若两边直接除以 (x-2)，就只剩 x=3 一个根，属于丢根错误。检验：x=2 时左边 =0、右边 =0；x=3 时左边 =3、右边 =3，两根都成立。","difficulty":2,"tags":["因式分解法","丢根","易错"]},{"id":"m-num-yiyuan-erci-q5","type":"short","stem":"某厂第一季度的产量是 1000 件，经过连续两个季度的增产，第三季度的产量达到 1440 件。求这两个季度产量的平均增长率。（要求设未知数、列方程、完整求解并检验取舍）","answer":"设平均增长率为 $x$，列方程 $1000(1+x)^{2}=1440$，解得 $x=0.2$（另一根 $x=-2.2$ 不合题意舍去），平均增长率为 20%。","explain":"设这两个季度产量的平均增长率为 x。第一季度产量为 1000 件，则第二季度为 1000(1+x) 件，第三季度为 1000(1+x)² 件。由题意列方程 1000(1+x)²=1440。两边同除以 1000 得 (1+x)²=1.44，直接开平方得 1+x=1.2 或 1+x=-1.2，解得 x=0.2 或 x=-2.2。因为增长率不能为负数，舍去 x=-2.2。所以平均增长率为 20\\%。检验：1000× 1.2=1200 件，1200× 1.2=1440 件，与题意相符。","difficulty":2,"tags":["增长率","一元二次方程应用","取舍"],"rubric":["正确设年平均增长率为 x 并写出 1000(1+x)²=1440","正确化简为 (1+x)²=1.44 并用直接开平方法解得 x=0.2 或 x=-2.2","说明舍去 x=-2.2 的理由（增长率不能为负）","得出增长率 20%（写成 0.2 同样给分）","有检验或作答语句，过程完整"]},{"id":"m-num-yiyuan-erci-z1","type":"choice","stem":"方程 x²-3x=0 的根是（ ）","answer":"D","explain":"把左边因式分解：x(x-3)=0，故 x=0 或 x-3=0，即 x₁=0，x₂=3，选 D。方程两边不能直接除以 x，否则会丢掉 x=0 这个根而错选 A。","options":["x=3","x=0","x=± 3","x₁=0，x₂=3"],"difficulty":2,"tags":["解方程","因式分解法","丢根"]},{"id":"m-num-yiyuan-erci-z2","type":"short","stem":"用公式法解方程：3x²-2x-2=0，写出完整求解过程。","answer":"$x_{1}=\\frac{1+\\sqrt{7}}{3}$，$x_{2}=\\frac{1-\\sqrt{7}}{3}$","explain":"方程已是一般形式，a=3，b=-2，c=-2。先算判别式：Δ=b²-4ac=(-2)²-4× 3×(-2)=4+24=28>0，方程有两个不相等的实数根。代入求根公式：x=-b±√(Δ)2a=2±√(28)6=2± 2√(7)6=1±√(7)3。检验：两根之和 1+√(7)3+1-√(7)3=(2)/(3)=-(b)/(a)，两根之积 (1-7)/(9)=-(2)/(3)=(c)/(a)，均符合韦达定理。","difficulty":2,"tags":["解方程","根的判别式"],"rubric":["正确写出 a=3、b=-2、c=-2 并算出 Δ=28>0","正确代入求根公式得到 x=2±√(28)6","化简 √(28)=2√(7) 并正确约分，写出两个根"]}]},{"id":"m-num-erci-hanshu","title":"二次函数","subtitle":"人教版九上 · 第26章 二次函数","grade":"9a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版九上 · 第26章 二次函数"},{"type":"note","title":"一句话概述","text":"掌握二次函数的图像与性质，会用三种形式求解析式，能用二次函数解决最值问题。"},{"type":"h","text":"a 决定开口与形状"},{"type":"p","text":"二次函数 y=ax²+bx+c 的图像是一条抛物线，二次项系数 a 决定开口方向和开口大小：a>0 开口向上，a<0 开口向下；|a| 越大开口越小、抛物线越「瘦」。c 是图像与 y 轴交点的纵坐标，只影响抛物线的位置。"},{"type":"figure","figure":{"id":"fig-m-num-erci-hanshu-s1","title":"a 决定开口方向与大小","caption":"a>0 向上、a<0 向下；|a| 越大开口越小","view":"square","alt":"同一个坐标系里画了三条抛物线：y 等于 2x 平方开口向上且最窄，y 等于 x 平方开口向上较宽，y 等于负 x 平方开口向下。说明 a 大于零时开口向上、a 小于零时开口向下，a 的绝对值越大开口越小","prims":[{"t":"line","x1":10,"y1":70,"x2":88,"y2":70,"tone":"muted"},{"t":"arrow","x1":88,"y1":70,"x2":92,"y2":70,"tone":"muted"},{"t":"line","x1":50,"y1":99,"x2":50,"y2":18,"tone":"muted"},{"t":"arrow","x1":50,"y1":18,"x2":50,"y2":13,"tone":"muted"},{"t":"text","x":53,"y":73,"text":"O","size":3,"anchor":"start","tone":"muted"},{"t":"text","x":90,"y":67,"text":"x","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":54,"y":15,"text":"y","size":3.2,"anchor":"start","tone":"muted"},{"t":"curve","points":[[32,16],[38,46],[44,64],[50,70],[56,64],[62,46],[68,16]],"tone":"accent","width":2},{"t":"curve","points":[[26,22],[32,43],[38,58],[44,67],[50,70],[56,67],[62,58],[68,43],[74,22]],"tone":"main","width":2},{"t":"curve","points":[[32,97],[38,82],[44,73],[50,70],[56,73],[62,82],[68,97]],"tone":"danger","width":2},{"t":"text","x":71,"y":12,"text":"y = 2x²","size":3.2,"anchor":"start","tone":"accent"},{"t":"text","x":77,"y":26,"text":"y = x²","size":3.2,"anchor":"start","tone":"main"},{"t":"text","x":71,"y":95,"text":"y = -x²","size":3.2,"anchor":"start","tone":"danger"}]}},{"type":"note","title":"","text":"比较开口大小只看 |a|，与 b、c 无关；b 与 c 只改变抛物线在坐标系中的位置。"},{"type":"h","text":"对称轴与顶点坐标"},{"type":"p","text":"抛物线的对称轴是直线 x=-(b)/(2a)，顶点坐标是 (-(b)/(2a),\\ 4ac-b²4a)。求出对称轴的横坐标后，把它代回解析式就能算出顶点的纵坐标，而顶点纵坐标正是函数的最大值或最小值。"},{"type":"figure","figure":{"id":"fig-m-num-erci-hanshu-s2","title":"对称轴与顶点","caption":"在 x = -b/2a 处取得最值","view":"square","alt":"平面直角坐标系中画一条开口向上的抛物线，一条竖直虚线穿过抛物线的最低点，标注对称轴为直线 x 等于负 2a 分之 b，最低点用实心点标出并注明是顶点，顶点处函数取得最小值","prims":[{"t":"line","x1":8,"y1":80,"x2":88,"y2":80,"tone":"muted"},{"t":"arrow","x1":88,"y1":80,"x2":92,"y2":80,"tone":"muted"},{"t":"line","x1":30,"y1":92,"x2":30,"y2":20,"tone":"muted"},{"t":"arrow","x1":30,"y1":20,"x2":30,"y2":15,"tone":"muted"},{"t":"text","x":33,"y":84,"text":"O","size":3,"anchor":"start","tone":"muted"},{"t":"text","x":90,"y":84,"text":"x","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":34,"y":17,"text":"y","size":3.2,"anchor":"start","tone":"muted"},{"t":"line","x1":58,"y1":84,"x2":58,"y2":24,"tone":"muted","dashed":true},{"t":"curve","points":[[30,10],[37,34.5],[44,52],[51,62.5],[58,66],[65,62.5],[72,52],[79,34.5],[86,10]],"tone":"main","width":2},{"t":"dot","x":58,"y":66,"tone":"accent","label":"顶点","labelDx":2,"labelDy":7},{"t":"text","x":58,"y":91,"text":"x = -b/2a","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"顶点纵坐标的分子是 4ac-b²，别写成 b²-4ac；忘了负号是最常见的失分点。"},{"type":"h","text":"图象平移：左加右减"},{"type":"p","text":"把 y=ax² 的图像平移就得到 y=a(x-h)²+k：左右平移改变 h，规律是「左加右减」，向右平移 2 个单位要把 x 换成 x-2；上下平移改变 k，规律是「上加下减」。平移只改变位置，a 不变，所以抛物线的形状和开口方向都不变。"},{"type":"figure","figure":{"id":"fig-m-num-erci-hanshu-s3","title":"平移：左加右减、上加下减","caption":"y=x² 向右 2、向上 1 得到 y=(x-2)²+1","view":"square","alt":"同一个坐标系里画两条抛物线，虚线的是 y 等于 x 平方，实线的是把它向右平移 2 个单位、向上平移 1 个单位后得到的 y 等于 x 减 2 的平方加 1，一条箭头从原顶点指向新顶点；两条抛物线形状相同，说明平移只改变位置、不改变形状和开口方向","prims":[{"t":"line","x1":4,"y1":62,"x2":88,"y2":62,"tone":"muted"},{"t":"arrow","x1":88,"y1":62,"x2":92,"y2":62,"tone":"muted"},{"t":"line","x1":30,"y1":94,"x2":30,"y2":20,"tone":"muted"},{"t":"arrow","x1":30,"y1":20,"x2":30,"y2":15,"tone":"muted"},{"t":"text","x":33,"y":66,"text":"O","size":3,"anchor":"start","tone":"muted"},{"t":"text","x":90,"y":67,"text":"x","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":34,"y":17,"text":"y","size":3.2,"anchor":"start","tone":"muted"},{"t":"curve","points":[[6,14],[12,35],[18,50],[24,59],[30,62],[36,59],[42,50],[48,35],[54,14]],"tone":"muted","dashed":true,"width":1.6},{"t":"curve","points":[[30,2],[36,23],[42,38],[48,47],[54,50],[60,47],[66,38],[72,23],[78,2]],"tone":"main","width":2},{"t":"arrow","x1":30,"y1":62,"x2":54,"y2":50,"tone":"accent"},{"t":"dot","x":30,"y":62,"hollow":true,"tone":"muted"},{"t":"dot","x":54,"y":50,"tone":"accent"},{"t":"text","x":30,"y":30,"text":"y = x²","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":54,"y":30,"text":"y = (x-2)² + 1","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":86,"text":"右移 2 个单位、上移 1 个单位","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"左右平移作用在 x 上（左加右减），上下平移作用在整个函数值上（上加下减），两类方向不要混。"},{"type":"h","text":"x 轴交点与顶点最值"},{"type":"p","text":"抛物线 y=ax²+bx+c 与 x 轴交点的横坐标，就是方程 ax²+bx+c=0 的根，交点的个数由判别式 Δ 决定。同时顶点的纵坐标就是函数的最值：a>0 时开口向上、顶点最低，取最小值；a<0 时开口向下、顶点最高，取最大值。"},{"type":"figure","figure":{"id":"fig-m-num-erci-hanshu-s4","title":"交点与最值都在图上","caption":"交点的横坐标是方程的根，顶点的纵坐标是最值","view":"square","alt":"平面直角坐标系中画一条开口向下的抛物线 y 等于负 x 平方加 2x 加 3，与 x 轴交于 x₁ 等于负 1 和 x₂ 等于 3 两点，用虚线标出对称轴，顶点在 1 逗号 4，它是这条抛物线的最高点，所以函数的最大值是 4；与 x 轴交点的横坐标就是对应一元二次方程的两个根","prims":[{"t":"line","x1":6,"y1":74,"x2":88,"y2":74,"tone":"muted"},{"t":"arrow","x1":88,"y1":74,"x2":92,"y2":74,"tone":"muted"},{"t":"line","x1":34,"y1":92,"x2":34,"y2":18,"tone":"muted"},{"t":"arrow","x1":34,"y1":18,"x2":34,"y2":13,"tone":"muted"},{"t":"text","x":37,"y":78,"text":"O","size":3,"anchor":"start","tone":"muted"},{"t":"text","x":90,"y":79,"text":"x","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":38,"y":15,"text":"y","size":3.2,"anchor":"start","tone":"muted"},{"t":"line","x1":46,"y1":80,"x2":46,"y2":20,"tone":"muted","dashed":true},{"t":"curve","points":[[17.2,95.1],[22,74],[28,53],[34,38],[40,29],[46,26],[52,29],[58,38],[64,53],[70,74],[74.8,95.1]],"tone":"main","width":2},{"t":"dot","x":22,"y":74,"hollow":true,"tone":"danger","label":"x₁=-1","labelDx":-2,"labelDy":9},{"t":"dot","x":70,"y":74,"hollow":true,"tone":"danger","label":"x₂=3","labelDx":-2,"labelDy":9},{"t":"dot","x":46,"y":26,"tone":"accent","label":"顶点(1,4)","labelDx":2,"labelDy":-7},{"t":"text","x":52,"y":10,"text":"Δ>0 时有两个交点，横坐标就是方程的根","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"求最值前先看自变量有没有取值范围：顶点不在范围内时，最值要改在端点处取。"},{"type":"h","text":"核心概念"},{"type":"p","text":"二次函数的定义：形如 y=ax²+bx+c（a、b、c 是常数，a≠ 0）的函数叫二次函数。关键点：a≠ 0 是前提；图像是一条抛物线，a 决定开口方向。"},{"type":"p","text":"抛物线的开口、对称轴与顶点：抛物线的对称轴是直线 x=-(b)/(2a)，顶点坐标是 (-(b)/(2a),4ac-b²4a)。a>0 时开口向上，顶点是最低点；a<0 时开口向下，顶点是最高点。"},{"type":"p","text":"顶点式：把函数写成 y=a(x-h)²+k 的形式叫顶点式，顶点坐标为 (h,k)、对称轴是直线 x=h，最值为 y=k。关键点：括号内 x 后的常数与 h 的符号相反，y=2(x+3)²-1 的顶点是 (-3,-1)。"},{"type":"p","text":"交点式：若抛物线与 x 轴交于 (x₁,0)、(x₂,0) 两点，则可设 y=a(x-x₁)(x-x₂)，再由另一个已知点求出 a。关键点：交点式只有在抛物线与 x 轴有交点时才能使用。"},{"type":"p","text":"二次函数的增减性与最值：以对称轴为界：a>0 时在对称轴左侧 y 随 x 增大而减小、右侧增大，故顶点处取得最小值；a<0 时相反，顶点处取得最大值。含自变量取值范围的问题要在端点与顶点处比较。"},{"type":"p","text":"二次函数图像的平移：把抛物线配成顶点式后按「左加右减、上加下减」平移：左右平移改变 h（作用于 x），上下平移改变 k（作用于整体），a 始终不变，所以形状与开口方向都不变。"},{"type":"p","text":"二次函数与一元二次方程的关系：抛物线 y=ax²+bx+c 与 x 轴交点的横坐标就是方程 ax²+bx+c=0 的根。交点有两个则 Δ>0，有一个则 Δ=0，没有则 Δ<0。同理，y>0 的解集对应图像在 x 轴上方的部分。"},{"type":"note","title":"中考考法","text":"二次函数的图象性质与三种解析式互化\n由顶点式读顶点与对称轴，一般式与交点式、顶点式相互转化，踩分点是平移时 h 的符号「左加右减」。"},{"type":"note","title":"中考考法","text":"抛物线与坐标轴、直线的交点及判别式\n联立方程组求交点，用判别式判断交点个数，由图象在 x 轴上下方读出函数值正负的解集。"},{"type":"note","title":"中考考法","text":"二次函数的最值与实际建模\n销售利润、投物轨迹、面积围栏等情境中设变量写利润式，配方或用顶点坐标求最值，踩分点是注明自变量实际范围并检验。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["二次函数的一般式","y=ax²+bx+c\\ (a≠ 0)","a 决定开口方向与开口大小（|a| 越大开口越小）；a=0 时它就不是二次函数。"],["对称轴与顶点坐标","x=-(b)/(2a), (-(b)/(2a),\\ 4ac-b²4a)","顶点纵坐标的分子是 4ac-b²，前面的 4ac 不要漏掉 a，也不能写成 b²-4ac。"],["顶点式","y=a(x-h)²+k","顶点是 (h,k)，对称轴是 x=h；注意 h 的符号与括号内的常数相反，y=2(x+3)²-1 中 h=-3。"],["交点式","y=a(x-x₁)(x-x₂)","要求抛物线与 x 轴有两个交点 (x₁,0)、(x₂,0)；只需求出 a 即可确定解析式。"],["最值","x=-(b)/(2a)\\ ⇒\\ y_(min)=4ac-b²4a\\ (a>0)","a<0 时该值为最大值；若自变量有限制范围，最值可能在端点处取得，需比较后确定。"],["抛物线与 x 轴的交点个数","Δ=b²-4ac","Δ>0 有两个交点，Δ=0 有一个交点（顶点在 x 轴上），Δ<0 没有交点。"]]},{"type":"note","title":"例题","text":"用配方法把 y=x²-4x+5 化成顶点式，并写出开口方向、对称轴、顶点坐标和最小值。"},{"type":"list","title":"解题步骤","items":["把含 x 的项配方：x²-4x=(x-2)²-4（加上的是一次项系数一半的平方，即 2²=4）。","代回原式：y=(x-2)²-4+5=(x-2)²+1。","所以顶点式是 y=(x-2)²+1。","因为二次项系数 a=1>0，所以抛物线开口向上。","对称轴是直线 x=2，顶点坐标是 (2,1)。","开口向上时顶点最低，所以当 x=2 时 y 取最小值 1。"]},{"type":"p","text":"答案：y=(x-2)²+1，开口向上，对称轴 x=2，顶点 (2,1)，最小值 1"},{"type":"note","title":"方法小结","text":"配方法的关键是「加一次项系数一半的平方，再减去同样的数」，不能只加不减。写成顶点式后，顶点是 (2,1) 而不是 (-2,1)，这一点务必看清 h 的符号。"},{"type":"note","title":"例题","text":"已知抛物线顶点为 (1,-4)，且经过点 (0,-3)，求它的解析式，并求它与 x 轴的交点坐标。"},{"type":"list","title":"解题步骤","items":["已知顶点，设顶点式 y=a(x-1)²-4。","把 (0,-3) 代入：-3=a(0-1)²-4，即 -3=a-4。","解得 a=1。","所以解析式为 y=(x-1)²-4，展开得 y=x²-2x-3。","令 y=0 求与 x 轴交点：(x-1)²-4=0，即 (x-1)²=4。","开平方得 x-1=2 或 x-1=-2，所以 x=3 或 x=-1。","交点坐标为 (-1,0) 和 (3,0)。"]},{"type":"p","text":"答案：y=(x-1)²-4（即 y=x²-2x-3），与 x 轴交于 (-1,0)、(3,0)"},{"type":"note","title":"方法小结","text":"已知顶点设顶点式、已知与 x 轴的两个交点设交点式、只知三个普通点设一般式，这是待定系数法的选式原则。已知顶点时用顶点式只需一个条件就能求出 a，比一般式解三元方程组快得多。"},{"type":"note","title":"例题","text":"用总长为 20 米的篱笆围成一个矩形花园，花园的一边靠墙（墙足够长，不用篱笆），设垂直于墙的一边长为 x 米，求花园面积 S（平方米）与 x 之间的函数关系式，并求出面积的最大值。"},{"type":"list","title":"解题步骤","items":["垂直于墙的边有两条，每条长 x 米，共用去篱笆 2x 米。","平行于墙的一边用去剩下的篱笆：(20-2x) 米。","由实际意义，x>0 且 20-2x>0，所以自变量取值范围是 0<x<10。","面积 S=x(20-2x)=-2x²+20x。","配方：S=-2(x²-10x)=-2[(x-5)²-25]=-2(x-5)²+50。","因为二次项系数 -2<0，抛物线开口向下，顶点处取最大值；x=5 在 0<x<10 范围内。","所以当 x=5 米时，面积最大，最大值为 50 平方米（此时另一边为 20-2× 5=10 米，是矩形花园）。"]},{"type":"p","text":"答案：S=-2x²+20x（0<x<10），最大面积为 50 平方米"},{"type":"note","title":"方法小结","text":"二次函数应用题必须写出自变量取值范围，并检验顶点是否落在范围内。本题若忽略 0<x<10，就无法说明 x=5 是合理的取值。"},{"type":"note","title":"例题","text":"已知抛物线的顶点坐标为 (1,-4)，且经过点 (2,-3)。（1）求该抛物线的解析式；（2）求它与 x 轴的交点坐标。"},{"type":"list","title":"解题步骤","items":["已知顶点坐标，想到设顶点式 y=a(x-h)²+k，把 (h,k)=(1,-4) 代入得 y=a(x-1)²-4。","把点 (2,-3) 代入：-3=a(2-1)²-4，即 -3=a-4，解得 a=1。","故解析式为 y=(x-1)²-4=x²-2x-3。","求与 x 轴的交点令 y=0：x²-2x-3=0，因式分解为 (x-3)(x+1)=0，得 x=3 或 x=-1。"]},{"type":"p","text":"答案：（1）y=x²-2x-3；（2）与 x 轴交点为 (-1,0) 和 (3,0)"},{"type":"note","title":"方法小结","text":"已知顶点或对称轴时优先设顶点式，只需要一个额外点就能确定 a。求与 x 轴交点时令 y=0 解一元二次方程，得到的两个交点关于对称轴 x=1 对称，可以用来检验。"},{"type":"note","title":"例题","text":"如图，抛物线 y=-x²+4x+5 与 x 轴交于 A、B 两点（A 在左），与 y 轴交于点 C。（1）求 △ ABC 的面积；（2）若点 P 是抛物线在第一象限内图象上的一动点，求 △ PAB 面积的最大值。"},{"type":"figure","figure":{"id":"fig-m-num-erci-hanshu-paowuxian-1","title":"抛物线 y=−x²+4x+5","caption":"A(-1,0)、B(5,0)、C(0,5)，顶点 (2,9)","view":"wide","alt":"平面直角坐标系中画出开口向下的抛物线 y 等于负 x 平方加 4x 加 5，与 x 轴交于 A 负 1 逗号 0 和 B 5 逗号 0，与 y 轴交于 C 0 逗号 5，顶点在 2 逗号 9，三角形 ABC 用阴影标出","prims":[{"t":"line","x1":10,"y1":72,"x2":85,"y2":72},{"t":"line","x1":25,"y1":18,"x2":25,"y2":78},{"t":"arrow","x1":85,"y1":72,"x2":89,"y2":72},{"t":"arrow","x1":25,"y1":18,"x2":25,"y2":14},{"t":"text","x":88,"y":76,"text":"x","size":3.4,"anchor":"middle"},{"t":"text","x":29,"y":16,"text":"y","size":3.4},{"t":"line","x1":45,"y1":20,"x2":45,"y2":76,"tone":"muted","dashed":true},{"t":"text","x":47,"y":18,"text":"x=2","size":3.2,"tone":"muted"},{"t":"poly","points":[[15,72],[75,72],[25,47]],"closed":true,"tone":"accent","fill":true},{"t":"curve","points":[[15,72],[25,47],[45,27],[65,47],[75,72]],"tone":"main","width":2},{"t":"dot","x":15,"y":72,"tone":"danger","label":"A(-1,0)","labelDx":-2,"labelDy":12},{"t":"dot","x":75,"y":72,"tone":"danger","label":"B(5,0)","labelDx":4,"labelDy":12},{"t":"dot","x":25,"y":47,"tone":"danger","label":"C(0,5)","labelDx":6,"labelDy":0},{"t":"dot","x":45,"y":27,"tone":"accent","label":"P(2,9)","labelDx":4,"labelDy":-2},{"t":"text","x":20,"y":76,"text":"O","size":3.2,"tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先求交点：令 y=0，-x²+4x+5=0，即 (x-5)(x+1)=0，得 A(-1,0)、B(5,0)，故底边 AB=6。","令 x=0 得 y=5，故 C(0,5)。△ ABC 以 AB 为底、OC 为高，面积 S=(1)/(2)× 6× 5=15。","△ PAB 的底 AB 固定为 6，面积大小只取决于点 P 到 x 轴的距离，想到在第一象限内求抛物线的最高点。","配方：y=-(x-2)²+9，顶点为 (2,9) 且在第一象限，最大高度为 9，故面积最大值 =(1)/(2)× 6× 9=27。"]},{"type":"p","text":"答案：（1）△ ABC 的面积为 15；（2）△ PAB 面积的最大值为 27"},{"type":"note","title":"方法小结","text":"两个三角形共底时，面积之比等于高之比。动点在抛物线上运动，要使共底三角形面积最大，只需让该点到公共底边的距离最大，即求抛物线顶点的纵坐标（先确认顶点所在象限符合题设）。"},{"type":"list","title":"易错点","items":["顶点式 $y=a(x-h)^{2}+k$ 中 $h$ 的符号判断错误，把 $y=2(x+3)^{2}-1$ 的顶点写成 $(3,-1)$。括号内是 $(x-h)$，$x+3=x-(-3)$，所以 $h=-3$。","顶点纵坐标公式记成 $\\frac{b^{2}-4ac}{4a}$，漏掉负号。正确形式是 $\\frac{4ac-b^{2}}{4a}$，验算时可代入简单例子核对。","平移方向记反，把 $y=x^{2}$ 向右平移 2 个单位写成 $y=(x+2)^{2}$。左右平移是「左加右减」作用于 $x$，向右平移 2 个单位得 $y=(x-2)^{2}$。","忽略 $a\\neq 0$ 的条件，在含参数的二次函数问题中不讨论二次项系数是否为 0。","求最值时只顾顶点，忘了自变量有取值范围。当顶点不在给定区间内时，最值要在端点上取，必须分段讨论。","混淆开口方向与最值：$a>0$ 时函数有最小值，$a<0$ 时有最大值，写反会导致整题结论错误。"]},{"type":"list","title":"解题方法","items":["求解析式三选一：已知顶点用顶点式 y=a(x-h)²+k，已知与 x 轴的两个交点用交点式 y=a(x-x₁)(x-x₂)，其余用一般式 y=ax²+bx+c。","配方法求顶点：先把二次项系数提出来，再在括号内加上一次项系数一半的平方并减去同样的数，最后整理成顶点式。","公式法求对称轴与顶点：直接代 x=-(b)/(2a) 求对称轴，代顶点纵坐标公式或把该 x 值代回解析式求最值。","数形结合解不等式：ax²+bx+c>0 的解集就是抛物线位于 x 轴上方时 x 的取值范围，先求与 x 轴交点再读图。","最值应用题的规范步骤：设自变量、列函数、写取值范围、求顶点（或比较端点）、作答并检验实际意义。"]}],"questions":[{"id":"m-num-erci-hanshu-q1","type":"choice","stem":"抛物线 y=2(x-3)²+1 的顶点坐标是（ ）","answer":"A","explain":"顶点式 y=a(x-h)²+k 的顶点是 (h,k)。本题中 y=2(x-3)²+1 对应 h=3、k=1，所以顶点为 (3,1)，选 A。若把括号内写成 x+3，则应取 h=-3，顶点为 (-3,k)，注意符号相反。","options":["(3,1)","(-3,1)","(3,-1)","(-3,-1)"],"difficulty":1,"tags":["顶点式","顶点坐标","易错"]},{"id":"m-num-erci-hanshu-q2","type":"choice","stem":"二次函数 y=x²-2x-3 的图像与 x 轴的交点个数是（ ）","answer":"C","explain":"交点个数由判别式决定：Δ=b²-4ac=(-2)²-4× 1×(-3)=4+12=16>0，所以有两个交点。具体求出来可验证：x²-2x-3=(x-3)(x+1)=0，得 x=3 或 x=-1，交点为 (3,0)、(-1,0)，恰好两个。","options":["0 个","1 个","2 个","无法确定"],"difficulty":2,"tags":["抛物线与x轴","判别式"]},{"id":"m-num-erci-hanshu-q3","type":"fill","stem":"抛物线 y=-x²+4x 的最大值是（ ）。","answer":"4","explain":"二次项系数 a=-1<0，开口向下，顶点处取最大值。对称轴 x=-(b)/(2a)=-(4)/(2×(-1))=2。把 x=2 代入：y=-2²+4× 2=-4+8=4，所以最大值是 4。也可配方验证：y=-(x²-4x)=-(x-2)²+4，顶点 (2,4)，最大值 4。","difficulty":2,"tags":["二次函数最值","顶点"]},{"id":"m-num-erci-hanshu-q4","type":"fill","stem":"若二次函数 y=x²+bx+c 的图像经过点 (0,3)，且对称轴是直线 x=1，则 b=（ ）。","answer":"-2","explain":"图像过 (0,3)，代入得 c=3，所以 y=x²+bx+3。由对称轴公式 x=-(b)/(2a)=1，又 a=1，得 -(b)/(2)=1，解得 b=-2。检验：此时解析式为 y=x²-2x+3=(x-1)²+2，对称轴确为 x=1，与条件一致。","difficulty":2,"tags":["对称轴","待定系数法"]},{"id":"m-num-erci-hanshu-q5","type":"short","stem":"某商店销售一种商品，进价为每件 40 元。经调查发现，若售价为每件 60 元，每天可售出 100 件；售价每降低 1 元，每天可多售出 10 件。设售价降低 x 元，每天获得的利润为 W 元。求 W 与 x 的函数关系式，并求售价定为多少元时每天利润最大，最大利润是多少。","answer":"$W=(60-x-40)(100+10x)=-10x^{2}+100x+2000$（$0\\leq x\\leq 20$）；配方得 $W=-10(x-5)^{2}+2250$，当 $x=5$ 即售价 55 元时，每天利润最大，最大利润为 2250 元。","explain":"售价每降低 1 元，销量增加 10 件，故降低 x 元后：单件利润 =(60-x)-40=20-x 元，日销量 =100+10x 件（且售价不能低于进价，故 0≤ x≤ 20）。于是 W=(20-x)(100+10x)=2000+200x-100x-10x²=-10x²+100x+2000。配方：W=-10(x²-10x)+2000=-10[(x-5)²-25]+2000=-10(x-5)²+250+2000=-10(x-5)²+2250。因为 -10<0，开口向下，当 x=5 时 W 取最大值 2250，而 x=5 在 0≤ x≤ 20 内，符合实际。此时售价为 60-5=55 元。检验：单件利润 15 元，销量 100+50=150 件，利润 15× 150=2250 元，一致。","difficulty":3,"tags":["二次函数应用","销售利润","最值"],"rubric":["正确写出单件利润 20-x 与日销量 100+10x","列出 W=(20-x)(100+10x) 并展开为 -10x²+100x+2000","配方得到 W=-10(x-5)²+2250（或用对称轴 x=5 求出最值）","正确说明 x=5 时利润最大并给出最大利润 2250 元","由 x=5 得售价 55 元，有检验或作答语句"]},{"id":"m-num-erci-hanshu-z1","type":"choice","stem":"抛物线 y=2(x-1)²+3 的顶点坐标是（ ）","answer":"A","explain":"顶点式 y=a(x-h)²+k 的顶点为 (h,k)。括号内为 x-1，故 h=1；常数项为 +3，故 k=3，顶点坐标是 (1,3)，选 A。把括号内的减号看成 h=-1 会错选 B。","options":["(1,3)","(-1,3)","(1,-3)","(-1,-3)"],"difficulty":2,"tags":["顶点式","顶点坐标","易错"]},{"id":"m-num-erci-hanshu-z2","type":"short","stem":"已知二次函数 y=x²-2x-3。（1）写出它的图象的顶点坐标；（2）结合图象直接写出当 y<0 时 x 的取值范围。","answer":"顶点坐标为 $(1,-4)$；当 $y<0$ 时，$-1<x<3$。","explain":"第（1）问配方：y=x²-2x-3=(x-1)²-4，故顶点为 (1,-4)，对称轴为直线 x=1。第（2）问令 y=0：x²-2x-3=0，即 (x-3)(x+1)=0，抛物线与 x 轴交于 (-1,0) 和 (3,0)。二次项系数为正、开口向上，图象在两交点之间位于 x 轴下方，所以 y<0 对应 -1<x<3（端点处 y=0，不满足严格小于，故不取等号）。","difficulty":2,"tags":["抛物线与x轴","图像法解不等式","顶点"],"rubric":["正确配方为 y=(x-1)²-4，写出顶点 (1,-4)","求出与 x 轴交点 (-1,0) 和 (3,0)","由开口方向与图象得出 -1<x<3（端点不取）"]}]},{"id":"m-num-fanbili","title":"反比例函数","subtitle":"人教版九上 · 第27章 反比例函数","grade":"9a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版九上 · 第27章 反比例函数"},{"type":"note","title":"一句话概述","text":"理解反比例函数的意义，掌握双曲线的图像与性质、k 的几何意义及实际应用。"},{"type":"h","text":"先看形状：两支曲线分居对顶象限"},{"type":"p","text":"把 x 取遍所有非零实数，y=(k)/(x) 的图像由两支曲线组成。因为 k 的符号决定 x、y 是否同号：同号（k>0）落在第一、三象限，异号（k<0）落在第二、四象限。两支夹在坐标轴之间，永远够不到坐标轴。"},{"type":"figure","figure":{"id":"fig-fanbili-s1","title":"k 的符号决定双曲线所在的象限","caption":"k>0 的实线两支在一、三象限；k<0 的虚线两支在二、四象限","view":"square","alt":"平面直角坐标系中画了两组双曲线：实线的一支在第一象限、另一支在第三象限，旁标 k 大于 0；虚线的一支在第二象限、另一支在第四象限，旁标 k 小于 0，四支曲线都不与坐标轴相交","prims":[{"t":"plane","x":50,"y":50,"right":40,"left":40,"up":40,"down":40,"xLabel":"x","yLabel":"y","xTicks":[{"at":-32,"label":"-4"},{"at":-16,"label":"-2"},{"at":16,"label":"2"},{"at":32,"label":"4"}],"yTicks":[{"at":16,"label":"2"},{"at":32,"label":"4"},{"at":-16,"label":"-2"},{"at":-32,"label":"-4"}]},{"t":"curve","points":[[56,10],[58,18],[62,29],[66,34],[74,39],[82,42],[90,44]],"tone":"accent","width":1.6},{"t":"curve","points":[[44,90],[42,82],[38,71],[34,66],[26,61],[18,58],[10,56]],"tone":"accent","width":1.6},{"t":"curve","points":[[56,90],[58,82],[62,71],[66,66],[74,61],[82,58],[90,56]],"tone":"danger","dashed":true,"width":1.4},{"t":"curve","points":[[44,10],[42,18],[38,29],[34,34],[26,39],[18,42],[10,44]],"tone":"danger","dashed":true,"width":1.4},{"t":"text","x":74,"y":22,"text":"k>0","size":3.8,"anchor":"middle","tone":"accent"},{"t":"text","x":70,"y":80,"text":"k<0","size":3.8,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"两支曲线是同一个图像，不能拆开看；判断题里说「图像经过原点」或「与坐标轴有交点」都是错的。"},{"type":"h","text":"抓条件：任取一点围出的矩形"},{"type":"p","text":"在图像上任取一点 P(x₀,y₀)，因为它满足 x₀y₀=k，所以过 P 向两坐标轴作垂线围成的矩形面积 S=|x₀|·|y₀|=|k|，与点 P 的位置无关。这说明 |k| 不是某个点的坐标，而是整个图像自带的面积常量。"},{"type":"figure","figure":{"id":"fig-fanbili-s2","title":"k 的几何意义：矩形面积恒为 |k|","caption":"过图像上一点向两轴作垂线，围成的矩形面积等于 |k|","view":"square","alt":"平面直角坐标系第一象限内有反比例函数 y 等于 x 分之六 的一支，点 P 坐标为二、三，过 P 向两坐标轴作垂线，与坐标轴围成的矩形用阴影标出，面积标注为 6，等于 k 的绝对值","prims":[{"t":"plane","x":30,"y":80,"right":62,"left":20,"up":68,"down":12,"xLabel":"x","yLabel":"y","xTicks":[{"at":16,"label":"2"},{"at":32,"label":"4"},{"at":48,"label":"6"}],"yTicks":[{"at":24,"label":"3"},{"at":48,"label":"6"}]},{"t":"curve","points":[[38,32],[46,56],[54,64],[62,68],[78,72]],"tone":"accent","width":1.6},{"t":"rect","x":30,"y":56,"w":16,"h":24,"tone":"accent","fill":true},{"t":"text","x":38,"y":70,"text":"S = 6","size":3.4,"anchor":"middle","tone":"accent"},{"t":"dot","x":46,"y":56,"tone":"danger","label":"P(2,3)","labelDx":3,"labelDy":-4},{"t":"dot","x":30,"y":80,"tone":"main","label":"O","labelDx":-6,"labelDy":8},{"t":"text","x":66,"y":18,"text":"矩形面积 = |x|·|y| = |k|","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"矩形面积是 |k|，而原点、垂足、点 P 围成的直角三角形面积是 (|k|)/(2)，别把这两个搞混。"},{"type":"h","text":"建立关系：交点就是方程组的解"},{"type":"p","text":"求 y=(k)/(x) 与 y=ax+b 的交点，就是把两式联立：ax+b=(k)/(x)。解这个方程得到的 x 就是交点的横坐标，再回代入任一解析式即得纵坐标；所以「交点个数」与「方程解的个数」是同一件事。"},{"type":"figure","figure":{"id":"fig-fanbili-s3","title":"反比例函数与一次函数的交点","caption":"y=x+1 与 y=6/x 交于 (-3,-2) 与 (2,3)","view":"square","alt":"平面直角坐标系中，直线 y 等于 x 加 1 与反比例函数 y 等于 x 分之六 的两支曲线相交，交点分别是负三、负二与正二、正三，两点关于原点中心对称","prims":[{"t":"plane","x":50,"y":50,"right":48,"left":36,"up":44,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-24,"label":"-3"},{"at":-16,"label":"-2"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":-16,"label":"-2"}]},{"t":"line","x1":10,"y1":82,"x2":90,"y2":2,"tone":"main","width":1.6},{"t":"curve","points":[[58,2],[62,18],[66,26],[74,34],[82,38],[90,40]],"tone":"accent","width":1.6},{"t":"curve","points":[[40,90],[38,82],[34,74],[26,66],[18,62],[10,60]],"tone":"accent","width":1.6},{"t":"dot","x":26,"y":66,"tone":"danger","label":"(-3,-2)","labelDx":-4,"labelDy":10},{"t":"dot","x":66,"y":26,"tone":"danger","label":"(2,3)","labelDx":4,"labelDy":-5},{"t":"text","x":84,"y":16,"text":"y=x+1","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":78,"y":46,"text":"y=6/x","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"联立时两边同乘 x 会引入 x=0 的可能，最后务必检验 x≠ 0，把不合理解舍去。"},{"type":"h","text":"换个情境：面积一定，长与宽成反比"},{"type":"p","text":"当矩形的面积 S 一定时，长 a 与宽 b 满足 ab=S，即 b=(S)/(a)，这正好是 y=(k)/(x) 的形状。长每增大一些，宽就必须相应减小，乘积始终等于那个固定的面积，所以长与宽成反比例。"},{"type":"figure","figure":{"id":"fig-fanbili-s4","title":"面积一定时，长与宽成反比","caption":"长由 8 减到 4，宽就由 3 增到 6，乘积始终是 24","view":"wide","alt":"两个面积相同的矩形并排摆放：左边矩形的长较长、宽较窄，右边虚线矩形的长较短、宽较宽，下方用双箭头分别标出两者的长，说明面积一定时长与宽成反比","prims":[{"t":"rect","x":14,"y":42,"w":30,"h":24,"tone":"main","label":"S"},{"t":"rect","x":60,"y":18,"w":15,"h":48,"tone":"accent","dashed":true,"label":"S"},{"t":"arrow","x1":14,"y1":74,"x2":44,"y2":74,"both":true,"tone":"muted","label":"长 8","labelDy":7},{"t":"arrow","x1":60,"y1":74,"x2":75,"y2":74,"both":true,"tone":"muted","label":"长 4","labelDy":7},{"t":"text","x":50,"y":10,"text":"长 × 宽 = S（定值）","size":3.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":90,"text":"长变小，宽就变大，乘积不变","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"判断两个量是否成反比，只看它们的乘积是不是定值，不要被「一个变大另一个变小」的表面现象迷惑（如周长一定时邻边并非成反比）。"},{"type":"h","text":"核心概念"},{"type":"p","text":"反比例函数的定义：形如 y=(k)/(x)（k 为常数，k≠ 0）的函数叫反比例函数，也可写成 xy=k 或 y=kx^(-1) 的形式。关键点：k≠ 0，且自变量 x≠ 0，所以图像与坐标轴永不相交。"},{"type":"p","text":"反比例函数的图像：反比例函数的图像是双曲线，由分别位于两个象限的两支曲线组成。当 k>0 时两支分别在第一、三象限；当 k<0 时两支分别在第二、四象限。两支关于原点成中心对称。"},{"type":"p","text":"反比例函数的性质（增减性）：k>0 时，在每一个象限内 y 随 x 的增大而减小；k<0 时，在每一个象限内 y 随 x 的增大而增大。关键点：增减性只在同一象限内成立，跨象限比较函数值必须先算出来或用图像判断。"},{"type":"p","text":"k 的几何意义：过双曲线上任意一点 P 分别向两坐标轴作垂线，与坐标轴围成的矩形面积等于 |k|，其中以原点和一个垂足、点 P 为顶点的直角三角形面积为 (|k|)/(2)。这是求面积问题的快捷工具。"},{"type":"p","text":"待定系数法求解析式：设 y=(k)/(x)，只要知道图像上任意一个点的坐标 (x₀,y₀)，由 k=x₀y₀ 即可确定解析式。关键点：k 等于点的横纵坐标之积。"},{"type":"p","text":"反比例函数与一次函数的综合：把两个解析式联立成方程组，解出的解就是图像交点的坐标。比较两个函数值的大小时，可由图像上下位置判断：上方图像对应的函数值更大。"},{"type":"note","title":"中考考法","text":"反比例函数的图象与性质、$k$ 的符号判断\n由图象所在象限或增减性判断 k 的正负并比较函数值，踩分点是增减性必须限定「在每个象限内」，跨象限比较看正负号。"},{"type":"note","title":"中考考法","text":"待定系数法与点、图象的关系\n给图象上一点求 k=xy，或给自变量范围求函数值范围，踩分点是点在图象上则坐标之积等于 k，并结合单调区间取端点。"},{"type":"note","title":"中考考法","text":"$k$ 的几何意义及与一次函数的综合\n过图象上一点向坐标轴作垂线，矩形面积为 |k|、三角形面积为 (|k|)/(2)；与直线联立求交点、比大小是常见综合题。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["反比例函数的一般形式","y=(k)/(x)\\ (k≠ 0)","也可写成 xy=k 或 y=kx^(-1)；x≠ 0，图像与坐标轴没有交点。"],["比例系数的求法","k=xy","把图像上任意一点的横纵坐标相乘即可得到 k；求解析式时不需要两个点。"],["k 的几何意义","S_()=|k|, S_(△)=(|k|)/(2)","矩形是过图像上一点向两坐标轴作垂线围成的，三角形是以原点为一顶点的直角三角形；都要加绝对值。"],["图像的对称性","P(x₀,y₀)∈ y=(k)/(x)\\ ⇒\\ (-x₀,-y₀)∈ y=(k)/(x)","双曲线关于原点成中心对称，因此若一个交点是 (a,b)，则另一个交点必为 (-a,-b)。"],["与一次函数联立","cases y=(k)/(x) \\\\ y=ax+b endcases","消去 y 后得到关于 x 的分式方程，解完后必须检验 x≠ 0，交点的横坐标不能为 0。"]]},{"type":"note","title":"例题","text":"已知反比例函数的图像经过点 (-2,3)。（1）求这个函数的解析式；（2）求当 x=6 时 y 的值。"},{"type":"figure","figure":{"id":"fig-fanbili-e1","title":"过点 (-2,3) 的双曲线 y=-6/x","caption":"k=-6<0，图像在第二、四象限，与两点位置相符","view":"square","alt":"平面直角坐标系中反比例函数 y 等于负 x 分之六 的两支曲线分别位于第二、四象限，第二象限一支上标出点负二、三，第四象限一支上标出点六、负一","prims":[{"t":"plane","x":50,"y":50,"right":44,"left":40,"up":44,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-14,"label":"-2"},{"at":14,"label":"2"},{"at":42,"label":"6"}],"yTicks":[{"at":21,"label":"3"},{"at":-7,"label":"-1"}]},{"t":"curve","points":[[43,8],[39,22],[36,29],[29,36],[22,40],[8,43]],"tone":"accent","width":1.6},{"t":"curve","points":[[57,92],[60,78],[64,71],[71,64],[78,61],[92,57]],"tone":"accent","width":1.6},{"t":"dot","x":36,"y":29,"tone":"danger","label":"(-2,3)","labelDx":-4,"labelDy":10},{"t":"dot","x":92,"y":57,"tone":"danger","label":"(6,-1)","labelDx":-9,"labelDy":-8},{"t":"text","x":60,"y":14,"text":"k = xy = -6","size":3.6,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["设反比例函数解析式为 y=(k)/(x)（k≠ 0）。","把 (-2,3) 代入得 3=(k)/(-2)，所以 k=3×(-2)=-6。","所求解析式为 y=-(6)/(x)。","当 x=6 时，y=-(6)/(6)=-1。","检验：把 (6,-1) 代入 xy=-6 得 6×(-1)=-6，与 k=-6 一致；且 k<0，图像在第二、四象限，与点的位置相符。"]},{"type":"p","text":"答案：y=-(6)/(x)；当 x=6 时 y=-1"},{"type":"note","title":"方法小结","text":"求 k 时用横纵坐标相乘（k=xy），不要错写成相除。求出 k 后可用它的符号复核：k=-6<0，图像应在第二、四象限，而 (-2,3) 恰在第二象限，检验通过。"},{"type":"note","title":"例题","text":"点 P 在反比例函数 y=(6)/(x) 的图像上，过 P 作 PA⊥ x 轴于点 A，求三角形 POA 的面积（O 为坐标原点），并说明它与点 P 的位置是否有关。"},{"type":"figure","figure":{"id":"fig-fanbili-e2","title":"三角形 POA 的面积恒为 |k|/2","caption":"S△POA=3，与 P 在图像上的位置无关","view":"square","alt":"平面直角坐标系第一象限内反比例函数 y 等于 x 分之六 的图像上取点 P，过 P 向 x 轴作垂线，垂足为 A，连接 OA，直角三角形 POA 用阴影标出，面积标注为 3","prims":[{"t":"plane","x":32,"y":80,"right":60,"left":20,"up":68,"down":12,"xLabel":"x","yLabel":"y","xTicks":[{"at":16,"label":"2"},{"at":32,"label":"4"}],"yTicks":[{"at":24,"label":"3"},{"at":48,"label":"6"}]},{"t":"curve","points":[[40,32],[48,56],[56,64],[64,68],[80,72]],"tone":"accent","width":1.6},{"t":"poly","points":[[32,80],[48,80],[48,56]],"closed":true,"tone":"accent","fill":true},{"t":"dot","x":48,"y":56,"tone":"danger","label":"P","labelDx":4,"labelDy":-4},{"t":"dot","x":48,"y":80,"tone":"danger","label":"A","labelDx":4,"labelDy":8},{"t":"dot","x":32,"y":80,"tone":"main","label":"O","labelDx":-7,"labelDy":8},{"t":"text","x":45,"y":72,"text":"S = 3","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":72,"y":22,"text":"S = ½|k|","size":3.8,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["设 P 的坐标为 (x₀,y₀)，由点 P 在图像上得 x₀y₀=6。","因为 PA⊥ x 轴，垂足 A 的坐标是 (x₀,0)。","三角形 POA 中，以 OA 为底，底长是 |x₀|，高是 |y₀|。","面积 S=(1)/(2)×|x₀|×|y₀|=(1)/(2)|x₀y₀|=(1)/(2)× 6=3。","结论：面积为 3，且等于 (|k|)/(2)，与点 P 在图像上的具体位置无关。"]},{"type":"p","text":"答案：面积为 3，与点 P 的位置无关（恒等于 (|k|)/(2)）"},{"type":"note","title":"方法小结","text":"k 的几何意义要记牢两种图形的区别：矩形面积是 |k|，以原点为顶点的直角三角形面积是 (|k|)/(2)。千万不要漏掉 (1)/(2) 或漏写绝对值。"},{"type":"note","title":"例题","text":"已知一次函数 y=x+1 与反比例函数 y=(6)/(x) 的图像相交，求交点坐标。"},{"type":"figure","figure":{"id":"fig-fanbili-e3","title":"联立后的交点就是方程的解","caption":"x²+x-6=(x+3)(x-2)=0，交点为 (-3,-2) 与 (2,3)","view":"square","alt":"平面直角坐标系中直线 y 等于 x 加 1 与反比例函数 y 等于 x 分之六 的两支曲线相交于负三、负二与正二、正三两点，图上方标注由联立得到的方程 x 平方加 x 减 6 等于 0 分解为 x 加 3 乘 x 减 2","prims":[{"t":"plane","x":50,"y":54,"right":48,"left":36,"up":42,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-24,"label":"-3"},{"at":-16,"label":"-2"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":-16,"label":"-2"}]},{"t":"line","x1":10,"y1":86,"x2":90,"y2":6,"tone":"main","width":1.6},{"t":"curve","points":[[58,6],[62,22],[66,30],[74,38],[82,42],[90,44]],"tone":"accent","width":1.6},{"t":"curve","points":[[40,94],[38,86],[34,78],[26,70],[18,66],[10,64]],"tone":"accent","width":1.6},{"t":"dot","x":26,"y":70,"tone":"danger","label":"(-3,-2)","labelDx":-4,"labelDy":10},{"t":"dot","x":66,"y":30,"tone":"danger","label":"(2,3)","labelDx":4,"labelDy":-5},{"t":"text","x":50,"y":10,"text":"x²+x-6=(x+3)(x-2)=0","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":84,"y":20,"text":"y=x+1","size":3.4,"anchor":"middle","tone":"main"},{"t":"text","x":78,"y":50,"text":"y=6/x","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["联立两个解析式：x+1=(6)/(x)。","方程两边同乘 x（x≠ 0）：x(x+1)=6。","整理成一般形式：x²+x-6=0。","因式分解得 (x+3)(x-2)=0，故 x=-3 或 x=2。","当 x=-3 时，y=-3+1=-2；当 x=2 时，y=2+1=3。","所以两个交点为 (-3,-2) 和 (2,3)。检验：(-3)×(-2)=6、2× 3=6，都在反比例函数图像上；且这两个点关于原点中心对称，符合双曲线的对称性。"]},{"type":"p","text":"答案：(-3,-2) 与 (2,3)"},{"type":"note","title":"方法小结","text":"解这类题要养成两个习惯：一是乘 x 前先声明 x≠ 0，二是求出结果后用 xy=k 复核。另外注意交点往往关于原点对称，这可以用来快速检查答案是否漏解。"},{"type":"note","title":"例题","text":"已知反比例函数 y=(k)/(x) 的图象经过点 A(-2,3)。（1）求 k 的值，并判断点 B(4,m) 在该图象上时 m 的值；（2）若点 P(x,y) 在该图象上，且 -3≤ x≤ -1，求 y 的取值范围。"},{"type":"figure","figure":{"id":"fig-fanbili-e4","title":"在同一分支内根据增减性求函数值范围","caption":"k<0 的第二象限分支内 y 随 x 增大而增大，故 2≤y≤6","view":"square","alt":"平面直角坐标系中反比例函数 y 等于负 x 分之六 的第二象限分支，横坐标为负三与负一的两个端点纵坐标分别为 2 与 6，中间一段用加粗曲线标出，说明当负三小于等于 x 小于等于负一时 y 的取值范围是 2 到 6","prims":[{"t":"plane","x":50,"y":60,"right":44,"left":46,"up":52,"down":20,"xLabel":"x","yLabel":"y","xTicks":[{"at":-32,"label":"-4"},{"at":-16,"label":"-2"}],"yTicks":[{"at":16,"label":"2"},{"at":32,"label":"4"},{"at":48,"label":"6"}]},{"t":"curve","points":[[42,12],[38,28],[34,36],[26,44],[18,48],[10,51]],"tone":"muted","dashed":true,"width":1},{"t":"curve","points":[[42,12],[38,28],[34,36],[30,41],[26,44]],"tone":"accent","width":2.4},{"t":"dot","x":42,"y":12,"tone":"danger","label":"(-1,6)","labelDx":4,"labelDy":3},{"t":"dot","x":26,"y":44,"tone":"danger","label":"(-3,2)","labelDx":-6,"labelDy":10},{"t":"text","x":70,"y":26,"text":"2 ≤ y ≤ 6","size":3.8,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["点在反比例图象上则坐标之积等于 k：k=xy=(-2)× 3=-6，故函数为 y=-(6)/(x)。","点 B(4,m) 在图象上：4m=-6，解得 m=-(3)/(2)。","第（2）问中 x 在负数范围内，两个端点代入：x=-3 时 y=2；x=-1 时 y=6。","k=-6<0，在第二象限（x<0 的分支）内 y 随 x 的增大而增大，故 2≤ y≤ 6。"]},{"type":"p","text":"答案：（1）k=-6，m=-(3)/(2)；（2）2≤ y≤ 6"},{"type":"note","title":"方法小结","text":"反比例函数的函数值范围不能跨象限讨论：先确认给定的 x 范围是否在同一分支内，再代入两个端点，并根据该分支的增减性决定不等号方向。"},{"type":"note","title":"例题","text":"如图，正比例函数 y=2x 与反比例函数 y=(k)/(x)（k>0）的图象交于 A、B 两点，过点 A 作 AC⊥ x 轴，垂足为 C。若 △ ABC 的面积为 4，求反比例函数的解析式。"},{"type":"figure","figure":{"id":"fig-m-num-fanbili-jiaodian-1","title":"正比例与反比例交于 A、B 两点","caption":"AC⊥x 轴，△ABC 面积为 4","view":"square","alt":"平面直角坐标系中，第一、三象限各有一条双曲线分支，直线 y 等于 2x 穿过原点与两支双曲线分别交于 A 和 B 两点，过 A 作 x 轴的垂线垂足为 C，三角形 ABC 用阴影标出","prims":[{"t":"line","x1":10,"y1":50,"x2":82,"y2":50},{"t":"line","x1":45,"y1":12,"x2":45,"y2":88},{"t":"arrow","x1":82,"y1":50,"x2":86,"y2":50},{"t":"arrow","x1":45,"y1":12,"x2":45,"y2":8},{"t":"text","x":86,"y":54,"text":"x","size":3.4,"anchor":"middle"},{"t":"text","x":49,"y":10,"text":"y","size":3.4},{"t":"line","x1":27,"y1":86,"x2":63,"y2":14,"tone":"main","width":2},{"t":"curve","points":[[48,26],[51,38],[57,44],[69,48],[81,49]],"tone":"accent","width":2},{"t":"curve","points":[[42,74],[39,62],[33,56],[21,52],[9,51]],"tone":"accent","width":2},{"t":"line","x1":53.5,"y1":33,"x2":53.5,"y2":50,"tone":"danger","dashed":true},{"t":"poly","points":[[53.5,33],[53.5,50],[36.5,67]],"closed":true,"tone":"accent","fill":true},{"t":"dot","x":53.5,"y":33,"tone":"danger","label":"A","labelDx":6,"labelDy":-2},{"t":"dot","x":36.5,"y":67,"tone":"danger","label":"B","labelDx":-8,"labelDy":4},{"t":"dot","x":53.5,"y":50,"tone":"danger","label":"C","labelDx":4,"labelDy":10},{"t":"text","x":60,"y":22,"text":"y=2x","size":3.2,"tone":"main"},{"t":"text","x":70,"y":40,"text":"y=k/x","size":3.2,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["正比例函数与反比例函数的两个交点关于原点对称，想到 A、B 的横、纵坐标分别互为相反数。","设 A(t,2t)（t>0），则 B(-t,-2t)，垂足 C(t,0)。","以 AC 为底：AC=2t，点 B 到直线 AC（直线 x=t）的水平距离为 2t，故 S_(△ ABC)=(1)/(2)× 2t× 2t=2t²=4，得 t²=2。","点 A 在反比例图象上：k=t· 2t=2t²=4，故解析式为 y=(4)/(x)。"]},{"type":"p","text":"答案：y=(4)/(x)"},{"type":"note","title":"方法小结","text":"过双曲线上一点向坐标轴作垂线，该点、垂足与原点组成的三角形面积恒为 (|k|)/(2)。本题的三角形虽不是这个标准模型，但利用两交点关于原点对称，设出一个点的坐标即可把面积转化为 k。"},{"type":"list","title":"易错点","items":["比较不同象限上两点的函数值大小时，直接套用「$k>0$ 时 $y$ 随 $x$ 增大而减小」，导致结论相反。增减性只在同一个象限内成立，跨象限必须先算函数值或用图像判断。","把 $k$ 的符号与图像所在象限对应关系记反。正确关系是：$k>0$ 在第一、三象限，$k<0$ 在第二、四象限。","忽略 $k\\neq 0$ 与 $x\\neq 0$ 的条件，认为双曲线与坐标轴有交点。事实上 $x$ 越接近 0，$y$ 的绝对值越大，图像只能无限靠近坐标轴。","求 $k$ 时把 $k=xy$ 写成 $k=\\frac{y}{x}$，如把过点 $(2,3)$ 的反比例函数写成 $k=\\frac{3}{2}$。正确结果是 $k=6$。","面积问题漏掉 $\\frac{1}{2}$ 或绝对值，把三角形面积算成 $|k|$。注意矩形面积才是 $|k|$。","联立方程求解时两边同乘 $x$ 后忘记检验 $x\\neq 0$，把 $x=0$ 当作解写进交点坐标。"]},{"type":"list","title":"解题方法","items":["求解析式：设 y=(k)/(x)，用 k=xy 代入一个已知点求出 k，一步到位。","比较函数值大小三步：先判断两个点是否在同一象限；同象限用增减性；不同象限分别算出函数值再比较。","面积问题用 k 的几何意义：先判断图形是矩形还是三角形，再套 |k| 或 (|k|)/(2)，有时需要把图形分割成几个这样的基本图形求和。","与一次函数综合：联立求交点，再画图象比较上下位置，从而写出两个函数值大小关系的自变量取值范围。","对称性巧用：已知一个交点即可写出与它中心对称的另一个交点，常用于求三角形面积或求解析式。"]}],"questions":[{"id":"m-num-fanbili-q1","type":"choice","stem":"反比例函数 y=-(3)/(x) 的图像位于（ ）","answer":"B","explain":"本题 k=-3<0，由性质知图像的两支分别位于第二、第四象限，故选 B。可验证：取 x=1 得 y=-3，点 (1,-3) 在第四象限；取 x=-1 得 y=3，点 (-1,3) 在第二象限。可见 k<0 时图像在第二、四象限。","options":["第一、二象限","第二、四象限","第一、三象限","第三、四象限"],"difficulty":1,"tags":["反比例函数图像","象限","k的符号"]},{"id":"m-num-fanbili-q2","type":"choice","stem":"已知反比例函数的图像经过点 (-2,3)，则下列各点中也在该图像上的是（ ）","answer":"A","explain":"设解析式为 y=(k)/(x)，把 (-2,3) 代入得 k=(-2)× 3=-6，所以图像上每个点的横纵坐标之积都等于 -6。逐项检验：(3,-2) 的积为 -6，符合；(2,3) 的积为 6，不符合；(-3,-2) 的积为 6，不符合；(1,6) 的积为 6，不符合。故选 A。","options":["(3,-2)","(2,3)","(-3,-2)","(1,6)"],"difficulty":2,"tags":["反比例函数","k=xy","点与图像"]},{"id":"m-num-fanbili-q3","type":"fill","stem":"若反比例函数 y=(k)/(x) 的图像经过点 (3,-4)，则 k=（ ）。","answer":"-12","explain":"把 x=3、y=-4 代入 y=(k)/(x) 得 -4=(k)/(3)，两边同乘 3 得 k=-12。也可直接用 k=xy=3×(-4)=-12。检验：解析式为 y=-(12)/(x)，取 x=3 得 y=-4，与已知一致，且 k<0 说明图像在第二、四象限，点 (3,-4) 正在第四象限。","difficulty":1,"tags":["反比例函数","待定系数法"]},{"id":"m-num-fanbili-q4","type":"fill","stem":"点 P 在反比例函数 y=(8)/(x) 的图像上，过 P 作 x 轴的垂线，垂足为 A，则三角形 POA（O 为原点）的面积是（ ）。","answer":"4","explain":"设 P(x₀,y₀)，由 P 在图像上得 x₀y₀=8。垂足 A(x₀,0)，故 OA=|x₀|，P 到 x 轴的距离为 |y₀|。三角形面积 S=(1)/(2)|x₀|·|y₀|=(1)/(2)|x₀y₀|=(1)/(2)× 8=4。所以面积恒为 4，与 P 的位置无关。","difficulty":2,"tags":["k的几何意义","面积"],"figure":{"id":"fig-num-fanbili-jizhi","title":"反比例函数图象上一点与原点围成的三角形","caption":"P 在 y = 8/x 的图象上，PA 垂直于 x 轴于 A：三角形 POA 的两条直角边是 OA 与 PA，面积等于 ½·OA·PA = ½·|x·y| 恒为 4，与 P 的位置无关","view":"square","alt":"平面直角坐标系中第一象限的一段反比例函数图象，点 P 在图象上，从 P 向 x 轴作垂线，垂足为 A；原点 O 与 P、A 围成的直角三角形被涂色并画有直角方框。","prims":[{"t":"arrow","x1":16,"y1":69.8,"x2":88,"y2":69.8,"tone":"muted"},{"t":"arrow","x1":23,"y1":78,"x2":23,"y2":12,"tone":"muted"},{"t":"text","x":89,"y":71.8,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":25.4,"y":11,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":18.4,"y":73,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[40.4,14.8],[41.5,18.2],[42.7,21.2],[43.9,23.9],[45,26.3],[46.2,28.5],[47.4,30.5],[48.5,32.3],[49.7,33.9],[50.8,35.4],[52,36.8],[53.2,38],[54.3,39.2],[55.5,40.3],[56.6,41.3],[57.8,42.3],[59,43.1],[60.1,44],[61.3,44.8],[62.5,45.5],[63.6,46.2],[64.8,46.8],[65.9,47.5],[67.1,48],[68.3,48.6],[69.4,49.1],[70.6,49.6],[71.7,50.1],[72.9,50.6],[74.1,51],[75.2,51.4],[76.4,51.8],[77.5,52.2],[78.7,52.6],[79.9,52.9],[81,53.3],[82.2,53.6],[83.4,53.9],[84.5,54.2],[85.7,54.5],[86.8,54.7],[88,55]],"tone":"accent"},{"t":"poly","points":[[23,69.8],[46.2,69.8],[46.2,28.5]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":42.7,"y1":69.8,"x2":42.7,"y2":66.3,"tone":"muted"},{"t":"line","x1":42.7,"y1":66.3,"x2":46.2,"y2":66.3,"tone":"muted"},{"t":"dot","x":46.2,"y":69.8,"label":"A","labelDx":-1.6,"labelDy":4},{"t":"dot","x":46.2,"y":28.5,"label":"P","labelDx":3,"labelDy":-1.4},{"t":"text","x":20,"y":72,"text":"S = ½ · OA · PA","anchor":"start","size":3.6,"tone":"accent"},{"t":"text","x":78,"y":20,"text":"y = 8/x","anchor":"end","size":3.6,"tone":"accent"}]}},{"id":"m-num-fanbili-q5","type":"short","stem":"已知反比例函数 y=(m)/(x) 的图像经过点 A(2,3)。（1）求 m 的值与函数解析式；（2）若点 B(-3,n) 也在该图像上，求 n 的值；（3）判断点 A 与点 B 所在象限，并比较 y_(A) 与 y_(B) 的大小。","answer":"（1）$m=2\\times 3=6$，解析式为 $y=\\frac{6}{x}$；（2）$n=\\frac{6}{-3}=-2$；（3）$A(2,3)$ 在第一象限，$B(-3,-2)$ 在第三象限，$y_{A}=3>y_{B}=-2$。","explain":"（1）把 A(2,3) 代入 y=(m)/(x) 得 3=(m)/(2)，故 m=6，解析式为 y=(6)/(x)。（2）点 B(-3,n) 在图像上，则 xy=6，即 -3× n=6，解得 n=-2。（3）因为 k=6>0，图像在第一、三象限。点 A(2,3) 的横纵坐标均为正，在第一象限；点 B(-3,-2) 的横纵坐标均为负，在第三象限。由于两点不在同一象限，不能直接用增减性比较，应分别求出函数值：y_(A)=3、y_(B)=-2，所以 y_(A)>y_(B)（第一象限内的函数值为正，第三象限内的为负，正数恒大于负数）。","difficulty":3,"tags":["反比例函数","跨象限比较","综合"],"rubric":["正确求出 m=6 并写出解析式 y=(6)/(x)","由 xy=6 求出 n=-2","正确判断 A 在第一象限、B 在第三象限","指出两点不在同一象限，不能直接用增减性比较，而是分别求出 y_(A)=3、y_(B)=-2 后比较","得出 y_(A)>y_(B) 的结论"],"figure":{"id":"fig-num-fanbili-liangzhi","title":"反比例函数图象上的两点","caption":"y = 6/x 的图象在第一、三象限各有一支：A(2,3) 在第一象限、B(-3,-2) 在第三象限。两点不在同一支上，比较函数值要分别求出 y 的值，不能直接用增减性","view":"square","alt":"平面直角坐标系中反比例函数 y = 6/x 的图象分为第一象限与第三象限两支；第一象限上标出点 A，第三象限上标出点 B，两点的坐标都标注在图上。","prims":[{"t":"arrow","x1":14,"y1":46.7,"x2":88,"y2":46.7,"tone":"muted"},{"t":"arrow","x1":51,"y1":80,"x2":51,"y2":10,"tone":"muted"},{"t":"text","x":89,"y":48.7,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":53.4,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":46.4,"y":49.9,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[63.6,13.3],[64.5,15.4],[65.3,17.3],[66.1,18.9],[67,20.4],[67.8,21.7],[68.7,22.9],[69.5,23.9],[70.3,24.9],[71.2,25.8],[72,26.7],[72.9,27.4],[73.7,28.1],[74.5,28.8],[75.4,29.4],[76.2,30],[77.1,30.5],[77.9,31],[78.8,31.5],[79.6,32],[80.4,32.4],[81.3,32.8],[82.1,33.2],[83,33.5],[83.8,33.8],[84.6,34.2],[85.5,34.5],[86.3,34.8],[87.2,35],[88,35.3]],"tone":"accent"},{"t":"curve","points":[[14,58],[14.8,58.3],[15.7,58.6],[16.5,58.9],[17.4,59.2],[18.2,59.5],[19,59.8],[19.9,60.2],[20.7,60.6],[21.6,61],[22.4,61.4],[23.2,61.8],[24.1,62.3],[24.9,62.8],[25.8,63.3],[26.6,63.9],[27.5,64.5],[28.3,65.2],[29.1,65.9],[30,66.7],[30.8,67.5],[31.7,68.4],[32.5,69.4],[33.3,70.5],[34.2,71.7],[35,73],[35.9,74.4],[36.7,76.1],[37.5,77.9],[38.4,80]],"tone":"accent"},{"t":"circle","cx":67.8,"cy":21.7,"r":1.6,"tone":"danger","fill":true},{"t":"circle","cx":25.8,"cy":63.3,"r":1.6,"tone":"danger","fill":true},{"t":"dot","x":67.8,"y":21.7,"label":"A","labelDx":-1.6,"labelDy":-3.6},{"t":"dot","x":25.8,"y":63.3,"label":"B","labelDx":3,"labelDy":3},{"t":"text","x":80,"y":14,"text":"y = 6/x","anchor":"end","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":90,"text":"A、B 不在同一支上，须分别求 y 的值再比较","anchor":"middle","size":3.6,"tone":"muted"}]}},{"id":"m-num-fanbili-z1","type":"choice","stem":"关于反比例函数 y=-(2)/(x)，下列说法正确的是（ ）","answer":"D","explain":"k=-2<0，图象位于第二、第四象限。当 x₁<0 时点在第二象限，y₁>0；当 x₂>0 时点在第四象限，y₂<0，故 y₁>y₂，D 正确。A 项代入 (1,2) 得 1× 2=2≠ -2，图象不过该点；B 项象限判断相反；C 项 k<0 时在每个象限内 y 随 x 的增大而增大。","options":["图象经过点 (1,2)","图象位于第一、第三象限","当 x>0 时，y 随 x 的增大而减小","若 x₁<0<x₂，则对应的函数值 y₁>y₂"],"difficulty":2,"tags":["反比例函数图像","象限","k的符号"]},{"id":"m-num-fanbili-z2","type":"fill","stem":"如图，点 A 是反比例函数 y=(k)/(x)（x>0）图象上一点，过 A 作 AB⊥ x 轴于点 B，连接 OA。若 △ AOB 的面积为 3，则 k=（ ）。","answer":"6","explain":"设 A(x,y)（x>0），则 OB=x，AB=y。△ AOB 的面积 S=(1)/(2)xy=3，故 xy=6。点 A 在 y=(k)/(x) 上，k=xy=6（图象在第一象限，k 取正值）。一般地，这个三角形的面积等于 (|k|)/(2)。","difficulty":2,"tags":["k的几何意义","面积"],"figure":{"id":"fig-m-num-fanbili-kjihe-1","title":"k 的几何意义：三角形面积 = |k|/2","caption":"S△AOB=3，则 k=6","view":"square","alt":"平面直角坐标系第一象限内有一条反比例函数图像的分支，点 A 在图像上，过 A 向 x 轴作垂线垂足为 B，连接 OA，三角形 AOB 用阴影标出","prims":[{"t":"line","x1":14,"y1":75,"x2":78,"y2":75},{"t":"line","x1":20,"y1":14,"x2":20,"y2":80},{"t":"arrow","x1":78,"y1":75,"x2":82,"y2":75},{"t":"arrow","x1":20,"y1":14,"x2":20,"y2":10},{"t":"text","x":82,"y":79,"text":"x","size":3.4,"anchor":"middle"},{"t":"text","x":24,"y":12,"text":"y","size":3.4},{"t":"curve","points":[[23,33],[34,54],[48,63],[69,70]],"tone":"accent","width":2},{"t":"line","x1":20,"y1":75,"x2":34,"y2":54,"tone":"main"},{"t":"line","x1":34,"y1":54,"x2":34,"y2":75,"tone":"main"},{"t":"poly","points":[[20,75],[34,75],[34,54]],"closed":true,"tone":"accent","fill":true},{"t":"dot","x":34,"y":54,"tone":"danger","label":"A(x,y)","labelDx":6,"labelDy":-4},{"t":"dot","x":34,"y":75,"tone":"danger","label":"B","labelDx":4,"labelDy":10},{"t":"dot","x":20,"y":75,"tone":"muted","label":"O","labelDx":-8,"labelDy":10},{"t":"text","x":28,"y":70,"text":"S=½xy=3","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":55,"y":30,"text":"y=k/x","size":3.2,"tone":"accent"}]}}]},{"id":"m-num-hanshu-zonghe","title":"函数综合与图像变换","subtitle":"人教版 · 函数综合","grade":"9b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版 · 函数综合"},{"type":"note","title":"一句话概述","text":"综合一次、二次、反比例函数，掌握图像平移对称变换与数形结合的解题方法。"},{"type":"h","text":"先看交点：两个图象的公共点"},{"type":"p","text":"求抛物线 y=x²-2x-3 与直线 y=x-3 的交点，就是解方程 x²-2x-3=x-3，整理得 x²-3x=0，即 x=0 或 x=3。图象上的两个公共点正是 (0,-3) 与 (3,0)——交点的横坐标与方程的解是同一回事。"},{"type":"figure","figure":{"id":"fig-hanshu-s1","title":"抛物线与直线的两个交点","caption":"联立解得 x=0 与 x=3，交点即 (0,-3)、(3,0)","view":"square","alt":"平面直角坐标系中，开口向上的抛物线 y 等于 x 平方减 2x 减 3 与直线 y 等于 x 减 3 相交于两个点，分别是零、负三与三、零","prims":[{"t":"plane","x":46,"y":50,"right":44,"left":20,"up":44,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-16,"label":"-2"},{"at":-8,"label":"-1"},{"at":8,"label":"1"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":16,"label":"2"},{"at":-16,"label":"-2"},{"at":-32,"label":"-4"}]},{"t":"line","x1":30,"y1":90,"x2":86,"y2":34,"tone":"main","width":1.6},{"t":"curve","points":[[30,10],[34,32],[38,50],[42,64],[46,74],[50,80],[54,82],[58,80],[62,74],[66,64],[70,50],[74,32]],"tone":"accent","width":1.8},{"t":"dot","x":46,"y":74,"tone":"danger","label":"(0,-3)","labelDx":-10,"labelDy":10},{"t":"dot","x":70,"y":50,"tone":"danger","label":"(3,0)","labelDx":4,"labelDy":-6},{"t":"text","x":30,"y":16,"text":"y=x²-2x-3","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":80,"y":26,"text":"y=x-3","size":3.3,"anchor":"middle","tone":"main"}]}},{"type":"note","title":"","text":"交点必须联立解方程求出，不能靠图象估读；求出后要代回两个解析式检验。"},{"type":"h","text":"抓条件：图象的高低就是不等式"},{"type":"p","text":"同一个 x 处，谁的图象在上方，谁的函数值就更大。抛物线在 x 轴下方的部分满足 y<0，而这一段恰好落在两个交点 (-1,0)、(3,0) 之间，所以 y<0 的解集是 -1<x<3。把不等式看成一张高低图，解集就是那段自变量的范围。"},{"type":"figure","figure":{"id":"fig-hanshu-s2","title":"抛物线在 x 轴下方的一段决定解集","caption":"两个交点之间的部分在 x 轴下方，对应 -1<x<3 时 y<0","view":"square","alt":"平面直角坐标系中开口向上的抛物线与 x 轴交于负一、零与三、零两点，两点之间抛物线位于 x 轴下方的部分用阴影标出，说明这时 y 小于 0","prims":[{"t":"plane","x":46,"y":50,"right":44,"left":20,"up":44,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-8,"label":"-1"},{"at":8,"label":"1"},{"at":24,"label":"3"}],"yTicks":[{"at":-32,"label":"-4"}]},{"t":"poly","points":[[38,50],[42,64],[46,74],[50,80],[54,82],[58,80],[62,74],[66,64],[70,50]],"closed":true,"tone":"accent","fill":true},{"t":"curve","points":[[30,10],[34,32],[38,50],[42,64],[46,74],[50,80],[54,82],[58,80],[62,74],[66,64],[70,50],[74,32]],"tone":"accent","width":1.8},{"t":"dot","x":38,"y":50,"tone":"danger","label":"(-1,0)","labelDx":-4,"labelDy":-8},{"t":"dot","x":70,"y":50,"tone":"danger","label":"(3,0)","labelDx":4,"labelDy":-8},{"t":"text","x":54,"y":12,"text":"y<0 的解集：-1<x<3","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"开口向上时 y<0 对应两根之间，开口向下时刚好相反；拿不准就画草图，别凭记忆下结论。"},{"type":"h","text":"建立关系：动点的最值在临界位置"},{"type":"p","text":"固定底边 AB=4 后，△ PAB 的面积只与 P 到 x 轴的距离（即 P 的纵坐标）有关：S=(1)/(2)|AB|·|y_(P)|。要让面积最大，就让 |y_(P)| 最大，而顶点正是抛物线的最高点，所以 P 落在顶点时面积取到最大值。"},{"type":"figure","figure":{"id":"fig-hanshu-s3","title":"动点在顶点时三角形面积最大","caption":"底边 AB 固定，P 越高面积越大，顶点是最高点","view":"square","alt":"平面直角坐标系中开口向下的抛物线，与 x 轴交于负二、零和正二、零两点，底边 AB 在 x 轴上，顶点 P 与 AB 连成三角形并用阴影标出，P 到 x 轴的垂线段也用虚线画出","prims":[{"t":"plane","x":50,"y":58,"right":40,"left":40,"up":40,"down":40,"xLabel":"x","yLabel":"y","xTicks":[{"at":-16,"label":"-2"},{"at":16,"label":"2"}],"yTicks":[{"at":16,"label":"2"},{"at":32,"label":"4"}]},{"t":"poly","points":[[34,58],[66,58],[50,26]],"closed":true,"tone":"accent","fill":true},{"t":"curve","points":[[26,98],[30,76],[34,58],[38,44],[42,34],[46,28],[50,26],[54,28],[58,34],[62,44],[66,58],[70,76],[74,98]],"tone":"accent","width":1.8},{"t":"line","x1":50,"y1":26,"x2":50,"y2":58,"tone":"muted","dashed":true},{"t":"dot","x":34,"y":58,"tone":"danger","label":"A","labelDx":-7,"labelDy":8},{"t":"dot","x":66,"y":58,"tone":"danger","label":"B","labelDx":4,"labelDy":8},{"t":"dot","x":50,"y":26,"tone":"danger","label":"P","labelDx":4,"labelDy":-4},{"t":"text","x":50,"y":10,"text":"P 在顶点时面积最大","size":3.6,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"最值问题要先把目标量写成某个坐标的函数，再看它在什么位置取到最大或最小，而不是凭图猜测。"},{"type":"h","text":"换个情境：不规则图形切成规则图形"},{"type":"p","text":"坐标系里的四边形 OABC 的底与高不在同一处，直接套面积公式很困难。连一条对角线 OB，把它切成 △ OAB 与 △ OBC 两个三角形，每个都能用「底乘高除以 2」算出面积，再把两块相加就得到总面积。分割的关键是让每一块都变成规则图形。"},{"type":"figure","figure":{"id":"fig-hanshu-s4","title":"用对角线把四边形分成两个三角形","caption":"四边形 OABC 的面积等于两个小三角形面积之和","view":"square","alt":"平面直角坐标系中有一个四边形 OABC，顶点分别在原点、左上、右上和右下方，连对角线 OB 把四边形分成两个三角形，两块用不同的颜色标出","prims":[{"t":"plane","x":28,"y":72,"right":60,"left":20,"up":60,"down":16,"xLabel":"x","yLabel":"y","xTicks":[{"at":8,"label":"1"},{"at":40,"label":"5"},{"at":56,"label":"7"}],"yTicks":[{"at":16,"label":"2"},{"at":40,"label":"5"}]},{"t":"poly","points":[[28,72],[36,32],[68,40]],"closed":true,"tone":"accent","fill":true},{"t":"poly","points":[[28,72],[68,40],[84,72]],"closed":true,"tone":"ok","fill":true},{"t":"line","x1":28,"y1":72,"x2":68,"y2":40,"tone":"main","dashed":true},{"t":"dot","x":28,"y":72,"tone":"main","label":"O","labelDx":-7,"labelDy":8},{"t":"dot","x":36,"y":32,"tone":"danger","label":"A","labelDx":-3,"labelDy":-5},{"t":"dot","x":68,"y":40,"tone":"danger","label":"B","labelDx":4,"labelDy":-4},{"t":"dot","x":84,"y":72,"tone":"danger","label":"C","labelDx":4,"labelDy":8},{"t":"text","x":48,"y":90,"text":"S四边形 = S△OAB + S△OBC","size":3.6,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"分割时要保证分出的图形面积之和恰好等于原图形，所连的线不能切到图形外面去。"},{"type":"h","text":"核心概念"},{"type":"p","text":"三类函数的对比识别：一次函数 y=kx+b 的图像是一条直线，反比例函数 y=(k)/(x) 的图像是双曲线，二次函数 y=ax²+bx+c 的图像是抛物线。看图判断类型，先看形状，再看增减性与对称性。"},{"type":"p","text":"图像的平移变换：把函数写成「顶点形式」或整体形式后按「左加右减、上加下减」变换：左右平移作用于自变量 x（y=f(x) 变为 y=f(x-h)），上下平移作用于整个函数值（y=f(x) 变为 y=f(x)+k）。"},{"type":"p","text":"图像的对称变换：关于 x 轴对称：把 y 换成 -y，得 y=-f(x)；关于 y 轴对称：把 x 换成 -x，得 y=f(-x)；关于原点对称：两者都用，得 y=-f(-x)。关键点：对称变换改变开口或增减方向。"},{"type":"p","text":"函数与方程、不等式的关系：两个函数图像交点的横坐标就是方程 f(x)=g(x) 的解；f(x)>g(x) 的解集对应 f 的图像在 g 的图像上方的那部分自变量范围。这体现了「以形助数」的思想。"},{"type":"p","text":"函数与几何图形的综合：常见题型有求三角形或四边形的面积、判断是否存在满足条件的点。解题关键是先用坐标表示线段的长度，再用面积公式或几何关系（相似、勾股定理）列方程求解，并检验解是否在自变量允许范围内。"},{"type":"p","text":"实际情境中的函数图像：读图三步：看横纵轴表示的实际意义与单位，看图像的升降与转折分别对应什么过程，看特殊点（起点、终点、交点、最高最低点）的坐标含义。关键点：自变量的实际范围往往就是图像的横坐标范围。"},{"type":"note","title":"中考考法","text":"函数图象的平移与对称变换\n给原图象按「左加右减、上加下减」或关于坐标轴对称求新解析式，踩分点是分清作用于自变量还是整个函数值，并写出新顶点坐标。"},{"type":"note","title":"中考考法","text":"两个函数的交点与图象法解方程、不等式\n联立一次、二次或反比例解析式求交点，由图象上下位置直接读出不等式解集，踩分点是双曲线要分象限讨论，解集别漏分支。"},{"type":"note","title":"中考考法","text":"函数与几何、实际情境的综合\n以坐标表示线段求面积、判断动点位置，或读实际情境的分段图象求速度、时间等，踩分点是自变量范围与端点取舍要结合实际。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["一般平移规律","y=f(x)\\ \\ y=f(x-h)+k","向右平移 h 个单位（h>0）再向上平移 k 个单位；记忆口诀「左加右减、上加下减」。"],["关于 x 轴对称","y=f(x)\\ \\ y=-f(x)","抛物线的开口方向反向、顶点纵坐标变为相反数，横坐标不变。"],["关于 y 轴对称","y=f(x)\\ \\ y=f(-x)","一次函数的斜率变号、常数项不变，如 y=2x+1 关于 y 轴对称得 y=-2x+1。"],["关于原点对称","y=f(x)\\ \\ y=-f(-x)","一次函数中 k、b 都变号；反比例函数的 k 不变（图像本身关于原点中心对称）。"],["交点的求法","f(x)=g(x)","联立两个解析式解方程，得到的解就是交点横坐标；解出后代入任一解析式求纵坐标，并检验是否在各自定义域内。"]]},{"type":"note","title":"例题","text":"把抛物线 y=x² 先向右平移 2 个单位，再向上平移 3 个单位，求所得抛物线的解析式、顶点坐标与对称轴。"},{"type":"figure","figure":{"id":"fig-hanshu-e1","title":"向右平移 2、再向上平移 3 后的抛物线","caption":"虚线是原抛物线 y=x²，实线是 (x-2)²+3，顶点从 (0,0) 移到 (2,3)","view":"square","alt":"平面直角坐标系中两条抛物线，虚线顶点在原点代表 y 等于 x 平方，实线顶点在二、三处代表 y 等于 x 减 2 的平方加 3，一条水平与一条竖直双箭头分别标出向右平移 2 个单位、向上平移 3 个单位，实线抛物线的对称轴 x 等于 2 用竖直虚线标出","prims":[{"t":"plane","x":42,"y":64,"right":50,"left":32,"up":58,"down":26,"xLabel":"x","yLabel":"y","xTicks":[{"at":-16,"label":"-2"},{"at":16,"label":"2"},{"at":32,"label":"4"}],"yTicks":[{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":32,"label":"4"}]},{"t":"curve","points":[[30,46],[34,56],[42,64],[50,56],[54,46],[58,32],[62,14]],"tone":"muted","dashed":true,"width":1.3},{"t":"curve","points":[[42,8],[46,22],[50,32],[54,38],[58,40],[62,38],[66,32],[70,22],[74,8]],"tone":"accent","width":1.8},{"t":"line","x1":58,"y1":10,"x2":58,"y2":66,"tone":"muted","dashed":true},{"t":"arrow","x1":42,"y1":64,"x2":58,"y2":64,"both":true,"tone":"main","label":"向右 2","labelDy":9},{"t":"arrow","x1":58,"y1":64,"x2":58,"y2":40,"both":true,"tone":"accent","label":"向上 3","labelDx":9},{"t":"dot","x":42,"y":64,"tone":"main","label":"(0,0)","labelDx":-14,"labelDy":10},{"t":"dot","x":58,"y":40,"tone":"danger","label":"(2,3)","labelDx":4,"labelDy":-4},{"t":"text","x":24,"y":58,"text":"y=x²","size":3.5,"anchor":"middle","tone":"muted"},{"t":"text","x":76,"y":76,"text":"y=(x-2)²+3","size":3.5,"anchor":"middle","tone":"accent"},{"t":"text","x":58,"y":4,"text":"对称轴 x=2","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["向右平移 2 个单位，变量替换为 x-2：得 y=(x-2)²。","再向上平移 3 个单位，整体加 3：得 y=(x-2)²+3。","对照顶点式 y=a(x-h)²+k，得 a=1、h=2、k=3。","所以顶点坐标是 (2,3)，对称轴是直线 x=2。","检验：平移不改变 a，原抛物线开口向上、顶点为 (0,0)，平移后开口仍向上、顶点向右上移到 (2,3)，符合「左加右减、上加下减」。"]},{"type":"p","text":"答案：y=(x-2)²+3，顶点 (2,3)，对称轴 x=2"},{"type":"note","title":"方法小结","text":"左右平移改变的是 x，所以是「左加右减」（向右平移 2 个单位写成 x-2）；上下平移改变的是整体，写成 +3。若把两次平移的顺序反过来做，结果完全相同，因为平移是可交换的。"},{"type":"note","title":"例题","text":"求抛物线 y=x²-2x-3 与直线 y=x-3 的交点坐标。"},{"type":"figure","figure":{"id":"fig-hanshu-e2","title":"交点横坐标就是方程的解","caption":"联立解 x²-3x=0 得 x=0、x=3，交点即 (0,-3) 与 (3,0)","view":"square","alt":"平面直角坐标系中开口向上的抛物线 y 等于 x 平方减 2x 减 3 与直线 y 等于 x 减 3 相交于两点，从位于 x 轴下方的交点向 x 轴作竖直虚线垂线，两个交点下方分别标出横坐标 0 和 3","prims":[{"t":"plane","x":46,"y":50,"right":44,"left":20,"up":44,"down":44,"xLabel":"x","yLabel":"y","xTicks":[{"at":-16,"label":"-2"},{"at":-8,"label":"-1"},{"at":8,"label":"1"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":16,"label":"2"},{"at":-16,"label":"-2"},{"at":-32,"label":"-4"}]},{"t":"line","x1":30,"y1":90,"x2":86,"y2":34,"tone":"main","width":1.6},{"t":"curve","points":[[30,10],[34,32],[38,50],[42,64],[46,74],[50,80],[54,82],[58,80],[62,74],[66,64],[70,50],[74,32]],"tone":"accent","width":1.8},{"t":"line","x1":46,"y1":74,"x2":46,"y2":50,"tone":"muted","dashed":true},{"t":"dot","x":46,"y":74,"tone":"danger","label":"(0,-3)","labelDx":-12,"labelDy":8},{"t":"dot","x":70,"y":50,"tone":"danger","label":"(3,0)","labelDx":4,"labelDy":-6},{"t":"text","x":46,"y":98,"text":"x=0","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":70,"y":98,"text":"x=3","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":28,"y":20,"text":"y=x²-2x-3","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":80,"y":26,"text":"y=x-3","size":3.3,"anchor":"middle","tone":"main"},{"t":"text","x":58,"y":10,"text":"x²-3x=0 ⇒ x=0 或 x=3","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["令两个函数值相等：x²-2x-3=x-3。","移项整理：x²-2x-3-x+3=0，即 x²-3x=0。","因式分解：x(x-3)=0，故 x=0 或 x=3。","当 x=0 时，y=0-3=-3，得交点 (0,-3)。","当 x=3 时，y=3-3=0，得交点 (3,0)。","检验：把 (0,-3) 代入抛物线得 0-0-3=-3，成立；把 (3,0) 代入得 9-6-3=0，成立。"]},{"type":"p","text":"答案：(0,-3) 与 (3,0)"},{"type":"note","title":"方法小结","text":"求交点就是解方程组，千万不要用图像估读坐标。本题中两式都有 -3 这一项，移项后常数恰好抵消，这是命题者留下的简化机会，要善于观察。"},{"type":"note","title":"例题","text":"抛物线 y=-x²+2x+3 与 x 轴交于 A、B 两点，与 y 轴交于点 C，求三角形 ABC 的面积，并直接写出 y<0 时 x 的取值范围。"},{"type":"figure","figure":{"id":"fig-hanshu-e3","title":"抛物线与坐标轴围成的三角形","caption":"底 AB=4、高 OC=3，面积 S=6；开口向下，x<-1 或 x>3 时 y<0","view":"square","alt":"平面直角坐标系中开口向下的抛物线 y 等于负 x 平方加 2x 加 3，与 x 轴交于负一、零与三、零两点 A、B，与 y 轴交于零、三的点 C，三角形 ABC 用阴影标出并标注面积等于 6","prims":[{"t":"plane","x":46,"y":62,"right":44,"left":20,"up":44,"down":36,"xLabel":"x","yLabel":"y","xTicks":[{"at":-8,"label":"-1"},{"at":8,"label":"1"},{"at":16,"label":"2"},{"at":24,"label":"3"}],"yTicks":[{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":32,"label":"4"}]},{"t":"poly","points":[[38,62],[70,62],[46,38]],"closed":true,"tone":"ok","fill":true},{"t":"curve","points":[[34,80],[38,62],[42,48],[46,38],[50,32],[54,30],[58,32],[62,38],[66,48],[70,62],[74,80]],"tone":"accent","width":1.8},{"t":"dot","x":38,"y":62,"tone":"danger","label":"A(-1,0)","labelDx":-4,"labelDy":-9},{"t":"dot","x":70,"y":62,"tone":"danger","label":"B(3,0)","labelDx":4,"labelDy":-9},{"t":"dot","x":46,"y":38,"tone":"danger","label":"C(0,3)","labelDx":6,"labelDy":-5},{"t":"text","x":50,"y":53,"text":"S=6","size":3.6,"anchor":"middle","tone":"ok"},{"t":"text","x":62,"y":14,"text":"y=-x²+2x+3","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":46,"y":96,"text":"y<0：x<-1 或 x>3","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["求与 x 轴交点：令 y=0 得 -x²+2x+3=0，即 x²-2x-3=0。","因式分解得 (x-3)(x+1)=0，所以 x=3 或 x=-1，即 A(-1,0)、B(3,0)。","求与 y 轴交点：令 x=0 得 y=3，即 C(0,3)。","底边 AB 的长度为 3-(-1)=4，C 到 x 轴的距离（即三角形的高）为 |3|=3。","面积 =(1)/(2)× 4× 3=6。","由图像开口向下（a=-1<0）可知，抛物线在 x 轴下方的部分位于两个交点之外，即 x<-1 或 x>3。"]},{"type":"p","text":"答案：面积为 6；当 x<-1 或 x>3 时 y<0"},{"type":"note","title":"方法小结","text":"开口向下时，「y<0」对应图像位于 x 轴下方的部分，即交点外侧的区间；开口向上时则相反，对应两交点之间。不确定时画草图最保险，切勿凭记忆下结论。"},{"type":"note","title":"例题","text":"已知抛物线 y=2(x-1)²+3。（1）求它关于 x 轴对称的抛物线的解析式与顶点坐标；（2）求对称后的抛物线与 y 轴的交点坐标。"},{"type":"figure","figure":{"id":"fig-hanshu-e4","title":"关于 x 轴对称的抛物线","caption":"实线是原抛物线 y=2(x-1)²+3，虚线是关于 x 轴对称的 y=-2(x-1)²-3","view":"square","alt":"平面直角坐标系中两条抛物线关于 x 轴对称，实线开口向上顶点在一、三处，虚线开口向下顶点在一、负三处，竖直虚线标出对称轴 x 等于 1，两个顶点与两个 y 轴交点成对对称","prims":[{"t":"plane","x":36,"y":50,"right":36,"left":12,"up":40,"down":42,"xLabel":"x","yLabel":"y","xTicks":[{"at":8,"label":"1"},{"at":16,"label":"2"}],"yTicks":[{"at":16,"label":"2"},{"at":24,"label":"3"},{"at":32,"label":"4"},{"at":-16,"label":"-2"},{"at":-24,"label":"-3"},{"at":-32,"label":"-4"}]},{"t":"line","x1":44,"y1":10,"x2":44,"y2":92,"tone":"muted","dashed":true},{"t":"curve","points":[[36,10],[40,22],[42,25],[44,26],[46,25],[48,22],[52,10]],"tone":"accent","width":1.8},{"t":"curve","points":[[36,90],[40,78],[42,75],[44,74],[46,75],[48,78],[52,90]],"tone":"ok","dashed":true,"width":1.6},{"t":"dot","x":44,"y":26,"tone":"danger","label":"(1,3)","labelDx":4,"labelDy":-8},{"t":"dot","x":44,"y":74,"tone":"danger","label":"(1,-3)","labelDx":4,"labelDy":10},{"t":"dot","x":36,"y":10,"tone":"muted","label":"(0,5)","labelDx":-10,"labelDy":-2},{"t":"dot","x":36,"y":90,"tone":"muted","label":"(0,-5)","labelDx":-12,"labelDy":4},{"t":"text","x":44,"y":4,"text":"对称轴 x=1","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":70,"y":20,"text":"y=2(x-1)²+3","size":3.3,"anchor":"middle","tone":"accent"},{"t":"text","x":70,"y":82,"text":"y=-2(x-1)²-3","size":3.3,"anchor":"middle","tone":"ok"}]}},{"type":"list","title":"解题步骤","items":["关于 x 轴对称，想到把函数值整体变号：y 换成 -y，即新解析式为 y=-2(x-1)²-3。","原顶点为 (1,3)，关于 x 轴对称后横坐标不变、纵坐标变号，得新顶点 (1,-3)，同时开口由向上变为向下。","求与 y 轴交点令 x=0：y=-2(0-1)²-3=-2-3=-5。","故交点为 (0,-5)。检验：原抛物线在 x=0 时 y=5，两点 (0,5)、(0,-5) 关于 x 轴对称，符合变换。"]},{"type":"p","text":"答案：（1）y=-2(x-1)²-3，顶点为 (1,-3)；（2）与 y 轴交点为 (0,-5)"},{"type":"note","title":"方法小结","text":"关于 x 轴对称是「把 y 变成 -y」，整个解析式取相反数，顶点横坐标不变、纵坐标变号，开口方向也反转。最容易出错的是只给顶点变号而忘记二次项系数也要变号。"},{"type":"note","title":"例题","text":"一个水池先只开进水管：前 5 分钟匀速进水，池中水量从 0 增加到 30 立方米；第 5 分钟起进水管保持开启，同时打开出水管，再过 10 分钟，池中水量为 40 立方米；第 15 分钟末关闭进水管，只开出水管直到水放完。设每分钟进、出水量恒定，求：（1）进水管每分钟的进水量；（2）出水管每分钟的出水量；（3）只开出水管放完全池水需要多少分钟。"},{"type":"figure","figure":{"id":"fig-m-num-hanshu-shuichi-1","title":"水池水量随时间变化的分段图像","caption":"三段：单进水 → 进出同开 → 单出水","view":"wide","alt":"时间与水量的关系图，第一段从原点到 5 分钟 30 立方米斜率较大，第二段从 5 分钟到 15 分钟水量缓慢增加到 40 立方米，第三段从 15 分钟开始水量下降到 23 分钟时为 0","prims":[{"t":"axis","x":15,"y":70,"w":75,"h":55,"xLabel":"时间/分钟","yLabel":"水量/立方米","xTicks":[{"at":5,"label":"5"},{"at":10,"label":"10"},{"at":15,"label":"15"},{"at":20,"label":"20"}],"yTicks":[{"at":20,"label":"20"},{"at":40,"label":"40"}]},{"t":"line","x1":15,"y1":70,"x2":30,"y2":34,"tone":"accent","width":2},{"t":"line","x1":30,"y1":34,"x2":60,"y2":22,"tone":"accent","width":2},{"t":"line","x1":60,"y1":22,"x2":84,"y2":70,"tone":"accent","width":2},{"t":"line","x1":30,"y1":34,"x2":30,"y2":70,"tone":"muted","dashed":true},{"t":"line","x1":60,"y1":22,"x2":60,"y2":70,"tone":"muted","dashed":true},{"t":"dot","x":30,"y":34,"tone":"danger","label":"(5,30)","labelDx":4,"labelDy":-4},{"t":"dot","x":60,"y":22,"tone":"danger","label":"(15,40)","labelDx":4,"labelDy":-2},{"t":"dot","x":84,"y":70,"tone":"danger","label":"(23,0)","labelDx":0,"labelDy":12},{"t":"text","x":22,"y":48,"text":"只进水","size":3,"tone":"main","anchor":"middle"},{"t":"text","x":45,"y":28,"text":"进出同开","size":3,"tone":"main","anchor":"middle"},{"t":"text","x":72,"y":44,"text":"只出水","size":3,"tone":"main","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["前 5 分钟只进水 30 立方米，进水管每分钟进水量为 30÷ 5=6 立方米/分。","第 5 到第 15 分钟共 10 分钟，两管同时开，净增加水量为 40-30=10 立方米，故每分钟净增 10÷ 10=1 立方米。","设出水管每分钟出水 v 立方米，由「进水量减去出水量等于净增量」列方程：6-v=1，解得 v=5 立方米/分。","第 15 分钟末池中有 40 立方米水，只开出水管放完所需时间为 40÷ 5=8 分钟。"]},{"type":"p","text":"答案：（1）进水量 6 立方米/分；（2）出水量 5 立方米/分；（3）放完水需要 8 分钟"},{"type":"note","title":"方法小结","text":"进出水问题要分段读图象或文字：只进水段求进水量，同时开进、出水管时算的是「净增量」，两段相减才得到出水量。最后放水时间用剩余水量除以出水速度。"},{"type":"list","title":"易错点","items":["平移方向记反，把向右平移写成 $x+h$。牢记「左加右减」：向右平移 $h$ 个单位是 $y=f(x-h)$。","对称变换时只改一部分，如把抛物线关于 $x$ 轴对称只变顶点纵坐标而开口方向没改，或一次函数关于 $y$ 轴对称时把常数项也变了号。","求交点时不联立、不解方程，直接看图像估读坐标，导致答案不精确；或求出的解不代回检验。","涉及实际情境的图像题忽略自变量取值范围，把图像无限延伸下去，得出不符合实际的结论。","存在性问题的分类讨论不全，如只考虑点在线段上的情形，漏掉点在延长线上的情形。","在图像上比较两个函数值大小时看错上下位置，或把「在图像上方」误判为函数值较小。"]},{"type":"list","title":"解题方法","items":["判断函数类型：先看图像形状（直线、双曲线、抛物线），再结合增减性与对称性确定解析式的形式。","图像变换两步走：先化成易于观察的形式（二次函数化顶点式），再按「左加右减作用于 x、上加下减作用于整体」逐次变换。","待定系数法选式原则：已知顶点用顶点式，已知与 x 轴交点用交点式，其余用一般式；求出解析式后代点检验。","数形结合解题：把方程的解看成交点横坐标，把不等式的解集看成图像的上下位置关系，把面积问题化归为坐标与线段长度的计算。","综合题分步作答：先求解析式，再求关键点坐标，最后处理面积或存在性问题；每一步都用题目条件复核，避免一步错、步步错。"]}],"questions":[{"id":"m-num-hanshu-zonghe-q1","type":"choice","stem":"将抛物线 y=x² 先向左平移 1 个单位，再向下平移 2 个单位，所得抛物线的解析式是（ ）","answer":"B","explain":"左加右减：向左平移 1 个单位要把 x 换成 x+1，得 y=(x+1)²；上加下减：向下平移 2 个单位是整体减 2，得 y=(x+1)²-2。故选 B。检验：顶点由 (0,0) 变为 (-1,-2)，即向左下移动，符合题意。","options":["y=(x-1)²-2","y=(x+1)²-2","y=(x+1)²+2","y=(x-1)²+2"],"difficulty":2,"tags":["图像平移","二次函数","顶点"]},{"id":"m-num-hanshu-zonghe-q2","type":"choice","stem":"若一次函数 y=kx+b 的图像经过第一、二、四象限，则反比例函数 y=(k)/(x) 的图像位于（ ）","answer":"B","explain":"一次函数图像不经过第三象限而经过第二、四象限，说明 y 随 x 增大而减小，即 k<0；又经过第一象限且在 y 轴上的截距为正，即 b>0。因为 k<0，反比例函数 y=(k)/(x) 的图像位于第二、四象限，故选 B。本题中 b 只影响一次函数与 y 轴的交点，与反比例函数无关。","options":["第一、三象限","第二、四象限","k 的符号不定，无法判断","与 b 的符号有关"],"difficulty":2,"tags":["函数图像","象限","符号判断"]},{"id":"m-num-hanshu-zonghe-q3","type":"fill","stem":"抛物线 y=x²-2x-3 与直线 y=x-3 的交点个数是（ ）个。","answer":"2","explain":"令 x²-2x-3=x-3，整理得 x²-3x=0，因式分解得 x(x-3)=0，所以 x=0 或 x=3，两个不同的解对应两个交点 (0,-3) 与 (3,0)，故交点个数为 2。也可用判别式判断：方程 x²-3x=0 的 Δ=9>0，说明有两个交点。","difficulty":2,"tags":["交点个数","联立方程"]},{"id":"m-num-hanshu-zonghe-q4","type":"fill","stem":"抛物线 y=-x²+2x+3 与 x 轴的两个交点之间的距离是（ ）。","answer":"4","explain":"令 y=0 得 -x²+2x+3=0，两边同乘 -1 得 x²-2x-3=0，因式分解得 (x-3)(x+1)=0，所以 x=3 或 x=-1，交点为 (-1,0)、(3,0)。两点间距离为 |3-(-1)|=4。也可用公式：距离 =|x₁-x₂|=(x₁+x₂)²-4x₁x₂=2²-4×(-3)=√(16)=4，结果一致。","difficulty":2,"tags":["抛物线与x轴","两点距离"]},{"id":"m-num-hanshu-zonghe-q5","type":"short","stem":"已知抛物线 y=x²-2x-3 与 x 轴交于点 A、B（A 在 B 左侧），与 y 轴交于点 C。（1）求 A、B、C 三点的坐标；（2）求三角形 ABC 的面积；（3）直接写出 y<0 时 x 的取值范围。","answer":"（1）$A(-1,0)$，$B(3,0)$，$C(0,-3)$；（2）面积 $=\\frac{1}{2}\\times 4\\times 3=6$；（3）当 $-1<x<3$ 时 $y<0$。","explain":"（1）令 y=0：x²-2x-3=0，因式分解得 (x-3)(x+1)=0，所以 x=3 或 x=-1。因为 A 在 B 左侧，故 A(-1,0)、B(3,0)。令 x=0：y=-3，故 C(0,-3)。（2）底边 AB=|3-(-1)|=4，点 C 到 x 轴的距离为 |-3|=3，所以三角形面积为 (1)/(2)× 4× 3=6。（3）抛物线的二次项系数 a=1>0，开口向上，图像在 x 轴下方的部分位于两个交点之间，即 -1<x<3 时 y<0。检验：取 x=0，y=0-0-3=-3<0，落在 -1<x<3 内，结论正确。","difficulty":3,"tags":["二次函数综合","面积","图像法解不等式"],"rubric":["正确求出 A(-1,0)、B(3,0)、C(0,-3) 三个点的坐标","正确算出底边 AB=4 与高为 3","面积计算正确，结果为 6","由开口向上判断出 y<0 对应两交点之间，写出 -1<x<3","过程完整，第三步有必要的依据说明"],"figure":{"id":"fig-num-hanshu-zonghe-abc","title":"抛物线与两条坐标轴围成的三角形","caption":"y = x²-2x-3 与 x 轴交于 A(-1,0)、B(3,0)，与 y 轴交于 C(0,-3)：三角形 ABC 以 AB = 4 为底、高为 3","view":"square","alt":"平面直角坐标系中开口向上的抛物线 y = x²-2x-3，与 x 轴交于 A、B，与 y 轴交于 C；A、B、C 三点连成的三角形被涂色，x 轴上两个交点之间的部分被加粗标出。","prims":[{"t":"arrow","x1":14,"y1":50.8,"x2":92,"y2":50.8,"tone":"muted"},{"t":"arrow","x1":43.8,"y1":82,"x2":43.8,"y2":10,"tone":"muted"},{"t":"text","x":93,"y":52.8,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":46.2,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":39.2,"y":54,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[14,10],[16.3,10],[18.6,10],[20.9,16.8],[23.2,24.7],[25.5,32],[27.8,38.8],[30.1,45],[32.4,50.8],[34.6,55.9],[36.9,60.5],[39.2,64.6],[41.5,68.1],[43.8,71.1],[46.1,73.6],[48.4,75.5],[50.7,76.8],[53,77.7],[55.3,77.9],[57.6,77.7],[59.9,76.8],[62.2,75.5],[64.5,73.6],[66.8,71.1],[69.1,68.1],[71.4,64.6],[73.6,60.5],[75.9,55.9],[78.2,50.8],[80.5,45],[82.8,38.8],[85.1,32],[87.4,24.7],[89.7,16.8],[92,10]],"tone":"accent"},{"t":"poly","points":[[32.4,50.8],[78.2,50.8],[43.8,71.1]],"closed":true,"tone":"accent","fill":true},{"t":"line","x1":32.4,"y1":50.8,"x2":78.2,"y2":50.8,"tone":"danger","width":1.4},{"t":"dot","x":32.4,"y":50.8,"label":"A","labelDx":-4.6,"labelDy":-1.2},{"t":"dot","x":78.2,"y":50.8,"label":"B","labelDx":2.6,"labelDy":-1.2},{"t":"dot","x":43.8,"y":71.1,"label":"C","labelDx":-5.4,"labelDy":-2.4},{"t":"text","x":50,"y":78,"text":"AB = 4，高 = 3","anchor":"middle","size":3.6,"tone":"accent"}]}},{"id":"m-num-hanshu-zonghe-z1","type":"choice","stem":"一次函数 y=2x-3 的图象关于 y 轴对称后得到的图象对应的函数解析式是（ ）","answer":"A","explain":"关于 y 轴对称要把自变量 x 换成 -x，代入得 y=2(-x)-3=-2x-3，故选 A。对称后直线斜率变号、与 y 轴的交点 (0,-3) 保持不变，也可用这一特征检验。","options":["y=-2x-3","y=-2x+3","y=2x+3","y=-(1)/(2)x-3"],"difficulty":2,"tags":["函数图像","对称变换"]},{"id":"m-num-hanshu-zonghe-z2","type":"short","stem":"已知直线 y=x+2 与反比例函数 y=(3)/(x) 的图象交于 A、B 两点（A 在右）。（1）求 A、B 两点的坐标；（2）结合图象直接写出 x+2>(3)/(x) 的解集。","answer":"（1）$A(1,3)$，$B(-3,-1)$；（2）$-3<x<0$ 或 $x>1$。","explain":"联立两个解析式：x+2=(3)/(x)（x≠ 0），两边乘 x 得 x²+2x=3，即 (x-1)(x+3)=0，故 x=1 或 x=-3。代入直线得 A(1,3)、B(-3,-1)。比大小时画草图：直线与双曲线在 x=1、x=-3 处相交，直线位于双曲线上方的范围是两交点之间且包含 x=0 附近直线在正半轴上方的部分；要注意 x=0 处双曲线无意义，故中间一段断开为两部分：在 -3<x<0 与 x>1 时直线在上方。取 x=-1 检验：直线值为 1，双曲线值为 -3，确有 1>-3，故中间区间不能漏掉。","difficulty":3,"tags":["交点个数","联立方程","图像法解不等式"],"rubric":["正确联立并整理为 (x-1)(x+3)=0，求出 A(1,3)、B(-3,-1)","写出 x>1 这一段解集","不遗漏 -3<x<0 这一段（注意 x≠ 0），最终解集为 -3<x<0 或 x>1"],"figure":{"id":"fig-num-hanshu-zonghe-jiaodian","title":"直线与反比例函数的两个交点","caption":"直线 y = x+2 与双曲线 y = 3/x 交于 A(1,3)、B(-3,-1)：观察图象可直接读出直线在双曲线上方的范围","view":"square","alt":"平面直角坐标系中反比例函数 y = 3/x 的图象分为两支，一条直线 y = x+2 与它交于第一象限的 A 与第三象限的 B；A、B 两点标出坐标，直线位于曲线上方的两段区间被提示出来。","prims":[{"t":"arrow","x1":14,"y1":49.3,"x2":88,"y2":49.3,"tone":"muted"},{"t":"arrow","x1":51,"y1":80,"x2":51,"y2":10,"tone":"muted"},{"t":"text","x":89,"y":51.3,"text":"x","size":3.4,"tone":"muted"},{"t":"text","x":53.4,"y":9,"text":"y","size":3.4,"tone":"muted"},{"t":"text","x":46.4,"y":52.5,"text":"O","size":3.2,"tone":"muted"},{"t":"curve","points":[[56.6,12.7],[57.4,17.3],[58.2,20.8],[59,23.7],[59.8,26],[60.7,27.9],[61.5,29.6],[62.3,31],[63.1,32.2],[63.9,33.3],[64.7,34.2],[65.5,35],[66.3,35.8],[67.1,36.5],[67.9,37.1],[68.7,37.6],[69.5,38.1],[70.3,38.6],[71.1,39],[71.9,39.4],[72.7,39.8],[73.5,40.1],[74.3,40.4],[75.1,40.7],[75.9,41],[76.7,41.3],[77.5,41.5],[78.3,41.7],[79.2,42],[80,42.2],[80.8,42.3],[81.6,42.5],[82.4,42.7],[83.2,42.9],[84,43],[84.8,43.2],[85.6,43.3],[86.4,43.4],[87.2,43.6],[88,43.7]],"tone":"accent"},{"t":"curve","points":[[14,54.8],[14.8,55],[15.6,55.1],[16.4,55.2],[17.2,55.4],[18,55.5],[18.8,55.7],[19.6,55.8],[20.4,56],[21.2,56.2],[22,56.4],[22.8,56.6],[23.7,56.8],[24.5,57],[25.3,57.3],[26.1,57.5],[26.9,57.8],[27.7,58.1],[28.5,58.4],[29.3,58.8],[30.1,59.1],[30.9,59.5],[31.7,59.9],[32.5,60.4],[33.3,60.9],[34.1,61.5],[34.9,62.1],[35.7,62.7],[36.5,63.5],[37.3,64.3],[38.1,65.3],[38.9,66.3],[39.7,67.6],[40.5,69],[41.3,70.6],[42.2,72.5],[43,74.9],[43.8,77.7],[44.6,80],[45.4,80]],"tone":"accent"},{"t":"curve","points":[[14,71.5],[18,67.2],[22,62.9],[26.1,58.7],[30.1,54.4],[34.1,50.1],[38.1,45.9],[42.2,41.6],[46.2,37.3],[50.2,33],[54.2,28.8],[58.2,24.5],[62.3,20.2],[66.3,16],[70.3,11.7]],"tone":"ok"},{"t":"circle","cx":59,"cy":23.7,"r":1.6,"tone":"danger","fill":true},{"t":"circle","cx":26.9,"cy":57.8,"r":1.6,"tone":"danger","fill":true},{"t":"dot","x":59,"y":23.7,"label":"A","labelDx":3,"labelDy":-1.4},{"t":"dot","x":26.9,"y":57.8,"label":"B","labelDx":-5.4,"labelDy":2.6},{"t":"text","x":78,"y":16,"text":"y = x + 2","anchor":"end","size":3.6,"tone":"ok"},{"t":"text","x":80,"y":30,"text":"y = 3/x","anchor":"end","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":90,"text":"直线在上方：-3 < x < 0 或 x > 1","anchor":"middle","size":3.6,"tone":"muted"}]}}]},{"id":"m-num-yinshifenjie","title":"因式分解常用方法","subtitle":"人教版八上 · 第17章 因式分解","grade":"8a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八上 · 第17章 因式分解"},{"type":"note","title":"一句话概述","text":"系统掌握提公因式、公式法、十字相乘与分组分解，能把多项式分解到不能再分解。"},{"type":"h","text":"一提：把每项都有的部分拿出去"},{"type":"p","text":"提公因式并不是新规矩，它只是把分配律 m(a+b+c)=ma+mb+mc 从右往左用。三块面积分别是 ma、mb、mc，它们同宽为 m，拼在一起就是宽 m、长为 a+b+c 的一个大长方形，所以反过来写就是把公共的 m 提出来。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-s1","title":"三块同宽的长方形拼成一个整体","caption":"ma、mb、mc 三块宽度都是 m，提出 m 后剩 a+b+c","view":"square","alt":"一个大长方形被两条水平线分成三块，三块宽度相同为 m，高度分别为 a、b、c，三块面积分别标为 ma、mb、mc，下方用双箭头标出三块同宽 m，右侧写出 ma 加 mb 加 mc 等于 m 乘以 a 加 b 加 c","prims":[{"t":"text","x":50,"y":9,"text":"提公因式：分配律反过来用","size":3.4,"anchor":"middle","tone":"muted"},{"t":"rect","x":22,"y":20,"w":26,"h":60,"tone":"main","fill":true},{"t":"line","x1":22,"y1":40,"x2":48,"y2":40,"tone":"muted"},{"t":"line","x1":22,"y1":60,"x2":48,"y2":60,"tone":"muted"},{"t":"text","x":35,"y":30,"text":"ma","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":35,"y":50,"text":"mb","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":35,"y":70,"text":"mc","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":52,"y":30,"text":"→ a","size":3.4,"anchor":"start","tone":"muted"},{"t":"text","x":52,"y":50,"text":"→ b","size":3.4,"anchor":"start","tone":"muted"},{"t":"text","x":52,"y":70,"text":"→ c","size":3.4,"anchor":"start","tone":"muted"},{"t":"arrow","x1":22,"y1":88,"x2":48,"y2":88,"both":true,"tone":"accent","label":"m","labelDy":-3},{"t":"text","x":35,"y":97,"text":"三块同宽","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":78,"y":40,"text":"ma+mb+mc","size":3.6,"anchor":"middle","tone":"main"},{"t":"text","x":78,"y":52,"text":"= m(a+b+c)","size":3.6,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"公因式的系数取各项系数的最大公约数，字母取各项都含有的最低次幂；某项被整体提出后，括号里必须留一个 1。"},{"type":"h","text":"二套：平方差公式其实就是剪出一个角"},{"type":"p","text":"边长 a 的大正方形面积是 a²，从右下角剪去边长 b 的小正方形（面积 b²），剩下的 L 形面积就是 a²-b²。把这块 L 形重新拼成一个长 a+b、宽 a-b 的长方形，面积不变，于是 a²-b²=(a+b)(a-b)——公式是「面积没变、形状变了」的结论。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-s2","title":"大正方形剪掉小正方形就是平方差","caption":"剩下的 L 形面积等于 a²-b²，可拼成 (a+b)(a-b) 的长方形","view":"square","alt":"一个边长为 a 的大正方形，右下角有一个边长为 b 的小正方形，小正方形面积标为 b 平方并用阴影标出，剩下部分表示 a 平方减 b 平方，下方写出 a 平方减 b 平方等于 a 加 b 乘以 a 减 b","prims":[{"t":"rect","x":15,"y":12,"w":52,"h":52,"tone":"main"},{"t":"rect","x":42,"y":39,"w":25,"h":25,"tone":"danger","fill":true},{"t":"text","x":54.5,"y":51,"text":"b²","size":3.8,"anchor":"middle","tone":"danger"},{"t":"text","x":30,"y":30,"text":"a²-b²","size":4,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":15,"y1":70,"x2":67,"y2":70,"both":true,"tone":"main","label":"a","labelDy":7},{"t":"arrow","x1":72,"y1":39,"x2":72,"y2":64,"both":true,"tone":"danger","label":"b","labelDx":6},{"t":"text","x":50,"y":90,"text":"a²-b² = (a+b)(a-b)","size":3.8,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"公式要求两项都是平方且相减；a²+b² 是有理数范围内的平方和，不能再分解。"},{"type":"h","text":"三十字：把常数项拆成两数之积"},{"type":"p","text":"因为 (x+p)(x+q)=x²+(p+q)x+pq，所以分解 x²+5x+6 就是反过来找两个数：它们的积等于常数项 6，和等于一次项系数 5。十字相乘只是把「拆积、验和」这件事排成两列一交叉，让试算看得见而已。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-s3","title":"十字相乘：拆常数项、验两项和","caption":"x²+5x+6 = (x+2)(x+3)，2×3=6 且 2+3=5","view":"square","alt":"十字相乘示意图，左上写 x、右上写正 2，左下写 x、右下写正 3，两条斜线交叉，右侧标注 x 乘 3 得 3x、x 乘 2 得 2x，相加得 5x 恰好等于一次项系数，下方写出分解结果 x 加 2 乘以 x 加 3","prims":[{"t":"text","x":28,"y":32,"text":"x","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":58,"y":32,"text":"2","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":28,"y":70,"text":"x","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":58,"y":70,"text":"3","size":5,"anchor":"middle","tone":"main"},{"t":"line","x1":33,"y1":37,"x2":53,"y2":65,"tone":"accent","width":1.5},{"t":"line","x1":53,"y1":37,"x2":33,"y2":65,"tone":"accent","width":1.5},{"t":"text","x":76,"y":42,"text":"x·3=3x","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":76,"y":56,"text":"x·2=2x","size":3.4,"anchor":"middle","tone":"ok"},{"t":"line","x1":10,"y1":80,"x2":84,"y2":80,"tone":"muted"},{"t":"text","x":45,"y":89,"text":"3x+2x = 5x ✓","size":4,"anchor":"middle","tone":"ok"},{"t":"text","x":45,"y":97,"text":"(x+2)(x+3)","size":4.2,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"试几次不成功很正常，关键是每次都要验算交叉相乘之和；二次项系数不为 1 时，拆的是二次项与常数项两个方向。"},{"type":"h","text":"换个方向：因式分解与整式乘法互为逆运算"},{"type":"p","text":"把 (x+2)(x-2) 展开成 x²-4 是整式乘法，把 x²-4 写回乘积则是因式分解，两者走的是同一条路、方向相反。正因如此，「分解对不对」只要乘回去就能验；也正是这个方向性，决定了「必须分解到不能再分解」——只要某个因式还能写成乘积，就说明这条路还没走到底。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-s4","title":"乘开与分解：同一条路，两个方向","caption":"整式乘法把积展开成多项式，因式分解把多项式写回积","view":"square","alt":"上下两个方框，上方方框里写积 x 加 2 乘以 x 减 2，下方方框里写多项式 x 平方减 4，左侧箭头向上标注因式分解，右侧箭头向下标注整式乘法，底部说明两者互为逆运算","prims":[{"t":"rect","x":25,"y":10,"w":50,"h":20,"tone":"accent","fill":true},{"t":"text","x":50,"y":20,"text":"积：(x+2)(x-2)","size":3.6,"anchor":"middle","tone":"accent"},{"t":"rect","x":25,"y":70,"w":50,"h":20,"tone":"main","fill":true},{"t":"text","x":50,"y":80,"text":"多项式：x²-4","size":3.6,"anchor":"middle","tone":"main"},{"t":"arrow","x1":40,"y1":32,"x2":40,"y2":68,"tone":"main","width":1.2},{"t":"arrow","x1":60,"y1":68,"x2":60,"y2":32,"tone":"accent","width":1.2},{"t":"text","x":32,"y":50,"text":"整式乘法","size":3.4,"anchor":"end","tone":"main"},{"t":"text","x":68,"y":50,"text":"因式分解","size":3.4,"anchor":"start","tone":"accent"},{"t":"text","x":50,"y":96,"text":"两者互为逆运算","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"检验两法：把结果乘开看是否还原；或给字母取简单数值代入原式与分解式，两者数值相等则基本正确。"},{"type":"h","text":"核心概念"},{"type":"p","text":"因式分解的意义：把一个多项式化成几个整式的积的形式，叫做把这个多项式因式分解（也叫分解因式）。它与整式乘法互为逆运算，例如 (x+2)(x-2)=x²-4 是乘法，x²-4=(x+2)(x-2) 则是因式分解。关键点：结果必须是乘积形式。"},{"type":"p","text":"提公因式法：如果多项式的各项都含有公因式，就把它提取到括号外面，写成公因式与另一个因式的积。公因式的系数取各项系数的最大公约数，字母取各项都含有的字母的最低次幂。关键点：某项被全部提出后括号里要补上 1。"},{"type":"p","text":"公式法：利用平方差公式 a²-b²=(a+b)(a-b) 与完全平方公式 a²± 2ab+b²=(a± b)² 把多项式分解。关键点：两项且是平方差用平方差公式，三项且首尾都是平方、中间是两数积的 2 倍用完全平方公式。"},{"type":"p","text":"十字相乘法：对于二次三项式 x²+(p+q)x+pq，可分解为 (x+p)(x+q)，即把常数项分成两个因数、检验它们的和是否等于一次项系数。二次项系数不为 1 时也可用十字相乘，如 2x²-5x-3=(2x+1)(x-3)。"},{"type":"p","text":"分组分解法：项数较多时，可把多项式适当分组，各组分别提取公因式或套用公式，再整体提取公因式。如 x²-y²+x-y=(x+y)(x-y)+(x-y)=(x-y)(x+y+1)。关键点：分组后要能继续提出公因式。"},{"type":"p","text":"立方和与立方差公式：a³+b³=(a+b)(a²-ab+b²)，a³-b³=(a-b)(a²+ab+b²)。关键点：两个公式的第二个因式分别是 a²-ab+b² 与 a²+ab+b²，中间项的符号与第一个因式中的符号相反，最容易记错。"},{"type":"p","text":"因式分解的一般步骤：一提（先提公因式）、二套（套用公式）、三十字（二次三项式试十字相乘）、四分组（项数多时分组）。最后检查每个因式是否还能继续分解，必须分解到不能再分解为止。"},{"type":"note","title":"中考考法","text":"四种基本方法的选择与综合使用\n直接给多项式要求分解，踩分点是按「一提二套三十字四分组」的顺序，先提公因式，三项看完全平方、两项看平方差，分解必须彻底。"},{"type":"note","title":"中考考法","text":"因式分解正误的辨析\n选择题判断分解是否正确、是否彻底，踩分点是把结果乘回原式检验，警惕平方和不能分解、中间项漏系数等典型错误。"},{"type":"note","title":"中考考法","text":"利用因式分解进行简便计算与求值\n把大数字运算改造成平方差、完全平方结构，或整体代入求值，踩分点是先识别两数和、两数积的结构，再用公式一步得出结果。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["提公因式法","ma+mb+mc=m(a+b+c)","公因式是各项都含有的因式；某一项被整体提出后括号内要留 1，如 a²-a=a(a-1)。"],["平方差公式（分解方向）","a²-b²=(a+b)(a-b)","要求两项都是平方且相减；a²+b² 在有理数范围内不能分解。"],["完全平方公式（分解方向）","a²± 2ab+b²=(a± b)²","三项式，首尾两项都是平方且符号相同，中间项的绝对值必须是 2ab。"],["十字相乘法","x²+(p+q)x+pq=(x+p)(x+q)","把常数项分解成两个因数 p、q，验证 p+q 是否等于一次项系数；二次项系数不为 1 时同样可十字相乘。"],["立方和公式","a³+b³=(a+b)(a²-ab+b²)","第二个因式中间项是 -ab，符号与前面 (a+b) 中的符号相反。"],["立方差公式","a³-b³=(a-b)(a²+ab+b²)","如 8a³-b³=(2a-b)(4a²+2ab+b²)，注意 8a³=(2a)³，要把 2a 整体代入公式。"]]},{"type":"note","title":"例题","text":"把 3x²-12xy+12y² 因式分解。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-e1","title":"先提公因式 3，再套完全平方","caption":"3x²-12xy+12y² = 3(x²-4xy+4y²) = 3(x-2y)²","view":"square","alt":"两步分解流程图，原式 3x 平方减 12xy 加 12y 平方，第一步提出公因式 3 得到 3 乘以括号 x 平方减 4xy 加 4y 平方，逐个标注首项、中间项与尾项，第二步套完全平方公式得到 3 乘以 x 减 2y 的平方","prims":[{"t":"text","x":50,"y":12,"text":"3x² - 12xy + 12y²","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":30,"text":"① 提公因式 3","size":3.8,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":44,"text":"3( x² - 4xy + 4y² )","size":4.6,"anchor":"middle","tone":"main"},{"t":"text","x":28,"y":58,"text":"首 x²","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":58,"text":"中 -2·x·2y","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":72,"y":58,"text":"尾 (2y)²","size":3.2,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":74,"text":"② 套完全平方公式","size":3.8,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":90,"text":"3(x-2y)²","size":5,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["先找公因式：三项系数的最大公约数是 3，字母方面每一项都含有的公共字母没有（x²、xy、y² 中字母不同），所以公因式是 3。","提取公因式：3x²-12xy+12y²=3(x²-4xy+4y²)。","观察括号内三项：x² 与 4y²=(2y)² 都是平方，中间项 -4xy=-2· x· 2y，符合完全平方公式。","套用完全平方公式：x²-4xy+4y²=(x-2y)²。","所以原式 =3(x-2y)²，因式均已分解到位。"]},{"type":"p","text":"答案：3(x-2y)²"},{"type":"note","title":"方法小结","text":"本题两次用到「提公因式」和「套公式」，顺序不能颠倒。若一开始就套公式会因系数 3、12、12 而看不出完全平方结构。检验：3(x-2y)²=3(x²-4xy+4y²)=3x²-12xy+12y²，与原式一致。"},{"type":"note","title":"例题","text":"把 2x²-5x-3 因式分解。"},{"type":"figure","figure":{"id":"fig-m-num-yinshifenjie-shizi-1","title":"十字相乘：交叉求和等于一次项","caption":"2x²−5x−3 = (2x+1)(x−3)","view":"square","alt":"十字相乘分解图，左上写 2x、右上写 1，左下写 x、右下写负 3，两条对角线交叉连接，标注交叉相乘的积为 x 和负 6x，相加得负 5x 恰好等于一次项","prims":[{"t":"text","x":30,"y":30,"text":"2x","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":60,"y":30,"text":"1","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":30,"y":70,"text":"x","size":5,"anchor":"middle","tone":"main"},{"t":"text","x":60,"y":70,"text":"-3","size":5,"anchor":"middle","tone":"main"},{"t":"line","x1":34,"y1":34,"x2":56,"y2":66,"tone":"accent","width":1.5},{"t":"line","x1":56,"y1":34,"x2":34,"y2":66,"tone":"accent","width":1.5},{"t":"text","x":72,"y":40,"text":"2x·(-3)=-6x","size":3.4,"tone":"danger"},{"t":"text","x":72,"y":50,"text":"x·1=x","size":3.4,"tone":"ok"},{"t":"line","x1":12,"y1":80,"x2":78,"y2":80,"tone":"muted"},{"t":"text","x":45,"y":90,"text":"交叉和：x + (-6x) = -5x  ✓","size":4,"tone":"ok","anchor":"middle"},{"t":"text","x":45,"y":98,"text":"(2x+1)(x−3)","size":4.2,"tone":"accent","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["这是二次项系数不为 1 的二次三项式，试用十字相乘。","把二次项 2x² 分为 2x 与 x；把常数项 -3 分为 1 与 -3（也可试其他分解）。","交叉相乘检验：(2x 与 1) 得 2x，(x 与 -3) 得 -3x，两者之和为 2x-3x=-x，不等于 -5x，此分解不合适。","换一种分解：常数项分为 +1 与 -3 不变，改为 (2x 与 -3)、(x 与 +1)：交叉相乘得 -3x 与 2x，和为 -x，仍不合适。","再试：把常数项分为 -3 与 +1 并交换位置，改用 (2x+1)(x-3)：交叉相乘得 1· x=x 与 2x·(-3)=-6x，和为 x-6x=-5x，恰好等于一次项系数。","所以 2x²-5x-3=(2x+1)(x-3)。"]},{"type":"p","text":"答案：(2x+1)(x-3)"},{"type":"note","title":"方法小结","text":"十字相乘试几次不成功很正常，关键是每次都要验算交叉相乘之和。检验：展开 (2x+1)(x-3)=2x²-6x+x-3=2x²-5x-3，正确。"},{"type":"note","title":"例题","text":"把 x²-y²+x-y 因式分解。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-e3","title":"两种分组，只有一种能继续分解","caption":"按 (x²-y²)+(x-y) 分组能提出 (x-y)，另一种分法走不下去","view":"square","alt":"左右两个虚线框对比两种分组方式，左边把前两项与后两项分组，用平方差分解后提出公因式 x 减 y 得到 x 减 y 乘以 x 加 y 加 1，右边把第一三项与第二四项分组得到 x 乘以 x 加 1 减 y 乘以 y 加 1，两组没有公共因式无法继续分解","prims":[{"t":"rect","x":6,"y":18,"w":42,"h":50,"tone":"ok","dashed":true},{"t":"rect","x":52,"y":18,"w":42,"h":50,"tone":"danger","dashed":true},{"t":"text","x":27,"y":27,"text":"(x²-y²)+(x-y)","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":27,"y":41,"text":"=(x+y)(x-y)+(x-y)","size":3,"anchor":"middle","tone":"ok"},{"t":"text","x":27,"y":55,"text":"=(x-y)(x+y+1)","size":3.4,"anchor":"middle","tone":"ok"},{"t":"text","x":27,"y":64,"text":"✓ 能提出公因式","size":3.2,"anchor":"middle","tone":"ok"},{"t":"text","x":73,"y":27,"text":"(x²+x)+(-y²-y)","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":73,"y":41,"text":"=x(x+1)-y(y+1)","size":3,"anchor":"middle","tone":"danger"},{"t":"text","x":73,"y":55,"text":"无公共因式","size":3.4,"anchor":"middle","tone":"danger"},{"t":"text","x":73,"y":64,"text":"✗ 分不下去","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":84,"text":"分组要保证两组出现相同因式","size":3.4,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["这是四项式，考虑分组分解。把前两项分为一组，后两项分为一组：(x²-y²)+(x-y)。","第一组用平方差公式：x²-y²=(x+y)(x-y)。","第二组是 x-y，可看作 1·(x-y)。","于是原式 =(x+y)(x-y)+(x-y)。","整体提取公因式 (x-y)：(x-y)[(x+y)+1]=(x-y)(x+y+1)。","检验：展开 (x-y)(x+y+1)=(x²-y²)+(x-y)=x²-y²+x-y，与原式一致，分解正确。"]},{"type":"p","text":"答案：(x-y)(x+y+1)"},{"type":"note","title":"方法小结","text":"分组分解的关键是「分组后能继续提出公因式」。若按 (x²+x)+(-y²-y) 分组，得 x(x+1)-y(y+1)，无法继续分解，说明分组方式不佳，应换一种分法重试。"},{"type":"note","title":"例题","text":"把下列各式因式分解：（1）8a³+27b³；（2）x⁴-16。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-e4","title":"高次平方差要分解到底","caption":"x⁴-16=(x²+4)(x²-4)=(x²+4)(x+2)(x-2)","view":"square","alt":"竖向分解流程，x 的四次方减 16 先写成 x 平方的平方减 4 的平方，用平方差分解为 x 平方加 4 乘以 x 平方减 4，其中 x 平方减 4 还能继续分解为 x 加 2 乘以 x 减 2，而 x 平方加 4 是平方和不能再分，底部给出 8a 立方加 27b 立方的分解结果","prims":[{"t":"text","x":50,"y":10,"text":"x⁴ - 16 连续分解","size":4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":26,"text":"(x²)² - 4²","size":4.2,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":32,"x2":50,"y2":40,"tone":"muted"},{"t":"text","x":44,"y":48,"text":"(x²+4)(x²-4)","size":4.2,"anchor":"middle","tone":"main"},{"t":"text","x":76,"y":48,"text":"x²-4 还能分","size":3.1,"anchor":"middle","tone":"danger"},{"t":"arrow","x1":50,"y1":54,"x2":50,"y2":62,"tone":"muted"},{"t":"text","x":50,"y":70,"text":"(x²+4)(x+2)(x-2)","size":4.4,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":84,"text":"x²+4 是平方和，不能再分","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":95,"text":"8a³+27b³=(2a+3b)(4a²-6ab+9b²)","size":3.2,"anchor":"middle","tone":"main"}]}},{"type":"list","title":"解题步骤","items":["第（1）问是两个立方的和，想到立方和公式：8a³=(2a)³，27b³=(3b)³。","套 A³+B³=(A+B)(A²-AB+B²)：原式 =(2a+3b)[(2a)²-2a· 3b+(3b)²]=(2a+3b)(4a²-6ab+9b²)。","第（2）问连续两次用平方差：x⁴-16=(x²)²-4²=(x²+4)(x²-4)。","其中 x²-4 还能继续分解为 (x+2)(x-2)，而 x²+4 是平方和、不能再分，故原式 =(x²+4)(x+2)(x-2)。"]},{"type":"p","text":"答案：（1）(2a+3b)(4a²-6ab+9b²)；（2）(x²+4)(x+2)(x-2)"},{"type":"note","title":"方法小结","text":"立方公式的第二个因式中间项符号与第一个因式相反，且不再继续分解。高次平方差用完一次公式后要再检查每个因式：x²-4 仍是平方差，漏掉这一步就是「分解不彻底」的典型失分。"},{"type":"note","title":"例题","text":"利用因式分解简便计算：（1）57²+2× 57× 43+43²；（2）2025²-2024× 2026。"},{"type":"figure","figure":{"id":"fig-yinshifenjie-e5","title":"看准结构再动笔","caption":"左栏三项是完全平方，右栏两个因数关于 2025 对称可套平方差","view":"square","alt":"左右两栏简便计算，左栏三个数呈首平方、积的两倍、尾平方的结构，套完全平方公式化为 57 加 43 的平方等于 100 的平方即一万；右栏两个因数关于 2025 对称，写成 2025 减 1 乘以 2025 加 1 等于 2025 的平方减 1，与原式相减结果为 1","prims":[{"t":"rect","x":6,"y":14,"w":42,"h":72,"tone":"accent","dashed":true},{"t":"text","x":27,"y":26,"text":"57²+2·57·43+43²","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":27,"y":40,"text":"首平方+积的两倍+尾平方","size":2.9,"anchor":"middle","tone":"muted"},{"t":"text","x":27,"y":56,"text":"=(57+43)²","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":27,"y":72,"text":"=100²=10000","size":3.8,"anchor":"middle","tone":"ok"},{"t":"rect","x":52,"y":14,"w":42,"h":72,"tone":"ok","dashed":true},{"t":"text","x":73,"y":26,"text":"2025²-2024×2026","size":3.2,"anchor":"middle","tone":"ok"},{"t":"text","x":73,"y":40,"text":"两数关于 2025 对称","size":2.9,"anchor":"middle","tone":"muted"},{"t":"text","x":73,"y":56,"text":"=2025²-(2025²-1)","size":3,"anchor":"middle","tone":"main"},{"t":"text","x":73,"y":72,"text":"=1","size":3.8,"anchor":"middle","tone":"ok"},{"t":"text","x":50,"y":95,"text":"先看结构，再动笔算","size":3.5,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["第（1）问的三项恰好是「首平方、尾平方、积的两倍在中央」，想到完全平方公式：原式 =(57+43)²=100²=10000。","第（2）问后两个因数关于 2025 对称，想到把它们写成平方差结构：2024× 2026=(2025-1)(2025+1)=2025²-1。","代入原式：2025²-(2025²-1)=1。","检验第（2）问：2024× 2026=4100624，2025²=4100625，相差 1，正确。"]},{"type":"p","text":"答案：（1）10000；（2）1"},{"type":"note","title":"方法小结","text":"大数字混合运算先别急着硬乘，观察数字之间的和、差关系：三个数呈完全平方结构就套完全平方，两个数关于某数对称就套平方差。这正是因式分解在计算中的直接应用。"},{"type":"list","title":"易错点","items":["分解不彻底，如 $3x^{2}-12xy+12y^{2}=3(x^{2}-4xy+4y^{2})$ 就停笔，未继续分解为 $3(x-2y)^{2}$；又如 $x^{4}-16=(x^{2}+4)(x^{2}-4)$ 漏掉 $x^{2}-4=(x+2)(x-2)$。","提公因式时漏掉 1，如把 $a^{2}-a$ 写成 $a\\cdot a$，或把 $a^{2}-a$ 写成 $a(a)$。正确结果是 $a(a-1)$。","把 $a^{2}+b^{2}$ 分解成 $(a+b)^{2}$。$a^{2}+b^{2}$ 在有理数范围内不能分解，两者相差 $2ab$。","十字相乘时只管常数项的分解、不验算交叉相乘之和，结果一次项系数对不上，如把 $x^{2}-5x+6$ 分解成 $(x+2)(x+3)$（展开是 $x^{2}+5x+6$）。","完全平方公式的中间项符号写错，如把 $x^{2}-6x+9$ 分解成 $(x+3)^{2}$。正确结果是 $(x-3)^{2}$。","立方和、立方差公式的第二个因式记错，把 $a^{3}-b^{3}$ 分解成 $(a-b)(a^{2}-ab+b^{2})$。正确结果是 $(a-b)(a^{2}+ab+b^{2})$，中间项符号与第一个因式相反。"]},{"type":"list","title":"解题方法","items":["分解顺序「一提二套三十字四分组」：先看有没有公因式，再看是否符合公式，二次三项式试十字相乘，四项及以上考虑分组。","十字相乘试根技巧：把常数项的所有分解与二次项的分解组合起来，只验算交叉相乘之和是否等于一次项系数，命中即用。","整体思想：把重复出现的整式（如 x+y）看成一个整体，能直接套用公式或提取公因式，如把 (a+b)²-4(a+b)+4 看作关于 (a+b) 的完全平方式。","检验两法：把分解结果乘开看是否还原；或给字母取简单数值（如 x=1）代入原式与分解式，两者数值相等则基本正确。","换元法处理高次或复杂结构：设 t=x² 把四次式化为二次式分解，再回代继续分解。"]}],"questions":[{"id":"m-num-yinshifenjie-q1","type":"choice","stem":"下列因式分解正确的是（ ）","answer":"A","explain":"A 正确：x²+4x+4 中首项 x²、末项 4=2² 都是平方，中间项 4x=2· x· 2，符合完全平方公式，分解为 (x+2)²。B 错：(x-4)(x+4)=x²-16≠ x²-4。C 错：(x-1)(x+1)=x²-1，与原式 x²-2x+1=(x-1)² 不符。D 错：x²+4 不能分解，且 (x+2)²=x²+4x+4。","options":["x²+4x+4=(x+2)²","x²-4=(x-4)(x+4)","x²-2x+1=(x-1)(x+1)","x²+4=(x+2)²"],"difficulty":1,"tags":["因式分解","公式法","辨析"]},{"id":"m-num-yinshifenjie-q2","type":"choice","stem":"把 x²-5x-6 因式分解，结果是（ ）","answer":"B","explain":"常数项 -6 分解为两个因数，要求它们的和为 -5。取 -6 与 +1：(-6)× 1=-6，(-6)+1=-5，符合，故 x²-5x-6=(x-6)(x+1)。检验：展开得 x²+x-6x-6=x²-5x-6。A 为 x²-5x+6，C 为 x²+5x-6，D 为 x²-x-6，都不符。","options":["(x-2)(x-3)","(x-6)(x+1)","(x+6)(x-1)","(x-3)(x+2)"],"difficulty":1,"tags":["十字相乘","因式分解"]},{"id":"m-num-yinshifenjie-q3","type":"fill","stem":"把 3a²-6a 因式分解，结果是（ ）。","answer":"3a(a-2)","explain":"公因式的系数取 3 与 6 的最大公约数 3，字母取各项都含有的 a 的最低次幂 a，故公因式是 3a。提取后 3a²÷ 3a=a，6a÷ 3a=2，所以 3a²-6a=3a(a-2)。检验：3a(a-2)=3a²-6a，与原式一致。","difficulty":1,"tags":["提公因式","因式分解"]},{"id":"m-num-yinshifenjie-q4","type":"fill","stem":"把 x²-9y² 因式分解，结果是（ ）。","answer":"(x+3y)(x-3y)","explain":"把两项都写成平方形式：x²-9y²=x²-(3y)²，符合平方差公式。于是 x²-(3y)²=(x+3y)(x-3y)。检验：展开得 x²-3xy+3xy-9y²=x²-9y²，正确。注意 9y² 的平方根是 3y 而不是 3，这是本题的关键。","difficulty":2,"tags":["平方差公式","因式分解"]},{"id":"m-num-yinshifenjie-q5","type":"short","stem":"已知 a²-b²=12，且 a+b=4，利用因式分解求 a-b 的值，并进一步求出 a 与 b 的值。","answer":"由 $a^{2}-b^{2}=(a+b)(a-b)$ 得 $12=4(a-b)$，所以 $a-b=3$；再由 $a+b=4$、$a-b=3$ 解得 $a=\\frac{7}{2}$，$b=\\frac{1}{2}$。","explain":"第一步用平方差公式把 a²-b² 分解为 (a+b)(a-b)，于是 12=(a+b)(a-b)。把 a+b=4 代入得 12=4(a-b)，两边同除以 4 得 a-b=3。第二步把 a+b=4 与 a-b=3 相加：2a=7，所以 a=(7)/(2)；把 a=(7)/(2) 代入 a+b=4 得 b=4-(7)/(2)=(1)/(2)。检验：a+b=(7)/(2)+(1)/(2)=4，a²-b²=((7)/(2))²-((1)/(2))²=(49)/(4)-(1)/(4)=(48)/(4)=12，完全符合。","difficulty":3,"tags":["平方差公式","因式分解应用","整体代入"],"rubric":["写出 a²-b²=(a+b)(a-b) 这一恒等变形","代入已知条件得 12=4(a-b)，求出 a-b=3","由 a+b=4 与 a-b=3 解出 a=(7)/(2)、b=(1)/(2)（写成 3.5 与 0.5 同样给分）","有检验过程，步骤完整"]},{"id":"m-num-yinshifenjie-z1","type":"choice","stem":"把 a³b-ab³ 因式分解，正确的结果是（ ）","answer":"D","explain":"先提公因式：a³b-ab³=ab(a²-b²)；括号内仍是平方差，必须继续分解：a²-b²=(a+b)(a-b)。故最终结果为 ab(a+b)(a-b)，选 D。A 项分解不彻底，B、C 项展开后分别为 a³b-2a²b²+ab³ 等，与原式不符。","options":["ab(a²-b²)","ab(a-b)²","ab(a+b)²","ab(a+b)(a-b)"],"difficulty":2,"tags":["提公因式","平方差公式","因式分解"]},{"id":"m-num-yinshifenjie-z2","type":"fill","stem":"因式分解：x²(x-2)+9(2-x)=（ ）。","answer":"(x-2)(x+3)(x-3)|(x-2)(x-3)(x+3)","explain":"注意 2-x=-(x-2)，原式化为 x²(x-2)-9(x-2)。提取公因式 (x-2)：(x-2)(x²-9)，再用平方差公式继续分解 x²-9=(x+3)(x-3)，故原式 =(x-2)(x+3)(x-3)。检验：取 x=1，原式 =1×(-1)+9× 1=8，分解式 =(-1)× 4×(-2)=8，一致。","difficulty":3,"tags":["提公因式","平方差公式","因式分解"]}]},{"id":"m-num-jisuan-yiucuo","title":"代数运算易错总攻","subtitle":"人教版初中 · 代数运算","grade":"all","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版初中 · 代数运算"},{"type":"note","title":"一句话概述","text":"汇总初中代数运算的符号、取值、检验三类高频错误，建立自查习惯，减少无谓失分。"},{"type":"h","text":"先看符号：负号归不归乘方管"},{"type":"p","text":"(-2)² 与 -2² 长得像，意思却完全不同：括号把负号也圈进了乘方，所以 (-2)²=(-2)×(-2)=4；而 -2² 的负号站在乘方外面，表示 2² 的相反数，等于 -4。动笔前先问一句「这个负号被乘方管着吗」，符号定了数值才定。"},{"type":"figure","figure":{"id":"fig-jisuan-s1","title":"负号在括号内还是括号外","caption":"(-2)²=4 而 -2²=-4，差别就在负号归不归乘方管","view":"square","alt":"左右两个虚线框对比，左边写括号负 2 的平方，说明负号参与乘方得 4；右边写负的 2 的平方，说明负号在括号外只是求相反数得负 4，底部提醒看到负号先问它是否被乘方管着","prims":[{"t":"text","x":50,"y":10,"text":"负号在括号内外，结果完全不同","size":3.4,"anchor":"middle","tone":"muted"},{"t":"rect","x":6,"y":20,"w":42,"h":44,"tone":"ok","dashed":true},{"t":"text","x":27,"y":32,"text":"(-2)²","size":5,"anchor":"middle","tone":"ok"},{"t":"text","x":27,"y":46,"text":"(-2)×(-2)","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":27,"y":58,"text":"= 4","size":4.2,"anchor":"middle","tone":"ok"},{"t":"rect","x":52,"y":20,"w":42,"h":44,"tone":"danger","dashed":true},{"t":"text","x":73,"y":32,"text":"-2²","size":5,"anchor":"middle","tone":"danger"},{"t":"text","x":73,"y":46,"text":"-(2×2)","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":73,"y":58,"text":"= -4","size":4.2,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":78,"text":"看到负号先问：它是否被乘方管着？","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":92,"text":"负数偶次幂为正，奇次幂为负","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"括号内偶次幂得正（(-2)²=4），奇次幂得负（(-2)³=-8）；括号外只是求相反数，与次数无关。"},{"type":"h","text":"抓变形：括号前是负号要逐项反号"},{"type":"p","text":"去括号的依据是分配律：-(a-2b+3)=-1×(a-2b+3)，负号乘进去，括号里每一项都要反号，得到 -a+2b-3。它和「移项」不是一回事——移项只把跨过等号的那一项变号，其它项原样不动，拿一句口诀套三种变形是失分的根源。"},{"type":"figure","figure":{"id":"fig-jisuan-s2","title":"括号前是负号，括号里逐项反号","caption":"-(a-2b+3) = -a+2b-3，三项同时变号","view":"square","alt":"上方写括号前带负号的式子负的 a 减 2b 加 3，三条箭头分别指向下一行的负 a 加 2b 减 3，说明括号内每一项都反号，底部对比说明前面是正号时括号内各项不变号","prims":[{"t":"text","x":50,"y":12,"text":"括号前是负号：每一项都变号","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":32,"text":"-(a - 2b + 3)","size":5,"anchor":"middle","tone":"main"},{"t":"arrow","x1":41,"y1":38,"x2":39,"y2":48,"tone":"danger","width":1.1},{"t":"arrow","x1":49,"y1":38,"x2":50,"y2":48,"tone":"danger","width":1.1},{"t":"arrow","x1":58,"y1":38,"x2":59,"y2":48,"tone":"danger","width":1.1},{"t":"text","x":50,"y":58,"text":"-a + 2b - 3","size":5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":76,"text":"对比：+(a-2b+3) = a-2b+3 不变号","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":90,"text":"去括号逐项变号，移项只动被移的那一项","size":3.2,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"去掉括号后要数一数项数是否和原来一致：三项进去必须三项出来，少一项就说明漏了。"},{"type":"h","text":"建立关系：移项就是两边同时加或减"},{"type":"p","text":"解 x+3=7 时把 3 移到右边写成 x=7-3，本质是等式两边同时减去 3：左边 x+3-3=x，右边 7-3。所以「移项变号」不是硬背的规矩，而是「两边同时做同一件事」的结果——也正因如此，只有被移动的那一项需要变号，其它项不受影响。"},{"type":"figure","figure":{"id":"fig-jisuan-s3","title":"移项的依据是两边同时加减","caption":"x+3=7 两边同时减 3，得 x=7-3=4","view":"square","alt":"上行写方程 x 加 3 等于 7，一条箭头指向下行，标注 3 移过去变成负 3，下行写 x 等于 7 减 3 等于 4，底部说明只把移动的那一项变号而其它项不动，并对比移项、去括号、去分母三种变形","prims":[{"t":"text","x":50,"y":12,"text":"移项：跨过等号的项要变号","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":30,"text":"x + 3 = 7","size":5.5,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":38,"x2":50,"y2":52,"tone":"accent","width":1.2,"label":"3 移过去变 -3","labelDx":25},{"t":"text","x":50,"y":66,"text":"x = 7 - 3 = 4","size":5.5,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":82,"text":"只把移动的那一项变号，其它项不动","size":3.3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":94,"text":"移项变号 · 去括号逐项变号 · 去分母两边同乘","size":3.1,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"移项与去括号都会出现「变号」，但对象不同：移项只动搬家的那一项，去括号是括号内每一项都动。"},{"type":"h","text":"换个情境：算完还要收尾检查"},{"type":"p","text":"会算不等于答对：分式要化到最简，取值范围要按「分母不为 0、根号内非负」提前标出，解完方程要把根代回去（分式方程还要验增根），应用题还要按实际意义取舍。把这三步做成固定动作，就能挡住大部分「会做却丢分」的情况。"},{"type":"figure","figure":{"id":"fig-jisuan-s4","title":"收尾三查：化简、取值、检验","caption":"算完别急着写答案，三关都过一遍再落笔","view":"square","alt":"三个虚线方框并排，分别写化简约到最简、取值分母不为 0、检验代回验证，下方用双箭头连成一个整体并注明算完别急着写答案，底部强调漏检验等于白算","prims":[{"t":"text","x":50,"y":10,"text":"算式收尾三查","size":4.2,"anchor":"middle","tone":"accent"},{"t":"rect","x":8,"y":20,"w":26,"h":40,"tone":"main","dashed":true},{"t":"text","x":21,"y":34,"text":"化简","size":3.8,"anchor":"middle","tone":"main"},{"t":"text","x":21,"y":48,"text":"约到最简","size":3.2,"anchor":"middle","tone":"muted"},{"t":"rect","x":37,"y":20,"w":26,"h":40,"tone":"accent","dashed":true},{"t":"text","x":50,"y":34,"text":"取值","size":3.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":48,"text":"分母不为 0","size":3.2,"anchor":"middle","tone":"muted"},{"t":"rect","x":66,"y":20,"w":26,"h":40,"tone":"ok","dashed":true},{"t":"text","x":79,"y":34,"text":"检验","size":3.8,"anchor":"middle","tone":"ok"},{"t":"text","x":79,"y":48,"text":"代回验证","size":3.2,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":21,"y1":70,"x2":79,"y2":70,"both":true,"tone":"muted","label":"算完别急着写答案","labelDy":9},{"t":"text","x":50,"y":90,"text":"漏检验 = 白算","size":4,"anchor":"middle","tone":"danger"}]}},{"type":"note","title":"","text":"应用题的结果要放回情境判断：长度不能为负、人数必须是正整数，不符合实际的根一律舍去并说明理由。"},{"type":"h","text":"核心概念"},{"type":"p","text":"符号意识：代数运算中的负号、括号、指数都携带符号信息：-2²=-4 而 (-2)²=4；去括号时括号前是负号要各项变号；乘方要看负号是否在括号内。关键点：动笔前先把符号标清楚。"},{"type":"p","text":"运算顺序与括号：先乘方，再乘除，最后加减；同级运算从左到右；有括号先算括号内。关键点：分数线同时具有除号和括号的作用，如 (a+b)/(c) 的分子必须先算好再除。"},{"type":"p","text":"等式与不等式性质的区分：等式两边乘（除）同一个非零数，等式仍然成立；而不等式两边乘（除）同一个负数时，不等号方向必须改变。关键点：解不等式的最后一步若除以负数，立刻把不等号反向。"},{"type":"p","text":"取值范围的检查意识：三类常见限制：分母不为 0、二次根式的被开方数不小于 0、一元二次方程与二次函数的二次项系数不为 0。关键点：题目给出的条件常常就藏在「有意义」「是一元二次方程」这些字眼里。"},{"type":"p","text":"检验意识：解方程后要检验：分式方程必须把根代入最简公分母，排除增根；应用题要把结果放回实际情境判断是否合理，如长度不能为负、人数必须是正整数。"},{"type":"p","text":"结果的规范表达：化简要彻底（分式约到最简、二次根式化成最简二次根式、因式分解分解到底），答案要写完整（多解不能丢根，实际问题要带单位并作答）。关键点：过程分往往就藏在这些规范里。"},{"type":"note","title":"中考考法","text":"符号、乘方与运算顺序的辨析\n选择题判断 -a² 与 (-a)²、负指数幂、去括号变号等是否正确，踩分点是先定符号再算数值，分数线兼具括号作用。"},{"type":"note","title":"中考考法","text":"取值范围与含参方程的限制条件\n分式、二次根式有意义的条件，含参一元二次方程要同时保证二次项系数不为 0，踩分点是多个限制取交集、判别式先于韦达定理。"},{"type":"note","title":"中考考法","text":"解方程（组）、不等式后的检验与规范作答\n分式方程验增根、开平方防漏解、实际问题按实际意义取舍，踩分点是变号、端点、整数解写全，结果化简彻底并带单位作答。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["运算顺序","先乘方，再乘除，最后加减；有括号先算括号内，同级运算从左到右。","分数线的括号作用常被忽略，如 (1)/(2)+(1)/(2)× 2 应先算乘法得 (1)/(2)+1=(3)/(2)。"],["乘方中的符号","(-a)²=a², (-a)³=-a³, -a²=-(a²)","负号在括号内时参与乘方，在括号外时只是求相反数：(-2)²=4，-2²=-4。"],["绝对值与正负判断","|a|=cases a & (a≥ 0) \\\\ -a & (a<0) endcases","去绝对值前必须先判断被减数与减数的大小，如 |√(2)-2|=2-√(2)、|a-3| 需对 a 分类讨论。"],["零指数幂与负整数指数幂","a⁰=1\\ (a≠ 0), a^(-n)=1a^(n)\\ (a≠ 0)","底数不能为 0；((1)/(2))^(-1)=2，(-1)²⁰²⁶=1（偶次幂），(-1)²⁰²⁵=-1（奇次幂）。"],["分式方程的检验条件","把去分母后整式方程的根代入最简公分母，公分母不为 0 才是原方程的根，为 0 的是增根必须舍去。","若整式方程的根使公分母为 0（且无其他根），则原分式方程无解，不能把该根写进答案。"]]},{"type":"note","title":"例题","text":"计算：(-2)²-2²+(-(1)/(2))^(-2)。"},{"type":"figure","figure":{"id":"fig-jisuan-e1","title":"逐项定符号，最后再合并","caption":"(-2)²=4、-2²=-4、(-1/2)⁻²=4，三项相加得 4","view":"square","alt":"三个虚线方框并排，第一框写括号负 2 的平方，因负号参与乘方得 4；第二框写负的 2 的平方，是 2 的平方的相反数得负 4；第三框写括号负二分之一 的负二次方，先化成倒数再平方得 4，底部写出 4 减 4 加 4 等于 4","prims":[{"t":"text","x":50,"y":10,"text":"逐项定符号，最后再合并","size":3.4,"anchor":"middle","tone":"muted"},{"t":"rect","x":6,"y":20,"w":28,"h":44,"tone":"ok","dashed":true},{"t":"text","x":20,"y":32,"text":"(-2)²","size":4.6,"anchor":"middle","tone":"ok"},{"t":"text","x":20,"y":46,"text":"负号参与乘方","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":20,"y":58,"text":"= 4","size":4.2,"anchor":"middle","tone":"ok"},{"t":"rect","x":36,"y":20,"w":28,"h":44,"tone":"danger","dashed":true},{"t":"text","x":50,"y":32,"text":"-2²","size":4.6,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":46,"text":"2² 的相反数","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":58,"text":"= -4","size":4.2,"anchor":"middle","tone":"danger"},{"t":"rect","x":66,"y":20,"w":28,"h":44,"tone":"accent","dashed":true},{"t":"text","x":80,"y":32,"text":"(-½)⁻²","size":4.4,"anchor":"middle","tone":"accent"},{"t":"text","x":80,"y":46,"text":"先倒数再平方","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":80,"y":58,"text":"= 4","size":4.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":78,"text":"4 - 4 + 4 = 4","size":4.4,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":92,"text":"每一项都先定符号，不要跳步","size":3.3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["先算乘方：(-2)²=4（负号在括号内，偶次幂得正）。","再算 2²=4，注意 -2² 表示 2² 的相反数，等于 -4。","计算负整数指数幂：(-(1)/(2))^(-2)=1(-(1)/(2))²=1(1)/(4)=4。","把三部分相加：4-4+4=4。"]},{"type":"p","text":"答案：4"},{"type":"note","title":"方法小结","text":"本题四个考点全部围绕符号：(-2)²=4 与 -2²=-4 的差别、负数的偶次幂为正、负整数指数幂先写成分数形式再计算。逐项算清再合并，不要跳步。"},{"type":"note","title":"例题","text":"先化简 (1-(1)/(x+1))÷ xx²-1，再取一个合适的 x 值求值，并说明 x 不能取哪些值。"},{"type":"figure","figure":{"id":"fig-jisuan-e2","title":"先定取值范围，再化简求值","caption":"限制条件必须提前写出，化简结果才可用","view":"square","alt":"顶部一个虚线方框写明限制条件 x 不等于 0 且 x 不等于正负 1，下方三步流程依次是原式、通分并把除法化为乘法、约分后得到 x 减 1，最后取 x 等于 2 时值为 1","prims":[{"t":"text","x":50,"y":9,"text":"先定取值范围，再化简","size":3.5,"anchor":"middle","tone":"muted"},{"t":"rect","x":12,"y":17,"w":76,"h":16,"tone":"danger","dashed":true},{"t":"text","x":50,"y":25,"text":"x≠0 且 x≠1 且 x≠-1","size":3.8,"anchor":"middle","tone":"danger"},{"t":"text","x":50,"y":46,"text":"(1 - 1/(x+1)) ÷ x/(x²-1)","size":3.4,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":52,"x2":50,"y2":60,"tone":"muted"},{"t":"text","x":50,"y":70,"text":"= x/(x+1) · (x+1)(x-1)/x","size":3.4,"anchor":"middle","tone":"main"},{"t":"arrow","x1":50,"y1":76,"x2":50,"y2":84,"tone":"muted"},{"t":"text","x":50,"y":93,"text":"= x-1（取 x=2 得 1）","size":3.8,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["先确定限制条件：x+1≠ 0 得 x≠ -1；除式的分母 x²-1≠ 0 得 x≠ ± 1；除式的分子 x≠ 0。合起来 x≠ 0 且 x≠ ± 1。","化简括号内：1-(1)/(x+1)=(x+1)/(x+1)-(1)/(x+1)=(x)/(x+1)。","把除法化为乘法，并把 x²-1 因式分解：原式 =(x)/(x+1)· ((x+1)(x-1))/(x)。","约去 x 与 (x+1)，得 x-1。","取 x=2（满足 x≠ 0 且 x≠ ± 1），代入得 2-1=1。"]},{"type":"p","text":"答案：化简结果为 x-1（x≠ 0 且 x≠ ± 1）；取 x=2 得值为 1"},{"type":"note","title":"方法小结","text":"「先化简再求值」的题目在因式分解后会「看不出」限制条件，但原式的限制始终存在，所以必须提前写出 x 的取值范围并据此选择代入值，这是最容易丢分的地方。"},{"type":"note","title":"例题","text":"一个直角三角形的两条直角边相差 3，面积是 20，求它的斜边长。"},{"type":"figure","figure":{"id":"fig-jisuan-e3","title":"列方程求出直角边，再算斜边","caption":"两条直角边为 8 与 5，斜边为 √89，负根已舍去","view":"square","alt":"一个直角三角形，两条直角边分别标为 x 和 x 减 3，直角处有直角标记，斜边标为根号 89，上方写出由面积列方程得 x 平方减 3x 减 40 等于 0，因式分解得 x 等于 8 或 x 等于负 5，并注明负 5 因边长不能为负而舍去","prims":[{"t":"text","x":50,"y":12,"text":"½·x(x-3)=20 ⇒ x²-3x-40=0","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":24,"text":"(x-8)(x+5)=0 ⇒ x=8 或 x=-5","size":3.4,"anchor":"middle","tone":"main"},{"t":"poly","points":[[16,80],[16,36],[72,80]],"closed":true,"tone":"main","fill":true},{"t":"angle","x":16,"y":80,"from":0,"to":90,"r":7,"right":true,"tone":"muted"},{"t":"text","x":8,"y":58,"text":"x-3","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":46,"y":92,"text":"x","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":52,"y":50,"text":"√89","size":3.6,"anchor":"middle","tone":"ok"},{"t":"text","x":82,"y":34,"text":"x=-5 舍去","size":3.2,"anchor":"middle","tone":"danger"}]}},{"type":"list","title":"解题步骤","items":["设较长的一条直角边为 x，则另一条为 x-3。","由面积公式列方程：(1)/(2)x(x-3)=20。","两边同乘 2 得 x(x-3)=40，整理得 x²-3x-40=0。","因式分解得 (x-8)(x+5)=0，所以 x=8 或 x=-5。","因为边长必须为正数，舍去 x=-5，取 x=8，另一条直角边为 8-3=5。","由勾股定理求斜边：8²+5²=√(64+25)=√(89)。","答：斜边长为 √(89)。检验：两条直角边 8、5 相差 3，面积 (1)/(2)× 8× 5=20，符合题意。"]},{"type":"p","text":"答案：斜边长为 √(89)"},{"type":"note","title":"方法小结","text":"这道题把方程、取舍、勾股定理串在一起，是典型的综合题型。负根必须舍去，斜边必须开平方而不是把边长直接相加；答案写成 √(89) 即可，不必化成小数。"},{"type":"note","title":"例题","text":"已知关于 x 的方程 (m-1)x²+2x-1=0 有两个不相等的实数根，求 m 的取值范围。"},{"type":"figure","figure":{"id":"fig-jisuan-e4","title":"两个限制条件缺一不可","caption":"二次项系数不为 0 与判别式大于 0 同时满足，取交集","view":"square","alt":"两个虚线方框分别写出两个限制条件，第一个是二次项系数 m 减 1 不等于 0 故 m 不等于 1，第二个是判别式等于 4m 大于 0 故 m 大于 0，下方数轴上把 0 到正无穷的区间加粗、在 1 处留空心点表示排除，底部给出交集结果 m 大于 0 且 m 不等于 1","prims":[{"t":"text","x":50,"y":10,"text":"「有两个不相等实根」的两个前提","size":3.3,"anchor":"middle","tone":"muted"},{"t":"rect","x":10,"y":19,"w":80,"h":15,"tone":"accent","dashed":true},{"t":"text","x":50,"y":27,"text":"① 二次项系数 m-1≠0 ⇒ m≠1","size":3.4,"anchor":"middle","tone":"accent"},{"t":"rect","x":10,"y":40,"w":80,"h":15,"tone":"ok","dashed":true},{"t":"text","x":50,"y":48,"text":"② 判别式 Δ = 4m > 0 ⇒ m > 0","size":3.4,"anchor":"middle","tone":"ok"},{"t":"line","x1":14,"y1":72,"x2":86,"y2":72,"tone":"main","width":1},{"t":"arrow","x1":86,"y1":72,"x2":90,"y2":72,"tone":"main","width":1},{"t":"dot","x":34,"y":72,"hollow":true,"tone":"main"},{"t":"arrow","x1":34,"y1":72,"x2":86,"y2":72,"tone":"accent","width":2.2},{"t":"dot","x":50,"y":72,"hollow":true,"tone":"danger"},{"t":"text","x":34,"y":84,"text":"0","size":3.2,"anchor":"middle","tone":"main"},{"t":"text","x":50,"y":84,"text":"1","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":60,"y":84,"text":"（1 处要挖掉）","size":3,"anchor":"start","tone":"danger"},{"t":"text","x":50,"y":96,"text":"取交集：m>0 且 m≠1","size":3.6,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["「一元二次方程有两个不相等实数根」要同时满足两个前提，想到二次项系数不为 0：m-1≠ 0，即 m≠ 1。","再算判别式：Δ=2²-4(m-1)×(-1)=4+4(m-1)=4m。","两个不相等实数根要求 Δ>0：4m>0，即 m>0。","把两个条件取交集：m>0 且 m≠ 1。"]},{"type":"p","text":"答案：m 的取值范围是 m>0 且 m≠ 1"},{"type":"note","title":"方法小结","text":"含参数的一元二次方程，「二次项系数不为 0」和「判别式的符号」两个条件缺一不可：只看 Δ 会把 m=1 时的一次方程误算进来。最后把两个限制写成交集，而不是只写一个不等式。"},{"type":"note","title":"例题","text":"已知 1<x<3，化简：|x-3|+|x-1|-(x-2)²。"},{"type":"figure","figure":{"id":"fig-m-num-jisuan-lingdian-1","title":"按零点分段去绝对值","caption":"零点 1、2、3 把范围分成两段讨论","view":"wide","alt":"数轴上标出零点 1、2、3 三个点，1 和 3 处为空心圆圈表示不包含端点，2 处为实心点，区间 1 到 3 之间用加粗线段标出，并在 1 到 2 段标注结果为 x，2 到 3 段标注结果为 4 减 x","prims":[{"t":"line","x1":10,"y1":50,"x2":90,"y2":50},{"t":"arrow","x1":90,"y1":50,"x2":94,"y2":50},{"t":"line","x1":10,"y1":47,"x2":10,"y2":53},{"t":"line","x1":26,"y1":47,"x2":26,"y2":53},{"t":"line","x1":42,"y1":47,"x2":42,"y2":53},{"t":"line","x1":58,"y1":47,"x2":58,"y2":53},{"t":"line","x1":74,"y1":47,"x2":74,"y2":53},{"t":"text","x":10,"y":60,"text":"0","size":3.4,"anchor":"middle"},{"t":"text","x":26,"y":60,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":42,"y":60,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":58,"y":60,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":74,"y":60,"text":"4","size":3.4,"anchor":"middle"},{"t":"dot","x":26,"y":50,"hollow":true,"tone":"danger"},{"t":"dot","x":58,"y":50,"hollow":true,"tone":"danger"},{"t":"dot","x":42,"y":50,"tone":"accent"},{"t":"arrow","x1":26,"y1":50,"x2":42,"y2":50,"tone":"accent","width":2.5},{"t":"arrow","x1":42,"y1":50,"x2":58,"y2":50,"tone":"ok","width":2.5},{"t":"text","x":34,"y":38,"text":"1<x≤2","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":50,"y":38,"text":"2<x<3","size":3.2,"tone":"ok","anchor":"middle"},{"t":"text","x":34,"y":30,"text":"原式 = x","size":3.2,"tone":"accent","anchor":"middle"},{"t":"text","x":50,"y":30,"text":"原式 = 4−x","size":3.2,"tone":"ok","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["去绝对值和根号前，想到先根据给定范围判断每个被包部分的正负号。","由 x<3 得 x-3<0，故 |x-3|=3-x；由 x>1 得 x-1>0，故 |x-1|=x-1。","由 1<x<3 不能直接断定 x-2 的正负，想到 a²=|a|，故 (x-2)²=|x-2|，需以 2 为界分类讨论。","当 1<x≤ 2 时，|x-2|=2-x，原式 =(3-x)+(x-1)-(2-x)=x；当 2<x<3 时，|x-2|=x-2，原式 =(3-x)+(x-1)-(x-2)=4-x。"]},{"type":"p","text":"答案：原式 =cases x & (1<x≤ 2) \\\\ 4-x & (2<x<3) endcases"},{"type":"note","title":"方法小结","text":"a² 等于 |a| 而不是 a，这是二次根式与绝对值的经典结合点。去绝对值的依据是范围内的正负号；正负号不能确定时，要以零点为界分类讨论，不能默认一种情况。"},{"type":"list","title":"易错点","items":["去括号、去分母、移项三类变形混为一谈：去括号要逐项变号，去分母要两边同乘且常数项也要乘，移项只把移动的那一项变号。三者依据不同，不能套用同一句口诀。","乘方与负号结合出错，如把 $-2^{2}$ 算成 4、把 $(-2)^{3}$ 算成 6（误当乘法）、把 $(-1)^{2n+1}$ 算成 1。","不等式两边同乘或同除负数时不改变不等号方向，如由 $-2x>6$ 得 $x>-3$（正确为 $x<-3$）。","忽略取值范围：分式方程忘记检验增根，二次根式忘记被开方数非负，含参方程忘记二次项系数不为 0。","求值类题目先代入后化简，或代入使原式分母为 0 的值，导致计算量大且答案错误。","结果不规范：分式没有约到最简、二次根式没有化成最简、因式分解没有分解到底、多解只写一个、应用题不写单位与答语。"]},{"type":"list","title":"解题方法","items":["三步自检法：一查符号（正负号、括号、指数），二查定义域（分母、被开方数、二次项系数），三查检验（方程验根、实际意义取舍）。","特殊值检验：对恒等变形，取一个简单数（如 x=1、x=2）分别代入原式与化简结果，数值相等说明变形正确。","逆运算检验：加法用减法验、乘法用除法验、乘方用开方验，尤其是解方程后的代入检验最省时间也最有效。","估算判界：先目测结果的符号与数量级是否合理，如面积不能为负、增长率不能小于 -100\\%，出现异常立刻回头检查。","错题归类：把错题按「符号类、定义域类、审题类、计算类」分类整理，针对高频类别专项训练，比盲目刷题更有效。"]}],"questions":[{"id":"m-num-jisuan-yiucuo-q1","type":"choice","stem":"下列计算正确的是（ ）","answer":"C","explain":"C 正确：底数是 -2，立方的结果是 -8。A 错：-2² 表示 2² 的相反数，等于 -4。B 错：(-3)²=9，负数的偶次幂为正。D 错：同底数幂相乘指数相加，应为 6a²+3=6a⁵，系数相乘得 6 是对的，但指数乘错。","options":["-2²=4","(-3)²=-9","(-2)³=-8","3a²· 2a³=6a⁶"],"difficulty":1,"tags":["符号","乘方","幂的运算"]},{"id":"m-num-jisuan-yiucuo-q2","type":"choice","stem":"若 (x-1)²=4，则 x 的值是（ ）","answer":"C","explain":"由 (x-1)²=4 直接开平方得 x-1=2 或 x-1=-2，所以 x=3 或 x=-1，选 C。只取 x=3 是漏解，因为 (-2)²=4 同样成立。检验：x=3 时 (3-1)²=4；x=-1 时 (-1-1)²=(-2)²=4，两根都正确。","options":["x=3","x=-1","x=3 或 x=-1","x=5"],"difficulty":1,"tags":["开平方","漏解","易错"]},{"id":"m-num-jisuan-yiucuo-q3","type":"fill","stem":"计算：((1)/(2))^(-1)+(-1)²⁰²⁶-(-2)³=（ ）。","answer":"11","explain":"逐项计算：((1)/(2))^(-1)=1(1)/(2)=2；(-1)²⁰²⁶=1，因为 2026 是偶数，负数的偶次幂为正；(-2)³=-8，所以 -(-2)³=-(-8)=8。三项相加得 2+1+8=11。注意最后一项是减去 (-2)³，负负得正，这是本题最容易错的地方。","difficulty":2,"tags":["负指数幂","乘方","符号"]},{"id":"m-num-jisuan-yiucuo-q4","type":"fill","stem":"解不等式 (x-1)/(2)>1-(x)/(3)，得 x（ ）。（如 x>1/2）","answer":"x>9/5|x>1.8","explain":"去分母：两边同乘 6（正数，不等号方向不变），注意常数项 1 也要乘 6，得 3(x-1)>6-2x。去括号得 3x-3>6-2x。移项得 3x+2x>6+3，即 5x>9。两边同除以 5（正数，方向不变）得 x>(9)/(5)。检验：取 x=2，左边 =(1)/(2)=0.5，右边 =1-(2)/(3)≈ 0.333，0.5>0.333 成立，方向正确。","difficulty":2,"tags":["解不等式","去分母","检验方向"]},{"id":"m-num-jisuan-yiucuo-q5","type":"short","stem":"解不等式组 cases (x+1)/(2)≥ x-1 \\\\ 3x-2>2(x-1) endcases，求它的解集与所有整数解，并写出完整过程（含每一步的依据）。","answer":"解集为 $0<x\\leq 3$，整数解为 1、2、3。","explain":"解第一个不等式 (x+1)/(2)≥ x-1：两边同乘 2（正数，方向不变）得 x+1≥ 2x-2；移项得 x-2x≥ -2-1，即 -x≥ -3；两边同除以 -1（负数，不等号方向改变）得 x≤ 3。解第二个不等式 3x-2>2(x-1)：去括号得 3x-2>2x-2；移项得 3x-2x>-2+2，即 x>0。两个解集在数轴上取公共部分：x≤ 3 与 x>0 的交集是 0<x≤ 3。因此整数解为 x=1,2,3。检验：取 x=3，第一式左边 =(4)/(2)=2、右边 =3-1=2，2≥ 2 成立；第二式左边 =7、右边 =4，7>4 成立。取 x=0，第二式为 -2>-2，不成立，说明 0 不满足，端点取舍正确。","difficulty":3,"tags":["不等式组","整数解","变号","综合"],"rubric":["正确解出第一个不等式得 x≤ 3，并说明除以 -1 时不等号改变方向","正确解出第二个不等式得 x>0","取公共部分得解集 0<x≤ 3（端点取舍正确）","正确写出整数解 1、2、3（三个都写全）","有检验过程或必要的依据说明，表述规范"]},{"id":"m-num-jisuan-yiucuo-z1","type":"choice","stem":"要使代数式 √(x-3)x-5 在实数范围内有意义，则 x 的取值范围是（ ）","answer":"A","explain":"代数式同时含二次根式与分式：被开方数要求 x-3≥ 0，即 x≥ 3；分母要求 x-5≠ 0，即 x≠ 5。两个条件取交集，得 x≥ 3 且 x≠ 5，选 A。x=3 时根号内为 0，分子为 0、分母不为 0，代数式仍有意义，端点不能丢。","options":["x≥ 3 且 x≠ 5","x>3 且 x≠ 5","x≥ 3","x>5"],"difficulty":2,"tags":["二次根式","取值范围","分式有意义"]},{"id":"m-num-jisuan-yiucuo-z2","type":"short","stem":"解不等式 (2x-1)/(3)≤ (x+1)/(2)-1，写出它的解集，并求出该解集中最大的整数解。","answer":"解集为 $x\\leq -1$，最大的整数解是 $-1$。","explain":"两边同乘最简公分母 6（正数，不等号方向不变），注意常数项 -1 也要乘 6：2(2x-1)≤ 3(x+1)-6。去括号得 4x-2≤ 3x+3-6，即 4x-2≤ 3x-3。移项得 4x-3x≤ -3+2，故 x≤ -1。该解集中的整数解为 -1,-2,-3,…，其中最大的是 -1。检验：取 x=-1，左边 =(-3)/(3)=-1，右边 =0-1=-1，-1≤ -1 成立，端点能取到；取 x=0，左边 =-(1)/(3)、右边 =(1)/(2)-1=-(1)/(2)，而 -(1)/(3)>-(1)/(2)，不成立，方向正确。","difficulty":2,"tags":["解不等式","去分母","整数解"],"rubric":["去分母时常数项 -1 也乘 6，正确得到 2(2x-1)≤ 3(x+1)-6","去括号、移项正确，得出解集 x≤ -1","正确写出最大整数解 -1，有检验或作答语句"]}]},{"id":"m-num-daishushi","title":"代数式：用字母表示数与整式的概念","subtitle":"人教版七上 · 第3章 代数式","grade":"7a","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版七上 · 第3章 代数式"},{"type":"note","title":"一句话概述","text":"用字母表示数、规范书写代数式，理解单项式与多项式的系数和次数，会代入求值并分析数量关系中的规律。"},{"type":"h","text":"先看什么：字母能表示一类数"},{"type":"p","text":"「每本笔记本 a 元，买 5 本要 5a 元」——这里 a 表示的是任意一本笔记本的价钱，写出来的 5a 一下子概括了所有同类问题。用字母表示数的好处正在于此：把「无数个具体算式」压成「一个式子」，从而能讨论数量之间的普遍关系。要注意两条：字母表示的是数，因此可以像数一样参与运算；同一个字母在同一问题中表示同一个量，不同字母可以表示同一个数（除非题目另有说明）。"},{"type":"figure","figure":{"id":"fig-num-daishushi-s1","title":"用字母概括一类数量关系","caption":"买 1 本、2 本、3 本……的价钱都可以用一个式子写出来","view":"wide","alt":"四行对照：每本 a 元时，买 1 本要 a 元、买 2 本要 2a 元、买 3 本要 3a 元，最后一行写买 n 本要 na 元，说明字母概括了所有情况","prims":[{"t":"rect","x":8,"y":10,"w":84,"h":9,"tone":"muted"},{"t":"text","x":14,"y":16,"text":"买 1 本：$a$ 元","size":4},{"t":"rect","x":8,"y":20,"w":84,"h":9,"tone":"muted"},{"t":"text","x":14,"y":26,"text":"买 2 本：$2a$ 元","size":4},{"t":"rect","x":8,"y":30,"w":84,"h":9,"tone":"muted"},{"t":"text","x":14,"y":36,"text":"买 3 本：$3a$ 元","size":4},{"t":"rect","x":8,"y":40,"w":84,"h":11,"tone":"accent"},{"t":"text","x":14,"y":47,"text":"买 $n$ 本：$na$ 元　—— 一个式子概括了全部情况","size":4,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"字母表示的是数，可以像数一样参与运算","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"a 既可以表示整数，也可以表示分数；只有题目限定「a 为正整数」时，才需要把取值范围写出来。"},{"type":"h","text":"写规范：代数式的书写约定"},{"type":"p","text":"代数式的书写有一整套约定，写错就会在阅卷时被判错：数与字母相乘，乘号省略且数写在前面（5a 不写成 a5，也不写成 5× a）；字母与字母相乘，乘号省略并按字母表顺序写（ab 不写成 ba）；带分数与字母相乘要化成假分数（1(1)/(2)a 写成 (3)/(2)a）；除法写成分数形式（a÷ 3 写成 (a)/(3)）；带单位的式子，若结果是和的形式要把式子加括号再写单位（(a+b) 米，不能写成 a+b 米）。"},{"type":"figure","figure":{"id":"fig-num-daishushi-s2","title":"代数式的书写规范","caption":"左边是常见写法，右边是规范写法","view":"wide","alt":"左右对照表：不规范写法如 a5、5×a、a÷3、a+b 米，规范写法如 5a、ab、a/3、加括号的 (a+b) 米","prims":[{"t":"rect","x":6,"y":10,"w":44,"h":8,"tone":"danger"},{"t":"text","x":10,"y":15.5,"text":"不规范：$5\\times a$、$a5$","size":4},{"t":"rect","x":6,"y":19,"w":44,"h":8,"tone":"danger"},{"t":"text","x":10,"y":24.5,"text":"不规范：$a\\div 3$、$ba$","size":4},{"t":"rect","x":6,"y":28,"w":44,"h":8,"tone":"danger"},{"t":"text","x":10,"y":33.5,"text":"不规范：$a+b$ 米","size":4},{"t":"rect","x":54,"y":10,"w":42,"h":8,"tone":"ok"},{"t":"text","x":58,"y":15.5,"text":"规范：$5a$","size":4},{"t":"rect","x":54,"y":19,"w":42,"h":8,"tone":"ok"},{"t":"text","x":58,"y":24.5,"text":"规范：$\\frac{a}{3}$、$ab$","size":4},{"t":"rect","x":54,"y":28,"w":42,"h":8,"tone":"ok"},{"t":"text","x":58,"y":33.5,"text":"规范：$(a+b)$ 米","size":4},{"t":"text","x":50,"y":48,"text":"带单位的和式必须加括号，否则单位只加在最后一个字母上","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"「返回一个代数式」的题目里，含单位的答案一定要检查括号；这是选择题与填空题里最常见的丢分点。"},{"type":"h","text":"认结构：单项式、多项式与次数"},{"type":"p","text":"代数式里专门研究整式。数或字母的积叫单项式（5a、-(2)/(3)x²y、a 都是单项式），单项式中的数字因数叫系数，所有字母的指数和叫次数；几个单项式的和叫多项式，其中每个单项式叫项，次数最高的项的次数就是多项式的次数。要点有三：(1)/(x) 与 a+(1)/(b) 的分母里含字母，不是整式；单项式的次数只算字母的指数，与系数无关（-3x²y 的次数是 3）；多项式的次数看最高次项，而不是把所有次数相加。"},{"type":"figure","figure":{"id":"fig-num-daishushi-s3","title":"单项式与多项式的结构","caption":"系数看数字因数，次数看字母指数之和","view":"wide","alt":"上方用方框标出单项式 -3x²y 的系数是 -3、次数是 3；下方标出多项式 2a²-a+1 的三项与次数 2","prims":[{"t":"rect","x":10,"y":10,"w":80,"h":14,"tone":"main"},{"t":"text","x":50,"y":20,"text":"单项式：$-3x^2y$　系数 $-3$　次数 $2+1=3$","size":4.4,"anchor":"middle"},{"t":"rect","x":10,"y":30,"w":80,"h":14,"tone":"accent"},{"t":"text","x":50,"y":40,"text":"多项式：$2a^2-a+1$　三项：$2a^2$、$-a$、$1$　次数 2","size":4,"anchor":"middle"},{"t":"text","x":50,"y":54,"text":"次数只数字母的指数；多项式的次数取最高次项的次数","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"多项式的每一项都带着它前面的符号：2a²-a+1 的第二项是 -a 而不是 a，移项、合并同类项时符号错最常见。"},{"type":"h","text":"会代入：代数式求值与整体代入"},{"type":"p","text":"代数式的值就是把字母换成具体的数后算出来的结果。代入时要注意三件事：一是代入负数要加括号（求 x=-2 时 x² 写成 (-2)²，否则会算成 -2²）；二是代入分数时也要加括号；三是当题目没给出每个字母的值、却给出像 a+b=3 这样的条件时，要用整体代入：把 a+b 看成一个整体去替换，不必分别求出 a 与 b。"},{"type":"figure","figure":{"id":"fig-num-daishushi-s4","title":"整体代入的思路","caption":"把 a+b 看成一个整体，直接替换，不必分别求出 a 与 b","view":"wide","alt":"已知 a+b=3，求 2(a+b)+1：把 a+b 整体换成 3，得到 2×3+1=7，说明整体代入的写法","prims":[{"t":"rect","x":8,"y":12,"w":84,"h":10,"tone":"main"},{"t":"text","x":50,"y":19,"text":"已知 $a+b=3$，求 $2(a+b)+1$","size":4.4,"anchor":"middle"},{"t":"arrow","x1":50,"y1":24,"x2":50,"y2":32,"tone":"accent"},{"t":"rect","x":8,"y":32,"w":84,"h":10,"tone":"ok"},{"t":"text","x":50,"y":39,"text":"把 $a+b$ 整体换成 3：$2\\times 3+1=7$","size":4.4,"anchor":"middle"},{"t":"text","x":50,"y":52,"text":"整体代入：不必分别求出 $a$ 与 $b$（它们并不唯一）","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"代入求值的格式要写全：先写「当 x=-2 时」，再写「原式 = …」，最后给结果。直接写得数会丢掉过程分。"},{"type":"h","text":"核心概念"},{"type":"p","text":"代数式：用运算符号（加、减、乘、除、乘方）把数与表示数的字母连接起来的式子。单独一个数或一个字母也是代数式，例如 a、5 都是代数式；含等号或不等号的不叫代数式。\n判断代数式的口诀是「有运算、无关系符号」。"},{"type":"p","text":"单项式与多项式：数或字母的积叫单项式，几个单项式的和叫多项式。单项式中的数字因数是系数，所有字母的指数和是次数；多项式中次数最高的项的次数，就是多项式的次数。\n分母里含字母的式子（如 (1)/(x)）不是整式，因为除数是字母；初中阶段讨论系数与次数只针对整式。"},{"type":"p","text":"代数式的值：用具体数值代替代数式中的字母，按照代数式指明的运算算出的结果。代入负数或分数时要加括号，含单位的答案若是和的形式要把整个式子括起来。\n当字母的值不易求出时，先看所求式子能否由已知式的倍数、和差凑出来，用整体代入。"},{"type":"p","text":"列代数式：把文字叙述的数量关系翻译成含字母的式子。关键是抓「和、差、积、商、倍、几分之几、多、少」这些词对应的运算，并弄清运算顺序。\n「a 的平方与 b 的差」是 a²-b，而「a 与 b 的差的平方」是 (a-b)²——读题时要盯住「的」字的归属。"},{"type":"note","title":"中考考法","text":"代数式的书写规范\n选择题常给出四种写法，要求挑出规范的或改正不规范的。判断顺序是：数字是否在前、除号是否化成分数、和式是否加括号、带分数是否化假分数。"},{"type":"note","title":"中考考法","text":"用代数式表示数量关系\n填空题高频：给定情境（行程、利润、周长面积、数位）列式子。作答后要检查运算顺序与单位。"},{"type":"note","title":"中考考法","text":"代数式求值\n既有直接代入（注意负数加括号），也有整体代入（给出 a+b、ab 之类的条件）。整体代入题要先观察所求式与已知式的倍数关系。"},{"type":"note","title":"中考考法","text":"单项式与多项式的系数、次数\n常考「指出系数与次数」「已知次数求字母的值」。-(2)/(3)x²y 的系数是 -(2)/(3)、次数是 3，别把系数与次数混在一起。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["单项式的系数与次数","系数 = 单项式中的数字因数（含符号）；次数 = 所有字母的指数之和","如 -3x²y：系数是 -3，次数是 2+1=3。单个字母 a 的系数是 1、次数是 1；单独一个非零数（如 5）的次数是 0。"],["多项式的次数","多项式的次数 = 次数最高的那一项的次数","如 2a²-a+1 的最高次项是 2a²，次数为 2，它是二次三项式；不要把各项次数相加。"],["常见数量关系的代数式","路程 s=vt；总价 = 单价 × 数量；长方形周长 C=2(a+b)、面积 S=ab","列式前先写清「谁是常量、谁是变量」，再按公式套用；含单位的和式要加括号，如 (a+b) 米。"]]},{"type":"note","title":"例题","text":"用代数式表示：(1) 某商品原价 a 元，打八折后的售价；(2) 一个两位数，十位数字是 x、个位数字是 y，这个两位数。"},{"type":"figure","figure":{"id":"fig-num-daishushi-e1","title":"数位与两位数的关系","caption":"十位上的 x 表示 x 个十，个位上的 y 表示 y 个一","view":"wide","alt":"一个两位数写成两格，十位上是 x、个位上是 y；下方标出这个数是 10x+y，说明十位数字要乘 10","prims":[{"t":"rect","x":30,"y":12,"w":18,"h":16,"tone":"main"},{"t":"rect","x":48,"y":12,"w":18,"h":16,"tone":"accent"},{"t":"text","x":39,"y":24,"text":"$x$","size":6,"anchor":"middle"},{"t":"text","x":57,"y":24,"text":"$y$","size":6,"anchor":"middle"},{"t":"text","x":39,"y":33,"text":"十位","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":57,"y":33,"text":"个位","size":3.4,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":46,"text":"两位数 $=10x+y$","size":4.6,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["(1) 打八折就是按原价的 80% 出售，所以售价是 0.8a 元（也可写成 (4)/(5)a 元）。","(2) 十位数字 x 表示 x 个十、个位数字 y 表示 y 个一，所以这个两位数是 10x+y。"]},{"type":"p","text":"答案：(1) 0.8a 元；(2) 10x+y。"},{"type":"note","title":"方法小结","text":"第 (2) 问最典型的错误是写成 xy——那样表示的是 x 与 y 的乘积，无法表示数位关系。"},{"type":"note","title":"例题","text":"当 a=-2、b=(1)/(3) 时，求代数式 a²-3ab 的值。"},{"type":"list","title":"解题步骤","items":["当 a=-2、b=(1)/(3) 时，","原式 =(-2)²-3×(-2)×(1)/(3)","=4-(-2)=4+2=6。"]},{"type":"p","text":"答案：代数式的值是 6。"},{"type":"note","title":"方法小结","text":"代入负数和分数都必须加括号：若把 (-2)² 写成 -2²，结果就变成 -4，整题错误。"},{"type":"list","title":"易错点","items":["把「$a$ 的平方与 $b$ 的差」写成 $(a-b)^2$：前者是 $a^2-b$，后者是差的平方，读题时要看清「的」字管到哪一步。","代入负数不加括号：求 $x=-3$ 时 $x^2$ 必须写成 $(-3)^2=9$，写成 $-3^2=-9$ 就错了。","把单项式的次数与系数搞混：$-3x^2y$ 的次数是 3（字母指数和），系数是 $-3$，别写成次数 $-3$。","含单位的和式忘记括号：$(a+b)$ 米不能写成 $a+b$ 米，否则单位只加在 $b$ 上。","把 $\\frac{1}{x}$ 当作单项式：分母含字母的式子不是整式，不能讨论它的系数与次数。"]},{"type":"list","title":"解题方法","items":["列代数式的三步：先设字母并表示各个量 → 找出数量关系中的运算 → 按运算顺序写出式子并检查规范。","代入求值的格式：写「当…时」 → 代替代数式中的字母（负数、分数加括号） → 按运算顺序计算 → 写出结果。","整体代入：当已知条件是 a+b、a-b、ab 这类组合值时，把所求式变形为含这个组合的式子，再整体替换。","判断整式：看分母里有没有字母。分母含字母的代数式不是整式，本题中若出现请直接排除。"]}],"questions":[{"id":"m-num-daishushi-q1","type":"choice","stem":"下列代数式中，书写规范的是","answer":"C","explain":"数与字母相乘时乘号省略、数字写在字母前面，5a 规范；a5 把数字写在了后面，5× a 没有省略乘号，a÷ 5 应写成分数形式 (a)/(5)。","options":["a5","5× a","5a","a÷ 5"],"difficulty":1,"tags":["代数式书写"]},{"id":"m-num-daishushi-q2","type":"choice","stem":"单项式 -(2)/(3)x²y 的系数和次数分别是","answer":"A","explain":"系数是单项式中的数字因数，要带上符号，所以是 -(2)/(3)；次数是所有字母的指数之和，x 的指数是 2、y 的指数是 1，共 3。C 项漏掉了 y 的指数 1，D 项把分数写成了整数。","options":["-(2)/(3)，3","(2)/(3)，3","-(2)/(3)，2","-2，3"],"difficulty":2,"tags":["单项式","系数与次数"]},{"id":"m-num-daishushi-q3","type":"choice","stem":"某商品原价 m 元，先提价 10%，再打九折出售，则现在的售价是","answer":"A","explain":"提价 10% 后是 1.1m 元，再打九折即乘以 0.9，得 1.1m× 0.9=0.99m 元。注意「先提价再打折」不能相互抵消，B 项正是把两者当成相互抵消的错误结果。","options":["0.99m 元","m 元","1.09m 元","0.9m 元"],"difficulty":2,"tags":["列代数式","数量关系"]},{"id":"m-num-daishushi-q4","type":"choice","stem":"已知 x+y=5，则 3x+3y-4 的值是","answer":"A","explain":"把所求式变形为含整体 x+y 的形式：3x+3y-4=3(x+y)-4，代入 x+y=5 得 3× 5-4=11。这类题不需要分别求出 x、y（它们的值并不唯一），用整体代入即可。","options":["11","15","19","不能确定"],"difficulty":3,"tags":["整体代入","代数式求值"]},{"id":"m-num-daishushi-q5","type":"fill","stem":"当 x=-3、y=2 时，代数式 x²-2xy 的值是________。","answer":"21","explain":"代入时负数和它的平方都要加括号：原式 =(-3)²-2×(-3)× 2=9+12=21。若把 (-3)² 写成 -3²，会得到 -9-(-12)=3，整题错误。","difficulty":2,"tags":["代数式求值"]},{"id":"m-num-daishushi-q6","type":"short","stem":"用一根长 a 米的绳子围成一个长方形，长比宽多 2 米。(1) 用含 a 的代数式表示这个长方形的宽；(2) 当 a=20 时，求这个长方形的面积。","answer":"(1) 设宽为 $x$ 米，则长为 $(x+2)$ 米。由周长公式 $2(x+x+2)=a$，得 $2x+2=\\frac{a}{2}$，即 $x=\\frac{a}{4}-1$，所以宽是 $\\left(\\frac{a}{4}-1\\right)$ 米。(2) 当 $a=20$ 时，宽 $=\\frac{20}{4}-1=4$ 米，长 $=4+2=6$ 米，面积 $=6\\times 4=24$（平方米）。","explain":"第 (1) 问的关键是把「长比宽多 2 米」翻译成「长 = 宽 +2」，再用周长公式建立关系；第 (2) 问把 a=20 代回宽的表达式中求出具体的长与宽，最后用面积公式作答。注意面积的单位是「平方米」，写成「米」是单位错误。","difficulty":3,"tags":["列代数式","代数式求值","应用"],"rubric":["设出宽并写出长的表达式（1 分）","用周长公式列关系、正确解出宽（1 分）","代入 a=20 求出长与宽（1 分）","面积结果 24 平方米并带单位（1 分）"]}]},{"id":"m-num-hanshu","title":"函数：变量与函数、三种表示与图象","subtitle":"人教版八下 · 第22章 函数","grade":"8b","tags":[],"blocks":[{"type":"note","title":"教材章节","text":"人教版八下 · 第22章 函数"},{"type":"note","title":"一句话概述","text":"认识变量与常量，理解函数「一个自变量值对应唯一函数值」的含义，会求自变量取值范围与函数值，会用解析式、列表、图象表示函数并读图。"},{"type":"h","text":"先看什么：变量与常量，以及「唯一确定」"},{"type":"p","text":"在一辆汽车匀速行驶的过程中，速度 v 保持不变，是常量；行驶时间 t 与路程 s 都在变化，是变量；并且给一个 t 就唯一确定一个 s，这时说 s 是 t 的函数，t 是自变量。函数的核心只有四个字——**唯一确定**：对于自变量的每一个确定的值，因变量都有唯一确定的值与之对应。理解这一点后就能判断：气温随时间变化是函数关系；而「一个长方形的面积是 12，长与宽」也是函数关系（长取一个值，宽就唯一确定）。"},{"type":"figure","figure":{"id":"fig-num-hanshu-s1","title":"函数关系：一个自变量值对应唯一函数值","caption":"左边每个 t 都能在右边找到唯一的 s；反过来一个 s 可以对应两个 t（往返行程）","view":"wide","alt":"左侧列出时间 t 取 1、2、3，右侧列出对应的路程 s 为 60、120、180，箭头一一对应，说明每个 t 都唯一确定一个 s","prims":[{"t":"rect","x":6,"y":12,"w":34,"h":12,"tone":"main"},{"t":"text","x":23,"y":20,"text":"自变量 $t$：1、2、3","size":4,"anchor":"middle"},{"t":"arrow","x1":42,"y1":18,"x2":56,"y2":18,"tone":"accent"},{"t":"rect","x":58,"y":12,"w":36,"h":12,"tone":"accent"},{"t":"text","x":76,"y":20,"text":"函数 $s$：60、120、180","size":4,"anchor":"middle"},{"t":"text","x":50,"y":33,"text":"每一个 $t$ 都唯一确定一个 $s$ → $s$ 是 $t$ 的函数","size":4.2,"anchor":"middle"},{"t":"text","x":50,"y":44,"text":"若一个 $t$ 对应两个不同的 $s$，就不是函数关系","size":3.8,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":54,"text":"速度 $v$ 保持不变 → 常量；$t$、$s$ 都在变 → 变量","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"判断函数关系只看「唯一确定」这一条，与「是不是用式子表示」「图象是不是直线」都无关；看图象时用竖直线去截，若与图象有两个交点，就不是函数。"},{"type":"h","text":"求范围：自变量的取值范围由什么决定"},{"type":"p","text":"函数的自变量不是随便取的，要同时满足两条：一是**式子本身有意义**——分式的分母不能为 0（y=(1)/(x-2) 中 x≠ 2），二次根式的被开方数不能为负（y=√(x-1) 中 x≥ 1）；二是**符合实际意义**——人数必须是正整数，长度必须是正数，时间不能为负。所以 y=(20)/(t) 在纯数学里只要求 t≠ 0，而作为「行驶 20 千米所用时间」时还必须 t>0。"},{"type":"figure","figure":{"id":"fig-num-hanshu-s2","title":"自变量取值范围的两道关口","caption":"先看式子有意义，再看实际意义，两者取交集","view":"wide","alt":"流程图：第一步检查式子是否有意义（分母不为 0、被开方数非负），第二步检查实际意义（长度为正、人数为正整数），两步的结果取交集得到自变量的取值范围","prims":[{"t":"rect","x":4,"y":16,"w":28,"h":18,"tone":"main"},{"t":"text","x":18,"y":24,"text":"①式子有意义","size":4,"anchor":"middle"},{"t":"text","x":18,"y":31,"text":"分母$\\ne 0$、被开方数$\\ge 0$","size":3.4,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":33,"y1":25,"x2":37,"y2":25},{"t":"rect","x":38,"y":16,"w":28,"h":18,"tone":"accent"},{"t":"text","x":52,"y":24,"text":"②符合实际","size":4,"anchor":"middle"},{"t":"text","x":52,"y":31,"text":"人数、长度、时间都为正","size":3.4,"anchor":"middle","tone":"muted"},{"t":"arrow","x1":67,"y1":25,"x2":71,"y2":25},{"t":"rect","x":72,"y":16,"w":24,"h":18,"tone":"ok"},{"t":"text","x":84,"y":25,"text":"取交集","size":4,"anchor":"middle"},{"t":"text","x":50,"y":46,"text":"例：$y=\\sqrt{x-1}$ 纯数学 $x\\ge 1$；若表示人数则 $x$ 取正整数","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"写取值范围时不要漏「等号」：√(x-1) 中 x=1 时式子为 0，是有意义的，所以是 x≥ 1 而不是 x>1。"},{"type":"h","text":"三种表示：解析式、列表、图象可以互相翻译"},{"type":"p","text":"同一个函数可以有三种表示：解析式（s=60t）最便于计算，列表（t 取 1、2、3 时 s 分别是 60、120、180）最便于查值，图象（把表格中的点画到坐标系里再连线）最便于看出变化趋势。用描点法画图分三步：列表取点、描点、用平滑曲线（或直线）连接。注意：取点要有代表性，既要取正值也要取负值；连线要用平滑曲线而不能用折线把点硬连起来。"},{"type":"figure","figure":{"id":"fig-num-hanshu-s3","title":"描点法画函数图象","caption":"列表 → 描点 → 用平滑曲线连接","view":"wide","alt":"左侧是 t 与 s 的对应表格，中间是坐标系中按表格描出的点，右侧是用平滑直线把这些点连接后得到 s=60t 的图象","prims":[{"t":"rect","x":4,"y":14,"w":26,"h":30,"tone":"muted"},{"t":"text","x":17,"y":21,"text":"$t$：1、2、3","size":3.8,"anchor":"middle"},{"t":"text","x":17,"y":29,"text":"$s$：60、120、180","size":3.8,"anchor":"middle"},{"t":"text","x":17,"y":39,"text":"①列表","size":3.8,"tone":"main","anchor":"middle"},{"t":"arrow","x1":31,"y1":29,"x2":37,"y2":29},{"t":"axis","x":40,"y":46,"w":22,"h":30,"xLabel":"t","yLabel":"s","origin":true,"grid":true},{"t":"dot","x":47,"y":40},{"t":"dot","x":54,"y":34},{"t":"dot","x":61,"y":28},{"t":"text","x":50,"y":56,"text":"②描点","size":3.8,"tone":"main","anchor":"middle"},{"t":"arrow","x1":64,"y1":29,"x2":70,"y2":29},{"t":"axis","x":73,"y":46,"w":22,"h":30,"xLabel":"t","yLabel":"s","origin":true,"grid":true},{"t":"curve","points":[[73,46],[95,22]],"tone":"accent","width":1},{"t":"text","x":84,"y":56,"text":"③连线","size":3.8,"tone":"accent","anchor":"middle"}]}},{"type":"note","title":"","text":"由图象判断是否为函数，就看任意一条竖直线与图象是否最多只有一个交点；画图时若把点连成折线，会改变函数的实际变化规律，属于画图错误。"},{"type":"h","text":"会读图：从图象里读出「谁在变、怎么变」"},{"type":"p","text":"读图题按三步走：一看坐标轴（横轴、纵轴各表示什么、单位是什么），二看关键点（起点、终点、与坐标轴的交点、拐点），三看趋势（上升、下降还是水平）。以「小明骑车去图书馆再返回」的图象为例：上升段表示离家越来越远，水平段表示停在图书馆看书（路程不变），下降段表示返回家中。三个阶段的斜率（陡缓）不同，表示速度不同——这就是图象题最常考的信息。"},{"type":"figure","figure":{"id":"fig-num-hanshu-s4","title":"从路程—时间图象读出三个阶段","caption":"上升＝出发，水平＝停留，下降＝返回","view":"wide","alt":"路程随时间变化的图象：先上升表示骑车前往，中间一段水平表示在图书馆停留，随后下降表示返回家中，最后回到路程为零的位置","prims":[{"t":"axis","x":14,"y":52,"w":72,"h":42,"xLabel":"时间/min","yLabel":"路程/km","origin":true,"grid":true,"xTicks":[{"at":0.25,"label":"10"},{"at":0.5,"label":"20"},{"at":0.75,"label":"30"}],"yTicks":[{"at":0.5,"label":"3"}]},{"t":"curve","points":[[14,52],[32,31],[50,31],[68,52]],"tone":"accent","width":1},{"t":"text","x":22,"y":26,"text":"骑车前往","size":3.6,"tone":"accent"},{"t":"text","x":41,"y":27,"text":"在图书馆停留","size":3.6,"tone":"muted"},{"t":"text","x":62,"y":40,"text":"返回","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":62,"text":"水平段的含义是「路程不变」，不是「静止不动」","size":3.8,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"","text":"读图务必先看两轴的名称与单位：横轴是时间、纵轴是路程时，斜率表示速度；若换成速度—时间图象，水平段才表示匀速。看错坐标轴的含义，整题都会答反。"},{"type":"h","text":"核心概念"},{"type":"p","text":"变量与常量：在某一变化过程中，数值发生变化的量叫变量，数值始终不变的量叫常量。例如匀速行驶中，速度是常量，时间与路程是变量。常量和变量是相对于**同一个变化过程**而言的，换一个过程，常量也可能变成变量。\n先明确「在什么过程中」，再判断谁是常量、谁是变量。"},{"type":"p","text":"函数：一般地，在一个变化过程中有两个变量 x 与 y，如果对于 x 的每一个确定的值，y 都有唯一确定的值与之对应，就说 y 是 x 的函数，x 是自变量。\n关键词是「唯一确定」：一个 x 只能对应一个 y，但不同的 x 可以对应同一个 y。"},{"type":"p","text":"自变量与函数值：自变量是主动变化的量（取值可以自行选定），函数值是当自变量取某个值时对应的因变量的值。求函数值就是把自变量的值代入解析式计算。\n求函数值时要把负数、分数代入时加括号；解析式中含多个字母时，注意看清题目要求谁的值。"},{"type":"p","text":"函数的三种表示方法：解析式法（用式子表示对应关系，便于计算）、列表法（用表格列出自变量与函数值的对应，便于查值）、图象法（用图象表示，便于看出变化趋势）。三者可以互相转化。\n同一函数的三种表示各有长处，考题常要求在它们之间转换，例如由表格描点画图、由图象写解析式。"},{"type":"note","title":"中考考法","text":"判断两个变量是否构成函数关系\n给表格、图象或文字叙述，要求判断 y 是不是 x 的函数。判据只有「唯一确定」：表格中同一个 x 出现两个不同的 y 就不是函数；图象用竖直线去截，有两个交点就不是函数。"},{"type":"note","title":"中考考法","text":"求自变量的取值范围\n先看式子：分母不为 0、偶次根号下非负；再看实际意义：长度、人数、时间等有正负与整数要求。两条件取交集，注意等号能不能取到。"},{"type":"note","title":"中考考法","text":"求函数值与代入计算\n给出解析式与自变量的值，直接代入求函数值；也可能反过来已知函数值求自变量的值（解方程）。代入负数、分数要加括号。"},{"type":"note","title":"中考考法","text":"从函数图象中获取信息\n行程问题的路程—时间图象是高频素材：上升段表示前进、水平段表示停留、下降段表示返回。读图三看：看轴、看点、看趋势。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["函数值的计算","把自变量的值代入解析式，按运算顺序算出结果，即得对应的函数值","代入负数或分数时要加括号：已知 y=2x-1，当 x=-3 时 y=2×(-3)-1=-7。"],["自变量取值范围的常用限制","分式：分母 ≠ 0；二次根式：被开方数 ≥ 0；实际问题：还要符合实际意义","如 y=√(x)x-2：由根号得 x≥ 0，由分母得 x≠ 2，合起来是 x≥ 0 且 x≠ 2。"],["行程问题中的函数关系","匀速运动：s=vt（v 是常量、t 是自变量）；停留阶段路程不变，图象为水平线段","图象的陡缓反映速度大小：同样的时间内上升得越快，速度越大；水平段表示停留而不是「速度为负」。"]]},{"type":"note","title":"例题","text":"已知函数 y=√(x-2)x-3。(1) 求自变量 x 的取值范围；(2) 当 x=6 时，求函数值。"},{"type":"figure","figure":{"id":"fig-num-hanshu-e1","title":"取值范围的两条限制同时生效","caption":"被开方数非负给出左边界，分母不为零挖掉一个点","view":"wide","alt":"数轴上从 2 开始向右的射线（含 2）表示 x≥2，在 3 处画空心点表示 x≠3","prims":[{"t":"line","x1":10,"y1":30,"x2":60,"y2":30},{"t":"arrow","x1":60,"y1":30,"x2":78,"y2":30},{"t":"dot","x":30,"y":30,"tone":"main"},{"t":"dot","x":48,"y":30,"hollow":true,"tone":"danger"},{"t":"text","x":30,"y":40,"text":"2（可取）","size":3.6,"anchor":"middle"},{"t":"text","x":48,"y":40,"text":"3（不可取）","size":3.6,"anchor":"middle","tone":"danger"},{"t":"text","x":44,"y":18,"text":"$x\\ge 2$ 且 $x\\ne 3$","size":4.4,"tone":"accent"},{"t":"text","x":44,"y":52,"text":"实心点表示取得到，空心点表示取不到","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["(1) 要使式子有意义，需要同时满足：二次根式的被开方数非负，即 x-2≥ 0；分式的分母不为零，即 x-3≠ 0。","由 x-2≥ 0 得 x≥ 2；由 x-3≠ 0 得 x≠ 3。所以 x≥ 2 且 x≠ 3。","(2) 当 x=6 时，y=√(6-2)6-3=√(4)3=(2)/(3)。"]},{"type":"p","text":"答案：(1) x≥ 2 且 x≠ 3；(2) y=(2)/(3)。"},{"type":"note","title":"方法小结","text":"取值范围要把多个条件**同时**列出来求交集，只写其中一个是最常见的错误；代入求值时注意先化简再计算。"},{"type":"note","title":"例题","text":"小明从家出发匀速骑车去图书馆，骑了 20 分钟到达；在图书馆停留 10 分钟后按原路匀速返回，又用 20 分钟回到家。已知家到图书馆的路程为 3 千米。(1) 求去时的速度；(2) 画出路程 s（千米）随时间 t（分钟）变化的图象。"},{"type":"figure","figure":{"id":"fig-num-hanshu-e2","title":"去图书馆再返回的路程—时间图象","caption":"上升 20 分钟到 3 千米，水平 10 分钟，再用 20 分钟回到 0","view":"wide","alt":"路程随时间变化的折线图：从原点上升到 20 分钟时 3 千米，然后水平到 30 分钟，再下降到 50 分钟时回到 0","prims":[{"t":"axis","x":16,"y":50,"w":70,"h":40,"xLabel":"t/min","yLabel":"s/km","origin":true,"grid":true,"xTicks":[{"at":0.2,"label":"10"},{"at":0.4,"label":"20"},{"at":0.6,"label":"30"},{"at":0.8,"label":"40"}],"yTicks":[{"at":0.5,"label":"3"}]},{"t":"curve","points":[[16,50],[44,30],[58,30],[86,50]],"tone":"accent","width":1},{"t":"dot","x":44,"y":30,"tone":"main"},{"t":"dot","x":58,"y":30,"tone":"main"},{"t":"text","x":30,"y":26,"text":"前往","size":3.6,"tone":"accent"},{"t":"text","x":51,"y":26,"text":"停留","size":3.6,"tone":"muted"},{"t":"text","x":74,"y":38,"text":"返回","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"关键点 $(0,0)$、$(20,3)$、$(30,3)$、$(50,0)$","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["(1) 去时 20 分钟行驶 3 千米，速度为 3÷ 20=0.15（千米/分）。","(2) 图象分三段：0≤ t≤ 20 时 s 从 0 增大到 3；20≤ t≤ 30 时 s 保持 3 不变（水平线段）；30≤ t≤ 50 时 s 从 3 减小到 0。","描出关键点 (0,0)、(20,3)、(30,3)、(50,0)，再用线段依次连接。"]},{"type":"p","text":"答案：(1) 速度为 0.15 千米/分（即 9 千米/时）；(2) 图象为三段折线：上升到 3、水平停留、下降回到 0。"},{"type":"note","title":"方法小结","text":"画这类图象要标出关键点的坐标，并注意水平段表示「停留」；若把下降段画成上升，就表示继续前进，与实际不符。"},{"type":"list","title":"易错点","items":["把「一个 $x$ 对应两个 $y$」的情形当成函数：如 $|y|=x$ 中 $x=1$ 时 $y=\\pm 1$，不满足「唯一确定」，不是函数关系。","求自变量取值范围时只列一个条件：分母不为 0 与被开方数非负要同时满足，还要考虑实际意义（长度为正、人数为正整数）。","漏掉等号：$\\sqrt{x-2}$ 中 $x\\ge 2$，$x=2$ 时被开方数为 0 仍然有意义，写成 $x>2$ 就是错的。","读图时看错坐标轴：把横轴当成速度、纵轴当成时间，整个图象的含义都会读反。","画图象时用折线硬连各点：函数图象一般要用平滑曲线（直线型的例外），取点过少也会画出失真的图象。"]},{"type":"list","title":"解题方法","items":["判断函数关系的三步：找出两个变量 → 固定其中一个的取值 → 看另一个是否唯一确定，唯一则是函数。","求自变量取值范围：先列「式子有意义」的所有条件，再加上「实际意义」的限制，最后取交集并检验端点能否取到。","读图象三看：看坐标轴（名称与单位） → 看关键点（起点、终点、交点、拐点） → 看趋势（上升、下降、水平各表示什么）。","用描点法画图：列表取点（取值有代表性） → 在坐标系中描点 → 用平滑曲线或直线连接，并标注关键点坐标。"]}],"questions":[{"id":"m-num-hanshu-q1","type":"choice","stem":"下列各式中，y 是 x 的函数的是","answer":"C","explain":"函数要求对于 x 的每一个确定的值，y 都有唯一确定的值与之对应。y=2x+1 满足这一条；|y|=x 与 y²=x 中，给定一个正数 x 会有两个互为相反数的 y；x²+y²=4 是圆，多数 x 也对应两个 y，都不是函数。","options":["|y|=x（x>0）","y²=x（x>0）","y=2x+1","x²+y²=4"],"difficulty":2,"tags":["函数的概念"]},{"id":"m-num-hanshu-q2","type":"choice","stem":"函数 y=(1)/(x-3) 中，自变量 x 的取值范围是","answer":"A","explain":"分式有意义要求分母不为零，即 x-3≠ 0，所以 x≠ 3。这里没有根号，也没有实际意义的限制，因此只需排除 3 这一点，其余实数都可以取。","options":["x≠ 3","x>3","x<3","全体实数"],"difficulty":1,"tags":["自变量取值范围"]},{"id":"m-num-hanshu-q3","type":"choice","stem":"已知函数 y=3x-2，当 x=-2 时，y 的值是","answer":"A","explain":"代入时负数要加括号：y=3×(-2)-2=-6-2=-8。若漏掉括号算成 3× 2-2=4，就会错选 C。两种算法差一个符号，正是这类题最常见的陷阱。","options":["-8","-4","4","8"],"difficulty":2,"tags":["函数值","代入求值"]},{"id":"m-num-hanshu-q4","type":"short","stem":"如图是小明从家出发去图书馆再返回的路程 s（千米）随时间 t（分钟）变化的图象。请回答：(1) 他在图书馆停留了多长时间？(2) 返回时的速度是多少？(3) 图象中哪一段表示的路程不变？为什么？","answer":"(1) 水平段从第 20 分钟到第 30 分钟，共停留 10 分钟。(2) 返回路程 3 千米、用 20 分钟，速度 $=3\\div 20=0.15$（千米/分），即 9 千米/时。(3) 第 20 分钟到第 30 分钟这一段（水平段）路程不变，因为这段时间他在图书馆停留，与家的距离始终是 3 千米。","explain":"读图先看坐标轴：横轴是时间、纵轴是路程。上升段表示路程增大（前往），水平段表示路程不变（停留），下降段表示路程减小（返回）。求速度用「路程 ÷ 时间」，注意单位要统一（分钟对应千米/分）。","difficulty":3,"tags":["函数图象","行程问题"],"rubric":["(1) 答出停留 10 分钟（1 分）","(2) 速度 0.15 千米/分或 9 千米/时（1 分）","(3) 指出水平段并说明路程不变（1 分）"],"figure":{"id":"fig-num-hanshu-q4","title":"路程—时间图象","caption":"上升前往、水平停留、下降返回","view":"wide","alt":"路程随时间变化的折线：从原点上升到 20 分钟时 3 千米，水平到 30 分钟，再下降到 50 分钟时回到 0","prims":[{"t":"axis","x":16,"y":50,"w":70,"h":40,"xLabel":"t/min","yLabel":"s/km","origin":true,"grid":true,"xTicks":[{"at":0.2,"label":"10"},{"at":0.4,"label":"20"},{"at":0.6,"label":"30"},{"at":0.8,"label":"40"}],"yTicks":[{"at":0.5,"label":"3"}]},{"t":"curve","points":[[16,50],[44,30],[58,30],[86,50]],"tone":"accent","width":1},{"t":"text","x":30,"y":26,"text":"前往","size":3.6,"tone":"accent"},{"t":"text","x":51,"y":26,"text":"停留","size":3.6,"tone":"muted"},{"t":"text","x":74,"y":38,"text":"返回","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"横轴看时间、纵轴看路程：水平段表示路程不变","size":3.8,"tone":"muted","anchor":"middle"}]}},{"id":"m-num-hanshu-q5","type":"fill","stem":"用长 20 米的篱笆围成一个一面靠墙的长方形菜园（墙足够长），设垂直于墙的一边长为 x 米，菜园的面积为 y 平方米。(1) 写出 y 与 x 的关系式：________；(2) 自变量 x 的取值范围是________。","answer":"$y=x(20-2x)$；$0<x<10$","explain":"垂直于墙的一边有两条，各长 x 米，共 2x 米，所以平行于墙的一边为 (20-2x) 米，面积 y=x(20-2x)。自变量范围要同时满足「边长都为正」：x>0 且 20-2x>0，解得 0<x<10——这里必须写「<」而不是「≤」，因为边长为 0 不成菜园。","difficulty":3,"tags":["列函数关系式","自变量取值范围","实际应用"]},{"id":"m-num-hanshu-q6","type":"short","stem":"已知等腰三角形的周长为 20，底边长为 y，腰长为 x。(1) 写出 y 与 x 的关系式；(2) 求自变量 x 的取值范围；(3) 当 x=6 时，求底边的长。","answer":"(1) 两腰共 $2x$，故 $y=20-2x$。(2) 自变量要满足：边长都为正，即 $x>0$、$20-2x>0$，得 $x<10$；还要满足三角形的三边关系（两边之和大于第三边），即 $2x>y$，代入得 $2x>20-2x$，解得 $x>5$；三条限制取交集，得 $5<x<10$。(3) 当 $x=6$ 时，$y=20-2\\times 6=8$，底边长为 8。","explain":"这是一道把函数与几何结合的综合题。第 (2) 问最容易丢分：只写「边长为正」得到 0<x<10 是不完整的，还必须用三边关系补上 x>5，否则 x=2 时会得到底边 16 > 2+2，构不成三角形。","difficulty":3,"tags":["函数关系式","自变量取值范围","三角形三边关系"],"rubric":["(1) 写出 y=20-2x（1 分）","(2) 由边长为正得 0<x<10（1 分）","(2) 由三边关系得 x>5，最终 5<x<10（2 分）","(3) 代入得 y=8 并作答（1 分）"]}]}];
